INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('6d4de45e-44ae-43c3-8d19-f613ce9d10bf', 217, 'Citazioni & Easter Egg', 'L''ispirazione per il design dei Pyke', 'Il sindacato dei Pyke, già introdotto in Star Wars: The Clone Wars e riproposto in live-action nella serie, mantiene le caratteristiche facciali acquatiche ideate originariamente da George Lucas e dal team di animazione della Lucasfilm, ispirate ai cefalopodi e alle specie marine abissali.', 'The Art of The Mandalorian: Season 2 / Making-of Gallery', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:47:18.733982+00:00'),
('c2111a93-1a5d-4789-b085-5dd07bc5a82a', 228, 'Curiosità & Retroscena', 'Il cameo di Donald Trump', 'Donald Trump concesse le riprese all''interno del Plaza Hotel, di cui era proprietario all''epoca, a una sola condizione: apparire personalmente in una breve scena del film in cui indica a Kevin la direzione per la hall.', 'Dichiarazioni ufficiali del regista Chris Columbus', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:47:41.063085+00:00'),
('c5c57ccc-6802-44ca-98c6-cebf528f61c3', 228, 'Casting & Scelte', 'Il cameo del regista nei panni del passeggero', 'Il regista Chris Columbus appare brevemente in un cameo non accreditato all''inizio del film, interpretando uno dei passeggeri in aeroporto che osserva confuso Kevin mentre corre.', 'Crediti e commento audio del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:47:41.063085+00:00'),
('8fa640df-df40-4bed-be2b-6b421163e26c', 228, 'Aneddoti dal set', 'La paura reale di Daniel Stern per la tarantola', 'Nella famosa scena in cui la tarantola si posa sul viso di Daniel Stern (Marv), l''attore dovette gridare in silenzio, mimando l''espressione terrorizzata, per evitare che il rumore spaventasse l''aracnide e provocasse un vero morso.', 'Intervista retrospettiva a Daniel Stern', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:47:41.063085+00:00'),
('c3009d9f-e467-4664-865b-f8016daac57f', 228, 'Aneddoti dal set', 'La cicatrice reale di Joe Pesci', 'Macaulay Culkin ha rivelato in varie interviste che Joe Pesci lo morse realmente a un dito durante le prove della scena in cui i Banditi Sanguinari appendono Kevin a un appendiabiti, lasciandogli una piccola cicatrice permanente.', 'Intervista a Macaulay Culkin in vari talk show', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:47:41.063085+00:00'),
('cbd5b5ce-9860-4ef5-aa52-e60e24d1604f', 228, 'Citazioni & Easter Egg', 'Il giocattolo dei 2 piccioni e il legame con il primo film', 'La donna dei piccioni regala a Kevin una copia di una statuetta raffigurante due tortore di plastica, tenendone una per sé e dicendogli che finché saranno amici conserveranno l''altra, omaggio diretto alla colomba spezzata del primo capitolo.', 'Analisi della sceneggiatura di John Hughes', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:47:41.063085+00:00'),
('d7908ee3-6fca-480f-a976-633405e3333d', 228, 'Segreti di produzione', 'La torre di Radio City Music Hall ricostruita in studio', 'La spettacolare sequenza dell''inseguimento finale attorno al gigantesco albero di Natale e nei pressi del Radio City Music Hall fu in realtà girata quasi interamente su un set appositamente ricostruito nei teatri di posa della Fox.', 'Making-of ufficiale e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:47:41.063085+00:00'),
('ad4d2d16-743a-4ead-8c65-2914b02047a5', 228, 'Curiosità & Retroscena', 'Il regalo per il ritorno di Donald Trump', 'Per girare al Plaza Hotel, la produzione dovette pagare una tariffa elevata e rispettare le rigide richieste contrattuali imposte da Trump, che pretese di approvare personalmente la sua inquadratura.', 'Archivi di produzione della 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:47:41.063085+00:00'),
('a6a704e6-a928-409a-8123-e00395cc2122', 228, 'Segreti di produzione', 'Le torri gemelle nel panorama iniziale', 'Nelle sequenze aeree panoramiche di New York all''inizio del film, sono chiaramente visibili le torri del World Trade Center, elemento architettonico che caratterizzava lo skyline originale dell''epoca.', 'Visione diretta del montaggio cinematografico del 1992', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:47:41.063085+00:00'),
('95d16636-cc3a-496a-bfd9-80491b021959', 234, 'Curiosità & Retroscena', 'La collaborazione alla sceneggiatura con Krysty Wilson-Cairns', 'Edgar Wright ha scritto la sceneggiatura del film insieme alla co-sceneggiatrice Krysty Wilson-Cairns, nota per ''1917''. I due hanno lavorato a stretto contatto per due anni, attingendo alla comune passione per il quartiere di Soho e per il lato oscuro della Londra degli anni ''60.', 'Note di produzione ufficiali di Focus Features', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:47:50.911191+00:00'),
('3a6a5d25-d6f8-4535-8a09-f43c64e631cf', 97, 'Segreti di produzione', 'Il bagno di fango e l''addestramento dei cavalli', 'Per girare la leggendaria sequenza della corsa delle bighe, il supervisore della seconda unità gen. Harry D. Parker fece allestire una pista speciale a Livorno e ingaggiò addestratori di cavalli professionisti provenienti da tutta Europa, facendo correre gli animali su un terreno fangoso per aumentare il realismo e ridurre i rischi di scivolamento.', 'Documentario ''The Making of Ben-Hur'' e bollettini di produzione del 1925', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:53:14.671865+00:00'),
('85692cf1-154f-491f-8355-ba52e07eddd2', 97, 'Casting & Scelte', 'La comparsa di futuri grandi registi e attori', 'Tra le migliaia di comparse e figuranti impiegate nelle sequenze di massa girate a Roma e a Livorno figuravano giovani aspiranti attori e tecnici che sarebbero diventati celebri, tra cui un giovane Clark Gable e Gary Cooper, presenti sul set come comparse non accreditate.', 'Biografie ufficiali di Clark Gable e registri di casting della MGM', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:53:14.671865+00:00'),
('be5e5984-d39b-4e6f-9aae-2d5fd4953554', 239, 'Effetti speciali & Trucco', 'La maschera di William Shatner', 'La celebre maschera di Michael Myers fu creata acquistando una maschera di gomma del capitano Kirk di ''Star Trek'' interpretato da William Shatner per soli 1,98 dollari in un negozio di costumi di Hollywood. Lo scenografo Tommy Lee Wallace la modificò allargando i fori degli occhi, tingendo i capelli di castano scuro e sprayando la faccia di bianco.', 'Documentario ''Halloween: A Cut Above the Rest''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:53:41.161361+00:00'),
('dc3754f8-a33d-46fe-a539-be3b94a35042', 239, 'Segreti di produzione', 'Il guardaroba economico e i jeans personali', 'Data l''estrema ristrettezza del budget, la costumista e co-sceneggiatrice Debra Hill acquistò gran parte dei vestiti per il cast nei negozi economici locali. La stessa Jamie Lee Curtis indossò i propri jeans personali per interpretare Laurie Strode per gran parte delle riprese.', 'Note di produzione e commento audio del Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:53:41.161361+00:00'),
('29963235-c85b-4273-a76b-9aed0f0674db', 239, 'Aneddoti dal set', 'Le foglie autunnali di carta dipinte', 'Le riprese si svolsero in primavera inoltrata in California, il che significava che non c''erano foglie autunnali sugli alberi. La troupe dovette raccogliere sacchi di foglie morte e riutilizzarle continuamente, ridipingendole persino di giallo e arancione per mantenere la continuità visiva della scena.', 'Intervista al regista John Carpenter nel libro ''The Cinema of John Carpenter''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:53:41.161361+00:00'),
('f61d5885-62b0-485e-b3eb-0f052a2071c0', 239, 'Casting & Scelte', 'Il nome d''arte ''The Shape'' nei crediti', 'Nei titoli di coda originali del film, il personaggio di Michael Myers adulto non è accreditato con il suo nome proprio, bensì come ''The Shape'' (La Sagoma), un termine coniato da John Carpenter in sceneggiatura per enfatizzare la sua natura di entità sovrannaturale e informe piuttosto che di semplice serial killer.', 'Sceneggiatura originale e crediti cinematografici del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:53:41.161361+00:00'),
('de97ff1b-2c77-4f5a-a970-119c86eca875', 239, 'Citazioni & Easter Egg', 'L''omaggio a Alfred Hitchcock e Psycho', 'I nomi dei personaggi di Loomis e Brackett sono chiari omaggi alla storia del cinema: il dottor Loomis riprende Sam Loomis di ''Psycho'', mentre lo Sceriffo Leigh Brackett prende il nome dal celebre sceneggiatore di Howard Hawks e dello stesso Carpenter in ''Rio Bravo''.', 'Interviste retrospettive a John Carpenter e Debra Hill', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:53:41.161361+00:00'),
('0b3b9143-2280-4ea9-a103-008dac89564d', 239, 'Curiosità & Retroscena', 'Il primo montaggio rifiutato dai distributori', 'Quando il primo montaggio del film fu mostrato ai dirigenti degli studios, fu giudicato totalmente privo di spaventi e noioso. Fu solo grazie all''aggiunta successiva della celebre colonna sonora elettronica in post-produzione e a una sessione di missaggio del suono incentrata sui battiti cardiaci che il film acquisì la tensione claustrofobica definitiva.', 'Making-of ''Halloween: Unmasked''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:53:41.161361+00:00'),
('7e650b7e-4e64-4e80-9758-7a247b7861de', 239, 'Segreti di produzione', 'La troupe costretta a fare i doppi ruoli', 'Il team di produzione era così ridotto che quasi tutti dovettero svolgere mansioni multiple: il produttore Irwin Yablans aiutò a spostare le attrezzature, mentre la co-sceneggiatrice Debra Hill si occupava anche del trucco e della gestione delle comparse sul set.', 'Booklet ufficiale dell''edizione speciale in home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:53:41.161361+00:00'),
('df735d95-e9db-452e-b4de-0ad5fd230c60', 239, 'Aneddoti dal set', 'Il vero fischio minaccioso di Michael Myers', 'Nella famosa sequenza in cui Michael Myers cammina con nonchalance stringendo la biancheria dopo l''omicidio di Annie, l''attore Nick Castle stava semplicemente canticchiando e fischiettando per rilassarsi tra una ripresa e l''altra, finché Carpenter decise di mantenere quell''atteggiamento inquietantemente casuale nella versione finale.', 'Commento audio del cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:53:41.161361+00:00'),
('7740567e-0115-4d38-b83c-f4ec91814288', 221, 'Casting & Scelte', 'La straordinaria trasformazione di Peter Ustinov', 'Peter Ustinov ottenne la parte di Nerone dopo che la produzione aveva valutato attori più anziani. All''epoca delle riprese aveva solo trent''anni e dovette sottoporsi a lunghe sedute giornaliere di trucco per incarnare la decadenza e la corporatura dell''imperatore romano.', 'Autobiografia di Peter Ustinov e note di produzione MGM', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:47:22.730654+00:00'),
('80e34f4c-d940-4c3a-ab26-349d9694b4d7', 221, 'Aneddoti dal set', 'L''infortunio sul set di Leo Genn', 'Leo Genn, che interpretava Petronio, si ferì lievemente durante le riprese della sequenza del suo celebre suicidio rituale. L''attore chiese di utilizzare un vero calice di metallo pesante per rendere più realistica la scena del banchetto prima di tagliarsi le vene.', 'Documentario retrospettivo sul kolossal MGM del 2001', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:47:22.730654+00:00'),
('5f4752aa-d291-4c5f-a3fd-efed23a68173', 221, 'Segreti di produzione', 'La statua colossale di Nerone', 'Negli studi di Cinecittà a Roma fu edificata una riproduzione in gesso e legno alta oltre quaranta metri della statua di Nerone, una delle strutture scenografiche più imponenti mai realizzate all''interno di un set cinematografico europeo dell''epoca.', 'Archivio storico degli stabilimenti di Cinecittà', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:47:22.730654+00:00'),
('45899b3f-807a-45c0-8070-8766d2d09c95', 221, 'Casting & Scelte', 'La scelta di Elizabeth Taylor non realizzata', 'Nei primissimi stadi di sviluppo del film, quando la produzione era stata pianificata per la prima volta alla fine degli anni ''30 prima dello scoppio della seconda guerra mondiale, la MGM aveva pensato a una giovanissima Elizabeth Taylor per il ruolo di Licia.', 'Registri di casting prebellici della Metro-Goldwyn-Mayer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:47:22.730654+00:00'),
('ff2b0986-33a9-4acb-a5ad-abddea3ce88a', 221, 'Segreti di produzione', 'L''impiego record di comparse romane', 'Per girare le scene delle persecuzioni nel circo massimo ricostruito a Cinecittà, la produzione impiegò regolarmente oltre 15.000 comparse locali, reclutate tra i disoccupati della Roma del dopoguerra, creando enormi sfide logistiche e di ordine pubblico.', 'Cronache giornalistiche dell''epoca e note di produzione di Mervyn LeRoy', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:47:22.730654+00:00'),
('bd6b683c-a0fe-4440-9e82-0f2878157ab7', 114, 'Citazioni & Easter Egg', 'Il nome di Jackie Treehorn e il omaggio a Orson Welles', 'La villa in cui vive il magnate della pornografia Jackie Treehorn (Ben Gazzara) è la celebre Sheats-Goldstein Residence progettata dall''architetto John Lautner a Beverly Hills, un esplicito omaggio visivo alle atmosfere dei thriller cinematografici classici e al cinema noir di stampo californiano.', 'Analisi di architettura cinematografica di Architectural Digest', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:53:20.398053+00:00'),
('b0494417-2ddb-460a-96d3-d347fa26a794', 280, 'Casting & Scelte', 'Il rifiuto di Claudia Wells e il recasting di Jennifer', 'Claudia Wells, che aveva interpretato Jennifer Parker nel primo film, fu costretta a rifiutare di riprendere il ruolo a causa di gravi problemi di salute di sua madre. La produzione scelse quindi Elisabeth Shue, costringendo Bob Gale e Robert Zemeckis a rigirare interamente la sequenza iniziale del 1985 con la nuova attrice.', 'Documentario ''Making the Trilogy'' e commento audio del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:53:47.198964+00:00'),
('2086e9d7-87ee-489b-84aa-a6ea5e7662aa', 280, 'Casting & Scelte', 'Il debutto cinematografico di Elijah Wood', 'Un giovanissimo Elijah Wood, all''età di otto anni, fa la sua prima apparizione sul grande schermo interpretando uno dei due bambini che giocano al videogioco arcade ''Wild Gunman'' nel bar degli anni ''80. Nel backstage, l''attore ha raccontato di aver indossato un abito di scena che trovava particolarmente scomodo.', 'Intervista ufficiale di Elijah Wood per Vanity Fair e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:53:47.198964+00:00'),
('b01abb9b-30e5-445b-aacb-7dfa374eff6b', 280, 'Effetti speciali & Trucco', 'La complessa tecnologia per il triplo ruolo di Thomas F. Wilson', 'Per permettere a Thomas F. Wilson di interpretare contemporaneamente Biff Tannen da vecchio, Biff Tannen da giovane e il nipote Griff nel 2015, la produzione utilizzò una complessa cinepresa con controllo di movimento e la tecnica del ''VistaGlide''. Questo permise di dividere l''inquadratura in più sezioni fondendole digitalmente e otticamente in post-produzione.', 'Special TV ''The Secrets of the Future'' e documentario sul set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:53:47.198964+00:00'),
('3f3f93a3-b216-47fb-a15c-170dd8a7a732', 280, 'Effetti speciali & Trucco', 'Il trucco invecchiato per Lea Thompson e Donald Fullilove', 'Gli attori Lea Thompson (Lorraine) e Donald Fullilove (Goldie Wilson) dovettero sottoporsi a lunghe sessioni giornaliere di trucco prostetico della durata di oltre quattro ore per interpretare le loro versioni invecchiate nel 2015. Il truccatore Ken Chase si occupò di applicare maschere in lattice avanzate per conferire loro un aspetto realistico da settantenni.', 'Making-of ufficiale ''The Making of Back to the Future Part II''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:53:47.198964+00:00'),
('cc318428-5d23-455b-bea9-d690daf797d3', 280, 'Segreti di produzione', 'L''invenzione dell''Hoverboard e le finte dichiarazioni', 'Per promuovere il film, Robert Zemeckis scherzò in un''intervista dicendo che gli hoverboard (le tavole volanti) erano reali ma messi al bando dai genitori per eccessiva pericolosità. Questa trovata scatenò una tale ondata di lettere di bambini e genitori alla Universal che la produzione dovette smentire pubblicamente la notizia.', 'Intervista d''archivio a Robert Zemeckis e documentario Universal', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:53:47.198964+00:00'),
('c7629078-4dab-438b-893a-c850d987eef6', 280, 'Citazioni & Easter Egg', 'La finta copertina del giornale con Jaws 19', 'Nel cinema 3D di Hill Valley nel 2015 viene proiettato ''Jaws 19'', diretto da Max Spielberg, chiaro omaggio al figlio di Steven Spielberg. Il finto squalo olografico che attacca Marty è stato realizzato con i primi test digitali di animazione tridimensionale dell''epoca.', 'Note di produzione e libro ''Back to the Future: The Ultimate Visual History''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:53:47.198964+00:00'),
('4d25faab-007a-40e1-a236-c84b59f6af85', 280, 'Aneddoti dal set', 'L''incidente dello stuntman sullo skate volante', 'Durante le complesse sequenze di inseguimento con gli hoverboard, la stuntwoman Cheryl Dunye e gli altri acrobati venivano sospesi tramite cavi d''acciaio sottili che venivano poi cancellati digitalmente in post-produzione. Uno stuntman riportò una frattura alla clavicola dopo una caduta da un''altezza di tre metri mentre simulava l''impatto con il tribunale.', 'Report sugli incidenti di set della Universal Studios e interviste agli stunt', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:53:47.198964+00:00'),
('3dfee5a1-cf91-49dd-9532-2daebaba7639', 280, 'Curiosità & Retroscena', 'La presenza segreta di J.J. Abrams nei ringraziamenti', 'Prima di diventare il celebre regista di Hollywood, J.J. Abrams lavorò indirettamente nell''ambiente cinematografico e la sua influenza amichevole con alcuni membri della troupe fu tale da garantirgli una menzione speciale nei materiali promozionali interni della produzione.', 'Archivi storici della produzione Universal e biografie ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:53:47.198964+00:00'),
('d7233d86-a344-40d6-a042-231ca52b9a7f', 221, 'Aneddoti dal set', 'I veri leoni importati dall''Africa', 'Per le scene ambientate nell''arena, la produzione fece arrivare appositamente in aereo e nave decine di veri leoni dall''Africa. Gli animali furono ospitati in recinti speciali allestiti vicino agli studi cinematografici e seguiti costantemente da domatori professionisti.', 'Intervista al regista Mervyn LeRoy per i contenuti extra dell''edizione Home Video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:47:22.730654+00:00'),
('1c47d24d-694b-49c9-92cb-fcaa60f26a5d', 108, 'Aneddoti dal set', 'Le riprese blindate nell''area di Atlanta', 'Le riprese principali hanno preso il via nella primavera del 2024 ad Atlanta e nelle contee limitrofe dello stato della Georgia. Per preservare i segreti della trama, la produzione ha adottato protocolli di massima sicurezza nei quartieri residenziali prescelti, limitando rigorosamente l''accesso e l''uso di telefoni ed elicotteri di monitoraggio nei pressi delle vie di set.', 'Atlanta Journal-Constitution', TRUE, 'IA (Admin)', 'IA Verificata', 1, 5, '2026-11-02T18:13:56.94748+00:00'),
('c671c35e-01f5-4885-8013-76e860a1d6d3', 138, 'Casting & Scelte', 'Il provino di Robert Forster e la seconda possibilità', 'Robert Forster aveva fatto un provino disastroso per le Iene (Reservoir Dogs) anni prima e pensava di essere stato scartato per sempre da Tarantino. Invece, il regista lo convocò direttamente per il ruolo di Max Cherry senza fargli fare ulteriori audizioni, colpito dalla sua aura da duro dal cuore tenero.', 'Commento audio del regista e Making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:53:25.109944+00:00'),
('c9f80dde-8420-46c7-b66f-1c8619a61ef8', 138, 'Casting & Scelte', 'La persistenza di Robert De Niro per il ruolo di Louis Gara', 'Robert De Niro contattò personalmente Quentin Tarantino per esprimere il suo forte interesse a recitare nel film, chiedendo esplicitamente di interpretare Louis Gara, il galeotto taciturno uscito di prigione.', 'Note di produzione ufficiali Miramax', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:53:25.109944+00:00'),
('7d0dc406-3229-4800-ac3e-05d23cbe0803', 138, 'Casting & Scelte', 'Sylvester Stallone considerato per Ordell Robbie', 'Nelle prime fasi di sviluppo del casting, prima che Samuel L. Jackson venisse blindato per la parte, la produzione prese in considerazione Sylvester Stallone per il ruolo del trafficante d''armi Ordell Robbie.', 'Archivi di casting e biografia autorizzata di Quentin Tarantino', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:53:25.109944+00:00'),
('ded19ff3-eac9-462a-af0e-62b8a630ca88', 138, 'Segreti di produzione', 'Il vero furgone di Max Cherry', 'Il furgone marrone guidato dal personaggio di Max Cherry nel film apparteneva realmente a un amico di Quentin Tarantino, e fu utilizzato sul set senza alcuna modifica estetica particolare per mantenere il realismo urbano anni ''70.', 'Intervista allo scenografo David Wasco', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:53:25.109944+00:00'),
('97caa9d4-f3a9-4e7c-9e5f-3c841e37f9d5', 138, 'Curiosità & Retroscena', 'L''ispirazione per il titolo originale e il romanzo', 'Quentin Tarantino decise di cambiare il titolo del film da ''Rum Punch'' (il titolo del libro di Elmore Leonard) a ''Jackie Brown'' come esplicito omaggio ai film blaxploitation degli anni ''70, in particolare a ''Coffy'' (1973) sempre interpretato da Pam Grier.', 'Intervista ufficiale di Quentin Tarantino per Rolling Stone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:53:25.109944+00:00'),
('ae5f3032-59cc-4ea2-ac10-59e894dd8970', 138, 'Aneddoti dal set', 'Le riprese nel vero centro commerciale Del Amo Fashion Center', 'La complessa sequenza dello scambio di denaro al centro commerciale fu girata nel reale Del Amo Fashion Center di Torrance, in California, costringendo la troupe a lavorare principalmente di notte per evitare il flusso dei normali acquirenti.', 'Diario di bordo della produzione e note di regia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:53:25.109944+00:00'),
('a3f471b3-8eb3-40e2-8aeb-5bd262bef205', 138, 'Segreti di produzione', 'La scelta della pistola di Ordell', 'La pistola calibro .45 Colt Commander utilizzata da Samuel L. Jackson nel film fu scelta personalmente da Tarantino per riflettere il gusto eccentrico ma letale di un criminale che vuole apparire sofisticato.', 'Armorer''s report e documentario sul set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:53:25.109944+00:00'),
('800c891d-0e8d-4989-a411-654b77e30696', 281, 'Aneddoti dal set', 'L''infortunio sul set di Michael J. Fox', 'Durante le riprese della celebre sequenza in cui Marty viene quasi impiccato dalla banda di Buford ''Cane Pazzo'' Tannen, Michael J. Fox rischiò realmente la vita. Per errore l''attore perse il controllo del sostegno che avrebbe dovuto proteggerlo e rimase appeso al cappio per diversi secondi prima che la troupe si accorgesse della situazione e intervenisse.', 'Documentario ufficiale ''The Making of Back to the Future Part III''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:53:53.685159+00:00'),
('14053381-4349-4da8-8633-38119baedbf6', 281, 'Casting & Scelte', 'La scelta originale per Clara Clayton', 'Prima che il ruolo di Clara Clayton venisse affidato a Mary Steenburgen, i produttori e Robert Zemeckis avevano offerto la parte all''attrice Mary Steenburgen non era la prima scelta; in realtà, la produzione aveva valutato a lungo l''attrice e cantante country Dolly Parton, la quale dovette rifiutare a causa di altri impegni professionali.', 'Commento audio del regista Robert Zemeckis e dello sceneggiatore Bob Gale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:53:53.685159+00:00'),
('70c06d83-8af1-49dd-b296-9b2762db0cd0', 281, 'Casting & Scelte', 'Il cameo dei leggendari ZZ Top', 'I membri della rock band ZZ Top compaiono in un cameo all''interno del film nel ruolo dei musicisti della festa cittadina del 1885, intenti a suonare strumenti d''epoca. La band fu fortemente voluta da Robert Zemeckis, grande appassionato del loro stile rock-blues.', 'Note di produzione ufficiali Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:53:53.685159+00:00'),
('e70abfe4-5ea7-484f-ae6e-8f8f751dfb74', 281, 'Segreti di produzione', 'La costruzione della città di Hill Valley del 1885', 'L''intera cittadina di Hill Valley del 1885 non fu ricostruita nei backlot degli studi Universal (distrutti da un incendio), bensì fu edificata da zero in una zona remota della riserva indiana di Jamestown, nella contea di Tuolumne, in California. La costruzione richiese mesi di lavoro per erigere oltre trenta edifici storici perfettamente funzionanti.', 'Archivio di produzione Universal e libro ''Back to the Future: The Official Book of the Animation/Film''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:53:53.685159+00:00'),
('a3878bc1-d269-4114-891f-0305fc894c45', 281, 'Citazioni & Easter Egg', 'L''omaggio a Clint Eastwood', 'Quando Marty McFly arriva nel 1885 e viene interrogato sui suoi dati personali dai pistoleri locali, decide di fingersi il celebre attore western Clint Eastwood, usando lo pseudonimo ''Clint Eastwood''. Questa scelta giustifica anche la celebre citazione visiva in cui Marty usa una piastra di ghisa nascosta sotto il poncho per salvarsi la vita dal fucile a canne mozze, chiaro omaggio a ''Per un pugno di dollari''.', 'Sceneggiatura originale di Bob Gale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:53:53.685159+00:00'),
('fc18a208-ed43-4978-b49d-35f2eb80a90f', 281, 'Effetti speciali & Trucco', 'Le vere origini della DeLorean ferroviaria', 'Per girare la sequenza in cui la DeLorean viene spinta dalla locomotiva a vapore lungo i binari, la produzione modificò realmente una vera vettura DeLorean DMC-12 dotandola di ruote in acciaio ferroviarie. Vennero costruite diverse repliche, alcune delle quali erano scocche leggere trainate da cavi di acciaio o montate su camion attrezzati per le scene in primo piano.', 'Documentario ''Making the Trilogy: Part III''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:53:53.685159+00:00'),
('a7eaa59c-735e-47dd-bdad-35978a7fe84b', 281, 'Segreti di produzione', 'Il trucco delle lettere d''epoca', 'La lettera scritta da Doc Brown nel 1885 e ritrovata da Marty nel 1955 fu realizzata con estrema cura calligrafica utilizzando inchiostro seppia e carta invecchiata artificialmente con il tè. Per garantire la continuità visiva tra le inquadrature ravvicinate e quelle larghe, la troupe dovette produrre decine di copie identiche scritte a mano da un calligrafo professionista.', 'Note di produzione e reparto scenografia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:53:53.685159+00:00'),
('5be578c5-93bb-4fc3-ac43-4cfc099209d6', 281, 'Aneddoti dal set', 'Thomas F. Wilson e l''abilità con il lazo', 'Thomas F. Wilson, interprete del cattivo Buford ''Cane Pazzo'' Tannen, si allenò duramente per mesi con un esperto di lanci di lazo per poter eseguire personalmente la complessa sequenza in cui intrappola Marty a cavallo. Wilson riuscì a compiere l''acrobazia dal vivo senza l''ausilio di controfigure o effetti digitali.', 'Intervista speciale a Thomas F. Wilson nel cofanetto Blu-ray della trilogia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:53:53.685159+00:00'),
('cfee4a98-f789-4caa-a1ca-0cae1fd45354', 145, 'Casting & Scelte', 'Il provino rifiutato da George Clooney', 'George Clooney fece un provino per ottenere una parte nel film (probabilmente per il ruolo di Mr. Blonde), ma venne scartato da Tarantino e dal produttore Lawrence Bender. Anni dopo, proprio grazie al successo del film, Clooney avrebbe ottenuto la parte principale in ''Dal tramonto all''alba'' scritto dallo stesso Tarantino.', 'Interviste retrospettive a Lawrence Bender e George Clooney', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:53:30.834923+00:00'),
('03abacee-80a2-4f9d-84e3-cc42adcffda4', 145, 'Citazioni & Easter Egg', 'Il vero nome di Mr. Orange rivelato dal copione originale', 'Durante la scena della macchina in cui Mr. White cerca di calmare il ferito Mr. Orange, il nome di battesimo dell''agente sotto copertura (Freddy Newandyke) non viene mai pronunciato chiaramente nel montaggio finale, ma appare esplicitamente nella sceneggiatura originale e nei titoli di coda completi.', 'Sceneggiatura originale pubblicata e crediti di montaggio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:53:30.834923+00:00'),
('7f820cef-c951-4eb5-b647-7dcaf55c8ffc', 145, 'Citazioni & Easter Egg', 'L''ispirazione visiva da ''City on Fire'' di Ringo Lam', 'La struttura narrativa e visiva del film, in particolare la figura dell''agente di polizia infiltrato in una banda di rapinatori che finisce in un bagno di sangue, è fortemente debitrice al film d''azione di Hong Kong ''City on Fire'' (1987) diretto da Ringo Lam, da cui Tarantino mutuò apertamente diverse sequenze.', 'Dichiarazioni pubbliche e interviste di Quentin Tarantino', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:53:30.834923+00:00'),
('0a4a6c7a-b65e-43c5-90f9-825cea1dd865', 145, 'Effetti speciali & Trucco', 'Il trucco artigianale per la ferita da sparo di Mr. Orange', 'Per simulare la copiosa emorragia addominale di Tim Roth durante la scena in macchina con Harvey Keitel, la troupe utilizzò tubicini di plastica nascosti sotto gli abiti dell''attore e azionati manualmente fuori campo per regolare il flusso dello sciroppo colorato.', 'Making-of ufficiale e contenuti speciali del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:53:30.834923+00:00'),
('ab01dfc9-722c-43d0-9a6a-8840ba1409b7', 145, 'Casting & Scelte', 'Il rifiuto di Samuel L. Jackson al primo provino', 'Samuel L. Jackson fece un provino per il film ma non ottenne la parte perché Tarantino lo considerò ''troppo bravo'' per il ruolo minore per cui stava provando, preferendogli altri attori. Tuttavia, impressionato dal suo talento, Tarantino scrisse appositamente per lui il personaggio di Jules Winnfield in ''Pulp Fiction''.', 'Intervista retrospettiva a Samuel L. Jackson e Quentin Tarantino', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:53:30.834923+00:00'),
('cfada776-e9fe-4150-aa07-fb2f0592b049', 282, 'Casting & Scelte', 'Il rifiuto di Tom Cruise per il ruolo di Andy', 'Prima che Tim Robbins venisse scelto per la parte di Andy Dufresne, la produzione aveva offerto il ruolo principale a Tom Cruise, il quale partecipò anche alla prima lettura del copione (''table read'') prima di rifiutare l''offerta.', 'Documentario ufficiale e interviste di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:53:59.433918+00:00'),
('a60299b9-6933-482b-8bd1-89917683107a', 282, 'Casting & Scelte', 'Brad Pitt e Johnny Depp scartati o rinunciatari', 'Oltre a Tom Cruise, anche Brad Pitt, Johnny Depp e Nicolas Cage furono considerati o contattati per interpretare il protagonista Andy Dufresne nelle primissime fasi di sviluppo del progetto.', 'Archivi di casting di Castle Rock Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:53:59.433918+00:00'),
('97dff6e2-4f9a-484b-80db-3c90c222d4e8', 282, 'Casting & Scelte', 'La scelta iniziale per il direttore Norton', 'Prima che Bob Gunton ottenesse l''acclamato ruolo del direttore Samuel Norton, la produzione aveva valutato attori del calibro di Gene Hackman e Robert Duvall per la parte del sadico amministratore del penitenziario.', 'Note di produzione e retroscena del casting', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:53:59.433918+00:00'),
('0eccc888-e817-44eb-bcaf-536c7888444f', 282, 'Casting & Scelte', 'William Sadler e il provino per un altro ruolo', 'L''attore William Sadler, che nel film interpreta il detenuto Heywood, si era originariamente presentato ai provini per il ruolo di Bogs Diamond, il capo della gang dei ''Sisters''.', 'Commento audio del Blu-Ray di Frank Darabont', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:53:59.433918+00:00'),
('2b06788c-c65f-41bb-a00f-e7a3a22e3687', 282, 'Segreti di produzione', 'La vera prigione di Mansfield', 'Il film è stato girato principalmente all''interno e intorno al riformatorio statale dell''Ohio a Mansfield, una struttura carceraria reale dismessa che versava in condizioni così fatiscenti da richiedere ingenti lavori di ristrutturazione prima delle riprese.', 'Making-of ufficiale ''Hope Springs Eternal''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:53:59.433918+00:00'),
('1a61f030-ac10-4b51-bcca-5d68bdbfb862', 282, 'Segreti di produzione', 'La demolizione parziale del set', 'Poco dopo la fine delle riprese, gran parte del riformatorio di Mansfield fu demolito, inclusi gli edifici amministrativi e la falegnameria, rendendo il film una preziosa testimonianza visiva di quell''architettura carceraria storica.', 'Reportage storici sulla produzione del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:53:59.433918+00:00'),
('8fda233a-87be-4fd1-8353-0f89aa46023e', 282, 'Aneddoti dal set', 'La vera natura della geode di Andy', 'La pietra che Andy scava e leviga nel corso degli anni non è una vera geode di roccia naturale, ma un oggetto di scena appositamente scolpito e realizzato in legno e argilla dal reparto scenografia.', 'Note del dipartimento di scenografia e oggetti di scena', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:53:59.433918+00:00'),
('e2d31b7b-e5d5-43e3-b1a0-d7e9995e25f5', 282, 'Aneddoti dal set', 'Le ore di lancio della palla da baseball', 'Nella celebre scena in cui Andy si avvicina a Red nel cortile chiedendogli di procurargli un martelletto da intaglio, l''attore Morgan Freeman passò nove ore consecutive a lanciare una palla da baseball contro un muro solo per girare quella sequenza.', 'Interviste ufficiali a Morgan Freeman', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:53:59.433918+00:00'),
('aa3a6ffc-673c-4c29-8e39-ce9d45c8053b', 282, 'Aneddoti dal set', 'Il braccio dolorante di Tim Robbins nel tunnel', 'Durante la sequenza in cui Andy striscia nel tubo fognario, Tim Robbins dovette sopportare uno sforzo fisico notevole e un forte dolore alle braccia a causa della melma viscosa, composta da sciroppo di cioccolato e acqua, usata per simulare i liquami.', 'Commento audio del regista Frank Darabont', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T14:53:59.433918+00:00'),
('caa03cab-45ec-4fb5-b3c2-fb61dfd23826', 282, 'Curiosità & Retroscena', 'L''improvvisazione della foto di Rita Hayworth', 'Il poster di Rita Hayworth nella cella di Andy non fu l''unico: nel corso dei decenni di prigionia la parete ospita anche Raquel Welch e Marilyn Monroe, rispecchiando fedelmente l''evoluzione temporale del racconto originale di Stephen King.', 'Analisi visiva e sceneggiatura ufficiale di Frank Darabont', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T14:53:59.433918+00:00'),
('47e8a5ee-5a3d-4073-867f-8d3a8dd033af', 282, 'Citazioni & Easter Egg', 'Il cameo del figlio del regista', 'Il neonato che appare nelle primissime scene del film, tenuto in braccio da Andy Dufresne nella sua auto prima del duplice omicidio, è in realtà il figlio del regista Frank Darabont.', 'Curiosità ufficiali dai contenuti speciali del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 10, '2026-11-02T14:53:59.433918+00:00'),
('56bec9d9-3065-486c-a3d6-2fdcb729edf0', 224, 'Aneddoti dal set', 'Il conflitto creativo tra Kubrick e Douglas', 'Durante la lavorazione sorsero forti tensioni artistiche tra Stanley Kubrick e Kirk Douglas, al punto che il regista arrivò a lamentarsi apertamente del fatto che la sceneggiatura di Dalton Trumbo gli impedisse di esprimere pienamente la sua visione autoriale.', 'Documentario ''The Making of Spartacus'' e interviste d''archivio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:47:27.140716+00:00'),
('20f47c67-7ac4-450e-9ebc-a14f0cca0fae', 204, 'Segreti di produzione', 'La colonna sonora registrata a casa di Lorde', 'Lorde ha supervisionato l''intera colonna sonora coordinando artisti internazionali del calibro di Kanye West, Chemical Brothers e Charli XCX, registrando gran parte del suo contributo vocale direttamente in studio casalingo mentre era in tour.', 'Intervista di Billboard alla curatrice Lorde e note stampa della Republic Records', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:53:35.948081+00:00'),
('ef2a43b7-a011-4ca3-a76c-bacfebedd6da', 204, 'Effetti speciali & Trucco', 'L''uso dei veri ''Propos'' con cineprese reali', 'Per girare i video di propaganda (i Propos) della rivoluzione, la troupe ha utilizzato veri dispositivi di ripresa modificati e telecamere digitali a spalla per dare un look grezzo e documentaristico, evitando l''uso di pulite cineprese cinematografiche di lusso.', 'Special contenuto nel Blu-ray ufficiale ''The Making of Mockingjay Part 1''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:53:35.948081+00:00'),
('21df80aa-a122-440b-8ea7-0db82a3b72a8', 204, 'Casting & Scelte', 'Il tributo finale a Julianne Moore e la sua entrata nel cast', 'Julianne Moore ha accettato con entusiasmo il ruolo della Presidente Alma Coin principalmente perché i suoi figli adolescenti erano grandi fan della saga letteraria di Suzanne Collins e la supplicavano di accettare la parte.', 'Intervista promozionale concessa da Julianne Moore a Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:53:35.948081+00:00'),
('3ddc9111-b31d-4bf6-8cdf-a3961ae80be4', 283, 'Aneddoti dal set', 'La reclusione reale degli attori nell''ospedale psichiatrico', 'Per favorire l''autenticità delle interpretazioni, Miloš Forman impose agli attori che interpretavano i pazienti di vivere effettivamente per settimane all''interno del vero reparto psichiatrico dell''Oregon State Hospital, mescolandosi con i veri degenti durante le pause.', 'Documentario making-of ''The Making of One Flew Over the Cuckoo''s Nest''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:54:04.480191+00:00'),
('92107771-5134-4c69-9c30-5a469b3a6f11', 283, 'Aneddoti dal set', 'L''improvvisazione shock della seduta di elettroshock', 'Durante la scena in cui McMurphy attende la terapia elettroconvulsivante, l''attore Vincent Schiavelli (Taber) improvvisò una serie di battute bizzarre e tic nervosi che fecero scoppiare a ridere spontaneamente la troupe, costringendo a ripetere il ciak.', 'Note di produzione e commento audio del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:54:04.480191+00:00'),
('d0322d62-1ef2-4a2e-8c1b-d186b696f72b', 283, 'Casting & Scelte', 'Il provino rifiutato da Burt Reynolds', 'Prima che il ruolo di Randle McMurphy fosse assegnato a Jack Nicholson, la produzione prese seriamente in considerazione Burt Reynolds, ma l''attore fu scartato o rifiutò l''offerta a causa di disaccordi sul tono generale che il film avrebbe dovuto assumere.', 'Autobiografia di Burt Reynolds ''But Enough About Me''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:54:04.480191+00:00'),
('687397f3-8ba8-43fc-bfb9-90f38ecb7003', 283, 'Casting & Scelte', 'Il vero passato criminale dei pazienti di supporto', 'Molti dei pazienti compresi nel reparto psichiatrico non erano attori professionisti, ma veri residenti della struttura e persone reclutate localmente nell''Oregon, alcune delle quali avevano trascorsi giudiziari reali che conferirono al film un ineguagliato realismo.', 'Archivio storico dell''Oregon State Hospital', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:54:04.480191+00:00'),
('b39c712e-c352-4a57-b214-8de9996f0528', 283, 'Casting & Scelte', 'La scelta iniziale di Hal Ashby alla regia', 'Prima che Miloš Forman venisse ingaggiato per dirigere il film, Michael Douglas aveva pensato inizialmente ad Hal Ashby per la regia, ma i produttori insistettero per Forman dopo aver visto il suo lavoro in ''Taking Off'' e la sua sensibilità visiva.', 'Biografia di Michael Douglas', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:54:04.480191+00:00'),
('641b5296-b0a1-4dee-8d2b-ae4cfc6d4e32', 283, 'Curiosità & Retroscena', 'La frustrazione di Louise Fletcher per la percezione del pubblico', 'Dopo l''uscita del film, Louise Fletcher raccontò di essere stata spesso evitata o guardata con timore dalle persone comuni per via della sua interpretazione spietata dell''Infermiera Ratched, un ruolo che temette potesse rovinarle definitivamente la carriera.', 'Intervista retrospettiva ad American Film Institute', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:54:04.480191+00:00'),
('02e9748d-c9fe-4aae-bc38-46bd2ab1eb0b', 224, 'Curiosità & Retroscena', 'Il contributo di Dalton Trumbo nella lista nera', 'Lo sceneggiatore Dalton Trumbo era inserito nella famigerata Hollywood blacklist a causa della sua militanza nel Partito Comunista; Kirk Douglas ruppe clamorosamente l''omertà accreditandolo ufficialmente con il suo vero nome nei titoli di testa del film.', 'Archivi storici della Writers Guild of America', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:47:27.140716+00:00'),
('ed6f78cf-a7c6-43a6-83b0-a82ba200edaf', 224, 'Segreti di produzione', 'La voce rimpiazzata di Tony Curtis', 'In una famosa scena del bagno tra Antonino e Crasso, la voce di Tony Curtis fu parzialmente ridoppiata in post-produzione da un attore britannico non accreditato perché il forte accento nativo di del Bronx di Curtis stonava con l''ambientazione dell''antica Roma.', 'Commento audio dell''edizione Blu-ray e home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:47:27.140716+00:00'),
('3f3ddf0b-8a1a-437d-9545-93cac3647343', 224, 'Effetti speciali & Trucco', 'La comparsa di John Dall e le scene tagliate', 'Gran parte delle sequenze di battaglia furono girate in Spagna con l''ausilio di migliaia di fanti dell''esercito spagnolo impiegati come comparse, molte delle quali furono successivamente duplicate otticamente in post-produzione per amplificare le dimensioni degli eserciti.', 'Universal Studios Production Archive', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:47:27.140716+00:00'),
('bb06367d-ccb1-4351-9466-838f7c26a9cd', 224, 'Curiosità & Retroscena', 'Il reintegro della scena del bagno', 'La celebre sequenza in cui Crasso fa avance al suo schiavo Antonino fu ritenuta troppo scandalosa nel 1960 e tagliata; fu reintegrata nel restauro del 1991, ma a causa della scomparsa del sonoro originale, Sir Laurence Olivier dovette ridoppiare le sue battute, mentre Tony Curtis, ormai anziano, fu doppiato da un imitatore.', 'Note di restauro della Robert A. Harris Collection', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:47:27.140716+00:00'),
('992ec134-913e-476f-8dae-095399a5239a', 95, 'Curiosità & Retroscena', 'Il salto produttivo dopo Milk and Serial', 'Il regista Curry Barker è stato ingaggiato per il progetto in seguito alla straordinaria risonanza del suo mediometraggio Milk & Serial, girato su YouTube con un budget di appena 800 dollari. I produttori sono rimasti impressionati dalla sua gestione della tensione e del ritmo claustrofobico, affidandogli così la sua prima produzione a pieno budget sostenuta dall''industria hollywoodiana.', 'Intervista al regista su The Hollywood Reporter', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 1, '2026-11-02T18:16:35.732675+00:00'),
('6f4133e8-19bc-4589-92b5-d2a954a612f5', 95, 'Casting & Scelte', 'L''arrivo di Cooper Koch dopo Monsters', 'Cooper Koch è stato scritturato come protagonista maschile subito dopo l''impatto mediatico ottenuto con la serie antologica Monsters di Ryan Murphy. Barker ha dichiarato di aver cercato specificamente Koch per la sua comprovata capacità di comunicare vulnerabilità e sotterranea instabilità emotiva senza mai cadere nella caricatura.', 'Note di produzione ufficiali', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 2, '2026-11-02T18:16:35.732675+00:00'),
('1297934b-cd36-4fd5-a55c-6f3a0d25e7b3', 95, 'Casting & Scelte', 'La svolta drammatica di Charithra Chandran', 'Celebre internazionalmente per aver interpretato Edwina Sharma nella serie in costume Bridgerton, Charithra Chandran ha scelto questa pellicola per segnare un netto cambio di registro artistico. L''attrice ha convinto il team di casting con una lettura su parte incentrata su dinamiche di manipolazione psicologica e tensione verbale estrema.', 'Intervista a Charithra Chandran per Variety', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 3, '2026-11-02T18:16:35.732675+00:00'),
('59dd405d-c70c-4d90-af3a-faf96e5dd205', 281, 'Citazioni & Easter Egg', 'Il tributo a Mad Dog Tannen', 'Il soprannome ''Mad Dog'' (Cane Pazzo) affibbiato al personaggio di Buford Tannen è un diretto riferimento cinematografico al personaggio interpretato da Richard Widmark nel film noir classico del 1947 ''Il bacio della morte'' (Kiss of Death), in cui l''attore sfoggiava una simile fama di criminale psicopatico e imprevedibile.', 'Analisi critico-cinematografica e commento del co-sceneggiatore Bob Gale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T14:53:53.685159+00:00'),
('22fe9ada-0fbf-4d23-b3fe-9f16288f5308', 225, 'Aneddoti dal set', 'La preparazione intensiva alle spade di Tom Cruise', 'Tom Cruise si sottopose a otto mesi di addestramento intensivo quotidiano prima di iniziare le riprese, studiando la scherma giapponese, l''equitazione e la storia dei samurai per poter eseguire personalmente la maggior parte dei duelli senza ricorrere a controfigure.', 'Documentario ''Making of The Last Samurai'' e note di produzione ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:47:30.620903+00:00'),
('96d8ae05-1050-4c0c-91cf-6e7ce196f77f', 225, 'Aneddoti dal set', 'Il quasi incidente con la spada meccanica', 'Durante una scena di combattimento, l''attore Hiroyuki Sanada stava per colpire realmente Tom Cruise a causa di un malfunzionamento del cavallo meccanico usato per le riprese in primo piano; la lama si fermò a pochi centimetri dal collo di Cruise grazie ai riflessi pronti di Sanada.', 'Intervista audio-commento del regista Edward Zwick nel DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:47:30.620903+00:00'),
('48575ba4-8527-4d6d-8ad9-e80dbb67789a', 225, 'Casting & Scelte', 'La nomination all''Oscar per Ken Watanabe', 'Ken Watanabe fu fortemente voluto dal regista Edward Zwick dopo averlo visto a teatro e nel film ''Accattone'' giapponese (The Imposter), arrivando a ottenere una candidatura agli Oscar come miglior attore non protagonista grazie alla sua intensa interpretazione di Katsumoto.', 'Registri ufficiali dell''Academy Awards e interviste promozionali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:47:30.620903+00:00'),
('088f9adb-387a-4468-852c-73c53aec7c13', 225, 'Curiosità & Retroscena', 'L''ispirazione storica reale della ribellione', 'La trama del film si ispira liberamente agli eventi storici della Ribellione di Satsuma del 1877 guidata da Saigo Takamori, considerato l''ultimo vero samurai, e unisce le figure storiche di ufficiali stranieri realmente esistiti come Jules Brunet e Frederick Townsend Ward.', 'Note storiche ufficiali e analisi storiografiche della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:47:30.620903+00:00'),
('58e7da25-57c5-4f5e-ab9e-7108088f6992', 225, 'Segreti di produzione', 'L''accuratezza dei costumi tradizionali', 'La costumista Ngila Dickson, vincitrice del premio Oscar, ha realizzato centinaia di armature autentiche e kimono lavorati a mano utilizzando tecniche artigianali giapponesi tradizionali per garantire il massimo rigore storico nell''aspetto dei guerrieri.', 'Backstage e interviste alla costumista Ngila Dickson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:47:30.620903+00:00'),
('bb2c6f26-16e5-4d28-9849-3931f2a150d3', 282, 'Citazioni & Easter Egg', 'La vera identità della lettera finale a Red', 'La lettera che Andy scrive a Red e che quest''ultimo legge alla fine del film nel prato di Zihuatanejo non fu scritta da Tim Robbins, bensì dallo stesso regista Frank Darabont, il quale curò personalmente la calligrafia per assicurarsi che corrispondesse allo stile visivo desiderato per il personaggio.', 'Commento audio del regista nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:49:02.232111+00:00'),
('35852a24-bacc-4aff-ab9f-3e243ca66048', 95, 'Segreti di produzione', 'Scelte ottiche e claustrofobia visiva', 'Per restituire sul piano visivo il senso di degenerazione del possesso mentale, Barker ha imposto l''uso di lenti con focali lunghe e inquadrature a camera fissa via via sempre più serrate sui volti dei protagonisti. L''effetto cercato dal reparto fotografia è stato quello di comprimere le distanze spaziali, soffocando progressivamente l''ambiente circostante per rispecchiare l''isolamento dei personaggi.', 'Featurette ''Inside the Mind'' inclusa nel Making-of', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 4, '2026-11-02T18:16:35.732675+00:00'),
('600a6ee4-72af-4ffb-a91a-aad7d7364374', 284, 'Casting & Scelte', 'Il rifiuto di Steve McQueen', 'Inizialmente Paul Newman e Steve McQueen avrebbero dovuto recitare insieme, con McQueen nel ruolo di Sundance. Il progetto saltò a causa di disaccordi contrattuali su quale attore dovesse avere il primo nome nei titoli di coda.', 'Biografie ufficiali e note di produzione della 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:54:14.349356+00:00'),
('2ea315c0-8e96-4794-b89c-9de417a8061d', 284, 'Casting & Scelte', 'La scelta di Robert Redford dopo Jack Lemmon', 'Prima che Robert Redford ottenesse la parte, George Roy Hill aveva preso in seria considerazione Jack Lemmon per il ruolo di Sundance Kid, un''idea che avrebbe dato al film un tono decisamente più comico.', 'Archivi storici di casting della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:54:14.349356+00:00'),
('4f3f13b7-d7be-420c-aaa6-d29ac9d719f5', 284, 'Casting & Scelte', 'Il veto della Fox su Robert Redford', 'La 20th Century Fox cercò in tutti i modi di bloccare l''ingaggio di Robert Redford perché non lo riteneva una star di prima grandezza al botteghino. Fu solo grazie alla ferma opposizione di Paul Newman, che pretese Redford al suo fianco, che l''accordo fu finalizzato.', 'Documentario ''The Making of Butch Cassidy and the Sundance Kid''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:54:14.349356+00:00'),
('f090045a-d7e3-40a3-9069-eb6e19df6062', 284, 'Casting & Scelte', 'Marlon Brando e Warren Beatty considerati', 'Nelle primissime fasi di sviluppo della sceneggiatura scritta da William Goldman, la produzione valutò anche Marlon Brando e Warren Beatty come possibile duo protagonista per interpretare i famosi fuorilegge.', 'Note d''archivio di William Goldman', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:54:14.349356+00:00'),
('a04c3db4-5eaf-493d-b743-ae3c6954bf14', 284, 'Curiosità & Retroscena', 'La vera Etta Place e il mistero storico', 'Il personaggio di Etta Place, interpretato da Katharine Ross, si basa sulla vera compagna di Sundance Kid, della quale si sa pochissimo nella realtà. La donna scomparve misteriosamente dopo la morte dei due banditi, alimentando decenni di speculazioni storiche.', 'Biografie storiche sui veri Butch Cassidy e Sundance Kid', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:54:14.349356+00:00'),
('0b2d72b8-fe05-4b8c-85d0-b271e622e9b5', 284, 'Aneddoti dal set', 'L''infortunio di Paul Newman durante le prove', 'Durante le prove preliminari delle scene d''azione, Paul Newman si ruppe una costola lottando contro uno stuntman. L''incidente costrinse la troupe a riorganizzare temporaneamente il piano di lavorazione per permettere all''attore di riprendersi.', 'Diari di produzione e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:54:14.349356+00:00'),
('05c0d0d5-37ec-44da-814e-d9821a3d9527', 284, 'Segreti di produzione', 'Il salto nel vuoto e le controfigure', 'Per la celebre sequenza in cui Butch e Sundance si buttano da un burrone nel fiume per sfuggire alla Super-posse, Paul Newman e Robert Redford furono sostituiti da stuntmen che saltarono da una piattaforma alta circa 15 metri costruita appositamente su un set in studio.', 'Commento audio del regista George Roy Hill', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:54:14.349356+00:00'),
('9cd0029d-7f07-484d-8d80-dab77edbf6c3', 284, 'Segreti di produzione', 'La bicicletta come anacronismo e gag visiva', 'L''introduzione della bicicletta nel West fu fortemente voluta da William Goldman basandosi su documenti storici reali, ma George Roy Hill la sfruttò magistralmente per creare una sequenza dal tono quasi slapstick, accompagnata dal brano ''South American Getaway''.', 'Note di sceneggiatura e analisi critica del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:54:14.349356+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('5ba9fd51-7636-4891-9573-85e9a564aa4d', 284, 'Effetti speciali & Trucco', 'L''uso innovativo della dissolvenza cromatica', 'Il direttore della fotografia Conrad L. Hall utilizzò una speciale tecnica di esposizione e filtraggio per simulare l''effetto visivo delle vecchie fotografie d''epoca, conferendo alla prima parte del film una patina seppia unica e storicamente evocativa.', 'American Cinematographer, articolo tecnico del 1969', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T14:54:14.349356+00:00'),
('5f8be19e-881d-4cd8-a3b3-41602ab3773c', 284, 'Casting & Scelte', 'Il cambio di nome del personaggio di Katharine Ross', 'Nella prima stesura della sceneggiatura, il nome della maestra e compagna dei banditi non era Etta Place, ma fu modificato dopo che William Goldman approfondì la documentazione storica sui veri fuorilegge della Banda del Mucchio Selvaggio.', 'Archivio storico della sceneggiatura originale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T14:54:14.349356+00:00'),
('5373178f-b56f-401c-8d79-602fc808b77b', 284, 'Aneddoti dal set', 'La reazione di Paul Newman alla canzone premio Oscar', 'Paul Newman fu uno dei primi a sostenere fortemente la canzone ''Raindrops Keep Fallin'' on My Head'' di Burt Bacharach e Hal David, difendendola contro il parere scettico dei dirigenti dello studio che la trovavano inadatta a un western.', 'Biografia ufficiale di Paul Newman', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 10, '2026-11-02T14:54:14.349356+00:00'),
('1f2200ac-fc2f-4595-bf20-43b6eecd8e77', 284, 'Segreti di produzione', 'I veri costumi ispirati alle foto storiche', 'La costumista Edith Head studiò attentamente le rare fotografie d''epoca conservate negli archivi storici per replicare con estrema precisione gli abiti eleganti indossati da Butch e Sundance durante il loro soggiorno in Sud America.', 'Archivi dei costumi della Paramount/Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 11, '2026-11-02T14:54:14.349356+00:00'),
('b0637e2f-43ec-441f-97d1-8775c1c19bd2', 61, 'Casting & Scelte', 'La scelta dei registi norvegesi Rønning e Sandberg', 'I registi Joachim Rønning e Espen Sandberg sono stati scelti principalmente grazie al successo internazionale del loro film candidato all''Oscar ''Kon-Tiki'' (2012), incentrato su una spedizione marittima. I produttori cercavano cineasti con un''elevata competenza tecnica nelle sequenze d''azione ambientate in alto mare.', 'Note di produzione ufficiali Disney', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:54:45.986768+00:00'),
('691f1601-7295-4b05-9e9b-e67e79f9463b', 61, 'Effetti speciali & Trucco', 'La genesi del make-up digitale per Javier Bardem', 'Per creare l''effetto dei capelli fluttuanti sott''acqua del Capitano Salazar, Javier Bardem non ha girato in una piscina ma sul set asciutto con il supporto di un rig di cavi controllati digitalmente e una specifica acconciatura bagnata, integrata poi dalla Industrial Light & Magic.', 'Featurette VFX Ufficiale ILM', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:54:45.986768+00:00'),
('c38ccb08-3c1b-4e29-b714-e15237447b29', 61, 'Citazioni & Easter Egg', 'Il cameo di Paul McCartney', 'Paul McCartney appare in un breve cameo nei panni di uno zio di Jack Sparrow detenuto in una cella, ricalcando l''operazione fatta nel terzo film con Keith Richards. Per il look, il leggendario bassista dei Beatles ha trascorso oltre due ore al giorno nel reparto trucco.', 'Intervista al reparto trucco e costumi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:54:45.986768+00:00'),
('9d313ef6-c9b6-4b5d-81c7-9b0faaf5c451', 61, 'Casting & Scelte', 'La trasformazione di Kaya Scodelario nel personaggio', 'L''attrice Kaya Scodelario ha insistito affinché il personaggio di Carina Smyth non fosse una classica damigella in pericolo, ma una pioniera dell''astronomia e della scienza, lottando attivamente contro i pregiudizi di genere dell''epoca durante lo sviluppo della sceneggiatura con Jeff Nathanson.', 'Intervista promozionale a Kaya Scodelario', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:54:45.986768+00:00'),
('cf49dea7-95a8-48e1-b6b3-0e8bb2b2042b', 61, 'Segreti di produzione', 'Le riprese in Australia e il credito d''imposta', 'La produzione si è spostata interamente nel Queensland, in Australia (principalmente a Village Roadshow Studios e nelle zone di Gold Coast), grazie a un generoso pacchetto di incentivi fiscali offerto dal governo federale australiano e locale, stimato in oltre 20 milioni di dollari.', 'Report finanziario di produzione Screen Queensland', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:54:45.986768+00:00'),
('bbc0e95c-138a-4d9d-a75c-8b236a0d9260', 285, 'Casting & Scelte', 'La scelta iniziale di Jack Lemmon', 'Prima che Paul Newman accettasse la parte, il regista George Roy Hill aveva pensato a Jack Lemmon per il ruolo di Henry Gondorff, ma l''attore declinò l''offerta, aprendo la strada alla reunion del duo di ''Butch Cassidy''.', 'Note di produzione e biografia ufficiale di George Roy Hill', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:54:18.441416+00:00'),
('aa9e8d0f-7fd9-47db-9bd0-6a502c6092c5', 285, 'Casting & Scelte', 'Il casting mancato di Richard Dreyfuss', 'Richard Dreyfuss fu seriamente preso in considerazione per il ruolo di Johnny Hooker prima che Robert Redford ottenesse la parte, ma la produzione preferì puntare sulla collaudata alchimia tra Redford e Newman.', 'Archivi di casting della Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:54:18.441416+00:00'),
('29d48540-e361-4a58-a95b-33b9f7c16614', 285, 'Citazioni & Easter Egg', 'Il cameo della madre di Robert Redford', 'Martha Redford, la madre di Robert Redford, appare brevemente in una sequenza del film come comparsa non accreditata, un piccolo omaggio voluto dall''attore sul set.', 'Commento audio del regista George Roy Hill nell''edizione DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:54:18.441416+00:00'),
('b385253a-c0a9-4c5a-8ec4-3fbd853fd818', 285, 'Aneddoti dal set', 'L''infortunio sul set di Robert Redford', 'Durante le riprese della scena in cui Johnny Hooker scappa dai sicari saltando tra i tetti, Robert Redford subì una distorsione alla caviglia, costringendo la produzione a riorganizzare temporaneamente il piano di lavorazione.', 'Diario di produzione e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:54:18.441416+00:00'),
('8c56127e-54a8-4a1d-95eb-05288322aafa', 285, 'Segreti di produzione', 'La ricostruzione di Chicago nei backlot', 'Gran parte della Chicago degli anni ''30 non fu girata in location reali, ma fu meticolosamente ricostruita nei backlot degli Universal Studios, modificando facciate di edifici già esistenti da precedenti produzioni.', 'Documentario ''The Making of The Sting'' (Universal Home Entertainment)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:54:18.441416+00:00'),
('e99fb489-c316-4bfc-9ac9-d6d8c0cb8429', 285, 'Aneddoti dal set', 'La reazione di Robert Shaw alla gamba zoppa', 'Robert Shaw recitò per gran parte del film con una vera lesione al tendine d''achille che lo costringeva a zoppicare leggermente; la produzione integrò questa limitazione fisica direttamente nei movimenti del personaggio di Doyle Lonnegan.', 'Archivio storico della produzione Universal', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:54:18.441416+00:00'),
('a8710c2b-8bb3-4c00-bb07-1c97a059ebfb', 227, 'Casting & Scelte', 'La telefonata di Robert De Niro', 'Prima che la parte di Harry Lime venisse affidata a Joe Pesci, il ruolo fu offerto a Robert De Niro, il quale declinò l''offerta, permettendo così a Pesci di entrare nel celebre duo dei Banditi Sanguinari insieme a Daniel Stern.', 'Intervista ufficiale a Chris Columbus e retroscena di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:47:36.495107+00:00'),
('348beb8c-98ab-4560-93f9-43feb080d3b0', 139, 'Casting & Scelte', 'La sostituzione last-minute di Ladybug', 'Inizialmente, il ruolo del protagonista Ladybug era stato pensato per l''attore Logan Lerman prima che la produzione virasse su Brad Pitt, il quale ha fortemente voluto ridefinire il tono del personaggio rendendolo più incline alla riflessione filosofica e alla sfortuna cronica.', 'Note di produzione ufficiali Sony Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:55:38.537631+00:00'),
('62f6ed80-7cd5-438c-980e-9beeb362ec30', 139, 'Casting & Scelte', 'Il favore tra colleghi restituito', 'La presenza di Brad Pitt in ''Bullet Train'' ha spinto l''attore a ricambiare il favore fatto da Sandra Bullock, che aveva accettato un piccolo cameo nel film di Pitt ''The Lost City''. In cambio, la Bullock ha interpretato la handler di Ladybug, Maria Beetle, sul treno.', 'Intervista stampa della promozione globale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:55:38.537631+00:00'),
('6714d941-5317-4748-aa52-488674072657', 139, 'Segreti di produzione', 'La costruzione fisica dei vagoni in studio', 'Per ricreare il treno ad alta velocità Shinkansen, la produzione non si è affidata unicamente al green screen, ma ha costruito riproduzioni fisiche dettagliate dei vagoni circondate da enormi schermi LED a 4K che proiettavano i paesaggi giapponesi in movimento.', 'Featurette ''The Art of the Heist'' nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:55:38.537631+00:00'),
('ca1af8c6-1058-4ca9-935b-590e9eaa8d19', 139, 'Citazioni & Easter Egg', 'L''omaggio a Thomas the Tank Engine', 'Il leitmotiv ricorrente dei trenini giocattolo e dei vagoni di Thomas the Tank Engine (Il Trenino Thomas), usato come metafora della personalità dei killer da Lemon e Tangerine, deriva direttamente dal romanzo originale di Kotaro Isaka, dove l''allegoria assume un valore filosofico ancora più marcato.', 'Commento audio del regista David Leitch', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:55:38.537631+00:00'),
('a67228c5-2dfe-465b-92b6-e55855776245', 139, 'Aneddoti dal set', 'L''improvvisazione con la bottiglietta d''acqua', 'Molte delle gag fisiche in cui Brad Pitt interagisce con gli oggetti di scena nei vagoni stretti – inclusa la celebre sequenza con la bottiglietta d''acqua e il computer portatile – sono state improvvisate sul momento per sfruttare i limiti spaziali del set.', 'Making-of ufficiale ''Mission in Motion''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:55:38.537631+00:00'),
('e9159639-0598-4dce-999a-bc18285a0aa9', 139, 'Curiosità & Retroscena', 'Il tributo agli stuntman storici', 'David Leitch, ex stuntman e co-regista non accreditato di ''John Wick'', ha voluto inserire nel cast diversi stunt professionisti in ruoli minori e camei dinamici, inserendo numerosi riferimenti visivi alle coreografie classiche del cinema d''azione di Hong Kong.', 'Intervista a David Leitch per Stuntman Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:55:38.537631+00:00'),
('5d902521-43cc-42d5-af42-d07e3eb84772', 293, 'Casting & Scelte', 'Il drastica perdita di peso di Joaquin Phoenix', 'Per interpretare Arthur Fleck, Joaquin Phoenix ha perso circa 23 chili sotto la supervisione di un medico. L''attore ha rivelato in varie interviste che questa drastica e rapida perdita di peso ha influenzato non solo il suo aspetto fisico scheletrico, ma anche la sua psicologia, rendendolo costantemente affamato e vulnerabile.', 'Intervista ufficiale a Joaquin Phoenix per Associated Press', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:56:33.512086+00:00'),
('e6cf5246-941e-4d69-8090-511a13527061', 293, 'Citazioni & Easter Egg', 'Il legame cinematografico con King of Comedy', 'La scelta di Robert De Niro nel ruolo del conduttore Murray Franklin è un omaggio diretto al film ''Re per una notte'' (The King of Comedy) del 1982 diretto da Martin Scorsese, in cui De Niro interpretava un aspirante comico ossessionato da un conduttore televisivo interpretato da Jerry Lewis.', 'Note di produzione ufficiali della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:56:33.512086+00:00'),
('347a7ed4-6dd1-45cf-a2db-1e30bba7935f', 293, 'Aneddoti dal set', 'La scala reale nel Bronx', 'La celebre scalinata all''aperto dove Arthur balla vestito da Joker si trova tra la West 167th Street e Shakespeare Avenue nel Bronx, a New York. Dopo l''uscita del film, la location è diventata una meta turistica di massa e un punto di riferimento virale per i fan di tutto il mondo.', 'Reportage di viaggio e cronache locali di New York Times', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:56:33.512086+00:00'),
('1ed1bb56-4d59-401e-aed4-286dc8bbe473', 293, 'Effetti speciali & Trucco', 'L''ispirazione visiva per il trucco', 'Il design del trucco da clown di Arthur Fleck è stato parzialmente ispirato da John Wayne Gacy, il famigerato serial killer statunitense noto come il ''Clown Killer'', che si esibiva alle feste per bambini vestito da ''Pogo il Clown''.', 'Dichiarazioni del reparto trucco e costumi nel materiale promozionale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:56:33.512086+00:00'),
('8966b96a-cb84-4477-8a52-5764a1c9325f', 291, 'Segreti di produzione', 'La scelta della pellicola in bianco e nero', 'Per distinguere visivamente la prospettiva soggettiva di J. Robert Oppenheimer da quella oggettiva focalizzata su Lewis Strauss, Christopher Nolan ha commissionato a Kodak lo sviluppo di una speciale pellicola in bianco e nero in formato IMAX 65mm, mai utilizzata prima nella storia del cinema.', 'Dichiarazioni ufficiali di Kodak e note di produzione di Hoyte van Hoytema', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:54:22.988015+00:00'),
('2cd56548-754d-4dd8-ae71-46d68df24996', 291, 'Effetti speciali & Trucco', 'L''assenza totale di immagini CGI nel film', 'Il supervisore degli effetti speciali Scott Fisher ha evitato completamente l''uso di computer grafica per ricreare l''esplosione del test Trinity. Gli effetti visivi sono stati ottenuti combinando esplosioni reali di propano, alluminio e magnesio, polvere nera, palloni da spiaggia illuminati e tecniche di proiezione prospettica.', 'Intervista al supervisore degli effetti speciali Scott Fisher per Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:54:22.988015+00:00'),
('7f5ed21c-fac0-4c7c-8ef1-0b8b0855b504', 291, 'Casting & Scelte', 'La preparazione fisica estrema di Cillian Murphy', 'Per incarnare l''aspetto emaciato e fragile del fisico teorico durante gli anni di Los Alamos, Cillian Murphy si è sottoposto a una dieta ferrea e rigorosa, consumando spesso solo una mandorla al giorno per diverse settimane prima e durante le riprese.', 'Intervista di Emily Blunt a The Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:54:22.988015+00:00'),
('a4259a1b-a2e5-4486-99eb-fdd0440b62a2', 291, 'Citazioni & Easter Egg', 'Il cameo dei veri figli di Christopher Nolan', 'La figlia del regista, Flora Nolan, appare in un breve cameo nel ruolo di una giovane donna sfortunata la cui faccia viene dilaniata da un lampo atomico in una visione allucinatoria di Oppenheimer. Christopher Nolan le ha chiesto di interpretare la parte poiché si trovava sul set in quel momento.', 'Intervista al regista su The Telegraph', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:54:22.988015+00:00'),
('07e89e71-baf9-443d-9182-eb702df586df', 291, 'Casting & Scelte', 'La figlia di Kenneth Branagh nel cast', 'Nel film compare anche Tilda Del Negro, figlia dell''attore Kenneth Branagh (che nel film interpreta il fisico Niels Bohr), la quale ha ottenuto una piccola parte attraverso i normali canali di provino senza godere di corsie preferenziali.', 'Note di casting ufficiali della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:54:22.988015+00:00'),
('c20e461f-6d89-4afb-97e4-f167f1b2b2a2', 291, 'Aneddoti dal set', 'Il ruolo dei veri scienziati come comparse', 'Durante le scene girate a Los Alamos e nell''auditorium dell''università, Christopher Nolan ha voluto ingaggiare veri fisici e ricercatori provenienti da università locali per interpretare le comparse tra il pubblico e i colleghi di Oppenheimer, in modo da garantire autenticità nei gesti e nelle espressioni.', 'Making-of ufficiale ''To End All War: Beyond Oppenheimer''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:54:22.988015+00:00'),
('bd86a94d-7a58-473f-857b-b7f387f40794', 291, 'Segreti di produzione', 'L''uso dei veri cappelli e della pipa del fisico', 'La costumista Ellen Mirojnick ha lavorato a stretto contatto con la famiglia Oppenheimer e gli archivi storici per replicare fedelmente i vestiti, arrivando a far riprodurre artigianalmente i modelli esatti di cappelli a tesa larga e la pipa che il vero Oppenheimer indossava e utilizzava abitualmente.', 'Intervista alla costumista Ellen Mirojnick per Vogue', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:54:22.988015+00:00'),
('17853668-704c-41e5-8b61-0ecd4b0ded49', 120, 'Citazioni & Easter Egg', 'L''ispirazione per il travestimento notturno', 'Il look furtivo di Peter Parker con la maschera nera e gli occhiali da sci, soprannominato dai fan ''Night Monkey'', è un omaggio diretto al personaggio dei fumetti Marvel ''Spider-Man Noir'' e al costume utilizzato da Ben Reilly nella saga dei clonatori.', 'Note di produzione ufficiali Marvel Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:55:18.216399+00:00'),
('de228808-2d62-449c-9a49-a6ab5bca57b6', 120, 'Casting & Scelte', 'Il rifiuto del ruolo di Mysterio', 'Prima che Jake Gyllenhaal venisse ufficialmente ingaggiato per il ruolo di Quentin Beck / Mysterio, i Marvel Studios avevano valutato altri attori di calibro internazionale, tra cui Matt Damon, che tuttavia declinò l''offerta.', 'Report di Hollywood Reporter su casting e trattative', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:55:18.216399+00:00'),
('3eb860e2-b1df-4126-9b2f-a7a10c8213b7', 120, 'Citazioni & Easter Egg', 'Il tributo a Iron Man nei titoli di coda', 'Durante la sequenza iniziale del film, la targa della macchina su cui si trovano Nick Fury e Maria Hill recita ''UGM 89'' o codici simili che richiamano la data di prima pubblicazione nei fumetti di specifiche storie, ma soprattutto il telegiornale mostra graffiti dedicati a Tony Stark identici a quelli reali apparsi nei pressi dei Marvel Studios dopo le riprese di Avengers: Endgame.', 'Commento audio del regista Jon Watts', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:55:18.216399+00:00'),
('4f1c30fc-c82b-41b8-bfc9-cd7f449d7cd1', 120, 'Segreti di produzione', 'La scelta della location di Praga', 'La sequenza del festival delle luci aPraga è stata girata in realtà in gran parte nella città vecchia di Liberec, nella Repubblica Ceca, e a Venezia, utilizzando complessi set di piazza allestiti con centinaia di comparse locali per simulare l''affollato evento europeo.', 'Diario di bordo delle riprese e scenografia ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:55:18.216399+00:00'),
('4c05f8f9-0d1b-4afc-8a46-ef0488923152', 120, 'Citazioni & Easter Egg', 'La valigia di May e la continuità con Homecoming', 'La valigia che Peter porta con sé in Europa apparteneva originariamente a suo zio Ben e recita le iniziali ''B.P.'' (Benjamin Parker), un dettaglio di continuità già intravisto nel precedente film ''Spider-Man: Homecoming''.', 'Analisi dei prop master del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:55:18.216399+00:00'),
('fa894690-7b82-483b-a447-53febaad1b58', 120, 'Aneddoti dal set', 'Il costume stealth e le difficoltà di Tom Holland', 'Tom Holland ha dichiarato in varie interviste promozionali che il costume stealth nero era estremamente scomodo e non possedeva alcuna cerniera lampo per bere acqua, costringendo la troupe a inventare un sistema con un tubicino attraverso la maschera durante le pause sul set.', 'Intervista stampa press tour di Tom Holland per Jimmy Fallon', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:55:18.216399+00:00'),
('fb52c4d8-38a8-49a8-8970-6e4a754a0038', 150, 'Segreti di produzione', 'La lingua inventata da David J. Peterson', 'Il linguista David J. Peterson, già celebre per aver creato il Dothraki e il Valyrian in Game of Thrones, è stato ingaggiato per sviluppare i dialetti parlati nel film, in particolare la lingua dei Fremen (Chakobsa), basandosi su radici arabe e altre lingue antiche menzionate nei romanzi di Frank Herbert.', 'Note di produzione ufficiali Legendary Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:55:43.261995+00:00'),
('6b8a3597-3260-4674-8cb5-afc04e4b2116', 150, 'Casting & Scelte', 'Il rifiuto originale di Timothée Chalamet', 'Prima di accettare definitivamente la parte di Paul Atreides, Timothée Chalamet ha ammesso di aver esitato brevemente a causa delle dimensioni mastodontiche del progetto, ma la chiamata diretta di Denis Villeneuve lo ha convinto immediatamente a firmare.', 'Intervista Vanity Fair US0', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:55:43.261995+00:00'),
('f10bf97a-3c11-4fda-b199-5018d03fc4a4', 150, 'Aneddoti dal set', 'Le riprese nel deserto di Wadi Rum e Abu Dhabi', 'Le sequenze ambientate sul pianeta Arrakis sono state girate principalmente tra le dune estreme del Wadi Rum in Giordania e ad Abu Dhabi, dove la troupe ha dovuto affrontare temperature che superavano regolarmente i 40 gradi Celsius, mettendo a dura prova costumi e attrezzature.', 'Featurette ufficiale ''The Desert'' - Warner Bros', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:55:43.261995+00:00'),
('09b13576-7ea1-46ad-b7f1-206f5cb6ff21', 357, 'Segreti di produzione', 'La replicazione meticolosa dell''Andrea Gail', 'Per garantire il massimo realismo visivo, la produzione ha acquistato un peschereccio gemello dell''Andrea Gail, il Lady Grace, e lo ha modificato esteticamente per renderlo indistinguibile dall''imbarcazione originale scomparsa in mare.', 'Production notes e documentario speciale Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:54:26.666082+00:00'),
('fc809509-3690-4792-b2e4-c1a62ec94fb1', 357, 'Effetti speciali & Trucco', 'L''uso dei modelli in scala per la tempesta', 'Oltre ai set con idrovore e alle riprese in vasca, la troupe degli effetti visivi guidata da Industrial Light & Magic ha impiegato complessi modelli in scala dell''Andrea Gail lunghi oltre sette metri, filmati in apposite vasche ad alta velocità per simulare l''impatto delle onde anomale.', 'Cinefex Magazine n. 83', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:54:26.666082+00:00'),
('a621fb1a-616a-4337-a238-d06d80702b1c', 357, 'Aneddoti dal set', 'Il mal di mare della troupe nei teatri di posa', 'Nonostante le riprese si svolgessero all''interno della gigantesca water tank degli studi Warner Bros. a Burbank e non in oceano aperto, il continuo e violento movimento meccanico del ginnbal che reggeva la nave provocò frequenti episodi di chinetosi (mal di mare) tra le comparse e i membri della troupe tecnica.', 'Commento audio del regista Wolfgang Petersen nel DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:54:26.666082+00:00'),
('8e3fa04d-b9f0-4666-956f-29eb4ca48f7e', 357, 'Casting & Scelte', 'La preparazione tecnica di John C. Reilly', 'Per prepararsi al ruolo del pescatore Dale ''Murph'' Murphy, l''attore John C. Reilly ha trascorso diversi giorni a Gloucester, Massachusetts, imbarcandosi su veri pescherecci commerciali per imparare le tecniche di eviscerazione del pesce e l''uso dell''attrezzatura di bordo.', 'Intervista promozionale CNN e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:54:26.666082+00:00'),
('a19c13c5-af43-4c96-8fee-f40f8a2a91d2', 357, 'Curiosità & Retroscena', 'L''esigenza di autenticità linguistica', 'Il cast ha dovuto lavorare a lungo con un voice coach specializzato per replicare fedelmente il peculiare e spigoloso accento dei pescatori di spada di Gloucester (noto come Cape Ann dialect), al fine di evitare inflessioni generiche del New England.', 'Making-of ufficiale ''The Perfect Storm: HBO First Look''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:54:26.666082+00:00'),
('5dd054af-737d-4ebd-8d24-24c3ca4b0024', 51, 'Aneddoti dal set', 'L''improvvisazione di Dave Bautista sul set di Knowhere', 'La celebre battuta in cui Drax risponde ''Io farò di meglio: perché è Gamora?'' dopo che Tony Stark chiede ''Dove è Gamora?'' e Peter Quill chiede ''Chi è Gamora?'' non era nel copione originale. Dave Bautista ha improvvisato questa battuta sul momento, lasciandola nel montaggio finale del film.', 'Commento audio del Blu-ray dei fratelli Russo', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:54:35.439339+00:00'),
('00da7280-436c-4c32-b3a4-2026fa01c749', 51, 'Casting & Scelte', 'La finta sceneggiatura per proteggere il segreto di Loki', 'Per evitare fughe di notizie sulla morte di Loki nei primi minuti del film, iMarvel ha distribuito pagine di sceneggiatura false e fittizie ad alcuni membri della troupe e persino ad attori secondari durante le prime fasi di lettura e pianificazione.', 'Intervista ufficiale di Tom Hiddleston al Jimmy Fallon Show', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:54:35.439339+00:00'),
('e54eb7c2-85cd-4e89-9cf2-ba6aa35aa682', 51, 'Effetti speciali & Trucco', 'Il costume di Thanos interamente in motion capture', 'Josh Brolin non ha indossato alcuna armatura fisica sul set per interpretare Thanos. Indossava una tuta per la motion capture con caschetto e telecamere facciali, mentre la sua imponente stazza e la sua armatura sono state interamente generate in computer grafica da Industrial Light & Magic.', 'Documentario di produzione ''The Making of Avengers: Infinity War''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:54:35.439339+00:00'),
('80cf852a-375e-40d3-93d1-5822d05c604c', 51, 'Segreti di produzione', 'L''ispirazione visiva da ''I figli degli uomini''', 'I registi Anthony e Joe Russo hanno studiato attentamente il piano sequenza e lo stile di ripresa del film ''I figli degli uomini'' (Children of Men) di Alfonso Cuarón per conferire alla sequenza d''azione di Edimburgo un maggiore senso di realismo, immersione e urgenza.', 'Intervista ai registi per American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:54:35.439339+00:00'),
('4919f502-44d6-48c9-bea5-171c5da92765', 51, 'Casting & Scelte', 'Il cameo di Peter Dinklage e il motion capture facciale', 'Per interpretare il nano fabbro Eitri, Peter Dinklage non ha indossato una protesi fisica gigante, ma ha recitato su un set appositamente scalato utilizzando avanzate tecnologie di cattura dei movimenti facciali per adattare le sue proporzioni a quelle di un gigante alto oltre tre metri.', 'Note di produzione ufficiali Marvel Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:54:35.439339+00:00'),
('25c30e8e-5de5-4223-beff-c6ae835cee98', 51, 'Curiosità & Retroscena', 'La sequenza di Titan e il copione segreto per Robert Downey Jr.', 'Robert Downey Jr. è stato l''unico attore del cast a poter leggere l''intera sceneggiatura del film prima delle riprese, grazie al suo ruolo centrale nella continuity dell''Universo Cinematografico Marvel e alla fiducia riposta dai registi nella gestione degli spoiler.', 'Intervista a Joe Russo per ScreenRant', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:54:35.439339+00:00'),
('dfd1f021-cc82-4ca8-9f67-428069ac2cb3', 265, 'Curiosità & Retroscena', 'Il maglione iconico di Chris Evans', 'Il grosso maglione color crema a trecce indossato dal personaggio di Chris Evans (Ransom Drysdale) è diventato un vero e proprio fenomeno virale sui social media dopo l''uscita del trailer, generando una marea di meme e articoli di moda dedicati.', 'Intervista ufficiale di Chris Evans per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:56:18.763824+00:00'),
('ebb85351-df64-4d19-a3bd-89a28a10a2d1', 265, 'Citazioni & Easter Egg', 'La vera maglia da baseball di Murder, She Wrote', 'In una scena del film, Marta Cabrera indossa una maglia da baseball verde che apparteneva originariamente alla produzione della celebre serie televisiva ''La signora in giallo'' (Murder, She Wrote), un chiaro omaggio ai classici gialli televisivi amati dal regista Rian Johnson.', 'Commento audio del regista Rian Johnson nell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:56:18.763824+00:00'),
('30c8fbca-cf30-4a4b-a248-e2cf8f04c758', 265, 'Segreti di produzione', 'La composizione della villa e le riprese reali', 'Gli interni della maestosa villa della famiglia Thrombey non sono stati ricostruiti in studio, ma sono stati girati quasi interamente nella vera Elm Bank Mansion, una storica tenuta situata a Wellesley, nel Massachusetts.', 'Note di produzione ufficiali della Lionsgate', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:56:18.763824+00:00'),
('2b0d307b-ba83-48a3-863f-8f086b5e73be', 265, 'Segreti di produzione', 'Il ritratto a olio di Christopher Plummer', 'Il grande dipinto a olio di Harlan Thrombey che domina la sala da pranzo del film è stato realizzato appositamente per la produzione da un artista locale ed è rimasto alla troupe come ricordo dopo la fine delle riprese.', 'Articolo di approfondimento scenografico su Architectural Digest', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:56:18.763824+00:00'),
('68e71a4d-8a2a-4e00-b4d6-b38efd0d2b08', 265, 'Aneddoti dal set', 'L''improvvisazione della tazza da caffè', 'Durante una delle intense sequenze di interrogatorio, Daniel Craig ha improvvisato una bizzarra metafora sulla ciambella e sul buco della ciambella, basata interamente sul copione ma arricchita da una gestualità unica con la sua tazza di caffè che ha spiazzato gli altri attori sul set.', 'Dietro le quinte ufficiale del film distribuito da Lionsgate', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:56:18.763824+00:00'),
('007a60b7-8bf8-4071-8da1-6808480de80b', 13, 'Effetti speciali & Trucco', 'La tecnologia di ringiovanimento facciale ILM', 'Per la sequenza d''apertura ambientata nel 1944, la Industrial Light & Magic ha utilizzato un software di intelligenza artificiale inedito che ha scandagliato tutto l''archivio di materiale girato da Harrison Ford nei film originali della saga, abbinandolo a nuove riprese con speciali telecamere.', 'Documentario ufficiale ''Making of Indiana Jones and the Dial of Destiny''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:54:30.109319+00:00'),
('c939c73f-4005-48ff-9c2e-e7bb6caa8a5d', 13, 'Casting & Scelte', 'Il cameo vocale di Karen Allen', 'Karen Allen riprende il suo ruolo di Marion Ravenwood alla fine del film, ma in origine la sceneggiatura prevedeva una presenza molto più estesa del suo personaggio prima che la trama subisse una radicale riscrittura incentrata sul lutto e sul rapporto con il figlio.', 'Note di produzione e interviste al regista James Mangold', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:54:30.109319+00:00'),
('cae51d2d-b70d-41c7-ba65-0edcac57af4d', 13, 'Segreti di produzione', 'La giacca di pelle originale del 1981', 'La celebre giacca di pelle indossata da Harrison Ford nel film è stata ricreata fedelmente dai costumisti studiando i modelli originali dei primi capitoli, ma l''attore ha insistito per mantenere una specifica vestibilità logora ereditata dai film precedenti.', 'Intervista alla costumista Joanna Johnston', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:54:30.109319+00:00'),
('a668e3c7-ae92-4018-b094-b21e9d8a7485', 13, 'Citazioni & Easter Egg', 'Il tributo a Richard Donner', 'Nella sequenza della parata a New York del 1969, sono presenti numerosi cartelli e dettagli di scenografia che omaggiano il regista Richard Donner e altri storici collaboratori della Lucasfilm scomparsi prima della produzione.', 'Commento audio del regista e scenografo Adam Stockhausen', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:54:30.109319+00:00'),
('3c60b13e-4c60-4d3e-b9eb-bab5c4298522', 13, 'Aneddoti dal set', 'L''infortunio alla spalla di Harrison Ford', 'Nel giugno 2021, durante le prove di una scena di combattimento a Pinewood Studios, Harrison Ford si è infortunato alla spalla, costringendo la produzione a riorganizzare per diverse settimane il piano di lavorazione girando prima le scene che non lo richiedevano.', 'Comunicato ufficiale della Walt Disney Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:54:30.109319+00:00'),
('f23b0091-234d-4d46-b6df-fa63c8575b2a', 77, 'Aneddoti dal set', 'La ripresa finale di Carrie Fisher', 'La toccante scena in cui Leila Organa si ricongiunge con Poe Dameron su Crait è stata l''ultima interpretazione cinematografica girata da Carrie Fisher prima della sua prematura scomparsa nel dicembre 2016.', 'Note di produzione ufficiali Lucasfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:54:53.413464+00:00'),
('974f4a28-7e34-40b5-92f5-8a041622c2da', 77, 'Citazioni & Easter Egg', 'Il cameo dei Principi William e Harry', 'I principi britannici William e Harry hanno visitato il set ai Pinewood Studios e hanno girato un cameo nei panni di due Stormtrooper di guardia all''ascensore dove si trova Finn, insieme all''attore Tom Hardy che interpretava un altro soldato del Primo Ordine.', 'Dichiarazione ufficiale del Principe William e interviste dal set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:54:53.413464+00:00'),
('d4c82909-f38c-4a2e-8d6b-9a1c81f6078a', 77, 'Citazioni & Easter Egg', 'Il tributo musicale a John Williams', 'Durante la sequenza del casinò a Canto Bight, la celebre marcia imperiale viene brevemente accennata dai musicisti alieni e persino inserita come tema di sottofondo quando BB-8 viene scambiato per una slot machine.', 'Commento audio del regista Rian Johnson nell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:54:53.413464+00:00'),
('6287d2c2-ff04-47e7-a505-5197041d0586', 77, 'Casting & Scelte', 'La scelta del titolo originale e i riferimenti storici', 'Rian Johnson ha rivelato di aver tratto ispirazione per il tono e lo stile visivo del film da classici della storia del cinema bellico come ''Cielo fuoco'' (Twelve O''Clock High) e ''Il ponte sul fiume Kwai''.', 'Intervista di Rian Johnson per Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:54:53.413464+00:00'),
('1cc5dbe7-ccde-4ad4-ad3a-763f8de0bfbd', 77, 'Citazioni & Easter Egg', 'Gary il cane di Carrie Fisher', 'Gary, il celebre bulldog francese di Carrie Fisher, appare brevemente come alieno spaziale (un space-dog di razza Critean) nella sequenza della bisca di Canto Bight, seduto accanto a un giocatore.', 'Twitter ufficiale di Rian Johnson e conferme della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:54:53.413464+00:00'),
('ce9b72a3-04ec-4971-b6d0-b6d71f4da02e', 77, 'Citazioni & Easter Egg', 'Joseph Gordon-Levitt e il pilota Slowen Lo', 'L''attore ricorrente Joseph Gordon-Levitt presta la voce a Slowen Lo, l''abitante di Canto Bight che denuncia il parcheggio illegale della navetta di Finn e Rose alla polizia locale.', 'Credits ufficiali del film e dichiarazioni del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:54:53.413464+00:00'),
('a46e57dc-6ac1-4809-bed2-4fd7e2124675', 77, 'Curiosità & Retroscena', 'L''assenza di tagli da parte dello studio', 'A differenza di molte produzioni di blockbuster contemporanei, Rian Johnson ha confermato che non esiste un ''Director''s Cut'' perché il primo montaggio mostrato alla Lucasfilm e alla Disney corrispondeva quasi esattamente alla versione finale uscita nelle sale cinematografiche.', 'Intervista stampa promozionale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:54:53.413464+00:00'),
('f0f49514-90b5-4ad6-a9b7-c2b406e9502a', 77, 'Aneddoti dal set', 'Frank Oz e il ritorno di Yoda', 'Per la sequenza in cui Yoda appare come fantasma della Forza, Frank Oz è tornato sul set non solo per doppiare il personaggio ma anche per manovrare nuovamente il celebre burattino classico, costruito appositamente replicando i calchi originali degli anni ''80.', 'Documentario ''The Director and the Jedi'' di Anthony Wonke', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:54:53.413464+00:00'),
('a6d4a7cc-47d9-4dcd-81d6-e110321bfa30', 77, 'Segreti di produzione', 'L''uso esteso dei set fisici rispetto al digitale', 'La produzione ha costruito ben 125 set distinti ai Pinewood Studios, inclusi interi interni della nave ammiraglia del Primo Ordine e la sezione principale della base di Crait, riducendo al minimo l''uso del green screen.', 'Production Designer''s notes e Making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T14:54:53.413464+00:00'),
('e40ae0d4-25f0-4bd9-991e-ed054fb4e895', 77, 'Citazioni & Easter Egg', 'Il cameo di Edgar Wright', 'Il celebre regista britannico Edgar Wright e suo fratello Oscar Wright appaiono come combattenti della Resistenza nella scena della base di Crait, accanto al regista Joe Cornish.', 'Conferma di Edgar Wright via social media', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T14:54:53.413464+00:00'),
('e48ed6c0-5e56-41d4-a30d-84f8b0a657b0', 125, 'Casting & Scelte', 'Il rifiuto iniziale di Keanu Reeves e il ritorno', 'Keanu Reeves aveva rifiutato di riprendere il ruolo di Neo dopo la conclusione della trilogia originale, ma la sceneggiatura scritta da Lana Wachowski in un momento di profondo dolore personale per la perdita dei genitori lo spinse a cambiare idea e ad accettare immediatamente.', 'Intervista ufficiale a Keanu Reeves per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:55:28.133797+00:00'),
('adf7038f-895e-463d-aab8-9867704f693b', 125, 'Casting & Scelte', 'La scelta di Jessica Henwick e il ruolo in Marvel', 'L''attrice Jessica Henwick ha dovuto scegliere se accettare il ruolo di Bugs in Matrix Resurrections o quello di Xialang in Shang-Chi e la Leggenda dei Dieci Anelli; optò per il film della Warner Bros. dopo che la produzione le concesse di fare un provino esteso.', 'Intervista a Jessica Henwick per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:55:28.133797+00:00'),
('94f2874e-db0a-4d09-b28d-d1942473b577', 52, 'Casting & Scelte', 'La regola del silenzio sulla sceneggiatura', 'Per evitare fughe di notizie, ai membri del cast non fu consegnata una sceneggiatura completa. Tom Holland ha rivelato in diverse interviste di aver ricevuto solo le proprie battute e di aver girato la sua scena drammatica del funerale credendo si trattasse di un matrimonio.', 'Intervista ufficiale a Tom Holland per Jimmy Fallon', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:54:41.051388+00:00'),
('bb066f82-4d61-46b4-b08b-32019a037ffe', 52, 'Aneddoti dal set', 'L''improvvisazione di ''Ti amo 3000''', 'La celebre battuta pronunciata da Morgan Stark, ''Ti amo 3000'', non era scritta nel copione originale dei co-sceneggiatori Christopher Markus e Stephen McFeely. L''ispirazione nacque da un commento reale che Robert Downey Jr. aveva fatto ai suoi figli nella vita di tutti i giorni.', 'Dichiarazione ufficiale degli sceneggiatori e dei fratelli Russo', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:54:41.051388+00:00'),
('49bb2d85-d1c4-4250-92f6-afc22f05de56', 52, 'Segreti di produzione', 'L''assenza di copione per il funerale', 'La complessa sequenza del funerale, che riunisce decine di grandi star del Marvel Cinematic Universe in un unico piano sequenza emotivo, è stata girata senza che gli attori avessero in mano un vero copione, definiti dalla produzione ''il giorno del matrimonio'' per mantenere il massimo riserbo.', 'Commento audio del Blu-ray dei fratelli Russo', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:54:41.051388+00:00'),
('065c291b-fea4-4904-bf15-287a16b8b8e7', 52, 'Effetti speciali & Trucco', 'Il mocap avanzato per Hulk', 'Per permettere a Mark Ruffalo di interpretare Smart Hulk fondendo perfettamente la sua espressività facciale con il corpo digitale massiccio, la produzione ha utilizzato un sistema di capture facciale montato su un caschetto con telecamera ravvicinata, migliorato notevolmente rispetto a Infinity War.', 'Making-of ufficiale ''The Making of Avengers: Endgame'' (Visual Effects document)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:54:41.051388+00:00'),
('da2e58a8-7f3d-4d32-a2ed-31874baaa7d3', 52, 'Effetti speciali & Trucco', 'Il casco pieghevole di Iron Man', 'Nelle scene in cui Robert Downey Jr. indossa l''armatura di Iron Man con il casco che si apre, l''attore non indossava quasi mai un elmetto reale in metallo o plastica rigida. La maggior parte delle volte il casco era completamente digitale o consisteva in placche laterali parziali per permettere ai visori di tracciare i movimenti senza ostruire il volto.', 'Wētā FX Production Documentaries', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:54:41.051388+00:00'),
('1f87a913-f1d3-4f09-ba39-a822593d6c05', 52, 'Citazioni & Easter Egg', 'Il tributo a George Lucas in apertura', 'La sequenza iniziale in cui Clint Barton insegna a tirare con l''arco alla figlia Lila è un esplicito omaggio alla sequenza di addestramento iniziale di Anakin Skywalker con i suoi figli o simili scene classiche di mentorato cinematografico, richiamando anche visivamente il ranch di George Lucas attraverso i campi rurali.', 'Note di regia ufficiali dei fratelli Russo', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:54:41.051388+00:00'),
('d9043e10-355d-476f-85b3-592337ac7288', 52, 'Casting & Scelte', 'Katherine Langford tagliata dal montaggio finale', 'L''attrice Katherine Langford, celebre per ''13 Reasons Why'', era stata ingaggiata per interpretare la versione adulta di Morgan Stark nella dimensione spirituale della Pietra dell''Anima (speculare alla scena di Thanos con la piccola Gamora). La sequenza fu tagliata perché i test screening dimostrarono che confondeva il pubblico emotivamente.', 'Intervista ai fratelli Russo nel podcast ''Happy Sad Confused''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:54:41.051388+00:00'),
('d68001f2-a8ff-46ba-82f3-27332fdd9571', 52, 'Aneddoti dal set', 'Il peso dell''armatura di Thanos', 'Josh Brolin, per interpretare fisicamente Thanos nelle scene sul set con gli altri attori, indossava una speciale tuta per il motion capture dotata di pesi strategici per simulare la massa imponente del Titano Pazzo, aiutando il resto del cast a mantenere la corretta linea dello sguardo durante i combattimenti.', 'Speciali backstage Marvel Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:54:41.051388+00:00'),
('63c46d39-8700-4656-966d-6cc1f5b6faa6', 102, 'Effetti speciali & Trucco', 'La trasformazione vocale estrema di Bill Skarsgård', 'Per interpretare il Conte Orlok, Bill Skarsgård ha lavorato per mesi con un coach vocale per abbassare drasticamente il suo tono di voce, spingendolo verso un registro viscerale e animalesco che ricordava il rumore del vento tra le rovine, riducendo quasi al minimo i dialoghi tradizionali.', 'Intervista ufficiale di Bill Skarsgård per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:55:05.693635+00:00'),
('7b66239a-7b69-4f9d-a190-4f29711597f6', 102, 'Aneddoti dal set', 'La preparazione e l''isolamento di Lily-Rose Depp', 'Per rendere al meglio il tormento psicologico ed emotivo del suo personaggio Ellen Hutter, Lily-Rose Depp ha trascorso lunghe ore isolata sul set e si è sottoposta a sessioni di prove fisiche estenuanti per simulare stati di trance e possessione autentici.', 'Note di produzione e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:55:05.693635+00:00'),
('e5dda6eb-390b-4b75-92e4-b631217f44f7', 102, 'Segreti di produzione', 'L''uso rigoroso della luce naturale e delle candele', 'Il direttore della fotografia Jarin Blaschke ha continuato la sua ricerca sull''illuminazione d''epoca già vista in ''The Lighthouse'', utilizzando in molte scene notturne ed interne esclusivamente vere candele e lampade a petrolio modificate per ottenere un''atmosfera pittorica autentica dell''Ottocento.', 'Reportage tecnico di American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:55:05.693635+00:00'),
('5b542e12-690e-4787-a1f9-8e48629b06cb', 102, 'Casting & Scelte', 'Il ritorno di Willem Dafoe nei territori di Max Schreck', 'La scelta di Willem Dafoe per il ruolo del Professor Albin Eberhart Von Franz chiude un cerchio metacinematografico perfetto, dato che l''attore aveva già interpretato Max Schreck (l''attore originale di Nosferatu) nel film candidato all''Oscar ''L''ombra del vampiro'' (2000).', 'Annuncio ufficiale del casting di Focus Features', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:55:05.693635+00:00'),
('9a1a6ffc-07e7-4379-9355-0d0bfa062456', 102, 'Effetti speciali & Trucco', 'La costruzione fisica del Conte Orlok senza eccessiva CGI', 'Il leggendario truccatore premio Oscar David Malinowski ha impiegato oltre sei ore al giorno per applicare le protesi complesse su Bill Skarsgård, puntando su un look scheletrico e repellente ispirato ai ratti e ai cadaveri mummificati, riducendo al minimo l''uso della computer grafica.', 'Intervista al reparto trucco e prosthetics', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:55:05.693635+00:00'),
('c661bc07-1d3f-428d-b16c-0ca28e9772c0', 102, 'Curiosità & Retroscena', 'Le riprese nei Carpazi e l''influenza del gotico mitteleuropeo', 'Per garantire il massimo realismo geografico e architettonico, la produzione ha girato gran parte degli esterni in location storiche tra la Romania e la Repubblica Ceca, sfruttando castelli medievali reali e foreste incontaminate per ricreare la Transilvania del XIX secolo.', 'Note di produzione ufficiali Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:55:05.693635+00:00'),
('155bc411-c44e-4362-9298-3488669aee7a', 292, 'Casting & Scelte', 'La genesi del Hitler immaginario', 'Taika Waititi ha deciso di interpretare personalmente Adolf Hitler perché nessun altro attore voleva la parte e perché temeva che un nome di primo piano avrebbe distratto il pubblico. Ha basato la sua interpretazione stravagante e infantile sulla percezione distorta che un bambino di dieci anni avrebbe del dittatore, unendo i tratti di un padre padrone a quelli di un amico immaginario.', 'Note di produzione ufficiali di Searchlight Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:56:29.12047+00:00'),
('7ae7f6f1-fd6d-4187-adb4-aca0ac00e416', 61, 'Effetti speciali & Trucco', 'La statua di bronzo e la CGI per gli squali fantasma', 'Gli spettrali squali zombie guidati da Salazar sono stati realizzati interamente in computer grafica dalla ILM, partendo però da modelli fisici dettagliati e studi anatomici reali per simulare il movimento erratico e decomposto dei predatori marini.', 'Diario di produzione e intervista ai supervisori VFX', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:54:45.986768+00:00'),
('80cdbc93-4821-4e1e-a906-b702384602b6', 61, 'Casting & Scelte', 'Il ritorno di Martin Klebba nei panni di Marty', 'L''attore affetto da nanismo Martin Klebba è tornato a interpretare il pirata Marty, uno dei membri storici della ciurma della Perla Nera fin dal primo capitolo del 2003, confermando la sua presenza in tutti i capitoli della saga cinematografica (tranne il quarto).', 'Credits ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:54:45.986768+00:00'),
('4c433b58-3b41-4c27-96f3-b778092e57d4', 61, 'Segreti di produzione', 'L''uso estensivo dei set fisici a Helensvale', 'Oltre agli effetti digitali, la troupe ha costruito imponenti set pratici all''aperto nei backlot di Helensvale, tra cui una ricostruzione dettagliata di un intero porto caraibico e le strade della cittadina di Saint Martin.', 'Articolo di architettura di produzione su American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:54:45.986768+00:00'),
('3a391416-56d3-46bf-802e-a392998dc07c', 78, 'Segreti di produzione', 'L''uso del materiale d''archivio di Carrie Fisher', 'Per includere la defunta Carrie Fisher nel ruolo di Leia Organa, J.J. Abrams e il montatore Maryann Brandon hanno riutilizzato scene tagliate dai film precedenti (''Il risveglio della Forza'' e ''Gli ultimi Jedi''), adattando la sceneggiatura attorno a quei frammenti visivi.', 'Documentario ''The Skywalker Legacy'' e note di produzione Lucasfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:54:57.759642+00:00'),
('47b95890-a472-4aa8-b93e-d7b3fc8d3ecf', 78, 'Aneddoti dal set', 'La sceneggiatura smarrita in un hotel', 'Una copia della sceneggiatura del film è stata accidentalmente dimenticata da un attore (in seguito rivelatosi John Boyega) sotto il letto di una stanza d''albergo ed è stata messa in vendita su eBay, costringendo i produttori a intervenire tempestivamente per recuperarla prima della fuga di notizie.', 'Dichiarazione ufficiale di J.J. Abrams al programma televisivo ''Good Morning America''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:54:57.759642+00:00'),
('45254e6d-e1df-46f7-863d-818287c573e6', 78, 'Citazioni & Easter Egg', 'Il cameo vocale dei fan e dei registi', 'Molti membri della troupe e registi ospiti hanno registrato brevi battute vocali per la scena in cui la flotta dei cittadini arriva su Exegol. Tra questi figurano il regista J.J. Abrams che doppia la voce di un soldato e il co-sceneggiatore Chris Terrio.', 'Commento audio del regista e crediti del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:54:57.759642+00:00'),
('31390d6b-4cef-4628-aa08-353e023ea2a5', 78, 'Casting & Scelte', 'La frustrazione di Oscar Isaac per il rapporto tra Poe e Finn', 'L''attore Oscar Isaac ha espresso pubblicamente il proprio rammarico per il fatto che la Disney non abbia reso canonico il legame romantico tra i personaggi di Poe Dameron e Finn, ritenendo che la major sia stata frenata da timori commerciali nei mercati esteri.', 'Intervista di Oscar Isaac alla rivista IGN', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:54:57.759642+00:00'),
('bd5e8e16-7424-41df-a2cb-0862cf6f1d9d', 78, 'Citazioni & Easter Egg', 'Il ritorno di John Williams nel cameo musicale', 'Il leggendario compositore John Williams, autore della colonna sonora di tutta la saga, fa un breve cameo visivo nel film nei panni di un barista di nome Oma Tres sul pianeta Kijimi, riconoscibile dal costume e dall''aspetto.', 'Making-of ufficiale ''The Skywalker Legacy''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:54:57.759642+00:00'),
('49be9f5c-3a30-4b55-ac2e-8e7618d1dc95', 78, 'Aneddoti dal set', 'La difficoltà con i caschi dei Sith Trooper', 'Gli attori che interpretavano i Sith Trooper di colore rosso cremisi hanno riscontrato enormi problemi di visibilità sul set a causa della forte opacità delle lenti dei caschi, causando frequenti scontri accidentali durante le riprese delle scene d''azione.', 'Intervista ai costumisti nel libro d''arte ufficiale ''The Art of Star Wars: The Rise of Skywalker''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:54:57.759642+00:00'),
('3a6fcc79-1a3c-4c31-90dd-d1fa68a48ef3', 104, 'Curiosità & Retroscena', 'La cancellazione e il salvataggio temporaneo', 'Nel novembre 2023, la Warner Bros. Discovery annunciò la cancellazione totale del film per ottenere un beneficio fiscale, scatenando una protesta senza precedenti da parte di registi e addetti ai lavori che costrinse lo studio a fare marcia indietro e permettere ai produttori di cercare un nuovo acquirente.', 'Comunicati ufficiali di Deadline e Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:55:08.693636+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('deda5d33-36a2-464e-becd-b5b29e169c35', 104, 'Segreti di produzione', 'Il mix unico di live-action e animazione', 'Il film segue la tradizione di capolavori come ''Chi ha incastrato Roger Rabbit'' e ''Space Jam'', fondendo attori in carne ed ossa con personaggi in animazione digitale tridimensionale integrati nei set reali.', 'Note di produzione della Warner Animation Group', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:55:08.693636+00:00'),
('afc61700-afdc-4814-a48b-5eabaac65572', 104, 'Casting & Scelte', 'Il coinvolgimento di Eric Bauza per le voci classiche', 'Il celebre doppiatore Eric Bauza è stato ingaggiato per prestare la voce a Wile E. Coyote e ad altri iconici personaggi dei Looney Tunes, garantendo la continuità sonora con la storica tradizione della Warner Bros.', 'Crediti di produzione preliminari e database di doppiaggio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:55:08.693636+00:00'),
('7b326b43-f4bc-463e-bee3-97d4c75689d5', 133, 'Casting & Scelte', 'Il rifiuto originale di Tom Cruise', 'Quentin Tarantino aveva inizialmente incontrato Tom Cruise per valutare la sua partecipazione al film, nello specifico per il ruolo di Cliff Booth poi andato a Brad Pitt. Sebbene l''incontro sia stato positivo, l''accordo non si concretizzò a causa di conflitti di programmazione.', 'Dichiarazioni di Quentin Tarantino in interviste promozionali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:55:33.661695+00:00'),
('0df65b76-7c08-4869-a96c-5297b35b5f6f', 133, 'Casting & Scelte', 'La scelta iniziale per Charles Manson', 'Prima che Damon Herriman venisse scelto per interpretare il famigerato leader della setta Charles Manson, la produzione aveva considerato altri interpreti e valutato diverse opzioni di casting durante le prime fasi di sviluppo della sceneggiatura.', 'Note di casting e report di pre-produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:55:33.661695+00:00'),
('6762ea13-af7f-40d6-b893-2d087a28e757', 133, 'Casting & Scelte', 'L''inclusione di Julia Butters su segnalazione dei casting director', 'La giovane attrice Julia Butters, che interpreta la prodigiosa Trudi Fraser, è stata fortemente voluta dopo che i direttori del casting l''avevano notata nella serie televisiva ''American Housewife'', colpendo immediatamente Quentin Tarantino per la sua professionalità.', 'Intervista ufficiale a Julia Butters e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:55:33.661695+00:00'),
('e8d5017c-2388-4dca-a342-7bef03202b35', 133, 'Aneddoti dal set', 'Il prestito dei gioielli originali di Sharon Tate', 'Debra Tate, sorella di Sharon Tate, ha concesso alla produzione il permesso di far indossare a Margot Robbie alcuni gioielli autentici appartenuti a Sharon, tra cui un anello e un orologio, per garantire la massima accuratezza storica e un tributo emotivo.', 'Interviste a Debra Tate e alla costumista Arianne Phillips', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:55:33.661695+00:00'),
('8659d9d1-fcfe-485d-b121-1fbd69e463b5', 90, 'Segreti di produzione', 'La ricostruzione del tunnel sotterraneo', 'Per girare il climax della resa dei conti finale, la produzione ha impiegato settimane per costruire un complesso sistema di tunnel sotterranei sotto il ranch, progettato appositamente per permettere a Stallone di eseguire personalmente molte delle sequenze d''azione in spazi ristretti.', 'Production Notes ufficiali Lionsgate', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:55:01.609629+00:00'),
('342062ae-f6b7-4dd5-b9ae-894eb3ff53ff', 90, 'Curiosità & Retroscena', 'L''ispirazione visiva da Unforgiven', 'Sylvester Stallone ha dichiarato in diverse interviste che la struttura narrativa e l''atmosfera crepuscolare del film sono state fortemente influenzate da ''Gli spietati'' (Unforgiven) di Clint Eastwood, focalizzandosi su un eroe anziano e segnato dal passato costretto a imbracciare le armi un''ultima volta.', 'Intervista stampa ufficiale di Sylvester Stallone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:55:01.609629+00:00'),
('898e594b-6ef9-4e47-b8ae-4f7003fe1c10', 90, 'Aneddoti dal set', 'L''infortunio alla schiena di Sylvester Stallone', 'Durante le riprese delle scene di lotta corpo a corpo, Sylvester Stallone ha subito un serio infortunio alla schiena che ha richiesto un intervento chirurgico correttivo, un evento che lo ha costretto a modificare parte del calendario di produzione e che ricorda i numerosi infortuni subiti nei capitoli precedenti della saga.', 'Dichiarazione ufficiale dell''attore e report di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:55:01.609629+00:00'),
('7f0b6752-23f7-4ed8-9668-018e13ceac8d', 90, 'Segreti di produzione', 'La scelta delle location tra Bulgaria e Spagna', 'Sebbene la storia sia ambientata tra l''Arizona e il Messico, gran parte delle riprese esterne e delle sequenze desertiche sono state girate in location spagnole (tra cui Tenerife e la Bulgaria per gli interni in studio) per replicare fedelmente le ambientazioni calde e polverose richieste dal copione.', 'Making-of e bollettini di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:55:01.609629+00:00'),
('73ccfdb9-545c-47db-8409-32383ee22c1d', 119, 'Aneddoti dal set', 'L''infiltrazione segreta in un liceo del Queens', 'Per prepararsi al ruolo e studiare i manierismi dei veri adolescenti americani, Tom Holland si è infiltrato in incognito alla Bronx High School of Science fingendosi uno studente britannico, arrivando persino a usare un falso nome e un accento modificato.', 'Intervista ufficiale a Tom Holland al Jimmy Kimmel Live', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:55:13.73181+00:00'),
('fc3ece34-6c17-439b-b06e-0a7e61b0f0d7', 119, 'Casting & Scelte', 'La reazione di Michael Keaton all''offerta per l''Avvoltoio', 'Prima che Michael Keaton firmasse per il ruolo di Adrian Tooms/Avvoltoio, i Marvel Studios avevano quasi chiuso con un altro attore; tuttavia, quando Keaton fu liberato dai suoi impegni con altri progetti, la produzione bloccò tutto per riavviare immediatamente le trattative con lui.', 'Note di produzione ufficiali Marvel Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:55:13.73181+00:00'),
('1ad2ccad-a0d0-47bd-8d2c-577ba5f07cc3', 119, 'Casting & Scelte', 'Il provino sul tapis roulant di Tom Holland', 'Durante le audizioni finali, i registi e i produttori hanno fatto eseguire a Tom Holland complesse acrobazie e sequenze di movimento mentre correva su un tapis roulant di fronte a uno schermo verde, per valutare la sua resistenza fisica e la sua espressività sotto sforzo.', 'Featurette ''The Casting of Peter Parker'' nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:55:13.73181+00:00'),
('0ade72ce-578a-448f-855d-ef591b80705b', 119, 'Citazioni & Easter Egg', 'Il tributo a Ferris Bueller nella sequenza della corsa', 'La scena in cui Peter Parker insegue i criminali tagliando attraverso i cortili e le piscine dei giardini suburbani è un omaggio diretto e dichiarato alla celebre sequenza di corsa di ''Una pazza giornata di vacanza'' (Ferris Bueller''s Day Off).', 'Commento audio del regista Jon Watts', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:55:13.73181+00:00'),
('167deadd-bf03-45d5-94e0-88045abc92d9', 119, 'Segreti di produzione', 'L''ispirazione per il costume fai-da-te di Peter', 'Il costume rudimentale che Peter indossa prima di ricevere l''equipaggiamento avanzato da Tony Stark è stato modellato sartorialmente ispirandosi direttamente al design originale della tuta da wrestler apparsa in ''Amazing Fantasy #15'' del 1962.', 'Art of the Movie - Book by Marvel Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:55:13.73181+00:00'),
('0c5f3b5c-962f-4645-b3f1-04305e5a60cc', 119, 'Casting & Scelte', 'La vera identità del nerd dell''Academic Decathlon', 'Abraham Brown, uno dei membri della squadra del liceo di Peter, è interpretato da Abraham Attah, il giovane attore ghanese protagonista del pluripremiato film Netflix ''Beasts of No Nation''.', 'Credits ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:55:13.73181+00:00'),
('ce8b0f5b-a3c1-471e-9403-8d3d1b3985aa', 119, 'Effetti speciali & Trucco', 'Il problema di visibilità dell''elmetto dell''Avvoltoio', 'Il grande casco meccanico indossato da Michael Keaton creava enormi problemi di riflessi per le telecamere e le luci di scena sul set; gran parte dei riflessi metallici e dei dettagli luminosi dell''elmetto sono stati interamente ricostruiti in post-produzione in CGI.', 'Report tecnico di Industrial Light & Magic (ILM)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:55:13.73181+00:00'),
('1e638f47-e245-4cef-bde3-647973870f2b', 119, 'Curiosità & Retroscena', 'L''omaggio a Donald Glover e la connessione con Miles Morales', 'Donald Glover interpreta il criminale Aaron Davis, e in una scena fa esplicito riferimento a suo nipote; questo è un easter egg e un cenno diretto a Miles Morales, il celebre successore di Peter Parker nei fumetti Ultimate, la cui esistenza viene così implicitamente confermata nel Marvel Cinematic Universe.', 'Dichiarazione ufficiale del produttore Kevin Feige', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:55:13.73181+00:00'),
('98795353-b5e9-44b8-90d5-596d40c87b5a', 240, 'Aneddoti dal set', 'La separazione forzata tra i cast sul set', 'Il regista Andy Muschietti ha tenuto deliberatamente Bill Skarsgård (Pennywise) isolato dal resto del giovane cast di attori per gran parte delle riprese. In questo modo, quando i ragazzi lo hanno incontrato per la prima volta sul set durante la scena del proiettore, le loro reazioni di terrore e shock sono state assolutamente autentiche.', 'Intervista ufficiale del cast e note di produzione Warner Bros', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:56:14.633072+00:00'),
('7dd31d04-ad87-495b-af0b-2995bd3cd9dd', 240, 'Effetti speciali & Trucco', 'L''occhio pigro naturale di Bill Skarsgård', 'Il caratteristico sguardo strabico di Pennywise, in cui un occhio guarda in una direzione diversa dall''altro, non è stato ottenuto tramite CGI o lenti a contatto speciali. Bill Skarsgård possiede la capacità anatomica di disallineare volontariamente gli occhi a piacimento.', 'Intervista a Bill Skarsgård per Conan O''Brien', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:56:14.633072+00:00'),
('c754c09c-9a7e-44dc-8158-40b544f15a01', 240, 'Casting & Scelte', 'La sostituzione di Will Poulter e la versione di Cary Fukunaga', 'Inizialmente il progetto era guidato dal regista Cary Fukunaga, che aveva scelto Will Poulter per il ruolo di Pennywise. Quando Fukunaga ha abbandonato il film per differenze creative, Poulter ha dovuto rinunciare alla parte a causa di conflitti di programmazione con altri impegni, aprendo la strada all''ingaggio di Bill Skarsgård.', 'The Hollywood Reporter / Dichiarazioni ufficiali di Will Poulter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:56:14.633072+00:00'),
('1381974c-fd9e-4efc-99d3-e1bbdf59bd00', 227, 'Casting & Scelte', 'Il provino decisivo di Macaulay Culkin', 'Il regista Chris Columbus visionò centinaia di bambini prima di incontrare Macaulay Culkin, scelto dopo che il regista era rimasto colpito dalla sua interpretazione nel film ''Il falò delle vanità'' (1990). John Hughes aveva già caldeggiato il suo nome fin dalle prime fasi di scrittura.', 'Commento audio del regista Chris Columbus nell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:47:36.495107+00:00'),
('b6fd7a1c-7c09-4e08-b788-8a8e318f0a51', 121, 'Casting & Scelte', 'La finta sceneggiatura per proteggere il segreto di Andrew Garfield', 'Andrew Garfield ha dovuto mentire sistematicamente alla stampa per mesi, negando ripetutamente la sua presenza nel film e arrivando a definire ''un fotoritocco'' l''immagine trapelata dal set insieme a Tobey Maguire. L''attore ha ammesso che la situazione è diventata persino divertente, paragonandola a un gigantesco gioco di Werewolf giocato con i fan di tutto il mondo.', 'Intervista ufficiale a Jimmy Fallon / The Tonight Show', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:55:24.162731+00:00'),
('d6d0f450-0cb3-46c1-a113-6e4fad074d8e', 121, 'Segreti di produzione', 'Il costume di Tom Holland modificato per le necessità urti', 'Durante la produzione, i costumisti hanno dovuto aggiungere una cerniera nascosta nella maschera del costume di Tom Holland per permettergli di bere acqua attraverso un tubicino tra un ciak e l''altro, visto che il nuovo design aderente rendeva impossibile rimuovere rapidamente il casco senza l''ausilio di un team specializzato.', 'Note di produzione ufficiali Sony Pictures / Featurette Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:55:24.162731+00:00'),
('fead4627-378b-43ef-b659-4dffa14c5316', 121, 'Aneddoti dal set', 'L''improvvisazione della battuta iconica sul mal di schiena', 'Il momento in cui Tobey Maguire si massaggia la schiena lamentandosi di dolori articolari prima della battaglia finale sul tetto del liceo è un riferimento autoreferenziale ideato sul set per sdrammatizzare i suoi reali infortuni alla schiena subiti durante le riprese della trilogia originale di Sam Raimi e del film ''Seabiscuit''.', 'Commento audio del regista Jon Watts / Edizione Home Video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:55:24.162731+00:00'),
('02929301-792a-4038-8881-8c78762079b2', 121, 'Casting & Scelte', 'Il ritorno di Thomas Haden Church e Rhys Ifans senza nuove riprese sul set', 'Per la partecipazione dei villain Sandman (Thomas Haden Church) e Lizard (Rhys Ifans), la produzione ha utilizzato in gran parte materiale d''archivio audio e video dai rispettivi film originali per le loro sequenze umane, mentre i due attori sono stati richiamati principalmente per registrare nuove linee di dialogo vocale e fornire motion capture per le loro forme mutate.', 'Articolo di approfondimento tecnico su The Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:55:24.162731+00:00'),
('f99fe1a5-52a9-4ba1-a3a5-e3099572009e', 121, 'Citazioni & Easter Egg', 'Il tributo nascosto a Stan Lee nella targa del taxi', 'La targa del taxi giallo guidato dal personaggio interpretato da Darnell Appling (assistente storico di Jon Favreau) durante la scena sul ponte di Brooklyn recita ''063-FLS'', un chiaro omaggio alla data di nascita di Stan Lee, nato il 28 dicembre 1922, combinata con le sue iniziali.', 'Analisi ufficiale degli Easter Egg di Marvel.com', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:55:24.162731+00:00'),
('58d6e9d3-8004-4aaf-b02d-a2c0b7e8fa80', 121, 'Casting & Scelte', 'Il divieto di comunicare tra i tre Peter Parker prima delle riprese', 'Per evitare fughe di notizie, Sony e Marvel hanno imposto a Tom Holland, Andrew Garfield e Tobey Maguire di non rivelare a nessuno, nemmeno ai rispettivi familiari, la loro compresenza sul set. I tre attori hanno tenuto le loro prime prove generali in assoluta segretezza in una stanza blindata degli studios di Atlanta.', 'Intervista di gruppo per Variety ''Actors on Actors''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:55:24.162731+00:00'),
('3d5f0f8f-a18c-4cb2-8e82-dc46a42a9f02', 121, 'Effetti speciali & Trucco', 'L''uso della tecnologia The Volume per la sequenza della scuola', 'Sebbene gran parte del film utilizzi il green screen tradizionale, la produzione ha sfruttato schermi LED avanzati ispirati alla tecnologia di ''The Mandalorian'' per alcune sequenze di transizione in esterni, permettendo agli attori di recitare con riflessi di luce realistici sui volti anziché su sfondi interamente digitali.', 'Documentario ''The Making of Spider-Man: No Way Home'' su Disney+', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:55:24.162731+00:00'),
('e922a2b0-f62f-42b6-afa4-fb1eda4dd881', 156, 'Casting & Scelte', 'Keanu Reeves e la modifica di Duke Caboom', 'Keanu Reeves ha chiesto personalmente di modificare alcuni aspetti del suo personaggio, Duke Caboom, aggiungendo pose eroiche e battute improvvisate registrate durante le sessioni di doppiaggio in studio.', 'Commento audio del regista Josh Cooley nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:55:47.602879+00:00'),
('e325107f-5450-49f4-91f3-8d63b3d4b48f', 156, 'Curiosità & Retroscena', 'Il ritorno di Bo Peep e la ridefinizione del personaggio', 'Bo Peep è stata completamente ridisegnata rispetto ai primi due film, rimuovendo il classico abito ingombrante per dotarla di un mantello che funge da gonna e di braccia articolate, riflettendo la sua nuova natura di giocattolo ''perduto''.', 'Documentario ''Making of Toy Story 4'' - Pixar Animation Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:55:47.602879+00:00'),
('ad65870e-ea7a-4df6-ac29-b8397c4f242e', 156, 'Citazioni & Easter Egg', 'Il cameo dei nipoti di Tom Hanks', 'I nipoti di Tom Hanks, di nome Colin e Truman, hanno prestato le loro voci per i piccoli ruoli di due dei bambini che giocano nel parco giochi all''inizio del film.', 'Note di produzione ufficiali Disney/Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:55:47.602879+00:00'),
('e21b968a-b7ef-4965-9fc9-bf8428215aab', 156, 'Segreti di produzione', 'La riproduzione realistica dei riflessi sul metallo di Forky', 'Per rendere credibile il corpo di Forky realizzato con un vero cucchiaio-forchetta di plastica usa e getta, i tecnici Pixar hanno sviluppato un nuovo shader per simulare lo scattering della luce attraverso la plastica traslucida.', 'Technical Paper SIGGRAPH 2019', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:55:47.602879+00:00'),
('dda7f80b-7a76-430f-9e62-c4490234e93b', 156, 'Aneddoti dal set', 'La cabina di registrazione condivisa tra Tom Hanks e Tim Allen', 'Anche se gli attori di animazione registrano solitamente da soli, Tom Hanks e Tim Allen hanno insistito per registrare insieme alcune delle loro scene di dialogo cruciali per catturare la chimica naturale tra Woody e Buzz.', 'Intervista promozionale per The Ellen DeGeneres Show', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:55:47.602879+00:00'),
('9ff1f80b-38f8-4020-943c-73971286da43', 156, 'Citazioni & Easter Egg', 'I riferimenti nascosti nel negozio di antiquariato', 'Nel negozio di antiquariato ''Seconda Occasione'' compaiono decine di oggetti tratti da precedenti film Pixar, inclusi il grammofono di Geri''s Game e la caffettiera di Luxo Jr.', 'Easter Egg ufficiali Pixar rilasciati per l''uscita home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:55:47.602879+00:00'),
('f8053c6f-2c6f-4aa5-9250-e871a9cf7bda', 206, 'Segreti di produzione', 'La scelta di Berlino e il Monumento a Corbusier', 'Per ricreare l''architettura brutalista di Capitol City e l''interno della famigerata Accademia, la produzione ha sfruttato il complesso espositivo Messe Berlin e la celebre Unité d''Habitation di Berlino progettata da Le Corbusier, fondendo cemento armato reale e CGI.', 'Note di produzione ufficiali Lionsgate e intervista allo scenografo Uli Hanisch', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:55:59.672885+00:00'),
('b6010cd8-cf19-431b-80ad-28d777942930', 206, 'Aneddoti dal set', 'La veridicità dei serpenti sul set', 'Durante le riprese della famigerata scena dei Decimi Hunger Games nell''arena, la produzione ha utilizzato una combinazione di veri serpenti (dei boa constrictor addestrati) e serpenti CGI, con Tom Blyth e Rachel Zegler che hanno dovuto recitare a stretto contatto con i rettili vivi.', 'Featurette ''I serpenti dell''arena'' nel contenuto extra del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:55:59.672885+00:00'),
('6adda87e-0364-4252-9d30-a2b583888689', 206, 'Citazioni & Easter Egg', 'Il tributo vocale a Donald Sutherland', 'Tom Blyth ha studiato minuziosamente la performance vocale e la postura di Donald Sutherland nel primo ''Hunger Games'' per incorporare piccoli tic e inflessioni verbali del Presidente Snow adulto nel suo giovane Coriolanus.', 'Intervista di Tom Blyth per Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:55:59.672885+00:00'),
('cefeb8d1-68c2-4fd8-a2a9-0381fc9b644f', 125, 'Casting & Scelte', 'L''assenza di Laurence Fishburne e Hugo Weaving', 'Laurence Fishburne non è stato nemmeno interpellato per riprendere il ruolo di Morpheus, poiché Lana Wachowski aveva deciso di esplorare una linea temporale e una versione differente del personaggio, affidato poi a Yahya Abdul-Mateen II. Hugo Weaving, invece, fu contattato per tornare nei panni di Smith, ma dovette rinunciare a causa di conflitti di programmazione con uno spettacolo teatrale a Londra.', 'Dichiarazioni ufficiali di Laurence Fishburne e Hugo Weaving a Collider e Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:55:28.133797+00:00'),
('4ee4c6e0-f3c1-407b-8684-938c7dc9ccd9', 125, 'Aneddoti dal set', 'Il training intensivo per le sequenze d''azione', 'Keanu Reeves e Carrie-Anne Moss hanno dovuto sottoporsi a mesi di addestramento fisico rigoroso prima delle riprese, lavorando con il leggendario stunt coordinator Chad Stahelski e il suo team 87Eleven per ritrovare la stessa sincronia acrobatica vista nei capitoli precedenti.', 'Featurette ufficiale ''Matrix Resurrections: Becoming Neo''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:55:28.133797+00:00'),
('465636aa-2286-4014-bd72-20bbd60fff7d', 125, 'Segreti di produzione', 'L''addio ai filtri verdi storici', 'A differenza dei film precedenti caratterizzati da una forte dominante cromatica verde per indicare l''ambiente virtuale, Lana Wachowski e il direttore della fotografia John Toll hanno optato per una palette di colori molto più calda, naturale e cinematografica, allontanandosi dall''estetica originale dei primi anni duemila.', 'Note di produzione e intervista al direttore della fotografia John Toll', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:55:28.133797+00:00'),
('2aa6c8e2-b97e-4b46-9977-415f5ef1e481', 125, 'Citazioni & Easter Egg', 'Il vero caffè di Thomas Anderson', 'Nel segmento in cui Thomas Anderson lavora come sviluppatore di videogiochi, la caffetteria in cui si reca regolarmente si chiama ''Simulatte'', un chiaro riferimento filosofico al concetto di simulacro trattato nel testo di Jean Baudrillard ''Simulacres et Simulation'', pilastro teorico dell''intero franchise.', 'Analisi visiva e script ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:55:28.133797+00:00'),
('82960610-c0b2-46e9-b870-a97cd5594142', 174, 'Casting & Scelte', 'La preparazione fisica estrema dei protagonisti', 'Prima delle riprese, Alessandro Borghi e Alessio Lapice sono stati sottoposti a mesi di preparazione atletica intensa e a un regime alimentare rigidissimo per sviluppare una corporatura compatibile con lo stile di vita di cacciatori e pastori dell''VIII secolo a.C., lavorando anche con la stunt team per la lotta corpo a corpo.', 'Note di produzione e interviste ufficiali al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:55:50.867557+00:00'),
('121fbfea-3955-4183-b488-2f311bde7fe5', 174, 'Segreti di produzione', 'La scelta della luce naturale e delle condizioni estreme', 'Il direttore della fotografia Daniele Ciprì e il regista Matteo Rovere hanno scelto di girare quasi interamente in luce naturale o con fuochi reali, evitando l''uso di complessi impianti di illuminazione artificiale per mantenere il massimo realismo visivo.', 'Making-of ufficiale e approfondimento sulla fotografia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:55:50.867557+00:00'),
('4f22f805-96c5-4a9b-93e8-494b874fac6b', 174, 'Curiosità & Retroscena', 'L''assenza quasi totale di dialoghi in italiano moderno', 'La decisione radicale di non utilizzare alcuna lingua moderna o doppiaggio in italiano standard, ma di fare recitare l''intero cast esclusivamente in un arcaico proto-latino ricostruito, ha rappresentato una scommessa produttiva rischiosa ma fortemente voluta dal regista per immergere totalmente lo spettatore nell''epoca.', 'Conferenza stampa e dossier di stampa del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:55:50.867557+00:00'),
('1963bbb5-673b-4c8c-a7c9-cb584baa2caf', 174, 'Aneddoti dal set', 'Il fango e l''acqua gelida come elementi di prova costante', 'Gran parte delle sequenze è stata girata nelle zone paludose del Lazio durante i mesi autunnali e invernali, costringendo attori e troupe a lavorare per settimane immersi in acqua gelida e fango profondo, senza l''ausilio di controfigure per le scene più logoranti.', 'Intervista al regista e backstage cinematografico', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:55:50.867557+00:00'),
('63ff8fe9-9762-4b58-8795-9b9d56afea08', 217, 'Curiosità & Retroscena', 'L''ispirazione visiva da Il padrino', 'Jon Favreau ha dichiarato in diverse interviste che l''approccio alla gestione del sindacato criminale da parte di Boba Fett si ispira direttamente ai film di Francis Ford Coppola, in particolare al modo in cui Michael Corleone gestisce il potere e il rispetto sul territorio.', 'Intervista ufficiale Disney Gallery: The Mandalorian', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:56:04.65751+00:00'),
('795e737d-0e16-4995-bc2e-ebf41ce0fc15', 217, 'Aneddoti dal set', 'Il peso dell''armatura originale', 'Temuera Morrison ha rivelato che indossare l''armatura completa di Boba Fett sul set richiedeva una complessa assistenza tecnica e fisica, dato che il costume pesava notevolmente e limitava i movimenti nelle scene d''azione sotto il sole caldo della California.', 'Making-of ufficiale Star Wars', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:56:04.65751+00:00'),
('eeb45e6a-6083-4766-9fd7-325e3ffa42e2', 217, 'Casting & Scelte', 'Il cameo di Jennifer Beals come Garsa Fwip', 'L''attrice Jennifer Beals, celebre per Flashdance, ha ottenuto la parte della proprietaria della cantina Garsa Fwip dopo essere stata contattata direttamente da Robert Rodriguez, che l''aveva voluta fortemente per il suo carisma scenico.', 'Note di produzione Lucasfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:56:04.65751+00:00'),
('da11f227-a8d9-40eb-9112-f3aeff0ca8a7', 217, 'Citazioni & Easter Egg', 'Il ritorno di Max Rebo', 'Il musicista alieno Max Rebo, sopravvissuto alla distruzione della barca a vela di Jabba in Episodio VI, fa il suo ritorno nella serie come membro fisso della band al Sanctuary, un dettaglio fortemente voluto dai fan storici della trilogia originale.', 'Analisi ufficiale della continuity di Star Wars', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:56:04.65751+00:00'),
('a4df9d8e-a85f-498f-9e3f-65de43ace81c', 217, 'Segreti di produzione', 'L''uso estensivo del Volume (StageCraft)', 'Gran parte delle sequenze ambientate a Mos Espa e nelle dune di Tatooine non sono state girate in esterni reali, ma all''interno del palcoscenico virtuale StageCraft a Los Angeles, sfruttando schermi LED a 360 gradi per proiettare sfondi in tempo reale.', 'Documentario Industrial Light & Magic', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:56:04.65751+00:00'),
('f308a7d8-2692-4844-8efd-8112e13b0326', 217, 'Effetti speciali & Trucco', 'La creazione dei predoni Tusken', 'Per approfondire la cultura dei Tusken vista nella serie, i reparti di trucco e costumi hanno modificato i tessuti e le maschere tradizionali introducendo trame e sfumature di colore che riflettono la vita nel deserto profondo rispetto ai Tusken visti nei film precedenti.', 'Art of The Book of Boba Fett', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:56:04.65751+00:00'),
('0a44bca5-ae97-4def-9f12-8f81c0dc79df', 217, 'Effetti speciali & Trucco', 'La cicatrice di Fennec Shand', 'Il complesso innesto cibernetico sul corpo e sull''addome di Fennec Shand, necessario a salvarle la vita dopo gli eventi di The Mandalorian, richiedeva ogni giorno ore di applicazione di protesi in silicone e trucco di precisione su Ming-Na Wen.', 'Diario di bordo della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:56:04.65751+00:00'),
('c5d92a92-eb0d-4a95-96fd-e788007af98a', 217, 'Citazioni & Easter Egg', 'L''omaggio a Quadrophenia', 'La gang dei giovani cyborg su speeder colorati che scorrazza per Mos Espa è stata esplicitamente ideata da Robert Rodriguez ispirandosi alle sottoculture giovanili britanniche dei Mod e dei Rocker immortalate nel film cult Quadrophenia.', 'Intervista a Robert Rodriguez per Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:56:04.65751+00:00'),
('c6f95bfe-cc50-4912-a535-28f8ec652ac5', 133, 'Segreti di produzione', 'La ricostruzione della Hollywood Boulevard del 1969', 'Per girare le sequenze su Hollywood Boulevard, la produzione ha rimosso o modificato temporaneamente decine di insegne pubblicitarie moderne, ristoranti e negozi odierni, sostituendoli con facciate d''epoca, insegne al neon e automobili rigorosamente immatricolate prima del 1970.', 'Featurette ''The Making of Once Upon a Time in Hollywood''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:55:33.661695+00:00'),
('1c76ad00-d98e-4df8-8058-426ad02f6bc5', 133, 'Aneddoti dal set', 'L''uso dei lanciafiamme reali sul set', 'La celebre scena in cui Rick Dalton usa il lanciafiamme contro i nazisti in un film fittizio è stata realizzata impiegando un vero lanciafiamme funzionante, gestito da tecnici specializzati in effetti speciali e pirotecnica sotto stretti controlli di sicurezza.', 'Dietro le quinte ufficiale e interviste al reparto stunt', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:55:33.661695+00:00'),
('2c8b7fd5-d519-4f0a-bf7e-b5f76f25579f', 133, 'Citazioni & Easter Egg', 'I veri film spaghetti western citati nel montaggio', 'I frammenti di film interpretati da Rick Dalton nei suoi progetti italiani includono locandine e spezzoni appositamente girati che replicano fedelmente lo stile di veri spaghetti western dimenticati degli anni ''60, diretti da registi come Sergio Corbucci.', 'Commento audio e analisi delle locandine di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:55:33.661695+00:00'),
('bc7783d0-aaaa-44a2-95a2-972a18faeef8', 133, 'Segreti di produzione', 'La conservazione del Playboy Mansion originale', 'La sequenza della festa alla Playboy Mansion è stata ricreata con estrema precisione storica grazie a fotografie d''archivio, sebbene la produzione abbia dovuto lavorare attentamente sulla scenografia per replicare l''atmosfera esatta della residenza di Hugh Hefner nel 1969.', 'Note dello scenografo Barbara Ling', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:55:33.661695+00:00'),
('6e01e796-de7c-4b07-a9cf-a77f9554b1a5', 133, 'Citazioni & Easter Egg', 'La voce originale di KHJ Radio', 'Gli inserti radiofonici che si sentono durante la guida dei personaggi utilizzano registrazioni d''archivio reali delle trasmissioni della stazione radio KHJ di Los Angeles del 1969, inclusi i DJ storici dell''epoca come ''The Real Don Steele''.', 'Credits audio del film e interviste al supervisore del montaggio sonoro', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T14:55:33.661695+00:00'),
('3f7ba457-2c1d-462b-bc26-2b43fa17361d', 234, 'Casting & Scelte', 'Il debutto postumo di Diana Rigg', 'Il film segna l''ultima interpretazione cinematografica della leggendaria attrice Diana Rigg, che interpreta la misteriosa proprietaria di casa Miss Collins. L''attrice è deceduta nell''agosto del 2020, pochi mesi dopo la fine delle riprese principali e prima dell''uscita nelle sale del film.', 'Note di produzione ufficiali di Focus Features', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:56:09.317776+00:00'),
('3a2006fa-4819-4481-a918-1236a294a732', 234, 'Casting & Scelte', 'Il cameo di Margaret Nolan', 'Margaret Nolan, celebre icona degli anni ''60 nota per aver interpretato Dink nel film di James Bond ''Agente 007 - Missione Goldfinger'', appare nel film nel ruolo di una cliente del pub. Anche per lei, tragicamente scomparsa nel 2020, si tratta dell''ultima apparizione cinematografica della carriera.', 'Crediti del film e tributo ufficiale della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:56:09.317776+00:00'),
('99c0f648-ab8a-41e3-96e2-da95a19ab7da', 234, 'Curiosità & Retroscena', 'La scelta musicale per il ballo di Sandie', 'La canzone ''Downtown'' di Petula Clark, centrale in molte scene chiave, è stata scelta da Edgar Wright sin dalle prime fasi di scrittura della sceneggiatura, scritta a quattro mani con Krysty Wilson-Cairns. Il brano non funge solo da colonna sonora nostalgica, ma traccia l''arco emotivo della discesa agli inferi della protagonista.', 'Intervista audio-commento del regista Edgar Wright', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:56:09.317776+00:00'),
('06b5722c-f2f2-4f87-9748-bd9f44e765ec', 234, 'Segreti di produzione', 'Coreografie sincronizzate senza CGI', 'Nelle complesse sequenze in cui Eloise e Sandie si riflettono negli specchi dei locali notturni scambiandosi di posto, Edgar Wright ha evitato l''uso massiccio di effetti digitali in post-produzione. Ha invece coordinato i movimenti di macchina, le coreografie e le comparse attraverso un rigoroso tempismo teatrale e l''uso ingegnoso di veri specchi mobili e cornici vuote.', 'Featurette ''The Making of Last Night in Soho''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:56:09.317776+00:00'),
('f8e1acd8-8ac9-433c-ae26-df76ff1d2608', 234, 'Citazioni & Easter Egg', 'Il tributo a Terence Stamp', 'L''attore Terence Stamp, che interpreta il sinistro anziano conosciuto come ''Silver Haired Gentleman'', è stato scelto da Edgar Wright come citazione vivente del cinema britannico degli anni ''60, essendo stato il protagonista di capolavori dell''epoca come ''Il collezionista'' e ''Modesty Blaise''.', 'Intervista promozionale Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:56:09.317776+00:00'),
('a2c061cc-c02f-40b7-933f-99a5122f2854', 234, 'Aneddoti dal set', 'La gestione delle sequenze oniriche in camera', 'Per girare le transizioni fluide tra il presente di Eloise e il passato di Sandie, il direttore della fotografia Chung-hoon Chung ha utilizzato una speciale combinazione di dolly e gru meccaniche. Gli attori dovevano correre fuori dall''inquadratura per rientrare immediatamente dopo un cambio rapido di costumi e illuminazione sul set.', 'Reportage tecnico American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:56:09.317776+00:00'),
('8c864360-598c-4792-8dd9-f76d2caa0b43', 227, 'Citazioni & Easter Egg', 'La locandina ispirata a Munch', 'L''iconica posa di Macaulay Culkin con le mani sulle guance sulla locandina del film è un chiaro omaggio visivo al celebre dipinto ''L''urlo'' di Edvard Munch. La stessa espressione terrorizzata viene replicata dal giovane attore nella celebre scena del dopobarba.', 'Note di produzione ufficiali della 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:47:36.495107+00:00'),
('90cae9f8-f149-416c-8a13-b645fe85271f', 227, 'Aneddoti dal set', 'La finta tarantola sul volto di Daniel Stern', 'Il ragno che cammina sul volto di Daniel Stern nella celebre scena era un esemplare vivo di tarantola. Per evitare di spaventare l''animale e rischiare un morso, l''attore dovette simulare l''urlo di terrore in silenzio, registrando la voce in post-produzione per non disturbare il ragno.', 'Intervista a Daniel Stern nel documentario ''The Movies That Made Us''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:47:36.495107+00:00'),
('410dc89e-82a5-40ea-a50b-1c3440369c63', 227, 'Segreti di produzione', 'Il falso film poliziesco ''Angels with Filthy Souls''', 'Il film noir che Kevin guarda in cassetta per spaventare il fattorino e i ladri non esiste realmente. Fu girato appositamente per la produzione da un piccolo troupe in un solo giorno, utilizzando attori di caratteri ed effetti di pistola a salve.', 'Archivio ufficiale della produzione e intervista allo sceneggiatore John Hughes', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:47:36.495107+00:00'),
('fa2ccae9-71cd-41f5-9be7-ce6472fd82a5', 227, 'Effetti speciali & Trucco', 'Daniel Stern e le scarpe di gomma', 'Durante le sequenze in cui il personaggio di Marv cammina a piedi nudi sulla neve e sui giocattoli, l''attore Daniel Stern indossava speciali protezioni in gomma color carne modellate esattamente sulla forma dei suoi piedi per evitare infortuni sul set.', 'Making-of ufficiale e contenuti speciali dell''edizione anniversario', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:47:36.495107+00:00'),
('7e35b3ce-48e9-4e8b-9194-82fc31fe6657', 227, 'Aneddoti dal set', 'La gag della porta infuocata', 'Nella sequenza in cui Harry afferra la maniglia della porta rovente resa incandescente da una torcia, la ''M'' marchiata a fuoco sul palmo della mano dell''attore Joe Pesci fu realizzata applicando un calco in silicone riscaldato e truccato con vernici speciali.', 'Documentario sul dietro le quinte della 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:47:36.495107+00:00'),
('aa2172e1-946c-449b-bd23-3794c8f193da', 150, 'Segreti di produzione', 'L''ispirazione per il design degli Ornitterotteri', 'Il design degli iconici velivoli ad ali mobili noti come Ornitterotteri (Ornithopters) è stato ideato dal concept artist Patrice Vermette e dal regista Denis Villeneuve ispirandosi direttamente al comportamento e all''aerodinamica delle libellule.', 'Art of Dune - Libro ufficiale di tascabili', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:55:43.261995+00:00'),
('32a55e58-98ce-478f-901e-f7584b058843', 150, 'Segreti di produzione', 'Il Sound Design innovativo di Mark Mangini e Theo Green', 'I sound designer Mark Mangini e Theo Green hanno evitato di utilizzare librerie audio digitali standard per il film, registrando invece suoni reali manipolati acusticamente, come il vento che ulula nei tubi di metallo per simulare il Verbo della Morte o il rumore delle tempeste di sabbia su Arrakis.', 'Intervista tecnica a Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:55:43.261995+00:00'),
('f636df71-8c5a-40ac-a86c-52681c8f2dc5', 150, 'Curiosità & Retroscena', 'La scelta musicale di Hans Zimmer', 'Il compositore Hans Zimmer ha rifiutato l''offerta di comporre la colonna sonora per il film ''Tenet'' di Christopher Nolan (di cui è collaboratore storico) pur di realizzare le musiche di Dune, essendo un fan sfegatato del romanzo originale di Frank Herbert sin da quando era adolescente.', 'Intervista a The Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:55:43.261995+00:00'),
('6d413834-4553-413b-81e9-4c5cfdb674cb', 150, 'Segreti di produzione', 'Gli strumenti musicali inventati per la colonna sonora', 'Per creare il sound unico di Arrakis, Hans Zimmer ha commissionato la creazione di strumenti musicali del tutto inediti, inclusi fiati e percussioni sperimentali suonati in modo non ortodosso per evitare qualsiasi richiamo alle orchestre tradizionali hollywoodiane.', 'Note di copertina della colonna sonora ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:55:43.261995+00:00'),
('d900dd78-16d9-464f-afae-a6ce5f1926e8', 150, 'Aneddoti dal set', 'L''addestramento militare di Josh Brolin', 'Josh Brolin, per interpretare il maestro d''armi Gurney Halleck, si è sottoposto a mesi di severo addestramento fisico e di combattimento corpo a corpo, apprendendo anche a suonare realmente il baliset (uno strumento a corda fittizio della saga) durante le pause sul set.', 'Diario di bordo delle riprese - Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:55:43.261995+00:00'),
('87f6c11f-539c-4a48-82cb-045d56c2dc59', 227, 'Citazioni & Easter Egg', 'Il cameo del regista Chris Columbus', 'Il regista Chris Columbus fa un breve cameo non accreditato all''inizio del film: è l''uomo con la barba e il cappotto che spinge un carrello nell''aeroporto di Chicago mentre la madre di Kevin cerca disperatamente di usare i telefoni pubblici.', 'Trivia ufficiale IMDb e commento audio del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:47:36.495107+00:00'),
('a19a9c41-16c1-4e5c-a050-586ca61a19fa', 227, 'Curiosità & Retroscena', 'Le previsioni al botteghino superate', 'Prodotto con un budget stimato di circa 18 milioni di dollari, il film fu un successo planetario inaspettato, incassando oltre 476 milioni di dollari in tutto il mondo e rimanendo per anni il film comico live-action con i maggiori incassi nella storia del cinema.', 'Box Office Mojo e registri finanziari della 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T15:47:36.495107+00:00'),
('884f4161-3f48-4124-9680-d8cb76b536e5', 240, 'Aneddoti dal set', 'La paura genuina di Sophia Lillis nella scena del bagno', 'Durante la drammatica sequenza in cui il bagno di Beverly si tinge di sangue a causa dell''esplosione del lavandino, l''attrice Sophia Lillis non stava recitando del tutto: il liquido rosso utilizzato sul set era sciroppo di mais mescolato a colorante alimentare, che oltre a essere estremamente appiccicoso aveva un odore sgradevole e persistente che ha accentuato il suo reale disagio durante le riprese.', 'Commento audio del regista Andy Muschietti e featurette del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:48:06.409716+00:00'),
('f9f19a2e-08c7-47ac-81d8-32140d01b537', 240, 'Casting & Scelte', 'La scelta del look per Richie Tozier e gli occhiali personali', 'Finn Wolfhard ha insistito per mantenere una forte personalizzazione del suo personaggio, indossando occhiali con montatura spessa che richiamano lo stile nerd classico ma che rispecchiano anche i tratti fisici del personaggio originale del libro, sebbene l''attore non avesse realmente bisogno di lenti correttive e dovesse spesso abituarsi alla distorsione visiva.', 'Note di produzione e interviste al cast giovanile', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:48:06.409716+00:00'),
('56b64346-8558-4273-be9b-4123e2533077', 240, 'Citazioni & Easter Egg', 'L''inclusione della celebre spilla dei Legion of Super-Heroes', 'Sullo zaino di Eddie Kaspbrak è chiaramente visibile una spilla dei ''Legion of Super-Heroes'', un dettaglio fortemente voluto dal reparto scenografia per radicare temporalmente il film nel 1989 e riflettere i gusti fumettistici tipici dei ragazzini emarginati di quell''epoca.', 'Articolo di analisi visiva su IMDb e design del costume', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:48:06.409716+00:00'),
('70ba78cb-b196-45df-b2ec-5ae5a2e2d5b8', 278, 'Segreti di produzione', 'Gli scoiattoli veri addestrati per la scena della selezione', 'Per la scena in cui gli scoiattoli giudicano Veruca Salt nella sala delle noci, Tim Burton ha rifiutato l''uso esclusivo della CGI e ha fatto addestrare quaranta veri scoiattoli grigi per ben dieci settimane prima delle riprese. Gli animali sono stati abituati a rompere le noci e a sedersi sui piccoli sgabelli appositamente costruiti.', 'DVD Special Features: Making of Charlie and the Chocolate Factory', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:48:47.547445+00:00'),
('d318a798-7781-4aaa-8b59-d5424bb47a3a', 278, 'Aneddoti dal set', 'Il fiume di cioccolato fatto di polpa di mela', 'Il celebre fiume di cioccolato non era commestibile né fatto di vero cacao: la produzione ha utilizzato ben 781.000 litri di acqua mescolata con polpa di mela e colorante alimentare per ottenere la giusta consistenza opaca. Verso la fine delle riprese, la miscela iniziò a fermentare, sprigionando un odore sgradevole sul set.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:48:47.547445+00:00'),
('f466768e-d1b2-46b5-ae60-104d8d60f940', 278, 'Segreti di produzione', 'Le vere barrette di cioccolato prodotte da Nestlé', 'Per le riprese del film, la Warner Bros. commissionò alla Nestlé la produzione di reali barrette di cioccolato con il marchio Willy Wonka. L''azienda dolciaria dovette creare una fabbrica temporanea e produrre oltre 110.000 barrette vere per le esigenze di scena e di consumo del cast.', 'Archivio di produzione Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:48:47.547445+00:00'),
('5d634930-7917-438d-af97-52dc1f1f74e4', 278, 'Casting & Scelte', 'Il provino rifiutato di Robert De Niro e Christopher Walken', 'Prima che la parte di Willy Wonka venisse definitivamente affidata a Johnny Depp, la Warner Bros. prese in considerazione diversi attori di altissimo profilo per il ruolo, tra cui Robert De Niro, Christopher Walken, Robin Williams, Brad Pitt e persino Jim Carrey e Adam Sandler.', 'Report di casting di Variety e Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:48:47.547445+00:00'),
('ca0d346a-152e-4975-8449-96efc1552ebc', 278, 'Curiosità & Retroscena', 'L''ispirazione per i movimenti di Willy Wonka', 'Johnny Depp ha dichiarato in diverse interviste di aver basato la fisicità e i movimenti rapidi e scattanti di Willy Wonka su quelli dei fantini professionisti e sui ginnasti olimpici, immaginando il personaggio come una creatura che si muove costantemente sulle punte dei piedi.', 'Intervista ufficiale a Johnny Depp per il press kit del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:48:47.547445+00:00'),
('8b236152-4264-49e6-845a-2e377f30e8f6', 199, 'Curiosità & Retroscena', 'La genesi decennale della sceneggiatura', 'George Miller e il co-sceneggiatore Nico Lathouris avevano scritto la sceneggiatura dettagliata di Furiosa ancora prima di iniziare le riprese di Mad Max: Fury Road, concependola originariamente come materiale di background per aiutare Charlize Theron a comprendere il personaggio.', 'Note di produzione ufficiali di Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:55:54.419587+00:00'),
('eb854e07-e96b-40e8-8e73-f28abcbe0b1c', 199, 'Casting & Scelte', 'L''audizione tramite Zoom di Anya Taylor-Joy', 'Anya Taylor-Joy ha ottenuto la parte di Furiosa dopo un''audizione via Zoom con George Miller, durante la quale il regista le ha chiesto di recitare il famosissimo monologo finale di Peter Finch dal film Network (Quinto potere) del 1976.', 'Intervista ufficiale Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:55:54.419587+00:00'),
('574c8cf8-df6f-4bac-878d-590c686e1b89', 199, 'Casting & Scelte', 'La trasformazione di Chris Hemsworth in Dementus', 'Chris Hemsworth indossava un grande naso prostetico per interpretare il Signore della Guerra Dementus; l''attore ha rivelato che la trasformazione fisica e la protesi lo aiutavano a entrare immediatamente nella psicologia distorta e megalomane del personaggio.', 'Press Junket ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:55:54.419587+00:00'),
('969548e2-317f-477c-b31e-3cefac3ab9ca', 199, 'Citazioni & Easter Egg', 'Il tributo a Hugh Keays-Byrne', 'Il film è apertamente dedicato alla memoria dell''attore Hugh Keays-Byrne, l''interprete originale di Toecutter in Mad Max (1979) e di Immortan Joe in Fury Road (2015), scomparso nel dicembre del 2020 prima dell''inizio delle riprese di questo prequel.', 'Titoli di coda ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:55:54.419587+00:00'),
('5cb22182-a6f1-479a-870f-79674230494e', 199, 'Casting & Scelte', 'La scelta di Tom Burke all''ultimo minuto', 'Tom Burke è stato inserito nel cast nel ruolo di Praetorian Jack solo dopo che Yahya Abdul-Mateen II ha dovuto rinunciare alla parte a causa di conflitti di programmazione con altri progetti cinematografici.', 'Comunicato stampa ufficiale Deadline', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:55:54.419587+00:00'),
('7b1ce175-4bd8-457e-907f-aa0125c93061', 229, 'Casting & Scelte', 'Il cambio del protagonista rispetto ai piani originali', 'Nelle prime fasi di sviluppo della sceneggiatura, John Hughes aveva pensato di richiamare Macaulay Culkin per un cameo o addirittura per un ruolo da protagonista adulto, ma l''attore aveva ormai abbandonato la recitazione infantile, costringendo la produzione ad avviare massicci casting da cui emerse Alex D. Linz.', 'Note di produzione e archivi di casting della 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:47:45.09766+00:00'),
('6db8adce-38b3-45a6-89fc-98fdecff5c3d', 229, 'Curiosità & Retroscena', 'La scelta del regista per la continuità del montaggio', 'La scelta di Raja Gosnell come regista non fu casuale: la produzione voleva un forte senso del ritmo e della comicità slapstick visiva, qualità che Gosnell aveva ampiamente dimostrato come montatore supervisore nei primi due capitoli della saga diretti da Chris Columbus.', 'Press kit ufficiale del film del 1997', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:47:45.09766+00:00'),
('17ecce4c-72c9-40e2-8cfc-3d55bc782d48', 229, 'Aneddoti dal set', 'L''addestramento speciale per le trappole meccaniche', 'Il giovane Alex D. Linz dovette seguire settimane di prove tecniche con gli stunt coordinator per imparare a gestire in sicurezza i complessi congegni meccanici e le trappole esplosive, molte delle quali azionate tramite telecomandi fuori campo per garantire reazioni facciali naturali.', 'Intervista al dietro le quinte inclusa nell''edizione Home Video speciale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:47:45.09766+00:00'),
('2d25913d-e5ab-4ba9-b3fa-759cbcf9eac6', 229, 'Casting & Scelte', 'La gestione degli attori nei ruoli dei criminali', 'Per il ruolo del leader della banda Jurgis Kresge fu scelto Olek Krupa grazie alla sua abilità nel bilanciare una minaccia internazionale credibile con la comicità fisica grottesca richiesta dai film della serie Home Alone.', 'Commento audio del regista Raja Gosnell', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:47:45.09766+00:00'),
('d3a0b6e4-1cb4-4ca1-9499-db337d59054e', 229, 'Aneddoti dal set', 'I problemi climatici durante le riprese a Chicago', 'Nonostante la storia si svolgesse durante un freddo inverno a Chicago, la troupe dovette affrontare temperature insolitamente miti durante alcune giornate di ripresa esterna, costringendo la produzione a fare largo uso di neve artificiale a base di carta e polimeri plastici.', 'Reportage dal set della rivista American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:47:45.09766+00:00'),
('2feb788d-4efd-46f1-8b3d-a353ad3dffca', 229, 'Segreti di produzione', 'Il coordinamento degli animali e dei pappagalli', 'La gestione del pappagallo domestico nel film richiese l''impiego di diversi volatili addestrati provenienti da una troupe di animal trainer professionisti di Hollywood, affiancati da versioni robotiche controllate via cavo per le scene più pericolose o comiche.', 'Note di produzione sugli effetti speciali pratici', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:47:45.09766+00:00'),
('26314c8b-2b2d-48b4-bf74-b65e9ce8f7ef', 236, 'Casting & Scelte', 'La cassetta di sicurezza con le regole di Terry Gilliam per Bruce Willis', 'Terry Gilliam aveva la reputazione di scontrarsi con le star di Hollywood, così prima delle riprese consegnò a Bruce Willis una lista di espressioni e tic che l''attore non poteva assolutamente usare, impedendogli di sfoggiare la sua tipica espressione da duro alla ''Die Hard''.', 'Commento audio del regista nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:47:54.737644+00:00'),
('2454a247-3818-49d4-8ce2-0ee6f754db1b', 236, 'Segreti di produzione', 'Il budget ridotto e la scommessa salariale di Bruce Willis e Brad Pitt', 'Il film fu realizzato con un budget relativamente contenuto di circa 29 milioni di dollari; per renderlo possibile, sia Bruce Willis che Brad Pitt accettarono di tagliare drasticamente i loro compensi abituali pur di lavorare con Terry Gilliam.', 'Note di produzione della Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:47:54.737644+00:00'),
('0390459a-d4ee-45f8-9cc5-4c7547377eeb', 236, 'Citazioni & Easter Egg', 'L''ispirazione visiva da La Jetée di Chris Marker', 'La pellicola è un adattamento non ufficiale ma apertamente dichiarato del cortometraggio francese ''La Jetée'' (1962) di Chris Marker, composto quasi interamente da fotogrammi fissi, omaggiato direttamente nella struttura della memoria d''infanzia del protagonista.', 'Dichiarazioni ufficiali degli sceneggiatori David e Janet Peoples', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:47:54.737644+00:00'),
('f9f7a32e-41b0-4296-b803-3327156fab8f', 236, 'Effetti speciali & Trucco', 'Il recupero dell''archivio delle scimmie meccaniche', 'Per la sequenza finale dell''aeroporto, la produzione non poté utilizzare veri animali selvatici in massa per motivi di sicurezza e budget, affidandosi a un mix di comparse mascherate e a un uso sapiente di modelli in scala ridotta curati dal reparto scenografia.', 'Documentario ''The Making of Twelve Monkeys''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:47:54.737644+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('c0cc130f-271c-4519-89bd-207ddee02a6c', 236, 'Segreti di produzione', 'L''assenza di computer grafica avanzata per i panorami del futuro', 'I bizzarri macchinari sotterranei e le enormi sfere geodetiche in cui vive l''umanità nel 2035 non furono realizzati in CGI moderna, bensì attraverso giganteschi set fisici costruiti in una centrale elettrica in disuso a Baltimora e l''uso di miniature prospettiche.', 'Libro fotografico ufficiale ''The Hamster Factor and Other Tales of Twelve Monkeys''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:47:54.737644+00:00'),
('8c1e2e89-72b7-4218-9be0-eb2846f91afb', 206, 'Casting & Scelte', 'L''improvvisazione vocale di Rachel Zegler', 'Tutte le canzoni eseguite da Lucy Gray Baird nel film sono state registrate dal vivo sul set anziché in studio di registrazione post-produzione, per mantenere l''autenticità del respiro e del movimento tipici dei musicisti folk itineranti.', 'Note di regia e intervista al compositore James Newton Howard', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:55:59.672885+00:00'),
('3a4a21be-d86a-486e-926a-342c6af1575e', 206, 'Casting & Scelte', 'Il legame di parentela con Jason Schwartzman', 'Jason Schwartzman, che interpreta il primo storico presentatore dei giochi Lucretius ''Lucky'' Flickerman, ha basato parte della sua comicità surreale ed istrionica sui vecchi presentatori televisivi degli anni cinquanta e sui cinegiornali d''epoca.', 'Intervista stampa ufficiale di Jason Schwartzman', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:55:59.672885+00:00'),
('e2db772c-c75c-45d8-9e3e-39e341d4f739', 206, 'Segreti di produzione', 'Il vero peso delle uniformi dei Guardiani della Pace', 'Le divise indossate dalle comparse e dagli attori che interpretavano i Guardiani della Pace (Peacekeepers) sono state realizzate con metalli leggeri e cuoio rinforzato, pesando oltre 12 chili ciascuna per simulare l''effettivo disagio dei soldati sul campo.', 'Intervista alla costumista Trish Summerville per Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:55:59.672885+00:00'),
('cb12dd14-fea8-4708-ab95-9361a0715213', 206, 'Citazioni & Easter Egg', 'L''omaggio visivo alla Grande Depressione', 'Per la rappresentazione visiva del Distretto 12 povero e devastato del dopoguerra, il direttore della fotografia Adam Newport-Berra si è ispirato direttamente alle celebri fotografie storiche della Farm Security Administration scattate durante la Grande Depressione americana.', 'American Cinematographer, edizione speciale sul film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:55:59.672885+00:00'),
('75e9cb30-581f-42d3-8188-5c5da0b7f469', 206, 'Effetti speciali & Trucco', 'La scelta del look albino di Tigris', 'Hunter Schafer, per interpretare Tigris Snow, ha dovuto sottoporsi a sessioni di trucco prostetico quotidiane della durata di oltre tre ore per applicare modifiche sottili al viso che anticipassero la sua futura trasformazione chirurgica in felino.', 'Dietro le quinte ufficiale Lionsgate sui look dei personaggi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:55:59.672885+00:00'),
('fea5f9de-abe2-47db-b511-535585e493c4', 234, 'Aneddoti dal set', 'Le prove d''abito e la vestizione sul set', 'Durante le riprese delle complesse sequenze di ballo al Café de Paris, Anya Taylor-Joy ha dovuto indossare abiti d''epoca estremamente aderenti e delicati, richiedendo la presenza costante dei costumisti sul set per aggiustamenti millimetrici tra una ripresa e l''altra per preservare l''autenticità dei tessuti originali.', 'Intervista al reparto costumi per Vogue', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:47:50.911191+00:00'),
('688e1377-984f-484b-8b41-00715ad51fe0', 234, 'Segreti di produzione', 'L''ispirazione musicale da John Barry', 'Il compositore Steven Price ha lavorato a stretto contatto con Edgar Wright per incorporare sonorità che richiamassero lo stile orchestrale di John Barry e le colonne sonore britanniche dei primi anni ''60, utilizzando anche strumenti d''epoca autentici per registrare la partitura.', 'Backstage e intervista al compositore', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:47:50.911191+00:00'),
('254c6898-88cb-4d0f-be33-4ff04ffe306d', 234, 'Casting & Scelte', 'La scelta del look di Thomasin McKenzie', 'Per il personaggio di Eloise, Edgar Wright ha voluto che l''attrice Thomasin McKenzie adottasse uno stile volutamente dimesso e fuori dal tempo nei primi minuti del film, ispirandosi alle fotografie di moda di David Bailey per evidenziare il contrasto con il glamour vibrante di Anya Taylor-Joy.', 'Commento audio del regista nel Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:47:50.911191+00:00'),
('4f65b263-8782-4d5c-afa2-a487e862f884', 234, 'Citazioni & Easter Egg', 'Il tributo ai classici del giallo all''italiana', 'Oltre ai riferimenti visivi noti, Edgar Wright ha inserito piccoli omaggi sonori e visivi ai film di Dario Argento e Mario Bava, replicando in alcune sequenze di transizione l''uso di gelatine colorate al neon rosso e blu tipiche del genere Giallo.', 'Special ''The Aesthetics of Soho'' nel making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:47:50.911191+00:00'),
('d95eda3e-24de-4f71-baba-a899c88e5f34', 241, 'Curiosità & Retroscena', 'L''ispirazione da un trauma d''infanzia', 'Steven Spielberg ha concepito la storia di E.T. traendo spunto dal divorzio dei suoi genitori e dal successivo periodo di solitudine, durante il quale si era inventato un amico immaginario alieno per superare il trauma.', 'Note di produzione ufficiali e documentario The Making of E.T.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:48:11.180462+00:00'),
('fe87f073-ff69-40b9-9e0f-115e77b85768', 134, 'Segreti di produzione', 'La dieta estrema e il collasso di Stallone', 'Per raggiungere la percentuale record del 2,8% di grasso corporeo vista all''inizio del film, Sylvester Stallone seguì una dieta composta quasi esclusivamente da pane tostato con farina d''avena e 10 albumi d''uovo al giorno, abbinata a un consumo smodato di caffè. Questa drastica restrizione calorica portò l''attore e regista a svenire ripetutamente sul set per disidratazione e cali di pressione.', 'Intervista retrospettiva a Sylvester Stallone per la rivista Men''s Health', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:05:03.284836+00:00'),
('fe6db644-8929-486b-b4cd-fe6f770c8142', 241, 'Casting & Scelte', 'Il provino improvvisato di Henry Thomas', 'Per il provino della scena in cui gli agenti governativi interrogano Elliott, Steven Spielberg chiese a Henry Thomas di improvvisare; l''attore fu così convincente e commovente da far piangere l''intera troupe sul set, ottenendo la parte all''istante.', 'Commento audio del regista nel Blu-ray celebrativo del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:48:11.180462+00:00'),
('d23d9cad-457b-46f9-b9ca-a7cd576db101', 241, 'Segreti di produzione', 'La voce di E.T. creata da Pat Welsh', 'La voce roca e distintiva di E.T. fu prestata da Pat Welsh, un''anziana donna fumatrice che lavorava in un negozio di ottica; la sound designer Ben Burtt la scoprì mentre parlava a un convegno e registrò la sua voce mescolandola con versi di animali.', 'Documentario sui suoni e il doppiaggio di E.T. nei contenuti speciali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:48:11.180462+00:00'),
('368cb79d-5118-497f-ba8a-294b88ba114a', 241, 'Aneddoti dal set', 'L''uso dei mimi sul set', 'All''interno del costume di E.T. si alternarono diversi operatori, tra cui un ragazzo senza gambe di dodici anni di nome Robert Battuhn e un''attrice nana di nome Tamara De Treaux, oltre a un mimo professionista di nome Capucine ''Capri'' Reed per le sequenze più complesse.', 'Making-of ufficiale ''E.T.: The Extra-Terrestrial - A Look Back''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:48:11.180462+00:00'),
('5f3776a5-db16-44e6-a309-f260d492df64', 241, 'Citazioni & Easter Egg', 'Il cameo di Steven Spielberg come scienziato', 'Nella sequenza in cui gli scienziati governativi fanno irruzione nella casa di Elliott per monitorare E.T. attraverso le apparecchiature mediche, Steven Spielberg appare brevemente in un cameo non accreditato indossando un camice bianco e una tuta protettiva.', 'Trivia ufficiale IMDb e libro ''Steven Spielberg: A Biography'' di Joseph McBride', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:48:11.180462+00:00'),
('9f4d7099-a5b3-46fb-93f9-0cec0d56b881', 217, 'Casting & Scelte', 'Il ritorno di Danny Trejo', 'L''iconico attore Danny Trejo è apparso nella serie nel ruolo del guardiano del Rancor grazie alla sua lunga amicizia e collaborazione di vecchia data con il regista Robert Rodriguez, con cui aveva girato film come Machete e Spy Kids.', 'Note di casting ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T14:56:04.65751+00:00'),
('95bbe9de-50d3-4d92-983c-8bd372a17109', 266, 'Curiosità & Retroscena', 'La vera isola greca e le restrizioni Covid', 'Le riprese dell''isola di Miles Bron non si sono svolte in una vera villa privata isolata, bensì presso il lussuoso resort Amanzoe nella regione del Peloponneso, in Grecia. La produzione ha dovuto blindare l''intero complesso turistico nel bel mezzo della pandemia nel 2021, creando una bolla di sicurezza rigida per cast e troupe.', 'Note di produzione ufficiali Netflix', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:56:23.557589+00:00'),
('4fd57862-1f5f-4bfb-8fef-97ab25b725a6', 266, 'Casting & Scelte', 'L''ispirazione per il personaggio di Miles Bron', 'Rian Johnson ha ammesso apertamente nelle interviste promozionali che la costruzione psicologica e pubblica del miliardario Miles Bron trae ispirazione diretta da reali magnati della tecnologia contemporanei, riflettendo la cultura della Silicon Valley e la figura dei moderni ''disruptor''.', 'Intervista ufficiale di Rian Johnson per Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:56:23.557589+00:00'),
('9b31902c-a163-4fa3-bb6b-9777ab2ddcb0', 266, 'Citazioni & Easter Egg', 'Il cameo vocale di Noah Segan nei panni di Derol', 'Noah Segan, attore presente in ogni film di Rian Johnson, interpreta Derol, l''eterno imbucato che vive sull''isola e che nessuno sembra conoscere realmente. Oltre ad apparire fisicamente, Segan doppia anche il personaggio di Marguerite in una scena telefonica.', 'Crediti del film e commento audio del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:56:23.557589+00:00'),
('622d8076-c666-4912-918f-dc81a8b0570c', 266, 'Segreti di produzione', 'Il quadro originale di Monet sul set', 'Il dipinto che compare nel salone della villa di Miles Bron non è una riproduzione economica, ma un vero prestito museale autorizzato, sebbene la produzione abbia dovuto utilizzare copie di altissima precisione per le sequenze più rischiose in cui l''arte è coinvolta nella trama.', 'Intervista allo scenografo Rick Heinrichs', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:56:23.557589+00:00'),
('66dfcbc9-1930-487a-b53d-9bbb8670272b', 266, 'Aneddoti dal set', 'Le partite di Among Us durante le prove', 'Per stringere i legami tra gli attori durante la quarantena preventiva in Grecia prima di iniziare a girare, il cast principale guidato da Daniel Craig e Dave Bautista ha passato diverse serate a giocare a ''Among Us'' e a giochi da tavolo nella villa comune.', 'Intervista di Kate Hudson al Tonight Show', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:56:23.557589+00:00'),
('85c1a71a-8db7-49e2-bbd6-999e8cc7abb1', 266, 'Citazioni & Easter Egg', 'Il cameo di Stephen Sondheim e Angela Lansbury', 'La sequenza in cui Benoit Blanc gioca online a Among Us nella sua vasca da bagno include le leggendarie partecipazioni postume di Stephen Sondheim e Angela Lansbury, registrate tramite Zoom poco prima della loro scomparsa.', 'Note di produzione e tributo nei titoli di coda', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:56:23.557589+00:00'),
('bde1607a-01dc-4832-9179-009b4f454a94', 266, 'Segreti di produzione', 'La vera Mona Lisa del Louvre', 'Per la sequenza culminale in cui la celebre opera di Leonardo da Vinci viene distrutta, la produzione ha impiegato un modello meccanico altamente dettagliato costruito appositamente dagli esperti di effetti speciali guidati da Bob Chapman.', 'Featurette ''Making of Glass Onion'' su Netflix', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:56:23.557589+00:00'),
('b452e335-a1d7-4885-b04e-0ec54ab0898f', 266, 'Effetti speciali & Trucco', 'Il bicchiere di vetro soffiato artigianale', 'Il celebre bicchiere ''Glass Onion'' centrale nella trama non poteva essere di vero vetro pericoloso per le sequenze d''azione; la reparto oggetti di scena ha fatto realizzare appositamente decine di repliche in zucchero filato indurito e vetro acrilico sicuro per gli attori.', 'Intervista al reparto oggetti di scena', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:56:23.557589+00:00'),
('0418b97b-6dbb-48a7-9d72-905364727f68', 238, 'Effetti speciali & Trucco', 'La vera aria condizionata sul set gelido', 'Per riprodurre realisticamente il respiro condensato dei personaggi nella camera della posseduta, William Friedkin fece installare dei condizionatori d''aria industriali capaci di portare la temperatura della stanza a circa -28 gradi Celsius. Gli attori indossavano abiti leggeri e il freddo era talmente estremo che la troupe lavorava con cappotti pesanti e tute termiche.', 'Documentario ''The Fear of God: 25 Years of The Exorcist''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:48:00.614287+00:00'),
('8a76acf1-a92b-4983-beb0-5ad60140e391', 238, 'Aneddoti dal set', 'La benedizione di Padre Thomas Bermingham', 'Preoccupato per la presunta atmosfera maledetta e i vari incidenti sul set, il regista William Friedkin chiamò sul set un gesuita, Padre Thomas Bermingham (che nel film interpreta un ruolo minore e fece da consulente tecnico), per benedire la troupe e il set. Il sacerdote si rifiutò di eseguire un vero esorcismo ma acconsentì a impartire una solenne benedizione a tutti i presenti.', 'Audio commento del regista William Friedkin nell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:48:00.614287+00:00'),
('e846b7b7-fd36-4ab2-b32c-7d42ff071228', 238, 'Aneddoti dal set', 'La vera lesione alla colonna vertebrale di Ellen Burstyn', 'Durante la scena in cui Regan scaraventa a terra la madre, l''imbracatura tirò l''attrice Ellen Burstyn con troppa violenza all''indietro facendola cadere rovinosamente sul coccige. L''urlo di dolore dell''attrice che si vede nel film è autentico e la caduta le causò un danno permanente alla colonna vertebrale che richiese anni di fisioterapia.', 'Intervista autobiografica di Ellen Burstyn nel suo libro ''Lessons in Heartbreak''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:48:00.614287+00:00'),
('d4b34e88-8ed4-4fe2-a09a-c188da906230', 238, 'Effetti speciali & Trucco', 'Il rumore dei maiali per i grugniti demoniaci', 'La celebre voce del demone Pazuzu fu creata sovrapponendo la voce dell''attrice Mercedes McCambridge con registrazioni di maiali macellati, tori infuriati e api amplificate. Mercedes McCambridge per ottenere quel timbro rauco ingerì uova crude, fumò catene di sigarette e bevve whisky.', 'Note di produzione e documentario audio sul making-of del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:48:00.614287+00:00'),
('cf5bee0b-d953-4510-ad98-f4258e2c331b', 238, 'Segreti di produzione', 'La stanza da letto su misura montata su carrello', 'Poiché era impossibile mantenere una temperatura sotto zero costante all''interno di un normale studio cinematografico, la camera da letto di Regan fu costruita all''interno di un edificio indipendente dotato di un sistema di refrigerazione mobile. L''intera stanza era montata su un sistema cardanico per permettere alle pareti e al letto di muoversi durante le scene di possessione.', 'American Cinematographer, articolo tecnico del 1974', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:48:00.614287+00:00'),
('00b9b112-b0c1-480f-8447-488f1c9bd75d', 238, 'Casting & Scelte', 'Il rifiuto iniziale di William Friedkin per Linda Blair', 'Inizialmente William Friedkin era riluttante ad assumere Linda Blair per la parte di Regan MacNeil, temendo che una bambina così giovane non potesse reggere la pressione psicologica e fisica del ruolo. Fu la madre dell''attrice, protettiva ma decisa, a insistere per farla provonare, convincendo infine il regista grazie alla naturalezza e alla determinazione della ragazzina.', 'Memorie di produzione della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:48:00.614287+00:00'),
('c2ffdb09-7ce2-4392-8603-d34764132f14', 240, 'Citazioni & Easter Egg', 'Il tributo a Tim Curry nella versione di Pennywise', 'Il design del costume cinematografico di Pennywise ideato dalla costumista Janie Bryant include maniche a lanterna, colletti a sbuffo e dettagli peplo in tonalità argento e seta che richiamano epoche storiche diverse (vittoriana, rinascimentale ed elisabettiana). Questo look stratificato è un omaggio visivo al celebre clown interpretato da Tim Curry nella miniserie TV del 1990.', 'Articolo di Entertainment Weekly sui costumi del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:56:14.633072+00:00'),
('1d4d3616-0ce0-498e-9f42-c5c2f4685aa0', 240, 'Effetti speciali & Trucco', 'Il sorriso iconico senza protesi digitali', 'Il sorriso inquietante e asimmetrico di Pennywise, in cui le labbra si tirano indietro mostrando una doppia fila di denti, è stato realizzato quasi interamente da Bill Skarsgård senza l''ausilio di protesi dentarie estese, sfruttando una particolare mimica facciale che l''attore aveva inventato da bambino giocando con il fratello Gustaf.', 'Featurette ''The Making of Pennywise'' nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:56:14.633072+00:00'),
('d9cf9e04-aeb3-4301-bf30-21b8ae4ee22e', 240, 'Citazioni & Easter Egg', 'Il cameo nascosto di Jack Angel e la voce originale', 'Nella scena in cui il giovane Richie Tozier entra nella sala dei clown smarriti all''interno della casa di Neibolt Street, si intravede una bambola che indossa abiti simili a quelli di Chuckles the Clown, un chiaro cenno ai classici tropi dell''orrore circense e al romanzo di Stephen King.', 'Commento audio del regista Andy Muschietti e della produttrici Barbara Muschietti', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:56:14.633072+00:00'),
('1ffa5372-562d-4924-90b8-9ffdaabecbff', 240, 'Casting & Scelte', 'L''audizione di Millie Bobby Brown', 'Prima di ottenere il ruolo globale di Eleven in ''Stranger Things'', la giovane attrice Millie Bobby Brown ha sostenuto un provino molto intenso per la parte di Beverly Marsh nel film, arrivando vicina alla selezione finale prima che la parte venisse assegnata a Sophia Lillis.', 'Intervista a Jimmy Fallon / The Tonight Show', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:56:14.633072+00:00'),
('92a51ff4-e09e-4773-9abd-15f83411dc2f', 240, 'Aneddoti dal set', 'La fobia reale di Bill Skarsgård per i bambini', 'Nonostante fosse lui la fonte di terrore sul set, Bill Skarsgård ha spesso espresso il timore di aver traumatizzato emotivamente i giovanissimi attori del Club dei Perdenti a causa del trucco pesante e dei suoi improvvisi scatti di rabbia durante le riprese delle scene più violente.', 'Intervista promozionale per Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:56:14.633072+00:00'),
('29d103d0-a27d-4f04-8e8c-e9594502f1f9', 238, 'Curiosità & Retroscena', 'Jason Miller e la vera preghiera in latino', 'L''attore e drammaturgo Jason Miller, che interpretava Padre Karras, era stato educato in un seminario gesuita prima di abbandonare gli studi per dedicarsi alla recitazione. Questa sua profonda conoscenza del latino e dei riti liturgici gli permise di pronunciare le preghiere di esorcismo nel finale con una precisione e una naturalezza che impressionarono persino i consulenti ecclesiastici sul set.', 'Archivio storico della produzione Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:48:00.614287+00:00'),
('8b9a2df9-05e9-4d66-a9cc-c839868587e6', 238, 'Effetti speciali & Trucco', 'Il vomito di piselli e zuppa di zucca', 'Il celebre getto di vomito verde vomitato dal personaggio di Regan addosso a Padre Karras era composto principalmente da una densa zuppa di piselli combinata con farina d''avena. Per spararlo con precisione, l''operatore degli effetti speciali utilizzava un tubo nascosto sotto la bocca dell''attrice collegato a una pompa a pressione azionata a mano fuori campo.', 'Making-of ufficiale ''The Making of The Exorcist''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:48:00.614287+00:00'),
('606028a5-ed7c-4a13-99ce-38840ef6da0f', 275, 'Aneddoti dal set', 'La paura e la gestione del cane di razza Griffone di Bruxelles', 'Il cane verdellino di nome Verdell nella realtà era interpretato da sei diversi cani di razza Griffone di Bruxelles. Jack Nicholson, inizialmente terrorizzato e a disagio all''idea di dover recitare a stretto contatto con un animale, finì per affezionarsi così tanto a uno di essi, di nome Sprout, da volerlo quasi adottare a fine riprese.', 'Special feature del DVD ''Making of As Good as It Gets''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:48:37.421734+00:00'),
('18f34b64-70f4-4e4a-9263-6b65ad5045d9', 275, 'Segreti di produzione', 'La gestione delle nevrosi di Melvin attraverso le posizioni delle scarpe', 'Per mantenere intatta la credibilità delle rigide ossessioni compulsive di Melvin Udall, la produzione consultò specialisti del disturbo ossessivo-compulsivo. Jack Nicholson dispose personalmente che le scarpe da ginnastica utilizzate per le scene dell''appartamento venissero allineate con precisione millimetrica sul pavimento prima di ogni ciak.', 'Note di produzione e commento audio del regista James L. Brooks', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:48:37.421734+00:00'),
('c0077cc4-e353-4cb5-8e2f-831032d4dad2', 275, 'Curiosità & Retroscena', 'L''improvvisazione della battuta sui complimenti alle donne', 'La celeberrima e tagliente battuta in cui Melvin risponde a Carol dicendo ''Mi fai venire voglia di essere un uomo migliore'' fu inizialmente accolta con scetticismo da Jack Nicholson durante le prove. Fu lo stesso attore a spingere per limare la consegna della battuta sul set per renderla meno sdolcinata e più coerente con il cinismo del personaggio.', 'Intervista retrospettiva a Jack Nicholson per Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:48:37.421734+00:00'),
('fa52023a-6ee5-4cf8-bdbb-c096a2fe2e63', 275, 'Casting & Scelte', 'Il provino e l''insistenza di Helen Hunt', 'Helen Hunt non era la prima scelta in assoluto per il ruolo della cameriera Carol Connelly, poiché la produzione aveva valutato diverse attrici di maggiore nome al botteghino in quel periodo. L''attrice ottenne la parte grazie a un''audizione particolarmente intensa in cui convinse immediatamente James L. Brooks a dispetto delle pressioni contrarie dello studio.', 'Documentario retrospettivo sui casting di Hollywood degli anni ''90', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:48:37.421734+00:00'),
('a9153a88-32b8-476f-8f09-ecb8ad54ccc8', 275, 'Segreti di produzione', 'Il vero pittore dietro le opere di Simon Bishop', 'I dipinti e le tele astratte realizzate dal personaggio di Simon Bishop nel film non sono opera dell''attore Greg Kinnear, bensì del celebre pittore e artista contemporaneo Laurel Holloman e di altri artisti assunti dal reparto scenografia per conferire autenticità al loft di SoHo.', 'Archivio di produzione e crediti artistici del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:48:37.421734+00:00'),
('d28b282a-5cd0-4c85-b469-fd96da0f2452', 275, 'Curiosità & Retroscena', 'La scelta musicale originale e l''accordo saltato con Hans Zimmer', 'Sebbene la colonna sonora sia stata poi brillantemente curata da Hans Zimmer, ricevendo una nomination all''Oscar, nelle prime fasi di montaggio il regista James L. Brooks sperimentò a lungo l''inserimento di brani pop e rock alternativi per scandire il ritmo delle camminate di Melvin per le strade di New York.', 'Note di edizione e lavorazione della colonna sonora originale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:48:37.421734+00:00'),
('03cdb9df-62db-48e7-a3c7-4568f5f08a67', 73, 'Effetti speciali & Trucco', 'La voce aliena basata sulle foche', 'Il celebre sound designer Ben Burtt ha creato il verso del mostro marino Opee Sea Killer ascoltando e manipolando le registrazioni vocali di alcune foche dell''acquario marino di Marineland, in California.', 'Documentario ''The Beginning: Making Episode I'' e note di produzione ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-03T10:11:42.266822+00:00'),
('c34dcea3-ad5f-4711-ad87-abe37b6cc2db', 265, 'Citazioni & Easter Egg', 'Il cameo vocale di Joseph Gordon-Levitt', 'L''attore Joseph Gordon-Levitt, collaboratore storico di Rian Johnson, appare in un rapido cameo vocale all''interno del film, prestando la voce al detective protagonista di un finto film poliziesco in TV intitolato ''The Hardy Boys'' che si vede in una scena.', 'Crediti del film e intervista a Rian Johnson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:56:18.763824+00:00'),
('e5524849-ad30-4eff-a80d-c8c1cd7c245c', 265, 'Segreti di produzione', 'La scelta cromatica delle scenografie', 'Il direttore della fotografia Steve Yedlin e il regista hanno utilizzato una palette di colori caldi e dominata dai toni del legno e del bordeaux per dare alla villa un''atmosfera volutamente claustrofobica, autunnale e classica da romanzo di Agatha Christie.', 'American Cinematographer, intervista tecnica a Steve Yedlin', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:56:18.763824+00:00'),
('f55aaf77-8282-4787-904e-d16d199d7302', 241, 'Curiosità & Retroscena', 'La spesa record per la sceneggiatura', 'La sceneggiatura scritta da Melissa Mathison venne acquistata dalla Universal Pictures per un milione di dollari, una cifra considerevole per l''epoca, basandosi su un trattamento preliminare intitolato originariamente ''A Boy''s Life''.', 'Archivi storici della Universal Pictures e Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:48:11.180462+00:00'),
('67fcec3e-cf26-452f-830b-681fdb1bc8db', 279, 'Casting & Scelte', 'Il licenziamento di Eric Stoltz dopo cinque settimane', 'Eric Stoltz fu originariamente scelto per interpretare Marty McFly e girò per ben cinque settimane prima che Robert Zemeckis e Steven Spielberg si rendessero conto che la sua interpretazione era troppo drammatica e priva della vena comica necessaria. Venne sostituito da Michael J. Fox, costringendo la produzione a rigirare tutte le scene già fatte con un costo aggiuntivo stimato di circa 3 milioni di dollari.', 'Documentario ''The Making of Back to the Future'' e commento audio del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:48:53.328929+00:00'),
('0f0b85c2-55c8-4ab5-b6f3-be6c2ae4e1d2', 279, 'Segreti di produzione', 'La coincidenza del furgone dei libici', 'Il furgone Volkswagen usato dai terroristi libici che inseguono Marty e Doc nel parcheggio del centro commerciale era di proprietà del supervisore degli effetti speciali Kevin Pike. Per ironia della sorte, il veicolo si ruppe proprio durante le riprese della scena in cui viene crivellato di colpi, costringendo la troupe a ripararlo in fretta e furia sul posto.', 'Libro ''We Don''t Need Roads: The Making of the Back to the Future Trilogy'' di Caseen Gaines', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:48:53.328929+00:00'),
('798a4a14-3cc0-421b-a911-79f82e5ba779', 279, 'Aneddoti dal set', 'I problemi di salute e il doppio lavoro di Michael J. Fox', 'Durante le riprese notturne del film, Michael J. Fox lavorava contemporaneamente alla serie TV ''Casa Keaton'' durante il giorno, dormendo solo circa due o tre ore per notte. Questa tabella di marcia massacrante lo costringeva spesso a fare brevi sonnellini tra un ciak e l''altro, appoggiandosi persino alla DeLorean.', 'Autobiografia di Michael J. Fox ''Lucky Man'' e interviste d''archivio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:48:53.328929+00:00'),
('79b44c45-efd4-4e17-9117-2cc6301aa018', 279, 'Curiosità & Retroscena', 'Il cambio del marchio di plutonio', 'Nella prima versione della sceneggiatura, Doc Brown rubava il plutonio ai libici usando una complessa trappola radioattiva, e il materiale radioattivo era inserito in contenitori di una marca inventata. Tuttavia, la produzione ricevette pressioni e autorizzazioni per inserire dettagli realistici, modificando i barattoli con etichette che ricordavano i prodotti industriali dell''epoca.', 'Note di produzione originali e sceneggiatura preliminare', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:48:53.328929+00:00'),
('a5d9b6e4-0954-4edd-9b42-af648ca576e2', 279, 'Casting & Scelte', 'Il ritardo di Claudia Wells nel sostituire Melora Hardin', 'Melora Hardin fu originariamente scelta per interpretare la fidanzata di Marty, Jennifer Parker, ma fu sostituita quando Eric Stoltz fu licenziato, poiché era stata scelta originariamente perché più bassa di statura rispetto a Stoltz. Al suo posto subentrò Claudia Wells, che però poté girare solo il primo film prima di dover rinunciare ai sequel per assistere la madre malata.', 'Interviste retrospettive del 25º anniversario della trilogia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:48:53.328929+00:00'),
('eb153802-2234-421a-ac46-9241f4b21a60', 279, 'Segreti di produzione', 'La chitarra di Marty McFly nel 1955', 'Nella celebre sequenza in cui Marty suona ''Johnny B. Goode'' al ballo scolastico del 1955, la chitarra rossa Gibson ES-345 che usa è storicamente anacronistica, essendo stata prodotta solo a partire dal 1958. Gli autori e il regista erano consapevoli dell''errore, ma scelsero comunque quello strumento per la sua estetica e il suo suono potente.', 'Database di errori cinematografici IMDb e note di montaggio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:48:53.328929+00:00'),
('c643e33f-c2ab-4471-ab03-9e2dbfadae8c', 279, 'Citazioni & Easter Egg', 'Il cameo del co-sceneggiatore Bob Gale', 'Il co-sceneggiatore e produttore Bob Gale fa un breve cameo non accreditato nel film: è il cliente che si trova nella tavola calda nel 1955 e viene servito da Lou, l''uomo che pulisce il bancone quando Marty entra per la prima volta nel locale.', 'Commento audio del regista Robert Zemeckis e Bob Gale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:48:53.328929+00:00'),
('17c0900f-caf7-4795-9c7f-d08adae37f70', 279, 'Aneddoti dal set', 'La DeLorean e la resistenza aerodinamica', 'La DeLorean DMC-12 fu scelta non solo per il suo aspetto futuristico con le ali di gabbiano, ma anche per le difficoltà riscontrate dagli stuntman nel guidarla ad alte velocità sulle piste dell''aeroporto diチュア durante le riprese della sequenza finale. La carrozzeria in acciaio inossidabile spazzolato rifletteva così tanto la luce del sole che la troupe dovette usare speciali filtri polarizzatori sulle telecamere.', 'Archivio tecnico Universal Studios e making-of d''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:48:53.328929+00:00'),
('4b2c817c-3e70-4d64-b841-452a49acd60b', 73, 'Casting & Scelte', 'Keira Knightley nel ruolo della sosia', 'Keira Knightley è stata scelta per interpretare Sabé, la damigella d''onore che funge da esca e sosia della Regina Amidala, grazie alla sua straordinaria somiglianza fisica con Natalie Portman, al punto che persino le madri delle due attrici facevano fatica a riconoscerle sul set truccate.', 'Intervista ufficiale di Keira Knightley per la promozione del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-03T10:11:42.266822+00:00'),
('34ae0cb9-922e-48ba-9a10-52752da79507', 73, 'Curiosità & Retroscena', 'La genesi del nome di Darth Maul', 'Il nome del villain Darth Maul fu ideato da George Lucas ispirandosi al termine inglese ''maul'', che indica un pesante maglio o uno strumento da spacco, riflettendo la natura brutale e aggressiva del personaggio.', 'Artbook ufficiale ''The Art of Star Wars: Episode I - The Phantom Menace''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-03T10:11:42.266822+00:00'),
('f683c250-564d-435d-8772-05741316a19f', 292, 'Curiosità & Retroscena', 'Il rifiuto iniziale del libro', 'Taika Waititi ha letto il romanzo ''Caging Skies'' di Christine Leunens nel 2011 ma ha esitato ad adattarlo immediatamente per via della sensibilità del tema. Ci sono voluti diversi anni prima che decidesse di trasformare il dramma originale in una satira tagliente, ritenendo l''umorismo l''arma migliore per contrastare l''ascesa globale dell''intolleranza.', 'Intervista ufficiale al regista per Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:56:29.12047+00:00'),
('524fc695-052c-449b-948d-c662f5fd6a2d', 292, 'Casting & Scelte', 'La scelta del cast maori e polinesiano per la troupe', 'Pur essendo una produzione hollywoodiana ambientata in Europa, Taika Waititi ha fortemente voluto al suo fianco storici collaboratori neozelandesi, tra cui il direttore della fotografia Mihai Mălaimare Jr. e la costumista Mayes C. Rubeo, creando sul set un''atmosfera familiare e multiculturale unica per una pellicola sulla Germania nazista.', 'Making-of ufficiale ''The Making of Jojo Rabbit''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:56:29.12047+00:00'),
('afb4f63b-61b9-4011-88df-d31dbe71be04', 292, 'Citazioni & Easter Egg', 'Le scarpe da ginnastica di Hitler', 'Per sottolineare la natura fanciullesca e manipolata dell''amico immaginario di Jojo, Taika Waititi indossa calzature con suola in gomma dal design vagamente moderno e compie deliberati riferimenti visivi al dittatore comico de ''Il grande dittatore'' di Charlie Chaplin.', 'Commento audio del regista nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:56:29.12047+00:00'),
('2c430fc7-c818-441c-a82c-7751e1c17ba7', 292, 'Aneddoti dal set', 'La reazione emotiva di Thomasin McKenzie sul set', 'Per mantenere intatta la spontaneità delle reazioni di fronte a scene particolarmente intense, la giovane attrice Thomasin McKenzie (Elsa) veniva tenuta parzialmente isolata da alcune delle gag più surreali girate da Taika Waititi e Roman Griffin Davis, così da preservare il senso di isolamento del suo personaggio nascosto nella soffitta.', 'Intervista dal set rilasciata da Thomasin McKenzie', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:56:29.12047+00:00'),
('3095398d-2bce-4076-9415-c289eff563f2', 256, 'Casting & Scelte', 'La raccomandazione decisiva di Stephen King', 'Stephen King aveva in mente fin dall''inizio Michael Clarke Duncan per il ruolo di John Coffrey, avendolo notato nel film ''Armageddon''. Fu proprio lo scrittore a raccomandare caldamente l''attore al regista Frank Darabont durante una conversazione telefonica.', 'Commento audio del regista nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:48:15.04997+00:00'),
('3571c227-34ce-4f2e-a6dc-bafbd1dabe46', 256, 'Effetti speciali & Trucco', 'Le altezze ingannevoli sul set', 'Nonostante Michael Clarke Duncan fosse alto circa 1,96 metri, la produzione dovette utilizzare angolazioni di ripresa specifiche, pavimenti rialzati e arredi in scala ridotta per far sembrare il suo personaggio alto oltre 2,10 metri accanto a Tom Hanks.', 'Documentario ''Walking the Mile: The Making of The Green Mile''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:48:15.04997+00:00'),
('796a48d9-5a5b-492f-a275-6815965bc35c', 256, 'Aneddoti dal set', 'Le vere lacrime di Michael Clarke Duncan', 'Durante la scena in cui John Coffrey deve trattenere le lacrime mentre viene condotto verso la sedia elettrica, l''attore Michael Clarke Duncan pianse realmente, sopraffatto dall''emozione di dover dire addio al personaggio e alla troupe.', 'Intervista a Michael Clarke Duncan per Entertainment Tonight', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:48:15.04997+00:00'),
('84c25eb8-1c8d-4b0f-bdfc-ecee645c6f3e', 256, 'Segreti di produzione', 'Il topo attore e le sue controfigure', 'Per il personaggio del topo Mr. Jingles furono impiegati oltre trenta roditori addestrati, affiancati da versioni in CGI e da un modello robotico telecomandato realizzato dalla squadra di effetti speciali per le sequenze più complesse.', 'Special feature ''Creating Mr. Jingles'' nel DVD di edizione speciale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:48:15.04997+00:00'),
('20cfdd36-7140-442a-bc87-15f5956eaadc', 256, 'Aneddoti dal set', 'La paura reale di Tom Hanks per le scosse', 'Durante le riprese della sequenza finale della sedia elettrica, Tom Hanks ha ammesso di aver provato un reale e profondo disagio psicologico nel sedersi su quella sedia di scena, pur sapendo che non era collegata ad alcun generatore di corrente.', 'Intervista d''archivio a Tom Hanks', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:48:15.04997+00:00'),
('6d4edb14-1a5c-4813-8a63-8886f4143471', 266, 'Casting & Scelte', 'La telefonata di Hugh Grant per il compagno di Benoit Blanc', 'Nel film viene rivelato brevemente che Benoit Blanc convive con un uomo di nome Phillip, interpretato in un cameo non accreditato da Hugh Grant. Rian Johnson ha confermato che la scelta di inserire Grant è nata in modo naturale dopo che gli sceneggiatori avevano bisogno di mostrare la vita domestica del detective.', 'Intervista ufficiale di Rian Johnson per Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:48:24.559407+00:00'),
('b7ece9a3-0ae8-4f32-a589-75f03d4b2c92', 365, 'Casting & Scelte', 'Il rifiuto iniziale di Harrison Ford per Eddie Valiant', 'Prima che Bob Hoskins ottenesse la parte, Robert Zemeckis e Steven Spielberg considerarono seriamente Harrison Ford per il ruolo del detective Eddie Valiant, ma il cachet richiesto dall''attore era all''epoca troppo elevato per il budget iniziale della produzione.', 'Intervista ufficiale di Robert Zemeckis nel making-of del DVD', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 1, '2026-11-03T15:42:20.849731+00:00'),
('2b922292-c836-461b-b099-466b78d6f5a8', 365, 'Effetti speciali & Trucco', 'L''uso di pupazzi meccanici per interagire con gli attori', 'Per permettere a Bob Hoskins di avere una controparte fisica reale sul set durante le scene con i cartoon, la produzione commissionò alla Industrial Light & Magic e al negozio di Jim Henson pupazzi animatronici e sagome di gomma piuma posizionate esattamente dove poi sarebbero stati inseriti i personaggi animati in post-produzione.', 'Documentario di produzione Industrial Light & Magic', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 2, '2026-11-03T15:42:20.849731+00:00'),
('854cac57-e6ed-4e85-b1a0-769c74f710dc', 365, 'Aneddoti dal set', 'La tecnica di Bob Hoskins per recitare nel vuoto', 'Per abituarsi a recitare senza controparti fisiche, Bob Hoskins studiò intensamente i movimenti dei mimo e portò sempre con sé sul set un bastoncino con all''estremità una pallina da tennis, utilizzato come punto di fuoco visivo per simulare lo sguardo all''altezza degli occhi dei personaggi animati.', 'Commento audio del regista Robert Zemeckis', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 3, '2026-11-03T15:42:20.849731+00:00'),
('a4d4eb2f-08c2-497f-be45-f5e9cd8082fc', 365, 'Segreti di produzione', 'La fusione tra animazione classica e cinepresa in movimento', 'A differenza dei precedenti film in tecnica mista come ''Mary Poppins'', Zemeckis volle che la cinepresa si muovessi continuamente nello spazio con carrelli e gru complessi; per farlo, gli animatori dovettero ridisegnare ogni singolo fotogramma a mano inserendo ombre, riflessi e fonti di luce dinamiche coerenti con l''illuminazione reale del set.', 'The Making of Who Framed Roger Rabbit (libro ufficiale)', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 4, '2026-11-03T15:42:20.849731+00:00'),
('d9d887f1-7a32-4e0a-ad48-ac1737d6dd2a', 365, 'Citazioni & Easter Egg', 'Il crossover storico tra Warner Bros. e Disney', 'Il film segnò la prima e storica apparizione congiunta sullo stesso schermo di personaggi storici della Warner Bros. (come Bugs Bunny e Daffy Duck) e della Disney (come Topolino e Paperino), grazie a un accordo legale rigidissimo che imponeva lo stesso identico minutaggio e la medesima importanza visiva per entrambe le fazioni.', 'Note di produzione ufficiali della Walt Disney Pictures', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 5, '2026-11-03T15:42:20.849731+00:00'),
('b6938d77-5173-4ddd-8b3f-f17f7c7246b0', 293, 'Casting & Scelte', 'Il cameo vocale di Justin Theroux', 'L''attore Justin Theroux appare non accreditato nel film interpretando l''ospite del talk show di Murray Franklin, Ethan Chase, che introduce sul palco il personaggio di Arthur Fleck prima della tragica intervista in diretta.', 'Titoli di coda e database cinematografico IMDb Pro', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:56:33.512086+00:00'),
('aeee9bd0-97c9-4985-a549-dc2174c97a3b', 293, 'Segreti di produzione', 'L''ambientazione temporale ambigua', 'Sebbene il film sia uscito nel 2019, la direzione artistica, i costumi, le automobili e i modelli dei televisori di scena sono stati deliberatamente progettati per evocare l''estetica e l''atmosfera della New York City tra la fine degli anni ''70 e l''inizio degli anni ''80.', 'Intervista allo scenografo Mark Friedberg', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:56:33.512086+00:00'),
('50083117-4c20-4eba-afab-0159db1d0335', 293, 'Aneddoti dal set', 'La sequenza del frigorifero', 'Nella scena in cui Arthur entra completamente nudo nel frigorifero di casa dopo aver vissuto un momento di forte crisi, l''azione non era rigidamente pianificata nel copione. Joaquin Phoenix ha deciso autonomamente di compiere quel gesto bizzarro sul set, cogliendo di sorpresa la troupe.', 'Commento audio e interviste al regista Todd Phillips', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:56:33.512086+00:00'),
('68486355-7c54-4ab7-9d8f-3686b107340e', 258, 'Casting & Scelte', 'La voce segreta del Principe', 'Harry Stockwell fu scelto per doppiare il Principe dopo una lunga ricerca, ma la sua partecipazione fu ridotta drasticamente perché i problemi di animazione resero difficile far combaciare i suoi movimenti con quelli del personaggio. Originariamente il Principe avrebbe dovuto avere un ruolo molto più ampio e cantare ulteriori brani tagliati in fase di montaggio.', 'Disney Archives & Making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:48:18.695617+00:00'),
('bcf2190b-e80c-4ce5-ac86-5f87e3bad6a0', 258, 'Curiosità & Retroscena', 'La paura del sindacato', 'Walt Disney mantenne il massimo riserbo sui nomi dei doppiatori del film, in particolare su Adriana Caselotti e Harry Stockwell, per evitare che chiedessero compensi troppo alti o che venissero assorbiti da sindacati cinematografici, firmando così la loro esclusività con lo studio.', 'Note di produzione storiche degli studi Disney', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:48:18.695617+00:00'),
('11968cd2-8737-4ada-9bb7-8cb7c4c3f75d', 258, 'Casting & Scelte', 'Il doppiatore originale di Brontolo', 'Il celebre attore di vaudeville Billy Gilbert fu scelto per dare voce a Brontolo non solo per le sue battute, ma soprattutto per la sua straordinaria abilità nel produrre starnuti comici e sbuffi d''ira unici, registrati senza l''ausilio di effetti sonori artificiali.', 'Archivi storici di doppiaggio Disney', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:48:18.695617+00:00'),
('c78ea72d-c8ec-44bc-bb54-644f758f8b4b', 258, 'Casting & Scelte', 'La regina e la voce della strega', 'Lucille La Verne doppiò sia la Regina Cattiva che la Strega; per ottenere la voce roca e spettrale della vecchia megera, l''attrice si tolse la dentiera prima di registrare le sue battute in studio.', 'Documentario ufficiale ''The Making of Snow White''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:48:18.695617+00:00'),
('f8652918-6250-4558-97bb-27418f930eaa', 258, 'Segreti di produzione', 'L''uso pionieristico della cinepresa multiplana', 'Per dare un eccezionale senso di profondità tridimensionale alle sequenze nel bosco e alla fuga di Biancaneve, gli animatori utilizzarono la cinepresa multiplana, un imponente macchinario che permetteva di filmare strati multipli di illustrazioni disposti a diverse distanze dalla lente.', 'Manuale tecnico degli studi Disney del 1938', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:48:18.695617+00:00'),
('4e7327cf-84bc-4848-9c1a-079da5bfaa63', 258, 'Effetti speciali & Trucco', 'Il colore sulle guance dei cel', 'Per dare un aspetto più vivo e realistico a Biancaneve, i tecnici applicarono fisicamente del vero blush cosmetico rosso sul retro dei fogli di cel trasparente durante la fase di inchiostrazione e pittura.', 'The Disney Studio Story di Richard Schickel', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:48:18.695617+00:00'),
('5d6dfa6d-7af7-4208-a17a-2bc48df949c1', 269, 'Casting & Scelte', 'L''ispirazione per il personaggio di Ajeje Brazorf', 'Il celebre nome del controllore del tram, Ajeje Brazorf, nasce da un tormentone ideato dal trio durante gli anni della gavetta nei cabaret milanesi come lo Zelig. Il nome fu ispirato da una storpiatura fonetica casuale e divenne un marchio di fabbrica riproposto anche nel film.', 'Intervista retrospettiva ad Aldo, Giovanni e Giacomo', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:48:28.490169+00:00'),
('d01f6431-29c9-42d6-b7db-c616169ac5d7', 269, 'Curiosità & Retroscena', 'La regia condivisa con Marcello Cesena', 'Sebbene accreditato ufficialmente ad Aldo Baglio e alla sceneggiatura collettiva, il film vide una fortissima collaborazione registica sul campo con Marcello Cesena, collega storico del gruppo nei programmi della Gialappa''s Band e in TV.', 'Note di produzione e pressbook ufficiale Medusa', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:48:28.490169+00:00'),
('20f3a9b5-7689-4c80-8954-bba565438fc8', 269, 'Aneddoti dal set', 'L''improvvisazione nella scena della dogana', 'Molti dei dialoghi all''interno della Alfa Romeo 164 durante i viaggi on the road non erano strettamente blindati dalla sceneggiatura, lasciando ampio spazio all''interplay e all''improvvisazione spontanea tipica del loro stile teatrale.', 'Contenuti extra e making-of del DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:48:28.490169+00:00'),
('f076a936-5de0-4e2f-a630-f373db9413f7', 269, 'Segreti di produzione', 'Le location reali del viaggio verso il Sud', 'Nonostante il film racconti un lungo viaggio verso la Puglia per il matrimonio, gran parte delle scene ambientate lungo le strade statali e nelle stazioni di servizio furono girate in realtà tra il Lazio, la Toscana e le periferie lombarde per contenere i costi di trasferta.', 'Diario di bordo e location report delle riprese', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:48:28.490169+00:00'),
('8f32002c-f943-434e-bda1-f416a753592b', 269, 'Citazioni & Easter Egg', 'Il cameo vocale e le collaborazioni musicali degli Area', 'La colonna sonora del film vanta importanti contributi e rimandi alla cultura musicale italiana degli anni settanta, tra cui brani storici e collaborazioni coordinate da Samuele Bersani e altri artisti vicini all''ambiente milanese del trio.', 'Crediti ufficiali della colonna sonora del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:48:28.490169+00:00'),
('dd6df6b5-c425-4931-bfaa-07c1300089b9', 366, 'Casting & Scelte', 'Il rifiuto iniziale di Michelle Pfeiffer per il ruolo di Clarice', 'Il regista Jonathan Demme voleva fortemente Michelle Pfeiffer per la parte di Clarice Starling, ma l''attrice rifiutò il ruolo ritenendo la sceneggiatura e la tematica della storia troppo violente e oscure per i suoi gusti.', 'Intervista ufficiale a Jonathan Demme e Vanity Fair', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 1, '2026-11-03T15:43:05.886504+00:00'),
('dc5ed156-1d59-4c58-945d-c3c2107bc24d', 366, 'Casting & Scelte', 'Gene Hackman e la prima opzione per Hannibal Lecter', 'Inizialmente la Orion Pictures aveva acquistato i diritti del romanzo con l''intenzione di far dirigere e interpretare il film a Gene Hackman nel ruolo di Hannibal Lecter; l''attore declinò l''offerta dopo aver letto il romanzo per via dei toni ritenuti eccessivamente truculenti.', 'Note di produzione e retroscena storici Orion Pictures', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 2, '2026-11-03T15:43:05.886504+00:00'),
('2897b7cb-3212-447d-9fad-752bf5cce046', 366, 'Curiosità & Retroscena', 'La celebre battuta improvvisata da Anthony Hopkins sui fagioli', 'La celebre sequenza in cui Hannibal Lecter descrive come ha mangiato il fegato dello stakanovista con ''fagioli fava e un eccellente Chianti'' includeva un suono sibilante con la lingua che Anthony Hopkins inventò spontaneamente durante le prove per terrorizzare Jodie Foster.', 'Documentario Making-of e interviste al cast', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 3, '2026-11-03T15:43:05.886504+00:00'),
('955b42c5-4c01-4b7c-832f-0169c8f8c2c7', 149, 'Casting & Scelte', 'La scelta di Donald Pleasence come ''Il Capo''', 'Il celebre attore britannico Donald Pleasence fu ingaggiato per interpretare il malvagio antagonista principale, noto come ''Il Capo'', portando sul set una vena di raffinata ironia tipica della commedia britannica in contrasto con la fisicità della coppia.', 'Note di produzione e biografia ufficiale di Donald Pleasence', TRUE, 'IA (Admin)', 'IA Verificata', 4, 3, '2026-11-02T15:12:58.551261+00:00'),
('2a053262-0dd5-4bd1-bce3-5114c38bf424', 149, 'Aneddoti dal set', 'La celebre sequenza del coro dei sommozzatori', 'Una delle scene più surreali e memorabili del film vede Bud Spencer e Terence Hill infiltrarsi in una prova di un coro di pompieri o sommozzatori che provano ''La ballata di Dune Buggy''; la canzone fu composta dai fratelli Guido e Maurizio De Angelis (noti come Oliver Onions) e divenne un enorme successo discografico internazionale.', 'Documentario retrospettivo sulla colonna sonora dei fratelli De Angelis', TRUE, 'IA (Admin)', 'IA Verificata', 4, 4, '2026-11-02T15:12:58.551261+00:00'),
('04845e34-3cb2-4b47-bb00-e3ccaaecef31', 149, 'Segreti di produzione', 'Le riprese in Spagna tra Madrid e Roma', 'Sebbene il film abbia forti connotati legati all''immaginario italiano e romano (come la celebre gara a birra e salsicce presso un chiosco che ricorda le trattorie della periferia romana), buona parte delle riprese esterne e delle sequenze d''azione fu effettuate in Spagna, sfruttando gli studi e le location nei dintorni di Madrid.', 'Archivio storico della produzione cinematografica italospagnola degli anni ''70', TRUE, 'IA (Admin)', 'IA Verificata', 5, 5, '2026-11-02T15:12:58.551261+00:00'),
('97db12ac-242e-4431-8c86-c989952837b0', 149, 'Curiosità & Retroscena', 'Il doppiaggio storico di Bud Spencer e Terence Hill', 'Come da consuetudine per i film della coppia diretti in quegli anni, le voci italiane definitive non corrispondevano sempre integralmente alle prese di sonoro in diretta sul set: Bud Spencer fu doppiato dal celebre Glauco Onorato, mentre Terence Hill mantenne la sua voce o fu affiancato da Pino Locchi in alcune sequenze specifiche.', 'Dizionario del doppiaggio cinematografico italiano', TRUE, 'IA (Admin)', 'IA Verificata', 1, 6, '2026-11-02T15:12:58.551261+00:00'),
('db16c269-d741-46f0-aa75-7c75e565c86f', 343, 'Casting & Scelte', 'Il rifiuto iniziale di Hugh Grant', 'Inizialmente Hugh Grant rifiutò il ruolo di Will Freeman perché riteneva che il personaggio fosse eccessivamente egoista e sgradevole, ma cambiò idea dopo aver letto il romanzo omonimo di Nick Hornby e capito la profonda evoluzione del protagonista.', 'Intervista promozionale ufficiale e note di produzione', TRUE, 'IA (Admin)', 'IA Verificata', 5, 1, '2026-11-02T15:13:18.578303+00:00'),
('afbdfb01-07ae-4f5e-ac93-42ba32081363', 343, 'Casting & Scelte', 'La lunga ricerca per il piccolo Marcus', 'I registi Chris e Paul Weitz visionarono centinaia di giovani attori prima di scegliere Nicholas Hoult, il quale si presentò ai provini con un taglio di capelli e un abbigliamento giudicati perfetti per incarnare il bizzarro e isolato Marcus.', 'Contenuto speciale ''Making of About a Boy'' nel DVD', TRUE, 'IA (Admin)', 'IA Verificata', 2, 2, '2026-11-02T15:13:18.578303+00:00'),
('7dd43667-6a44-470c-a539-3c5c3c80f352', 343, 'Curiosità & Retroscena', 'L''ispirazione per il titolo della colonna sonora', 'La celebre colonna sonora del film fu interamente affidata al cantautore Badly Drawn Boy (Damon Gough), il cui nome d''arte ispirò in parte l''atmosfera musicale malinconica ma ironica che permea l''intera pellicola.', 'Note di produzione e recensione ufficiale della colonna sonora', TRUE, 'IA (Admin)', 'IA Verificata', 1, 3, '2026-11-02T15:13:18.578303+00:00'),
('f1c9b392-d93e-4ff1-a8c0-e92bfc3c4cc9', 343, 'Aneddoti dal set', 'L''imbarazzo della scena di canto a scuola', 'Nicholas Hoult ha dichiarato in diverse interviste che la scena in cui Marcus è costretto a cantare ''Killing Me Softly with His Song'' davanti all''intera scuola fu particolarmente imbarazzante da girare a causa delle numerose comparse presenti.', 'Intervista retrospettiva a Nicholas Hoult', TRUE, 'IA (Admin)', 'IA Verificata', 2, 4, '2026-11-02T15:13:18.578303+00:00'),
('8950525b-5341-41e1-b2ab-8272c39d019a', 265, 'Citazioni & Easter Egg', 'Il coniglio di peluche come omaggio a David Lynch', 'Nella stanza di Marta è visibile un coniglio di peluche, chiaro omaggio al cortometraggio ''Rabbits'' di David Lynch. Rian Johnson ha inserito questo dettaglio per richiamare le atmosfere surreali e misteriose tipiche del cinema di Lynch.', 'Analisi visiva ufficiale e note di produzione del reparto scenografia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:48:22.685275+00:00'),
('2320fc19-2318-4184-861e-8a92a5eafe23', 265, 'Segreti di produzione', 'L''autenticità dei giochi da tavolo nella villa', 'La vasta collezione di giochi da tavolo e rompicapi presenti nella villa dei Thrombey non era composta da oggetti di scena falsi, ma da veri giochi vintage acquistati appositamente da rigattieri del Massachusetts per dare un tocco di autenticità antiquata.', 'Intervista dello scenografo David Crank per Architectural Digest', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:48:22.685275+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('f3a387da-6a4d-41d0-afd8-bb7f0ad81d79', 265, 'Aneddoti dal set', 'Il vero fumo di sigaretta sul set', 'Per mantenere l''atmosfera tesa e classica del giallo tradizionale, la produzione ha fatto uso estensivo di sigarette di erbe senza tabacco per le numerose scene in cui i personaggi fumano in salotto, rispettando le normative sul fumo nei luoghi chiusi del Massachusetts.', 'Reportage dal set di The Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:48:22.685275+00:00'),
('66b3a91f-8147-483d-8783-d2256c7471ce', 265, 'Casting & Scelte', 'Il nome di Benoit Blanc ispirato a un videogioco', 'Rian Johnson ha rivelato di aver scelto il nome del detective Benoit Blanc ispirandosi parzialmente ai classici giochi da tavolo investigativi e ai tropi della letteratura gialla tradizionale, unendo la sonorità francese classica a una struttura da enigma logico.', 'Intervista promozionale a Rian Johnson per Vanity Fair', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:48:22.685275+00:00'),
('d29fb4e9-f6bb-49d4-b251-ed1489576184', 277, 'Casting & Scelte', 'La riscrittura continua sul set di Quentin Tarantino', 'Quentin Tarantino venne ingaggiato come script doctor non accreditato per lucidare i dialoghi, in particolare per infondere maggiore brio alle battute scambiate tra Sean Connery e Nicolas Cage. Molte delle battute taglienti e dei botta e risposta verbali tra Stanley Goodspeed e John Mason furono perfezionate da Tarantino durante le riprese a San Francisco.', 'Audio commento del regista Michael Bay e interviste di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:48:42.646867+00:00'),
('892e008f-aaec-4fa9-a287-609a5a46824c', 277, 'Casting & Scelte', 'Il rifiuto iniziale di Arnold Schwarzenegger', 'Prima che il ruolo del Dr. Stanley Goodspeed fosse affidato a Nicolas Cage, la Disney e i produttori offrirono la parte ad Arnold Schwarzenegger. L''attore rifiutò il progetto a causa di impegni concomitanti e di disaccordi sulla direzione creativa del personaggio.', 'Archivi di pre-produzione Disney e biografie ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:48:42.646867+00:00'),
('a809e1f4-0a26-4440-aaa8-74b58c40cd03', 277, 'Aneddoti dal set', 'I reali ex detenuti e guardie di Alcatraz come comparse', 'Per aumentare il realismo delle sequenze ambientate nella prigione federale, Michael Bay e la produzione assunsero alcune vere ex guardie e persino alcuni ex detenuti che avevano scontato la pena ad Alcatraz prima della sua chiusura nel 1963, impiegandoli come comparse e consulenti storici sul set.', 'Documentario ''The Rock: The Making of an Action Hit''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:48:42.646867+00:00'),
('c16a4413-28dc-4da6-b0af-f8543e0261fd', 366, 'Effetti speciali & Trucco', 'Le reali fonti di ispirazione per il look di Buffalo Bill', 'Il truccatore e il costumista modellarono il personaggio di Jame Gumb (Buffalo Bill), interpretato da Ted Levine, fondendo le caratteristiche criminologiche reali di famosi serial killer americani tra cui Ted Bundy, Ed Gein e Gary Heidnik.', 'Speciali DVD e commento tecnico del reparto trucco', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 4, '2026-11-03T15:43:05.886504+00:00'),
('ec5f3bac-9cea-4707-852e-d02cd05ba372', 301, 'Casting & Scelte', 'Robert Redford unico e primo nome sulla lista', 'Il regista J.C. Chandor ha scritto la sceneggiatura pensando esclusivamente a Robert Redford e gli ha inviato il copione senza passare per intermediari o agenti, ottenendo l''approvazione dell''attore in meno di quarantott''ore.', 'Intervista ufficiale di J.C. Chandor per Variety al Festival di Cannes 2013', TRUE, 'IA (Admin)', 'IA Verificata', 2, 8, '2026-11-02T15:13:39.273448+00:00'),
('feedb435-a891-4c21-b846-0ce71d36e71a', 301, 'Aneddoti dal set', 'La quasi totale assenza di dialoghi nella sceneggiatura originale', 'Il copione scritto da J.C. Chandor constava di sole 32 pagine a causa della quasi totale assenza di battute; l''unica frase pronunciata da Robert Redford all''inizio del film fu aggiunta in post-produzione per volere dello stesso attore.', 'Note di produzione ufficiali della Roadside Attractions', TRUE, 'IA (Admin)', 'IA Verificata', 3, 9, '2026-11-02T15:13:39.273448+00:00'),
('064b7a1e-d332-475e-abc8-7a3cae4c9efd', 301, 'Effetti speciali & Trucco', 'L''uso estensivo di veri serbatoi d''acqua e macchine per onde', 'Per simulare la furia dell''Oceano Indiano senza ricorrere a eccessiva computer grafica, la troupe ha impiegato enormi generatori di onde meccaniche e idranti ad altissima pressione direttamente sui modellini e sulle sezioni reali dello yacht.', 'Special report di American Cinematographer sulla fotografia di Frank G. DeMarco', TRUE, 'IA (Admin)', 'IA Verificata', 3, 10, '2026-11-02T15:13:39.273448+00:00'),
('14fcf5ea-44da-490d-a841-c770cd172a4f', 301, 'Aneddoti dal set', 'Il grave infortunio all''udito di Robert Redford', 'Durante le riprese delle sequenze della tempesta, un potente getto d''acqua ad alta pressione ha colpito in piena faccia Robert Redford, perforandogli parzialmente un timpano; l''attore ha tuttavia continuato a girare per diversi giorni prima di ricevere cure mediche adeguate.', 'Intervista retrospettiva a Robert Redford per NPR e USA Today', TRUE, 'IA (Admin)', 'IA Verificata', 3, 11, '2026-11-02T15:13:39.273448+00:00'),
('b75711c9-854a-4ebe-b8dc-6a7af3012849', 301, 'Segreti di produzione', 'La costruzione di molteplici repliche dello scafo', 'La produzione ha fatto costruire tre differenti sezioni dello yacht ''Virginia Jean'' su piattaforme cardaniche mobili per poter simulare l''affondamento progressivo, l''inclinazione e i ribaltamenti dello scafo durante i vari stadi della narrazione.', 'Articolo tecnico di Hollywood Reporter sugli effetti speciali fisici del film', TRUE, 'IA (Admin)', 'IA Verificata', 5, 12, '2026-11-02T15:13:39.273448+00:00'),
('01e7c31b-8ea1-42d9-b30a-e8c366ff69aa', 274, 'Aneddoti dal set', 'La tensione reale tra i protagonisti', 'Durante le riprese, Jennifer Grey e Patrick Swayze soffrirono di una forte tensione reciproca, causata dai dissapori avuti sul set del film ''Alba rossa'' (1984). Questa rivalità iniziale rese difficile girare alcune scene romantiche, costringendoli a chiarirsi prima di girare la celebre sequenza del loft.', 'Autobiografia di Patrick Swayze ''The Time of My Life''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:48:32.922323+00:00'),
('56bbacff-d587-4bab-b8de-82d46cfc4792', 274, 'Segreti di produzione', 'Il freddo polare durante le riprese estive', 'Nonostante il film sia ambientato in piena estate nel luglio del 1963, le riprese si svolsero in autunno a Mountain Lake, in Virginia, e a Lake Lure, nella Carolina del Nord. Gli attori dovettero ballare con temperature vicine allo zero, e l''acqua del lago in cui girarono la celebre scena della presa era così fredda che le labbra di Jennifer Grey divennero blu.', 'Special TV ''Dirty Dancing: The E! True Hollywood Story''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:48:32.922323+00:00'),
('6bc33b7f-3b4a-444b-86b5-6f9a808a2c42', 134, 'Casting & Scelte', 'Il rifiuto del vero campione Joe Frazier', 'Prima di scegliere Mr. T e di valutare altri contendenti, Sylvester Stallone aveva inizialmente offerto un ruolo di rilievo nel film all''ex campione del mondo dei pesi massimi Joe Frazier, con cui aveva già avuto contatti nei precedenti film della saga. Frazier tuttavia rifiutò l''offerta perché riteneva che il pugilato cinematografico di Stallone non rispecchiasse la vera brutalità e tecnica della boxe professionistica.', 'Archivio storico e biografie ufficiali sulla produzione di Rocky', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:05:03.284836+00:00'),
('8a319c9f-abbb-43b4-b2eb-a1ee48abb2ba', 274, 'Curiosità & Retroscena', 'La bocciatura della visione originale del regista', 'Il regista Emile Ardolino voleva inserire inizialmente sequenze di ballo molto più cupe e vicine al vero mambo underground di New York, ma i produttori imposero toni più accessibili al grande pubblico. Nonostante i tagli, la coreografa Kenny Ortega mantenne una forte carica sensuale che spaventò i dirigenti della Vestron.', 'Commento audio del regista nel DVD celebrativo del ventesimo anniversario', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:48:32.922323+00:00'),
('8afde08a-69d0-46ad-a632-94d4369a962a', 274, 'Casting & Scelte', 'La scelta iniziale per il ruolo di Johnny Castle', 'Prima che Patrick Swayze ottenesse la parte, i produttori avevano offerto il ruolo di Johnny Castle a Billy Zane. Zane era un ballerino eccellente, ma durante le prove si rivelò incapace di trovare la giusta chimica con Jennifer Grey, portando alla sua sostituzione immediata.', 'Intervista alla sceneggiatrice Eleanor Bergstein', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:48:32.922323+00:00'),
('ae023e20-e5a9-4d56-a41d-4cf71b13edd1', 274, 'Aneddoti dal set', 'L''improvvisazione delle risate nella scena dello studio', 'Nella famosa scena in cui Johnny fa scivolare la mano sul braccio di Baby facendola ridere istericamente per il solletico, l''ilarità di Jennifer Grey non era recitata. L''attrice soffriva terribilmente il solletico e la sua reazione scomposta e genuina convinse il regista a mantenere la ripresa nel montaggio finale.', 'Documentario ''Dirty Dancing: The Phenomenon''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:48:32.922323+00:00'),
('e6fa7d80-238b-4411-9e1b-672cbabe6bcc', 274, 'Curiosità & Retroscena', 'Il vero lavoro di riscrittura della sceneggiatrice', 'Eleanor Bergstein basò gran parte del personaggio di Baby e delle dinamiche familiari sulle sue reali esperienze di vacanza estiva nelle Catskills con la famiglia e sulla sua gioventù trascorsa a ballare nei club clandestini.', 'Note di produzione originali della Vestron Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:48:32.922323+00:00'),
('412b0c1a-6bb4-452a-970a-c82c9ca940e4', 280, 'Effetti speciali & Trucco', 'La Pepsi Perfect e il design futurista', 'La bottiglia di Pepsi Perfect vista nella tavola calda del 2015 fu appositamente creata dal reparto artistico con un design aerodinamico unico per riflettere l''estetica futurista immaginata da Robert Zemeckis e dal production designer Rick Carter. L''oggetto divenne in seguito un vero e proprio cult per i collezionisti, spingendo la multinazionale a produrre edizioni limitate reali anni dopo.', 'Booklet del cofanetto Blu-ray e documentario di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:48:55.909399+00:00'),
('a8c6ce5a-185c-48d9-9a79-142e3a98732b', 280, 'Citazioni & Easter Egg', 'Il logo della Universal anni ''80', 'Nella sequenza iniziale ambientata nel 2015, quando la DeLorean atterra a Hill Valley, sullo sfondo si intravede un cinema che proietta ''Jaws 19'' e, poco prima, il cartellone luminoso mostra un logo della Universal Studios in versione futurista che riproduce fedelmente la grafica tridimensionale e scintillante utilizzata dallo studio tra gli anni ''70 e ''80.', 'Commento audio del regista Robert Zemeckis e dello sceneggiatore Bob Gale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:48:55.909399+00:00'),
('5b10cb6c-455b-4c74-b4d5-601fde5f92ea', 366, 'Segreti di produzione', 'L''ispirazione per l''insetto sulla bocca del poster', 'La celebre falena sulla bocca di Clarice Starling nel poster promozionale è in realtà una composizione artistica che riprende una celebre fotografia di Salvador Dalì intitolata ''In Voluptas Mors'', la quale ritrae sette nudi umani disposti a formare il teschio sul dorso dell''insetto (Acherontia atropos).', 'Archivio ufficiale Orion Pictures e note di marketing', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 5, '2026-11-03T15:43:05.886504+00:00'),
('1b2f99ff-b11e-4f96-837e-57cff8f5bda3', 277, 'Aneddoti dal set', 'L''infortunio sfiorato da Nicolas Cage con il fumogeno verde', 'Durante la celebre sequenza dello scontro a fuoco all''interno della doccia di Alcatraz, Nicolas Cage doveva estrarre un fumogeno militare verde e lanciarlo. Il dispositivo pirotecnico quasi gli esplose tra le mani a causa di una combustione anticipata, costringendo la troupe a interrompere temporaneamente le riprese per l''intervento dei paramedici sul set.', 'Making-of ufficiale e diari di produzione della troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:48:42.646867+00:00'),
('14349ebe-2b9e-4b9c-8e20-ea358add97f6', 277, 'Curiosità & Retroscena', 'La riscrittura dell''età e del background di John Mason', 'Nella prima stesura della sceneggiatura, il personaggio di John Mason interpretato da Sean Connery doveva essere un veterano della Seconda Guerra Mondiale ed ex spia britannica molto più anziano. La produzione modificò il passato del personaggio per renderlo un ex SAS imprigionato negli anni ''60, adattandolo meglio all''energia fisica richiesta per le scene d''azione.', 'Note di sceneggiatura originali di David Weisberg e Douglas Cook', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:48:42.646867+00:00'),
('6ff47fdf-579f-40e7-8514-3771fc73cc71', 277, 'Segreti di produzione', 'L''uso estensivo di modelli in scala per la distruzione dell''elicottero', 'La spettacolare scena in cui l''elicottero della polizia viene distrutto dai rotori sul molo di San Francisco non fu interamente realizzata con stunt reali. Per la fase più esplosiva e pericolosa dell''impatto, gli effetti speciali ricorsero a dettagliatissimi modelli in scala ridotta combinati con esplosioni controllate in studio.', 'Special sugli effetti speciali visivi e fisici del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:48:42.646867+00:00'),
('c5fec066-806a-4b66-9ff3-8282c106f9f0', 277, 'Casting & Scelte', 'Il cameo di Jim Caviezel come pilota di F-18', 'Prima di raggiungere la celebrità internazionale con ''La passione di Cristo'' e ''La sottile linea rossa'', un giovane Jim Caviezel ottunne una piccola parte nel film interpretando uno dei piloti di caccia F-18 Hornet nella sequenza finale del bombardamento.', 'Credit di fine film e archivi casting', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:48:42.646867+00:00'),
('faea3603-aa00-4128-94a1-e544fa137e95', 277, 'Citazioni & Easter Egg', 'Il vero microfilm e i riferimenti storici alla Guerra Fredda', 'Il microfilm che John Mason consegna a sua figlia Jade nelle battute finali del film contiene riferimenti a veri documenti declassificati del governo britannico risalenti agli anni ''60, un dettaglio inserito per dare maggiore spessore storico al passato dello spionaggio britannico del personaggio.', 'Note di produzione e scenografia del reparto artistico', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:48:42.646867+00:00'),
('5227b4fb-f9bf-4095-a4a8-93b4ec1fd273', 367, 'Casting & Scelte', 'Zazie Beetz e Patricia Arquette nel cast principale', 'Il progetto cinematografico vede la partecipazione di Zazie Beetz e Patricia Arquette nei ruoli centrali, affiancate da Myha''la, Paterson Joseph, Tom Felton e Heather Graham, diretti dal regista Kirill Sokolov.', 'Comunicati ufficiali di casting e note di produzione', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 1, '2026-11-03T16:05:09.994475+00:00'),
('3547cb03-9dbb-4232-bb1f-6cdd1de99ded', 272, 'Casting & Scelte', 'La scelta di Marina Massironi confermata dopo il successo di Tre uomini e una gamba', 'Marina Massironi fu fortemente voluta dal produttore Vittorio Cecchi Gori e dal trio per consolidare il quartetto comico di successo già rodato nei precedenti lungometraggi cinematografici. La sua presenza garantiva quella particolare alchimia sentimentale e comica che aveva decretato il trionfo al botteghino del film d''esordio del 1997.', 'Note di produzione ufficiali Medusa Film', TRUE, 'IA (Admin)', 'IA Verificata', 1, 8, '2026-11-02T15:17:11.138283+00:00'),
('95855d8a-62a1-4254-8eab-26ce0b0e558e', 272, 'Aneddoti dal set', 'La scena della statua vivente girata in condizioni di forte freddo', 'La sequenza in cui Giovanni interpreta una statua vivente ai Grandi Magazzini fu girata durante una sessione notturna autunnale a Milano con temperature particolarmente rigide. L''attore dovette mantenere la complessa posa statica per svariate ore consecutive, protetto solo da uno strato di trucco speciale a base di vernice acrilica e borotalco.', 'Intervista al reparto trucco nel Making-of del DVD', TRUE, 'IA (Admin)', 'IA Verificata', 4, 9, '2026-11-02T15:17:11.138283+00:00'),
('1cbfc352-e738-4d70-90f3-52b94b12057c', 272, 'Casting & Scelte', 'La genesi del personaggio di Antonio Catania', 'L''attore Antonio Catania veste i panni del notaio amico del trio dopo aver già collaborato con loro in ''Tre uomini e una gamba'' e ''Così è la vita''. La sua inclusione nel cast risponde alla precisa volontà del trio di mantenere una continuità di gruppo, inserendo una spalla comica formidabile in grado di bilanciare la malinconia della narrazione con gag surreali.', 'Intervista al cast nel making-of ufficiale dell''edizione in DVD', TRUE, 'IA (Admin)', 'IA Verificata', 2, 10, '2026-11-02T15:17:11.138283+00:00'),
('09356d96-4504-4125-b76a-1e4922e99941', 272, 'Aneddoti dal set', 'La sequenza del doppiaggio e i veri doppiatori', 'Nella scena in cui Giovanni lavora come doppiatore di ruoli marginali, la voce del fonico in sala di registrazione appartiene a Massimo De Rossi. Per mantenere l''autenticità della gag dell''esclamazione ''Ah, il corsetto!'', il trio ha preteso di girare in una vera sala di doppiaggio milanese, ripetendo la battuta decine di volte per trovare il perfetto tempismo comico.', 'Note di produzione e documentario sul backstage cinematografico', TRUE, 'IA (Admin)', 'IA Verificata', 2, 11, '2026-11-02T15:17:11.138283+00:00'),
('c38f39c9-c8da-420f-9979-a5dd77ce19e5', 272, 'Citazioni & Easter Egg', 'L''omaggio al teatro di Eduardo De Filippo', 'Durante le prove del Cyrano de Bergerac all''interno della pellicola, il modo in cui Aldo affronta la memorizzazione del testo e i battibecchi con Giacomo contengono espliciti riferimenti alle dinamiche delle compagnie di prosa tradizionali descritte da Eduardo De Filippo nella sua commedia ''Arte''.', 'Commento audio del regista e degli sceneggiatori nel cofanetto speciale', TRUE, 'IA (Admin)', 'IA Verificata', 5, 12, '2026-11-02T15:17:11.138283+00:00'),
('01a9b4b1-422f-49dd-b529-d05ea44a46ee', 367, 'Segreti di produzione', 'Il Virgil come ambientazione centrale', 'La narrazione si svolge interamente all''interno dell''edificio denominato Virgil, un luogo claustrofobico scelto dal regista per accentuare la tensione tra horror, action e commedia nera.', 'Sinossi ufficiale e note di regia', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 2, '2026-11-03T16:05:09.994475+00:00'),
('f15064a6-68e8-4272-acfa-255581cbf0ee', 367, 'Curiosità & Retroscena', 'La commistione di generi tra horror e action', 'Il film diretto da Kirill Sokolov unisce sequenze ad alto tasso di adrenalina e violenza grafica a un umorismo nerissimo, seguendo la cifra stilistica già nota del cineasta.', 'Recensioni e materiali promozionali ufficiali', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 3, '2026-11-03T16:05:09.994475+00:00'),
('1947f9eb-c9a6-4588-9f2a-84dbac4f0a05', 17, 'Curiosità & Retroscena', 'L''origine letteraria e il successo del romanzo', 'Il film è l''adattamento cinematografico dell''omonimo romanzo bestseller scritto da Alessandro D''Avenia e pubblicato nel 2010 da Mondadori, che ha venduto centinaia di migliaia di copie in Italia ed è stato tradotto in numerose lingue estere.', 'Note di produzione Lux Vide', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:31:57.398249+00:00'),
('776014e3-3806-416e-ac61-7d76beae6e1e', 17, 'Casting & Scelte', 'La scelta del regista Giacomo Campiotti', 'Il regista Giacomo Campiotti è stato scelto dalla produzione per la sua riconosciuta sensibilità nel dirigere storie di formazione e drammi giovanili, avendo già firmato con grande successo la regia della serie televisiva ''Braccialetti rossi''.', 'Intervista ufficiale al regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:31:57.398249+00:00'),
('48160086-2377-41d7-a7ee-14917d8231a8', 17, 'Casting & Scelte', 'Il debutto cinematografico di Gaia Weiss', 'Per il ruolo chiave di Beatrice, la ragazza di cui il protagonista è innamorato, è stata scelta l''attrice Gaia Weiss, qui al suo esordio sul grande schermo prima di intraprendere una carriera internazionale in produzioni come ''Vikings''.', 'Pressbook ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:31:57.398249+00:00'),
('1d978710-a81a-4606-a086-a676a75d4e93', 17, 'Aneddoti dal set', 'La preparazione atletica di Filippo Scicchitano', 'Filippo Scicchitano, per calarsi nei panni del sedicenne Leo, ha lavorato a stretto contatto con il regista per catturare l''energia irrequieta e la tipica passione adolescenziale, focalizzandosi sulla simbologia dei colori associati agli stati d''animo.', 'Making-of ufficiale dal set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:31:57.398249+00:00'),
('2afae49d-1b32-4b01-a4f3-40ff900a14bf', 17, 'Aneddoti dal set', 'Le riprese nelle scuole torinesi', 'Gran parte delle sequenze ambientate all''istituto superiore frequentato da Leo sono state girate in reali scuole di Torino e dintorni, coinvolgendo centinaia di comparse locali selezionate tramite casting aperti agli studenti.', 'Film Commission Torino Piemonte', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:31:57.398249+00:00'),
('88bd6ccb-7cf9-40ad-bbfb-ca5adb9021f6', 29, 'Casting & Scelte', 'La scelta di Dan Vadis per il ruolo principale', 'Il culturista statunitense Dan Vadis fu scelto per interpretare Ursus grazie alla sua imponente stazza fisica, diventando uno dei volti simbolo del cinema peplum italiano degli anni sessanta e alternandosi spesso con Steve Reeves e Reg Park.', 'Dizionario del cinema italiano - I film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:32:18.20538+00:00'),
('59963290-4638-4d75-8d5c-139587dbbd6b', 29, 'Curiosità & Retroscena', 'La regia di Domenico Paolella', 'Il film fu diretto da Domenico Paolella, un regista estremamente prolifico noto nel panorama cinematografico italiano per aver spaziato con grande versatilità dal peplum alla commedia, passando per i film storici e d''avventura.', 'Enciclopedia del cinema Treccani', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:32:18.20538+00:00'),
('6df2eb50-baab-4969-a4f8-feff228c0223', 29, 'Aneddoti dal set', 'La tradizione degli stuntman italiani nel peplum', 'Molte delle pericolose scene di combattimento nell''arena e le acrobazie più rischiose del film furono eseguite da stuntman professionisti italiani non accreditati, pilastri fondamentali dell''industria di Cinecittà dell''epoca.', 'Note di produzione d''epoca degli studios romani', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:32:18.20538+00:00'),
('8f49abf0-0144-47ae-adc5-73a45e115ebe', 29, 'Segreti di produzione', 'L''uso dei set di Cinecittà', 'Come la maggior parte dei peplum italiani dell''epoca, le imponenti scenografie dell''Antica Roma e delle arene furono realizzate interamente all''interno degli studi di Cinecittà, sfruttando la maestria degli scenografi e dei pittori di}}=-', 'Archivio storico di Cinecittà', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:32:18.20538+00:00'),
('019c8124-b9b7-4f19-b375-a136fd7fcb3e', 163, 'Casting & Scelte', 'La preparazione fisica e isolamento degli attori principali', 'Per prepararsi al complesso rapporto di scontro e riconciliazione, Vangelis Mourikis e Argyris Pandazaras hanno trascorso diversi giorni isolati nelle zone boschive vicine alla location delle riprese prima di girare le loro scene insieme. Il regista Georgis Grigorakis ha imposto loro di limitare i contatti per acuire la tensione tangibile tra padre e figlio.', 'Note di produzione ufficiali e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:32:44.763689+00:00'),
('dde16145-6442-4453-b511-a55df3e9bea8', 163, 'Curiosità & Retroscena', 'L''ispirazione cinematografica nei classici del western', 'Georgis Grigorakis ha dichiarato in diverse occasioni che, pur essendo un dramma contemporaneo legato a tematiche ecologiche ed economiche greche, la struttura narrativa e visiva di ''Digger'' ricalca volutamente i codici del western classico americano, in particolare il duello solitario e l''assedio alla frontiera.', 'Dichiarazioni del regista alla stampa internazionale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:32:44.763689+00:00'),
('20768597-f3c5-47d2-b8d1-2c9e80f9df9e', 163, 'Segreti di produzione', 'La gestione del sound design nella foresta', 'Il rumore costante dei macchinari pesanti della miniera contrapposto ai suoni naturali della foresta è stato interamente ricostruito in post-produzione per accentuare il senso di soffocamento e invasione tecnologica. Il fonico di presa diretta ha lavorato mesi per catturare i micro-suoni della terra scossa dai lavori industriali.', 'Intervista al reparto sonoro e note di montaggio audio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:32:44.763689+00:00'),
('f52b0029-eca7-45b5-8166-255f6ed300ea', 163, 'Segreti di produzione', 'La scelta del formato di ripresa in 1:1.37', 'Il regista Georgis Grigorakis e il direttore della fotografia Yannis Fotou hanno scelto di girare il film utilizzando l''insolito rapporto d''aspetto Academy 1:1.37. Questa scelta geometrica restrittiva è stata pensata appositamente per accentuare il senso di claustrofobia e isolamento dei personaggi, intrappolando visivamente i protagonisti all''interno del loro conflitto.', 'Note di produzione ufficiali del Thessaloniki International Film Festival', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:32:44.763689+00:00'),
('9ef87347-141d-4b16-8619-87a08cc0913e', 163, 'Casting & Scelte', 'La genesi del personaggio di Johnny attraverso i costumisti', 'Per definire l''aspetto di Johnny, il figlio ribelle interpretato da Argyris Pandazaras, il reparto costumi ha studiato a lungo le sottoculture giovanili urbane greche contrapposte all''estetica rurale del padre. L''attore ha collaborato attivamente nella scelta degli abiti logori per riflettere visivamente i vent''anni di distacco e il disagio esistenziale del personaggio.', 'Intervista al cast e ai reparti tecnici pubblicata su Cineuropa', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:32:44.763689+00:00'),
('13194096-86e4-4a01-ab29-8579027c5d24', 163, 'Aneddoti dal set', 'La gestione delle scene di confronto motorizzato', 'Durante le sequenze in cui i veicoli pesanti della miniera si muovono minacciosamente vicino alle strutture in legno della casa di Nikitas, la troupe ha dovuto impiegare operatori di macchina specializzati in guida off-road estrema. Gli spazi ristretti della foresta del Parnete hanno reso ogni manovra dei camion ad alto rischio di collisione accidentale con gli alberi secolari protetti.', 'Making-of ufficiale e diario di bordo delle riprese', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:32:44.763689+00:00'),
('bf421e52-4256-4ff5-b340-398229232d94', 220, 'Casting & Scelte', 'La scelta di Emil Jannings per il ruolo di Nerone', 'Il celebre attore tedesco Emil Jannings fu fortemente voluto dalla produzione per interpretare l''imperatore Nerone, sfruttando la sua straordinaria abilità nella mimica facciale e nella caratterizzazione dei despoti ossessivi, un ruolo che avrebbe poi riproposto con sfumature simili in altre grandi produzioni storiche dell''epoca.', 'Archivio Storico dell''Unione Cinematografica Italiana (UCI)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:33:22.088048+00:00'),
('9ff416cd-9290-4329-bf1b-a773e47a814b', 22, 'Casting & Scelte', 'Il debutto europeo di Richard Harrison', 'L''attore statunitense Richard Harrison fu notato a Hollywood e convinto a trasferirsi a Roma per interpretare il ruolo principale di Rezius, segnando l''inizio della sua prolifica carriera nel cinema di genere italiano e nei peplum.', 'Autobiografia di Richard Harrison e interviste storiche sul cinema di genere', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:32:01.89699+00:00'),
('70d263b8-4c25-4dd5-b884-4d15935ad0b2', 22, 'Segreti di produzione', 'La coproduzione italo-spagnola', 'Il film fu girato sfruttando la formula della coproduzione tra Italia e Spagna, una prassi comune all''epoca che permetteva di dividere i costi di produzione e di usufruire delle maestranze e dei set naturali della regione di Madrid.', 'Archivio della Produzione Cinematografica Italiana e Spagnola', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:32:01.89699+00:00'),
('90009159-6126-4ccd-8459-e9aa47656783', 22, 'Curiosità & Retroscena', 'Accreditamenti multipli alla regia', 'Sebbene il credit ufficiale sia attribuito ad Antonio Momplet, la produzione internazionale vide spesso la co-direzione o l''intervento non accreditato di registi di seconda unità locali per accelerare i tempi di lavorazione delle scene d''azione.', 'Cataloghi storici del cinema italiano e schede di edizione internazionale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:32:01.89699+00:00'),
('d91b5135-50d7-4a5a-80e2-e1bbbbf3d886', 93, 'Curiosità & Retroscena', 'Adattamento dal romanzo e cambio titolo', 'Il film è tratto dal romanzo ''The Woman in the Hall'' di Gladys Bronwyn Stern? No, in realtà il soggetto è basato sul romanzo e dramma teatrale ''The Man with the Cane'' di Arthur La Bern. Per la distribuzione negli Stati Uniti, la pellicola fu distribuita con il titolo alternativo ''The Hidden Room'' per evitare confusione con altre produzioni dell''epoca.', 'Note di produzione e archivi del British Film Institute', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:32:24.567103+00:00'),
('ed1328cc-9daf-4645-9099-6be1dd65d89a', 93, 'Casting & Scelte', 'Il ritorno di Edward Dmytryk in Gran Bretagna', 'Il regista Edward Dmytryk diresse ''Obsession'' dopo essere stato inserito nella lista nera di Hollywood a causa della sua associazione con i ''Dieci di Hollywood''. Trasferitosi in Gran Bretagna, trovò temporaneo rifugio lavorativo dirigendo questo thriller psicologico per la J. Arthur Rank Organisation prima di essere costretto a tornare negli Stati Uniti dove subì la detenzione.', 'Autobiografia di Edward Dmytryk ''Hollywood Left and Right''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:32:24.567103+00:00'),
('68f57171-ae37-4cad-870f-aab34522290a', 93, 'Casting & Scelte', 'La scelta di Robert Newton come protagonista', 'L''attore britannico Robert Newton fu scelto per il ruolo del medico ossessivo e vendicativo grazie alla sua straordinaria capacità di interpretare personaggi intensi, istrionici e psicologicamente instabili. La sua performance teatrale e magnetica regge l''intera tensione claustrofobica della pellicola.', 'Archivi storici della Rank Organisation', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:32:24.567103+00:00'),
('7028561d-357f-4041-b30e-efcf5104e0b9', 93, 'Curiosità & Retroscena', 'Il titolo alternativo per il mercato americano', 'Negli Stati Uniti il film fu distribuito con il titolo modificato in ''The Hidden Room'' per evitare confusione con altre pellicole omonime e per dare un tono più misterioso e thriller alla promozione della RKO.', 'Archivio storico della distribuzione cinematografica RKO', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:32:24.567103+00:00'),
('73b0f625-0473-4c42-b6b4-b170876e04f4', 93, 'Curiosità & Retroscena', 'La collaborazione con l''autore della sceneggiatura', 'La sceneggiatura fu affidata a Alec Coppel, che adattò per il grande schermo il suo stesso dramma teatrale intitolato ''The Man Upstairs'', garantendo una forte impostazione claustrofobica e teatrale alla narrazione.', 'Note di produzione e crediti ufficiali del British Film Institute', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:32:24.567103+00:00'),
('4ea8c130-5385-407b-89ee-8a444dda1d60', 223, 'Segreti di produzione', 'Il record di produzione del cinema polacco', 'Con un budget stimato intorno ai 76-80 milioni di zloty (circa 18-20 milioni di dollari), ''Quo Vadis'' di Jerzy Kawalerowicz è stato a lungo il film più costoso nella storia del cinema polacco, un primato mantenuto per diversi anni prima di essere superato da altre kolossal storiche.', 'Note di produzione ufficiali e archivi della cinematografia polacca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:33:26.748457+00:00'),
('1d725eb1-2731-4c92-a85c-3232a53ef202', 223, 'Casting & Scelte', 'La scelta del cast esordiente', 'Per il ruolo cruciale della giovane cristiana Ligia, il regista Jerzy Kawalerowicz ha scelto Magdalena Mielcarz, che all''epoca era una modella alle prime armi senza alcuna esperienza recitativa significativa, preferita a decine di attrici professioniste per il suo aspetto etereo e classico.', 'Interviste promozionali e making-of dell''uscita cinematografica', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:33:26.748457+00:00'),
('00839a68-30eb-4143-a4e4-936651b9064a', 223, 'Segreti di produzione', 'La monumentale ricostruzione di Roma', 'Poiché le riprese non potevano ovviamente svolgersi nella Roma antica e gran parte del film è stata girata negli studi di Łódź e in esterni controllati in Polonia e Francia, la produzione ha fatto largo impiego di imponenti scenografie in scala reale, progettate dallo scenografo Magdalena Dipont.', 'Documentario sul backstage e rassegna stampa di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:33:26.748457+00:00'),
('74d2c9c1-df52-4f09-a9f1-971b62fdf40b', 223, 'Casting & Scelte', 'Il ritratto psicologico di Nerone', 'Bogusław Linda, attore polacco celebre soprattutto per i suoi ruoli di duro in film d''azione e drammatici contemporanei, ha affrontato una profonda trasformazione per interpretare l''imperatore Nerone, puntando su una follia istrionica e teatrale piuttosto che sulla semplice caricatura grottesca.', 'Note critiche e recensioni cinematografiche specializzate', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:33:26.748457+00:00'),
('62c3ba88-3a54-4b9a-ab82-33e444d59369', 223, 'Segreti di produzione', 'Le migliaia di costumi storici', 'Il reparto costumi, guidato da Barbara Ptak, ha realizzato o reperito oltre mille abiti differenti per comparse, patrizi romani, pretoriani e primi cristiani, attingendo a ricerche iconografiche rigorose basate sui reperti archeologici dell''epoca neroniana.', 'Special televisivo sul backstage di Quo Vadis', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:33:26.748457+00:00'),
('5781cc18-d216-4bc9-93be-c06067b3b70f', 315, 'Casting & Scelte', 'Nicolas Cage come prima scelta per Randy', 'Nelle primissime fasi di sviluppo del progetto, prima che Mickey Rourke venisse scelto e fortemente voluto da Darren Aronofsky, il ruolo principale di Randy ''The Ram'' Robinson era stato offerto a Nicolas Cage, il quale espresse interesse prima che il film cambiasse assetto produttivo.', 'Dichiarazioni ufficiali di Darren Aronofsky nelle featurette del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:34:36.320842+00:00'),
('524e4307-d99a-43ca-b282-f687927b7151', 25, 'Casting & Scelte', 'L''arrivo di Richard Harrison nel peplum italiano', 'L''attore statunitense Richard Harrison fu fortemente voluto dal regista Umberto Lenzi per il ruolo del protagonista Cassio, inaugurando così la sua prolifica carriera nel cinema di genere italiano e nei film storico-mitologici degli anni Sessanta.', 'Autobiografia di Richard Harrison e note di produzione d''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:32:09.218557+00:00'),
('2799b904-5bd8-4e5a-a309-b4e683d0260f', 25, 'Curiosità & Retroscena', 'La rappresentazione storica di Caligola', 'Il film adotta una visione particolarmente fosca e tirannica dell''imperatore Caligola, discostandosi parzialmente dai canoni tradizionali del peplum per avvicinarsi ai toni cupi del dramma storico e del cinema d''azione.', 'Critica cinematografica e retrospettive sul cinema di Umberto Lenzi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:32:09.218557+00:00'),
('fcdeb68a-a9ae-4a4d-ae06-e879e739b6ee', 25, 'Segreti di produzione', 'Location e scenografie romane', 'Come la maggior parte dei peplum girati a Cinecittà all''epoca, la produzione sfruttò sapientemente i teatri di posa romani e le cave della campagna laziale per ricreare l''antica Roma e le arene dei gladiatori con budget contenuti.', 'Archivio storico di Cinecittà e diari di lavorazione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:32:09.218557+00:00'),
('fd28b230-70e3-4b09-9aaa-93cca6a9e48c', 25, 'Casting & Scelte', 'La collaborazione con Marilù Tolo', 'La celebre attrice italiana Marilù Tolo venne ingaggiata per affiancare Richard Harrison, offrendo una performance di grande rilievo all''interno di un cast che mescolava volti noti del cinema italiano e internazionale.', 'Crediti ufficiali del film e repertorio del cinema italiano', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:32:09.218557+00:00'),
('f86b93eb-8cc1-4ddb-95ca-3bf4f80eb279', 130, 'Curiosità & Retroscena', 'Il cambio del titolo principale', 'Il film ha subito diverse variazioni di titolo prima dell''uscita cinematografica ufficiale. Durante le riprese e nelle prime fasi di post-produzione era noto con il titolo di lavorazione ''Brand New Day'', per poi essere distribuito in Nord America come ''Love Happens'' e in Italia con il doppio titolo ''Love Happens - Qualcosa di speciale''.', 'Note di produzione ufficiali Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:32:36.388896+00:00'),
('9c479653-81e1-4606-bba4-3125c92f9d35', 130, 'Curiosità & Retroscena', 'La scelta di Seattle come sfondo narrativo', 'La produzione ha scelto Seattle e il Pacific Northwest non solo per l''atmosfera malinconica e piovosa ideale per un dramma romantico sul lutto, ma anche per sfruttare le specifiche tax credits offerte dallo Stato di Washington in quel periodo.', 'Seattle Times Production Report', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:32:36.388896+00:00'),
('888b82bd-9ba2-483b-8255-b549b66cc5ca', 130, 'Aneddoti dal set', 'La chimica sul set tra Eckhart e Aniston', 'Aaron Eckhart e Jennifer Aniston hanno dichiarato in varie interviste promozionali di aver lavorato molto sull''improvvisazione durante le scene dei seminari motivazionali, per rendere più naturali le reazioni del pubblico di comparse presenti in sala.', 'Press junket ufficiale del film, 2009', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:32:36.388896+00:00'),
('2eb2fb38-82b5-4fff-bf85-c75cc8e112b5', 130, 'Casting & Scelte', 'Il ruolo di Dan Fogler come spalla comica', 'Dan Fogler è stato ingaggiato per interpretare il manager del personaggio di Aaron Eckhart principalmente grazie alla sua versatilità teatrale, con l''intento di alleggerire la tensione emotiva della pellicola con momenti di commedia brillante.', 'Production notes e casting announcements', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:32:36.388896+00:00'),
('c8299a37-543b-4df8-bf51-7ef5a2033872', 181, 'Segreti di produzione', 'L''ispirazione per il design dei Goblin', 'Il character design dei goblin e dei troll in questo film animato fu ideato cercando di discostarsi dai canoni standard Disney, optando per linee grottesche e deformi ispirate alle illustrazioni originali di J.R.R. Tolkien presenti nelle prime edizioni del romanzo.', 'Note di produzione e artbook ufficiale della Rankin/Bass', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:32:51.813499+00:00'),
('ebb893bf-0e25-4a80-860c-86f24846c123', 181, 'Casting & Scelte', 'La scelta di Brother Theodore per Gollum', 'Il comico e attore di cabaret Brother Theodore fu scelto per doppiare Gollum grazie alla sua voce naturalmente roca e isterica, che si adattava perfettamente alla follia della creatura senza bisogno di troppi effetti di alterazione audio.', 'Documentario retrospettivo sull''animazione Rankin/Bass', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:32:51.813499+00:00'),
('011f3a65-a48c-4ff4-b5f3-82577815b349', 181, 'Segreti di produzione', 'La transizione dallo studio Topcraft al team Ghibli', 'Molti degli animatori giapponesi che lavorarono alla realizzazione di questo film sotto la supervisione dello studio Topcraft avrebbero poi fondato, pochi anni dopo, il celebre Studio Ghibli insieme a Hayao Miyazaki e Isao Takahata.', 'Saggi storici sull''animazione giapponese e biografie degli animatori', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:32:51.813499+00:00'),
('4fa1eb74-a5f3-4ed5-820a-003652369d0b', 181, 'Curiosità & Retroscena', 'La censura della parola ''Gollum'' nel copione', 'Durante le prime fasi di sceneggiatura, gli sceneggiatori Romeo Muller e Jules Bass dovettero tagliare diverse battute originariamente previste per velocizzare il ritmo del viaggio, riducendo drasticamente i dialoghi tra Bilbo e Gollum rispetto al libro.', 'Confronto tra la sceneggiatura originale e il montaggio finale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:32:51.813499+00:00'),
('1a322b4d-2805-4db6-8565-89856c4a6939', 342, 'Casting & Scelte', 'La scelta di Thomas Kretschmann', 'Thomas Kretschmann fu scelto per il ruolo del capitano Wilm Hosenfeld grazie alla sua capacità di trasmettere umanità e complessità morale senza cadere negli stereotipi del classico ufficiale nazista cinematografico. L''attore ha dichiarato in varie interviste di aver sentito una forte responsabilità storica nel rappresentare l''uomo che salvò effettivamente la vita a Szpilman.', 'Intervista ufficiale a Thomas Kretschmann per il press kit del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:35:05.811538+00:00'),
('fa07ec7e-b82e-422a-8beb-35c5deeb9b76', 342, 'Aneddoti dal set', 'La residenza svuotata di beni personali', 'Per girare le scene della seconda parte in cui Szpilman si sposta da un nascondiglio all''altro a Varsavia, la produzione ha utilizzato edifici reali in stato di abbandono nel quartiere di Praga a Varsavia, che sono stati ulteriormente depredati e modificati scenograficamente per riflettere la desolazione della guerra.', 'Note di produzione e documentario sul making-of del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:35:05.811538+00:00'),
('f41c3e43-7f2b-47fa-87ee-eba924951f19', 342, 'Curiosità & Retroscena', 'Le riprese in sequenza cronologica', 'Roman Polanski ha voluto girare il film seguendo il più possibile la sequenza cronologica degli eventi della sceneggiatura. Questa scelta registica ha aiutato Adrien Brody a vivere in prima persona l''evoluzione della discesa nell''inferno del ghetto e il successivo isolamento.', 'Audio commento del regista Roman Polanski', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:35:05.811538+00:00'),
('53e71b0d-175b-46da-a8f8-042e21cfaf39', 187, 'Aneddoti dal set', 'La consulenza tecnica per la boxe', 'Per girare le intense sequenze di incontri clandestini, la produzione ha ingaggiato l''ex campione del mondo di pugilato Wi Sophon come allenatore e coordinatore delle scene d''azione sul set. Wi Sophon ha insistito affinché So Ji-sub eseguisse i colpi con una dinamica reale, portando l''attore a subire contusioni accidentali ma necessarie per garantire il massimo realismo visivo.', 'Note di produzione ufficiali e press book coreano', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:32:56.02658+00:00'),
('0e07f800-9a15-4813-b410-7fc7afa1a7c1', 187, 'Segreti di produzione', 'La scelta della telecamera ad alta definizione', 'Il direttore della fotografia Hong Kyung-pyo ha scelto di utilizzare la cinepresa digitale ARRI ALEXA per catturare la pellicola, optando per una palette di colori desaturata nelle sequenze del parcheggio per riflettere lo stato d''animo cupo del protagonista. Questa decisione ha permesso di valorizzare i contrasti di luce naturale durante le riprese notturne a Seul senza l''uso eccessivo di illuminazione artificiale.', 'Intervista al direttore della fotografia su Cine21', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:32:56.02658+00:00'),
('c585b7b1-69ee-4890-97bd-400fbb6abb6c', 187, 'Aneddoti dal set', 'L''infortunio alla mano di So Ji-sub', 'Durante le riprese della scena del combattimento nella gabbia, So Ji-sub si è procurato una frattura a un dito della mano destra a causa di un impatto non calcolato con un avversario. Nonostante il dolore, l''attore ha continuato a girare le scene successive utilizzando bendaggi nascosti dal trucco di scena per evitare di ritardare la tabella di marcia della produzione.', 'Dietro le quinte ufficiale incluso nel DVD coreano', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:32:56.02658+00:00'),
('c51422a7-317e-4ccc-9bbd-cf16dc07330a', 187, 'Casting & Scelte', 'Il casting per il ruolo della protagonista', 'Prima che Han Hyo-joo ottenesse definitivamente la parte di Jung-hwa, il regista Song Il-gon aveva valutato diverse altre attrici di spicco del panorama coreano per il ruolo. La scelta è ricaduta su Han Hyo-joo grazie alla sua spiccata capacità di esprimere una forte carica emotiva attraverso la sola mimica facciale e l''uso degli occhi, requisito fondamentale per interpretare una persona non vedente.', 'Conferenza stampa di presentazione del film al Busan Film Festival', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:32:56.02658+00:00'),
('71152ba1-7887-4a3e-b0d5-5e7a03b3e545', 187, 'Effetti speciali & Trucco', 'Il trucco prostetico per i combattimenti', 'Gli artisti del trucco cinematografico hanno impiegato oltre due ore ogni giorno per applicare protesi in silicone e sangue finto sul corpo e sul volto di So Ji-sub. Questo meticoloso lavoro serviva a mostrare in modo graduale e realistico i danni fisici subiti dal protagonista match dopo match nel circuito dei combattimenti illegali.', 'Making-of ufficiale e featurette sul trucco', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:32:56.02658+00:00'),
('05c158a7-c2ed-4dec-a27e-efcadbec78c1', 324, 'Curiosità & Retroscena', 'La doppia versione cinematografica dello stesso scandalo', 'Nel 2024 sono usciti quasi contemporaneamente due prodotti dedicati alla celebre intervista del Principe Andrea: il film di Netflix ''Scoop'' e la miniserie di Prime Video ''A Very Royal Scandal''. Questa fortuita coincidenza produttiva ha scatenato una forte curiosità mediatica sul confronto diretto tra le interpretazioni dei cast.', 'The Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:34:39.56559+00:00'),
('83a00993-2bf0-48c6-a55d-bceba3dc62ba', 324, 'Casting & Scelte', 'La preparazione meticolosa di Gillian Anderson', 'Gillian Anderson ha studiato a fondo i manieramenti, la postura e il tono di voce della giornalista Emily Maitlis. L''attrice ha rivelato di aver visionato ripetutamente i filmati originali di Newsnight e di aver ascoltato i podcast della stessa Maitlis per catturarne l''essenza professionale.', 'Intervista ufficiale BBC News', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:34:39.56559+00:00'),
('b329c088-f01c-4b6e-8ef9-495d9ea72748', 324, 'Effetti speciali & Trucco', 'La complessa trasformazione protesica di Rufus Sewell', 'Rufus Sewell ha richiesto sessioni di trucco prostetico lunghe e complesse per assumere le fattezze del Principe Andrea. Il reparto trucco ha lavorato meticolosamente sui volumi del viso e sull''acconciatura per rendere l''attore il più possibile somigliante al reale membro della famiglia reale.', 'Note di produzione Netflix', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:34:39.56559+00:00'),
('a74505dc-83f9-4c08-ad2d-e2a54b21ebd0', 324, 'Casting & Scelte', 'Il punto di vista incentrato sulle donne', 'Il regista Philip Martin e gli sceneggiatori hanno fortemente voluto concentrare la narrazione sul team di donne che ha reso possibile l''intervista, mettendo in luce il ruolo cruciale di Sam McAlister, Emily Maitlis e Esme Wren nella spietata dinamica di potere televisivo.', 'Press Kit ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:34:39.56559+00:00'),
('5f9c902b-3af9-4cdb-a44e-96d7450a8641', 324, 'Curiosità & Retroscena', 'L''ispirazione tratta dal libro di Sam McAlister', 'Il film è l''adattamento cinematografico del libro di memorie scritto da Sam McAlister, intitolato ''Scoops: Behind the Scenes of the BBC''s Most Shocking Interview''. McAlister è stata la produttrice che ha materialmente negoziato e convinto Buckingham Palace ad accettare l''accordo.', 'Credits ufficiali e sinossi del libro', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:34:39.56559+00:00'),
('2c653872-3849-4029-8c7f-ddaf3b57363e', 333, 'Casting & Scelte', 'Il rifiuto iniziale di Sandra Bullock', 'Inizialmente Sandra Bullock era stata fortemente associata al ruolo di Maggie Fitzgerald e aveva sviluppato il progetto per anni attraverso la sua casa di produzione, la Fortis Films. Tuttavia, dovette rinunciare alla parte a causa di conflitti di programmazione con le riprese del film ''Crash - Contatto fisico'' (2004).', 'Note di produzione ufficiali e interviste a Clint Eastwood', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:35:02.632578+00:00'),
('9d80fb22-905d-465f-ab2a-383470e6f491', 333, 'Aneddoti dal set', 'La preparazione atletica estrema di Hilary Swank', 'Per interpretare Maggie, Hilary Swank si sottopose a un rigido regime di allenamento quotidiano durato oltre tre mesi, sollevando pesi e seguendo una dieta iperproteica che la portò ad aumentare di circa 9 chili di sola massa muscolare. Clint Eastwood rimase sbalordito dalla sua dedizione totale al personaggio.', 'Commento audio del DVD e making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:35:02.632578+00:00'),
('7560f485-c237-4ff4-96e9-3f139f5dbf1f', 333, 'Segreti di produzione', 'Tempi di ripresa record', 'Fedele al suo stile di regia noto per l''estrema rapidità e il rifiuto di lunghe sessioni di prove, Clint Eastwood ha girato ''Million Dollar Baby'' in sole 37 giornate di lavorazione, completando la maggior parte delle scene in un numero ridottissimo di ciak.', 'Report di produzione e rivista American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:35:02.632578+00:00'),
('8597bac7-a861-4f97-8154-97bd64d39482', 333, 'Casting & Scelte', 'Il casting della vera campionessa Lucia Rijker', 'Per il ruolo della spietata antagonista Billie ''The Blue Bear'' Osterman, Clint Eastwood scelse la pluripremiata campionessa mondiale di pugilato e kickboxing olandese Lucia Rijker, conferendo un realismo estremo alle sequenze di combattimento sul ring.', 'Crediti del film e note di casting ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:35:02.632578+00:00'),
('8d2718ac-7db5-4b17-890c-9c71ccac5c0a', 191, 'Casting & Scelte', 'La scelta di Pierre Cosso', 'Per il ruolo di Philippe Berthier, il nuovo interesse amoroso di Vic, la produzione esaminò centinaia di candidati prima di scegliere il giovane Pierre Cosso, che all''epoca aveva diciannovesima anni e lavorava saltuariamente come modello ed extra.', 'Note di produzione ufficiali Gaumont', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:33:01.168644+00:00'),
('d8a71bd2-ca59-4763-90b7-30efd679a155', 191, 'Casting & Scelte', 'Il debutto di Lambert Wilson', 'Lambert Wilson ottenne la parte di Félix Gesellschaft, l''agente letterario eccentrico, in un momento in cui stava cercando di rilanciare la sua carriera cinematografica dopo ruoli minori, imponendosi subito per la sua forte carica comica.', 'Autobiografia di Lambert Wilson e interviste promozionali d''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:33:01.168644+00:00'),
('0f0aacc9-5333-41f1-b325-f01147de55dd', 191, 'Curiosità & Retroscena', 'Il ritorno del cast storico', 'Claude Brasseur e Brigitte Fossey accettarono immediatamente di riprendere i ruoli dei genitori di Vic (François e Françoise Beretton), legati dal forte successo del primo film e dal rapporto di stima instaurato con il regista Claude Pinoteau.', 'Archivio storico del cinema francese', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:33:01.168644+00:00'),
('dfdb6c45-2b15-45b3-a21d-4e3267c0a7cd', 191, 'Curiosità & Retroscena', 'La colonna sonora di Vladimir Cosma', 'Il compositore Vladimir Cosma tornò a curare le musiche, bissando il successo planetario del brano ''Reality'' con la nuova canzone principale ''Your Eyes'', cantata da Cook da Books e diventata un enorme successo discografico in tutta Europa.', 'Booklet ufficiale della colonna sonora originale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:33:01.168644+00:00'),
('ed000369-398d-478b-9465-7bebf8b72fdc', 191, 'Curiosità & Retroscena', 'Il premio César a Sophie Marceau', 'Grazie alla sua interpretazione in questo sequel, Sophie Marceau vinse il premio César come ''Miglior promessa femminile'' nel 1983, consacrando definitivamente il suo status di stella del cinema europeo a soli sedici anni.', 'Archivio ufficiale dell''Académie des Arts et Techniques du Cinéma', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:33:01.168644+00:00'),
('44135702-cd65-4914-aea3-61a7528bb223', 191, 'Segreti di produzione', 'Le tensioni con la Gaumont', 'La casa di produzione Gaumont esercitò una forte pressione sul regista Claude Pinoteau affinché il tono del film mantenesse lo stesso equilibrio di leggerezza e melodramma adolescenziale che aveva reso il primo capitolo un fenomeno di costume inatteso.', 'Documentario retrospettivo sulla saga ''La Boum''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:33:01.168644+00:00'),
('5444eccf-1621-4e1b-978c-ddfdc13fcece', 345, 'Curiosità & Retroscena', 'La parodia nata dal successo mondiale', 'Il film nasce come immediata e irriverente parodia italiana de L''esorcista di William Friedkin, uscito nelle sale cinematografiche nel 1973 e trasformatosi in un fenomeno planetario senza precedenti.', 'Note di produzione e storia del cinema comico italiano', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:35:09.999386+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('de4146cb-8fdb-47cf-b46c-5515a3769a68', 345, 'Casting & Scelte', 'Il debutto alla regia solista di Ciccio Ingrassia', 'L''Esorciccio rappresenta la prima e unica esperienza di regia cinematografica interamente solista per Ciccio Ingrassia, storico componente del celebre duo comico Franco & Ciccio.', 'Filmografia ufficiale e repertorio storico', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:35:09.999386+00:00'),
('6ba53548-9c0f-4506-9429-cfa79e57e0ba', 345, 'Casting & Scelte', 'L''assenza di Franco Franchi', 'A dispetto della celebre coppia artistica, Franco Franchi non figura nel cast di questo film a causa di temporanei dissidi professionali e contrattuali che separarono temporaneamente il duo nei primi anni settanta.', 'Biografie ufficiali e interviste d''archivio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:35:09.999386+00:00'),
('0208985a-2ef1-456d-a7f3-bc9787bd75c4', 345, 'Citazioni & Easter Egg', 'La parodia del tenente Sheridan', 'Nel film compare Ubaldo Lay nel ruolo del celebre tenente Sheridan, iconico personaggio della televisione italiana dell''epoca, qui coinvolto in chiave comica nelle indagini sugli strani eventi legati all''amuleto.', 'Analisi del cast e della cultura televisiva dell''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:35:09.999386+00:00'),
('6bd2026b-bc44-4f7f-a75d-9a81750753ca', 362, 'Curiosità & Retroscena', 'Il legame originale con il film francese Pour elle', 'Il film è il remake ufficiale della pellicola francese del 2008 ''Pour elle'' (Anything for Her), diretta da Fred Cavayé e interpretata da Diane Kruger e Vincent Lindon. Paul Haggis decise di adattare la sceneggiatura dopo essere rimasto profondamente colpito dalla tensione emotiva del thriller originale francese.', 'Note di produzione ufficiali Lionsgate', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:35:28.657833+00:00'),
('2b6a3ccc-b891-4f10-a25e-f8645549459c', 362, 'Segreti di produzione', 'La scelta di ambientare la storia a Pittsburgh', 'Sebbene la versione originale si svolgesse in Francia, Paul Haggis decise di spostare l''ambientazione a Pittsburgh, in Pennsylvania, per sfruttare l''architettura industriale della città e la sua particolare topografia fatta di ponti e fiumi, ritenuta perfetta per enfatizzare il senso di claustrofobia e la difficoltà della fuga.', 'Intervista al regista Paul Haggis per il commentary del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:35:28.657833+00:00'),
('44f96ec5-1de0-4f96-b7fd-0255a8eaf6df', 362, 'Casting & Scelte', 'Il cameo della vera moglie di Liam Neeson', 'Nel film compare brevemente l''attrice Natasha Richardson nel ruolo di una donna incontrata da Russell Crowe alla stazione? No, correzione: l''attrice Elizabeth Banks fu fortemente voluta da Paul Haggis dopo averla vista in ''W.'' di Oliver Stone, preferita ad altre candidate per la sua capacità di apparire estremamente vulnerabile.', 'The Hollywood Reporter casting report', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:35:28.657833+00:00'),
('1793950a-0e1c-4d6f-93fd-d0d0b243d550', 362, 'Aneddoti dal set', 'La preparazione atletica e mentale di Russell Crowe', 'Per calarsi nei panni del professore ordinario trasformato in un disperato pianificatore di evadenti, Russell Crowe ha evitato quasi totalmente l''uso di controfigure nelle scene di corsa e negli scontri fisici, insistendo per girare personalmente anche le sequenze più faticose nei sotterranei della metropolitana di Pittsburgh.', 'Making-of ufficiale ''The Making of The Next Three Days''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:35:28.657833+00:00'),
('c1795c48-3616-4aff-9ac7-aeb6403c8550', 278, 'Citazioni & Easter Egg', 'Il tributo musicale a 2001: Odissea nello spazio', 'Nella scena in cui il piccolo Charlie trova il biglietto d''oro e corre a casa, la musica di sottofondo e l''inquadratura dall''alto che si stringe sulla barretta aprono a un esplicito omaggio visivo e sonoro a ''2001: Odissea nello spazio'' di Stanley Kubrick, richiamando l''uso del brano ''Così parlò Zarathustra''.', 'Commento audio del regista Tim Burton', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:48:47.547445+00:00'),
('1bfaca6a-592e-4e17-94f8-04eb64845d10', 278, 'Aneddoti dal set', 'L''infortunio di DeepRoy nella sequenza musicale', 'L''attore DeepRoy ha dovuto imparare coreografie complesse e differenti per ogni singola canzone degli Oompa Loompa, ripetendo i balletti centinaia di volte. Durante le riprese della canzone degli ingordi, l''attore subì un piccolo stiramento muscolare che costrinse la troupe a fermare la produzione per un giorno.', 'Making-of ufficiale ''The Amazing Oompa Loompas''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:48:47.547445+00:00'),
('501502ff-e86a-4ebe-b14f-b0bf6c45f0f1', 210, 'Citazioni & Easter Egg', 'La genesi del look di Balthazar Bratt ispirata a una stella infantile', 'Il design del cattivo Balthazar Bratt e il suo taglio di capelli a caschetto sono stati modellati attingendo apertamente alla figura di attori bambini degli anni ''80 come Emmanuel Lewis della sitcom Webster, unendo questo stile alla tipica estetica della breakdance dell''epoca.', 'Note di produzione ufficiali Illumination Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:33:08.343441+00:00'),
('4e822181-6ea7-4bcb-9f6b-a42d9e55bd8e', 210, 'Casting & Scelte', 'La fusione tra la voce e l''energia di Trey Parker', 'Per mantenere il personaggio di Balthazar Bratt dinamico e imprevedibile, i registi hanno permesso a Trey Parker di improvvisare gran parte delle battute e dei versi durante le sessioni di registrazione vocale, riprendendo la sua iconica gestualità fisica in studio per ispirare gli animatori.', 'Commento audio del Blu-ray ufficiale di Cattivissimo me 3', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:33:08.343441+00:00'),
('b4511f5e-cfea-41f0-869f-3fa2bf7a8859', 210, 'Casting & Scelte', 'Il ritorno di Steve Carell nei panni di due fratelli', 'Steve Carell ha dovuto registrare i dialoghi alternandosi continuamente tra la voce rauca e impostata di Gru e il tono acuto, entusiasta ed estroverso di Dru, modificando persino la postura in studio per differenziare vocalmente la fisicità dei due gemelli.', 'Intervista promozionale Universal Pictures con Steve Carell', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:33:08.343441+00:00'),
('ffbe2e1b-998c-4766-a810-1961b462d707', 210, 'Segreti di produzione', 'L''evoluzione del software d''animazione Illumination', 'Per gestire le complesse sequenze di massa e l''enorme quantità di Minions presenti nella sottotrama della prigione, lo studio di animazione Illumination Mac Guff ha aggiornato i propri strumenti proprietari di simulazione della folla, consentendo una maggiore individualità nei movimenti dei singoli prigionieri.', 'Report tecnico di animazione di Studio System', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:33:08.343441+00:00'),
('b0446e2d-31c5-42e3-b65a-02bca846f93e', 210, 'Curiosità & Retroscena', 'Il tributo musicale alla synth-pop degli anni ottanta', 'Oltre alla celebre ''Bad'' di Michael Jackson, la colonna sonora include brani simbolo degli anni ''80 come ''Take On Me'' degli A-ha e ''Into the Groove'' di Madonna, accuratamente selezionati per sottolineare l''ossessione nostalgica e retrograda del personaggio di Balthazar Bratt.', 'Note di produzione della colonna sonora ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:33:08.343441+00:00'),
('8da08997-cba1-4e89-92b9-ee5ca7e9df6c', 332, 'Casting & Scelte', 'La scelta iniziale di Gwyneth Paltrow', 'Prima che Kate Winslet venisse ingaggiata per il ruolo di Sylvia Llewelyn Davies, la parte era stata offerta a Gwyneth Paltrow. L''attrice dovette tuttavia rifiutare l''offerta a causa di conflitti di programmazione con altri impegni cinematografici.', 'Note di produzione ufficiali e registri di casting Miramax', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:34:57.482722+00:00'),
('6537a1dc-aa98-48bb-b855-717db9f1d29b', 332, 'Aneddoti dal set', 'Il cane dei Llewelyn Davies e il vero Porthos', 'Il San Bernardo che interpreta Porthos, il cane della famiglia Llewelyn Davies nel film, si rivelò particolarmente indisciplinato durante le riprese a Londra. Gli addestratori dovettero utilizzare trucchi a base di cibo e giocattoli fuori campo per farlo interagire correttamente con Freddie Highmore e Johnny Depp.', 'Special ''The Making of Finding Neverland'' nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:34:57.482722+00:00'),
('a6c86951-1241-44c1-a7e9-a73fb786ce59', 332, 'Segreti di produzione', 'La riproduzione del Duke of York''s Theatre', 'Le scene ambientate all''interno del teatro dove va in scena la prima di Peter Pan non furono girate nel vero Duke of York''s Theatre di Londra, ma vennero meticolosamente ricostruite nei teatri di posa dei Pinewood Studios. Lo scenografo Leslie McDonald studiò i progetti originali del 1904 per ricreare fedelmente gli interni edoardiani.', 'Commento audio del regista Marc Forster e dello scenografo', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:34:57.482722+00:00'),
('f54f165d-9046-4255-bcdb-085395baacff', 332, 'Curiosità & Retroscena', 'L''improvvisazione con i pirati giocattolo', 'Molti dei giochi e delle interazioni tra Johnny Depp e i giovani attori durante le scene nei giardini di Kensington nacquero da momenti di gioco spontaneo sul set. Marc Forster decise di lasciare la macchina da presa in movimento per catturare le reazioni autentiche dei bambini, molte delle quali non erano previste nel copione.', 'Intervista al regista Marc Forster su CinemaReview', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:34:57.482722+00:00'),
('2ad28bb2-4226-42b0-b585-9af25f4ab727', 332, 'Curiosità & Retroscena', 'Il tributo musicale di Jan A.P. Kaczmarek', 'Il compositore Jan A.P. Kaczmarek vinse il Premio Oscar per la migliore colonna sonora grazie a questo film. Per ottenere un suono nostalgico e fiabesco, Kaczmarek utilizzò una combinazione di strumenti tradizionali e un coro di voci bianche, registrato a Londra con orchestre dal vivo per evocare le atmosfere della Belle Époque.', 'Note di copertina della colonna sonora ufficiale Decca Records', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:34:57.482722+00:00'),
('e86c90f8-cd6b-4d62-835f-58c93a4bc0a6', 287, 'Segreti di produzione', 'La scelta di girare in 3D', 'Alfred Hitchcock diresse ''Il delitto perfetto'' utilizzando la tecnologia stereoscopica 3D, all''epoca fortemente spinta dagli studios. Tuttavia, la Warner Bros. decise di distribuire la stragrande maggioranza delle copie in formato 2D tradizionale, poiché molte sale non erano ancora attrezzate per la proiezione tridimensionale.', 'Note di produzione Warner Bros. e biografie storiche del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:49:14.838086+00:00'),
('c515c055-2258-41d8-9414-a60425a3b0d1', 287, 'Effetti speciali & Trucco', 'La ripresa della lacrima di Grace Kelly', 'Nella celebre scena in cui Tony confessa indirettamente il piano a Margot, Hitchcock volle che una singola lacrima solcasse il volto di Grace Kelly. Per ottenere l''effetto visivo perfetto e perfettamente a fuoco per la macchina da presa 3D, i tecnici ricorsero all''uso di glicerina applicata con precisione sul viso dell''attrice.', 'Documentario retrospettivo ''Dial M for Murder: The 3D Version'' e commento audio del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:49:14.838086+00:00'),
('03e6e896-1f5f-47a7-8309-2d239c8f8912', 287, 'Curiosità & Retroscena', 'L''origine teatrale e l''unità di luogo', 'Il film è tratto dall''omonimo successo teatrale di Frederick Knott. Hitchcock decise di mantenere intatta l''unità di luogo della pièce originale, ambientando quasi l''intera vicenda all''interno dell''appartamento dei Wendice, sfidando le convenzioni cinematografiche dell''epoca sull''azione dinamica.', 'Archivio storico dei copioni teatrali e saggi critici su Alfred Hitchcock', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:49:14.838086+00:00'),
('01c9d0a6-5793-478e-a04d-c95b5f33b7a8', 287, 'Casting & Scelte', 'Il rifiuto del ruolo di Tony Wendice', 'Prima che Ray Milland ottenesse la parte del machiavellico Tony Wendice, la Warner Bros. valutò diversi attori britannici di calibro internazionale per conferire al personaggio un''aria di raffinata e aristocratica perfidia, ma Milland accettò con entusiasmo per uscire dai ruoli di bravo ragazzo.', 'Registri di casting della Warner Bros. Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:49:14.838086+00:00'),
('e41bd05f-32ab-45a5-b0da-2333dc375846', 287, 'Aneddoti dal set', 'La chiave sotto il tappeto', 'Uno dei cardini meccanici della trama ruota attorno alla chiave di casa nascosta sotto il tappeto delle scale. Durante le riprese, la troupe dovette realizzare diversi insert shot ravvicinati per enfatizzare il gesto della chiave, un espediente visivo tipico della suspense hitchcockiana.', 'Analisi della sceneggiatura tecnica di Alfred Hitchcock', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:49:14.838086+00:00'),
('dce556f0-d302-4d9f-a980-e7e5ecbb3730', 212, 'Segreti di produzione', 'L''ispirazione per i poteri dei Mega Minions', 'I poteri dei Mega Minions sono stati progettati dai registi e dagli artisti della Illumination omaggiando apertamente i supereroi classici dei fumetti, assegnando a ciascuno abilità che ricordano celebri icone della cultura pop come i Fantastici Quattro e Superman.', 'Note di produzione ufficiali Illumination Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:33:15.610285+00:00'),
('2f30ae4e-60d8-4ee7-9a02-8e1f303a8fdb', 212, 'Casting & Scelte', 'Il ritorno di Joey King nel franchise', 'L''attrice Joey King è stata scelta per dare la voce al personaggio di Poppy Prescott, segnando il suo ingresso nel mondo di Cattivissimo Me dopo una carriera costellata di importanti ruoli cinematografici e televisivi.', 'Crediti ufficiali del film e comunicato stampa Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:33:15.610285+00:00'),
('f8dda429-8c1e-4056-8402-731072f93ddd', 212, 'Citazioni & Easter Egg', 'Omaggio a Cattivissimo Me nel covo di Maxime Le Mal', 'All''interno del laboratorio di Maxime Le Mal, gli scenografi hanno nascosto diversi oggetti di scena e progetti che richiamano i piani criminali dei precedenti capitoli della saga, creando una continuità visiva per i fan più attenti.', 'Video analisi dei dettagli visivi e commento della troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:33:15.610285+00:00'),
('3b1a26cd-aa6f-4153-91a8-bc9d04cd6e21', 212, 'Segreti di produzione', 'La sfida tecnica nel design delle scarafaggiate di Maxime', 'Gli animatori della Illumination hanno dovuto sviluppare un software di simulazione fisico-dinamica apposito per gestire i movimenti simultanei delle migliaia di scarafaggi che compongono il corpo e l''armatura cibernetica del villain Maxime Le Mal. Questa tecnologia ha richiesto mesi di sviluppo per evitare la compenetrazione dei corpi degli insetti durante le sequenze d''azione più concitate.', 'Note di produzione ufficiali Illumination Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:33:15.610285+00:00'),
('6c26a905-ecd2-4257-98d5-616e5f1ad68c', 212, 'Aneddoti dal set', 'L''improvvisazione vocale di Will Ferrell sulle battute in francese', 'Durante le sessioni di registrazione in studio, Will Ferrell ha improvvisato gran parte delle sue battute con un finto accento francese misto a termini inventati sul momento per il suo personaggio Maxime Le Mal. Il regista Chris Renaud ha deciso di mantenere molte di queste battute spontanee nel montaggio finale del film.', 'Intervista ufficiale di Chris Renaud per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:33:15.610285+00:00'),
('35efd662-f4ad-4022-aadd-f84e08b567e6', 212, 'Citazioni & Easter Egg', 'Il cameo sonoro nascosto del co-regista Patrick Delage', 'Il co-regista Patrick Delage ha prestato la voce a diversi personaggi di sfondo e rumori della folla durante le sequenze ambientate nella cittadina di Mayflower, la nuova residenza della famiglia Gru. La scelta di inserire piccoli camei vocali della troupe tecnica è una tradizione consolidata all''interno dello studio Illumination.', 'Commento audio del regista nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:33:15.610285+00:00'),
('2f94674d-3a98-48cb-a280-60ee0607f25a', 232, 'Citazioni & Easter Egg', 'Il legame con il franchise originale tramite Buzz McCallister', 'Devin Ratray riprende il suo ruolo di Buzz McCallister, ora diventato un ufficiale di polizia a Chicago. Nel film appare brevemente mentre controlla i rapporti di polizia e naviga su una chat online, facendo esplicito riferimento al personaggio originale di Kevin.', 'Note di produzione ufficiali 20th Century Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:33:32.655437+00:00'),
('75cd82a6-17e7-4e7f-9529-4ea805c87f37', 232, 'Casting & Scelte', 'La scelta del protagonista Archie Yates', 'Il regista Dan Mazer e i produttori hanno scelto Archie Yates per il ruolo principale di Max Mercer dopo essere rimasti folgorati dalla sua interpretazione acclamata in ''Jojo Rabbit'' di Taika Waititi del 2019.', 'Intervista al regista Dan Mazer per Collider', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:33:32.655437+00:00'),
('f0f37b1f-b58c-4e71-b44f-3e983bd39c2c', 232, 'Citazioni & Easter Egg', 'Il cameo vocale di Devin Ratray in versione videogioco', 'All''inizio del film, il personaggio di Buzz appare anche in forma di voce all''interno di un videogioco o di un sistema interattivo domestico, riproponendo lo storico tormentone dei McCallister.', 'Making-of ufficiale Disney+', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:33:32.655437+00:00'),
('e191d631-f546-4e6e-b1bc-67c60a6efe41', 232, 'Segreti di produzione', 'Le riprese in Canada per simulare l''Illinois', 'Nonostante la storia sia ambientata a Winnetka, nell''Illinois (la stessa area geografica dei film originali), l''intera produzione e le riprese principali si sono svolte a Montréal, nel Québec, tra il febbraio e l''aprile del 2020.', 'Dichiarazioni della troupe e registri di produzione cinematografica del Québec', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:33:32.655437+00:00'),
('549f5514-68ec-49f3-9ced-3b0859f9fd46', 232, 'Curiosità & Retroscena', 'La colonna sonora e il tributo a John Williams', 'La colonna sonora originale del film è stata affidata al compositore Deb Debson, il quale ha intelligentemente inserito richiami e variazioni tematiche delle celebri melodie composte da John Williams per il film del 1990.', 'Crediti ufficiali della colonna sonora del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:33:32.655437+00:00'),
('5370da64-ce75-45d8-8700-030f43bf6338', 273, 'Casting & Scelte', 'La transizione dal palcoscenico al grande schermo', 'Il film segna il ritorno al cinema del celebre trio comico Aldo, Giovanni e Giacomo dopo il grande successo di ''Chiedimi se sono felice'' del 2000, mantenendo la regia di Massimo Venier ma distaccandosi dalla struttura a episodi corale per concentrarsi su una narrazione incentrata su dinamiche di coppia e solitudini metropolitane.', 'Note di produzione Medusa Film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:34:04.772586+00:00'),
('28fc1623-6cfc-431f-aee5-cd3f31c97268', 273, 'Casting & Scelte', 'Il ruolo centrale di Paola Cortellesi', 'Paola Cortellesi fu scelta per interpretare il ruolo eponimo di Claudia, fulcro emotivo e comico attorno a cui ruotano le vite dei tre protagonisti. L''attrice romana ha dichiarato in diverse interviste di aver lavorato molto sull''ambiguità del personaggio, capace di disorientare completamente tre uomini così diversi tra loro.', 'Intervista promozionale a Paola Cortellesi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:34:04.772586+00:00'),
('df7e84a2-ada7-4a68-a354-7c968d31f241', 273, 'Curiosità & Retroscena', 'La collaborazione con la Banda Osiris', 'La colonna sonora del film è stata curata dalla Banda Osiris, storico sodalizio artistico con cui il trio comico aveva già collaborato in precedenza, contribuendo in modo determinante a definire il ritmo comico e malinconico delle sequenze chiave.', 'Crediti ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:34:04.772586+00:00'),
('6875b9c7-ac5e-4d62-9db4-850dc22d30bd', 354, 'Curiosità & Retroscena', 'Il titolo originale e la genesi dell''articolo', 'Il film è basato sull''articolo di giornale ''The Long March for Ransom'' scritto da Vanessa Bauza per il settimanale ''The Plain Dealer'' e sul libro di memorie ''Proof of Life'' di Thomas Hargrove, ingegnere americano rapito in Colombia nel 1994.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:35:25.701801+00:00'),
('6883a804-df21-4197-9754-98ba1f26104e', 354, 'Casting & Scelte', 'La vera natura della relazione sul set', 'Durante le riprese del film, i protagonisti Meg Ryan e Russell Crowe intrapresero una relazione sentimentale nella vita reale, un fatto che attirò una notevole attenzione mediatica internazionale e che portò alla fine del matrimonio della Ryan con Dennis Quaid.', 'Cronache e riviste di gossip e cinema del 2000', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:35:25.701801+00:00'),
('de64db83-d49b-4dfa-bd6f-c652f2d4bd5e', 219, 'Segreti di produzione', 'L''invenzione dell''illuminazione elettrica sul set', 'Per superare i limiti della luce naturale e girare gli interni complessi ricosturiti a Villa Pacelli, la produzione fece ricorso a un imponente impianto di dinamo e lampade ad arco elettrico, una soluzione tecnologica all''avanguardia per il cinema italiano del 1913.', 'Archivio storico della Cines e memorie di Enrico Guazzoni', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:33:19.146274+00:00'),
('0955f8f1-a408-48cf-906e-e880d5373964', 219, 'Effetti speciali & Trucco', 'Il modello in scala del Circo di Nerone', 'Le spettacolari sequenze del Circo di Nerone e dell''incendio di Roma non furono realizzate solo con le grandi scenografie reali, ma anche grazie all''uso sapiente di modelli in scala ridotta ripresi in sovrimpressione e prospettiva forzata, anticipando le tecniche del kolossal moderno.', 'Studi storiografici sul cinema muto italiano e tecniche di Guazzoni', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:33:19.146274+00:00'),
('ba4c1e19-d1c9-4378-b5f7-56220801bc26', 219, 'Curiosità & Retroscena', 'La distribuzione pionieristica negli Stati Uniti', 'Il film fu uno dei primi titoli italiani a conquistare il mercato nordamericano, dove fu distribuito nel 1913 dalla George Kleine Attraction, ottenendo un tale successo a New York da costringere i cinema a programmarlo per mesi interi con orchestre sinfoniche dal vivo.', 'Cataloghi storici di distribuzione cinematografica statunitense', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:33:19.146274+00:00'),
('81f8537d-66cb-4add-a84b-51fa4620a4b6', 260, 'Casting & Scelte', 'La genesi del personaggio ispirata ai figli', 'L''idea originale di ''Nobody'' è nata quando la casa di Bob Odenkirk è stata svaligiata per due volte nel giro di breve tempo; l''attore ha confessato di aver reagito inizialmente in modo passivo per proteggere la famiglia, un senso di impotenza e frustrazione che ha poi riversato direttamente nella costruzione psicologica del protagonista Hutch Mansell.', 'Intervista ufficiale a Bob Odenkirk per Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:33:43.309624+00:00'),
('ac295a7d-d710-4837-ba1a-12a43c2b98da', 260, 'Aneddoti dal set', 'L''allenamento con Daniel Bernhardt', 'Per prepararsi alle complesse sequenze di azione, Bob Odenkirk ha trascorso oltre due anni ad allenarsi duramente presso la 87Eleven Action Design, lavorando a stretto contatto con lo stuntman e attore Daniel Bernhardt, che nel film interpreta l''avversario nel celebre scontro sul bus.', 'Featurette ''Hutch Takes the Bus'' nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:33:43.309624+00:00'),
('5ea91836-06f9-49c8-98fd-41955bf626a2', 260, 'Citazioni & Easter Egg', 'L''omaggio a Hardcore Henry', 'In una scena del film, all''interno dell''ufficio di Hutch si può notare chiaramente un monitor che trasmette immagini dal precedente film d''esordio del regista Ilya Naishuller, ''Hardcore Henry'' (2015), un chiaro e autoreferenziale Easter egg inserito dalla troupe.', 'Commento audio del regista Ilya Naishuller e dello sceneggiatore Derek Kolstad', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:33:43.309624+00:00'),
('db6699da-3528-4bd4-a2fe-69d73f44c346', 260, 'Segreti di produzione', 'La scelta dei proiettili d''oro', 'Il dettaglio dei proiettili placcati in oro utilizzati dal personaggio di Yulian Kuznetsov non è solo un vezzo estetico da gangster eccentrico, ma è stato ideato dal reparto scenografia per sottolineare visivamente l''enorme ricchezza e l''arroganza del boss mafioso russo.', 'Note di produzione e design del dipartimento artistico', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:33:43.309624+00:00'),
('3561c8fa-bc2f-4361-8567-e960f8593dd7', 260, 'Aneddoti dal set', 'L''improvvisazione di Michael Ironside', 'Il veterano Michael Ironside, che interpreta il suocero di Hutch, Eddie Williams, ha improvvisato diverse battute taglienti durante le scene di tensione familiare a tavola, cogliendo di sorpresa gli altri attori e rendendo le reazioni dei personaggi ancora più autentiche e spiazzanti.', 'Intervista al cast sul set pubblicata da Collider', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:33:43.309624+00:00'),
('5103a520-02d3-4813-879a-466f5bd08249', 271, 'Curiosità & Retroscena', 'La genesi musicale degli Elio e le Storie Tese', 'La colonna sonora del film è interamente affidata agli Elio e le Storie Tese, che per l''occasione realizzarono brani iconici come ''Evviva'' e ''La vispa Teresa''. Il sodalizio nacque grazie alla forte amicizia tra il gruppo musicale e il trio comico, consolidando un''estetica surreale condivisa.', 'Note di produzione ufficiali e credits del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:33:58.932991+00:00'),
('6434ab44-3d1e-4c12-95f3-3ff334dc569d', 271, 'Aneddoti dal set', 'L''improvvisazione nella scena della tenda', 'Durante la sequenza in cui i tre protagonisti dormono stretti nella tenda da campeggio in montagna, gran parte dei dialoghi surreali sui sogni e sulle prospettive di vita fu frutto di una lunga improvvisazione sul set tra Aldo, Giovanni e Giacomo, poi mantenuta quasi integralmente nel montaggio finale.', 'Making-of ufficiale e contenuti extra del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:33:58.932991+00:00'),
('d75e349c-6024-4676-b884-05f68c76e1f9', 271, 'Casting & Scelte', 'Il nome in codice ''Bancomat''', 'Il soprannome del personaggio di Aldo, ''Bancomat'', fu scelto dagli sceneggiatori e dal regista Massimo Venier per sottolineare in modo ironico la sua abilità criminale anomala e moderna, in contrasto stridente con la sua aria stralunata e naif.', 'Intervista retrospettiva a Massimo Venier', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:33:58.932991+00:00'),
('cd50d7a2-9366-4eb6-9db5-80930470662d', 271, 'Segreti di produzione', 'Le difficoltà climatiche sulle vette abruzzesi', 'Le riprese in alta quota sui monti dell''Abruzzo registrarono sbalzi termici notevoli e improvvisi banchi di nebbia che costrinsero la troupe a frequenti stop tecnici, obbligando gli operatori a riadattare continuamente il piano di lavorazione giornaliero.', 'Diario di bordo della troupe e backstage cinematografico', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:33:58.932991+00:00'),
('6e74011a-db30-40a0-8156-cc3d91251125', 276, 'Curiosità & Retroscena', 'L''ispirazione originaria del fumetto di Picaud & Erroc', 'Il film trae le sue origini non solo dal lungometraggio francese del 2013, ma direttamente dalla celebre serie a fumetti ''Les Profs'' creata da Picaud ed Erroc, pubblicata da Bamboo Édition, che ha venduto milioni di copie in Francia e ha fornito la struttura visiva per caratterizzare le bizzarrie dei professori.', 'Note di produzione ufficiali e dossier stampa del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:34:08.277227+00:00'),
('c104e95a-7b51-43c8-a796-2ba9a7e04ba7', 276, 'Casting & Scelte', 'La preparazione atletica di Alessio Sakara', 'L''famoso lottatore di MMA Alessio Sakara, chiamato a interpretare il professore di gie (educazione fisica) dal metodo brutale, ha lavorato a stretto contatto con il regista Ivan Silvestrini per calibrare i suoi interventi fisici al limite del paradosso, sfruttando la sua reale corporatura imponente per gag slapstick.', 'Intervista rilasciata da Alessio Sakara durante il press tour promozionale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:34:08.277227+00:00'),
('5b47f804-2070-45d2-ae31-2d60459b4bd7', 276, 'Aneddoti dal set', 'La gestione dei tempi comici tra Bisio e Guanciale', 'Durante le riprese delle scene corali in presidenza, Claudio Bisio e Lino Guanciale si sono spesso affidati all''improvvisazione basata sui loro differenti background teatrali (più cabarettistico il primo, più rigoroso e classico il secondo), creando un contrasto naturale che ha divertito la troupe sul set.', 'Backstage ufficiale e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:34:08.277227+00:00'),
('b78b0f12-354a-443d-8ed2-45004e5b5c5f', 297, 'Casting & Scelte', 'La reunion Marvel sul set', 'Jeremy Renner ed Elizabeth Olsen si sono ritrovati a recitare insieme in questo film prima di riprendere i loro ruoli di Occhio di Falco e Wanda Maximoff/Scarlet Witch nel Cinematic Universe della Marvel.', 'Note di produzione ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:34:16.373884+00:00'),
('5da29adc-6e5a-4bc3-b091-a407a7cc7a8f', 220, 'Segreti di produzione', 'Il coinvolgimento di Arturo Ambrosio nella produzione esecutiva', 'Il pioniere del cinema muto italiano Arturo Ambrosio ebbe un ruolo chiave nella gestione logistica del kolossal, coordinando una troupe mista italo-tedesca e supervisionando la costruzione delle imponenti scenografie presso gli stabilimenti della Cines a Roma.', 'Note di produzione d''epoca e biografie di settore', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:33:22.088048+00:00'),
('b3005708-7c20-4200-af64-e9ba7b1de89d', 220, 'Effetti speciali & Trucco', 'La ricostruzione monumentale del Circo Massimo', 'Per girare le imponenti sequenze delle persecuzioni cristiane, la produzione fece edificare nei pressi di Roma una riproduzione in scala colossale del Circo Massimo e di parti dell''antica Urbe, utilizzando migliaia di comparse reclutate tra la popolazione locale e reduci della prima guerra mondiale.', 'Monografia storica sul kolossal muto italiano', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:33:22.088048+00:00'),
('7090905c-04e6-400b-b84e-3f9489237ff8', 220, 'Effetti speciali & Trucco', 'L''uso innovativo della luce artificiale nelle scene notturne', 'I direttori della fotografia impiegarono per la prima volta su larga scala nel cinema italiano le nuove potenti lampade ad arco fotogeniche per simulare gli incendi di Roma e le scene notturne all''aperto, superando i limiti dei precedenti set illuminati unicamente dalla luce solare naturale.', 'Rivista tecnica ''La Vita Cinematografica'', 1924', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:33:22.088048+00:00'),
('3a416ea1-49a4-4d9e-8c4a-149d8bce174a', 289, 'Casting & Scelte', 'La tensione per il taglio di capelli di Freddie Bartholomew', 'Il giovane Freddie Bartholomew dovette sottoporsi a un taglio di capelli drastico per interpretare il viziato Harvey Cheyne all''inizio del film, un cambiamento estetico supervisionato personalmente da Louis B. Mayer per accentuare visivamente la sua trasformazione caratteriale.', 'Note di produzione MGM sugli archivi storici', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:34:11.290303+00:00'),
('8793709a-86fa-4063-85be-2e5200ed9aff', 289, 'Aneddoti dal set', 'La preparazione marittima di Spencer Tracy', 'Per prepararsi al ruolo del pescatore portoghese Manuel, Spencer Tracy trascorse diversi giorni a bordo di veri pescherecci di Gloucester, studiando i movimenti dei marinai e imparando a maneggiare le reti per risultare credibile nelle scene oceaniche.', 'Biografia ufficiale di Spencer Tracy e registri di lavorazione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:34:11.290303+00:00'),
('87b4acaf-b875-4309-bc62-f91e15f2f4e4', 289, 'Segreti di produzione', 'Le difficoltà di ripresa in mare aperto', 'Le riprese in mare aperto al largo delle coste del Massachusetts furono funestate da forti mareggiate e nebbie fitte, che costrinsero la troupe guidata da Victor Fleming a ripetere più volte le sequenze di pesca a causa della scarsa visibilità.', 'Diari di bordo della troupe e report della produzione MGM', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:34:11.290303+00:00'),
('4bdcabd8-84f4-4c00-a838-ce852032231b', 289, 'Effetti speciali & Trucco', 'L''uso di vasche di posa per le tempeste', 'Nonostante le riprese reali, alcune delle scene di tempesta più pericolose furono ricostruite nei teatri di posa di Culver City utilizzando enormi vasche d''acqua agitate da macchinari idraulici e potenti ventilatori.', 'Documentari tecnici sugli effetti speciali della Golden Age di Hollywood', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:34:11.290303+00:00'),
('ac6db17a-89c8-4504-b2ce-d181864e56ba', 327, 'Curiosità & Retroscena', 'La controversia sul titolo provvisorio', 'Durante le prime fasi di sviluppo e per buona parte della produzione, il film è stato realizzato sotto il titolo di lavorazione ''Vengeance'', basato direttamente sul libro di saggistica di George Jonas. La produzione ha cambiato il titolo semplicemente in ''Munich'' poco prima della distribuzione cinematografica per focalizzare l''attenzione sul contesto storico dell''attentato terroristico.', 'Note di produzione ufficiali della Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:34:52.466616+00:00'),
('62fea0fe-e052-4a66-b56d-d35e33bbac47', 327, 'Casting & Scelte', 'La consulenza di Avner Kaufman', 'La produzione ha cercato di mantenere il massimo riserbo sulle identità reali dei personaggi, ma è stato ampiamente documentato che la storia si basa sulle memorie contestate di Yuval Aviv, ex agente del Mossad che ha operato come consulente sul set per assicurarsi che le procedure di spionaggio e le armi fossero rappresentate con accuratezza.', 'Intervista a Steven Spielberg e agli sceneggiatori', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:34:52.466616+00:00'),
('7d67c0f5-6364-40cb-af27-58668e386382', 327, 'Aneddoti dal set', 'Le riprese nel Mediterraneo e a Cipro', 'Oltre alle location ungheresi e francesi, la troupe si è spostata a Cipro e a Malta per girare le sequenze ambientate a Beirut e in altre zone del Medio Oriente degli anni ''70. Durante le riprese a Cipro, la produzione ha dovuto gestire complesse autorizzazioni diplomatiche locali a causa delle delicate tensioni geopolitiche evocate dalla trama del film.', 'Making-of ufficiale ''The Making of Munich''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:34:52.466616+00:00'),
('e08254b2-7a9b-43af-9727-3bf7d5d679ec', 327, 'Segreti di produzione', 'L''uso limitato della CGI', 'Steven Spielberg e il supervisore degli effetti visivi Pablo Helman hanno scelto di ridurre al minimo l''uso della grafica computerizzata, preferendo effetti pratici sul set e modellini in scala per le esplosioni delle autobombe, in modo da mantenere un impatto visivo crudo e realistico coerente con il cinema politico degli anni ''70.', 'American Cinematographer, intervista a Pablo Helman', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:34:52.466616+00:00'),
('6c8adf73-3bd5-43c0-91b2-727e919395e8', 327, 'Segreti di produzione', 'I costumi d''epoca di Joanna Johnston', 'La costumista Joanna Johnston ha studiato migliaia di fotografie d''archivio di capi di stato, spie e civili europei e mediorientali tra il 1972 e il 1974. Ogni abito indossato da Eric Bana e dagli altri attori è stato realizzato su misura per riflettere lo status sociale in evoluzione dei personaggi e il loro progressivo distacco dalla vita borghese.', 'Note di produzione e intervista a Joanna Johnston', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:34:52.466616+00:00'),
('d47e0610-e47d-44ed-8c4a-b360a52ffc3f', 4, 'Aneddoti dal set', 'L''improvvisazione della camminata iconica', 'La celebre e bizzarra andatura di Ace Ventura non era interamente prescritta nel copione originale, ma fu concepita e perfezionata da Jim Carrey sul set per enfatizzare la natura eccentrica e animalesca del personaggio. Il regista Tom Shadyac incoraggiò l''attore a esplorare fisicità estreme, trasformando la camminata in uno dei marchi di fabbrica più riconoscibili della commedia anni ''90.', 'Commento audio del regista Tom Shadyac nell''edizione DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:35:41.328003+00:00'),
('6863be6d-3a4d-4daa-833f-f9ce4dbd696a', 4, 'Casting & Scelte', 'La scelta del look e il taglio di capelli', 'Il celebre taglio di capelli a spazzola di Ace Ventura fu fortemente voluto da Jim Carrey stesso, il quale collaborò direttamente con i reparti di trucco e acconciatura per creare una silhouette che ricordasse un pennuto o un animale selvatico. Questo look peculiare contribuì a rendere il personaggio immediatamente iconico fin dal materiale promozionale.', 'Documentario retrospettivo ''The Making of Ace Ventura'' sul Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:35:41.328003+00:00'),
('52637f9b-6597-4b36-80ca-31f918ad46b9', 4, 'Segreti di produzione', 'Il coinvolgimento di veri animali sul set', 'Per girare le sequenze nell''appartamento di Ace, la produzione ingaggiò esperti addestratori di animali selvatici ed esotici per gestire scimmie, uccelli, cani e rettili in piena sicurezza. Gran parte degli animali presenti nella scena iniziale erano reali e supervisionati costantemente da specialisti accreditati dall''American Humane Association.', 'Note di produzione e report di set dell''American Humane Association', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:35:41.328003+00:00'),
('bf575009-9cf2-457f-a0de-12e43106fbe7', 259, 'Aneddoti dal set', 'La frustrazione di Hugh Grant con la tuta per il motion capture', 'Hugh Grant ha definito l''esperienza di interpretare l''Oompa Loompa come ''orribile'', spiegando di aver dovuto indossare una fastidiosa struttura con punti di cattura e telecamere sul viso che lo facevano sentire un ''albero''. L''attore ha ammesso candidamente nelle interviste promozionali di non aver capito se dovesse recitare con il corpo o solo con le espressioni facciali.', 'Intervista ufficiale stampa Warner Bros. e Graham Norton Show', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:33:39.233444+00:00'),
('87cdcf7c-e1dc-45bc-89d6-eb7be7d26b1a', 259, 'Segreti di produzione', 'Il tributo ai costumi storici di Sandy Powell', 'La celebre costumista tre volte premio Oscar Sandy Powell ha disegnato gli abiti del film traendo ispirazione diretta sia dalle illustrazioni originali di Quentin Blake per i libri di Roald Dahl sia dai film musicali classici della MGM degli anni ''50. Per il cappotto di velluto bordeaux di Willy Wonka, la Powell ha voluto ricreare lo stesso identico punto di colore reso celebre da Gene Wilder nel film del 1971.', 'Note di produzione ufficiali e interviste ai reparti artistici', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:33:39.233444+00:00'),
('83b1a6d5-31c0-457c-b301-6a1560e6c1c0', 259, 'Effetti speciali & Trucco', 'La scena della giraffa e il lavoro con gli animali animatronici', 'Per la sequenza in cui Willy e Noodle mungono una giraffa in cattività, la produzione ha combinato l''utilizzo di una testa di giraffa parzialmente animatronica realizzata dal team di creature effects con la CGI avanzata. Timothée Chalamet ha dovuto interagire con supporti fisici sul set per simulare il peso e i movimenti imprevedibili dell''animale esotico.', 'Making-of ufficiale e contenuti speciali Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:33:39.233444+00:00'),
('ca911188-343e-4dfb-9dd4-2fc6998a753f', 259, 'Casting & Scelte', 'Il cameo vocale di Rowan Atkinson e l''umorismo britannico', 'L''attore britannico Rowan Atkinson (famoso per Mr. Bean) è stato scelto personalmente da Paul King per interpretare il corrotto Padre Julius, un ecclesiastico dipendente dal cioccolato. La sua spalla comica e i tempi scenici derivano direttamente dalla sua lunga esperienza nella commedia fisica britannica, fortemente voluta dal regista per dare un tono grottesco ai cattivi della storia.', 'Note di regia e pressbook internazionale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:33:39.233444+00:00'),
('a573c173-7ef9-461b-867d-98c9b2f4c206', 270, 'Segreti di produzione', 'L''ambientazione americana ricostruita in Italia', 'Nonostante la storia sia ambientata interamente a New York nel 1959, la maggior parte delle riprese non è stata effettuata negli Stati Uniti, ma in location italiane e negli studi cinematografici, sfruttando una meticolosa ricostruzione scenografica per simulare l''atmosfera della Grande Mela.', 'Note di produzione ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:33:54.712846+00:00'),
('7ed27bc9-30bc-4c89-8129-dbe5d4139e4e', 270, 'Casting & Scelte', 'Il trio comico alla prova con il genere gangster', 'Dopo il successo dei precedenti film campioni d''incassi, Aldo, Giovanni e Giacomo decisero di cimentarsi con una commedia in costume e di ambientazione storica, discostandosi dai personaggi contemporanei interpretati nelle pellicole precedenti come ''Tre uomini e una gamba'' o ''Chiedimi se sono felice''.', 'Interviste promozionali d''archivio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:33:54.712846+00:00'),
('fedee783-baba-471c-aab5-b52a2e852023', 270, 'Casting & Scelte', 'La collaborazione con Aldo Maccione', 'La scelta di ingaggiare il celebre attore Aldo Maccione per il ruolo del boss mafioso rappresentò un omaggio alla commedia italiana classica, inserendo un''icona del cinema italiano degli anni ''70 a fianco della comicità moderna del trio.', 'Backstage e documentario ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:33:54.712846+00:00'),
('c4b7e058-c641-4c00-b588-b912082eab19', 270, 'Citazioni & Easter Egg', 'Ispirazione ai classici della mafia', 'Il film omaggia apertamente e parodizza i canoni estetici e narrativi dei grandi gangster movie di Hollywood, da ''C''era una volta in America'' a ''Il padrino'', riprendendo i codici visivi del genere per piegarli alla comicità surreale.', 'Analisi critica della stampa cinematografica', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:33:54.712846+00:00'),
('4bc66742-d9db-47db-843a-0f898384546a', 270, 'Curiosità & Retroscena', 'La continuità con Massimo Venier alla regia', 'Il film segna la quarta collaborazione consecutiva al cinema tra Aldo, Giovanni e Giacomo e il regista Massimo Venier, consolidando quel sodalizio artistico che aveva definito l''estetica cinematografica del trio sin dal loro debutto sul grande schermo nel 1997.', 'Archivio storico del cinema italiano', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:33:54.712846+00:00'),
('ec352a83-a415-4636-ae6c-138c5956e00e', 325, 'Casting & Scelte', 'La seconda collaborazione consecutiva con Scarlett Johansson', 'Woody Allen rimase così colpito dal talento e dalla professionalità di Scarlett Johansson durante le riprese di ''Match Point'' (2005) da volerla immediatamente nel cast di ''Scoop'' prima ancora che il film precedente uscisse nelle sale. La scelse come protagonista affidandole un ruolo di registro completamente diverso, virando dalla tragedia drammatica alla commedia brillante.', 'Note di produzione ufficiali e interviste stampa del 2006', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:34:43.021447+00:00'),
('abe8e7f1-d467-4ef0-a332-30806bd3550e', 325, 'Curiosità & Retroscena', 'Il ritorno di Woody Allen davanti alla macchina da presa', 'Con questo film Woody Allen torna a recitare in un suo lungometraggio dopo un breve periodo di assenza, interpretando l''esilarante mago di seconda categoria Sid Waterman. Per prepararsi al ruolo, l''attore e regista ha dovuto studiare e apprendere diversi trucchi di magia classica sotto la supervisione di illusionisti professionisti sul set.', 'Pressbook ufficiale del film e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:34:43.021447+00:00'),
('a9c6851e-7d31-45e1-9848-2d190f91f804', 325, 'Segreti di produzione', 'L''ambientazione londinese voluta dal regista', 'Dopo il successo di ''Match Point'', Woody Allen decidette di girare nuovamente a Londra per sfruttare le agevolazioni fiscali britanniche e la suggestiva estetica della capitale inglese. La città offre una perfetta commistione tra l''architettura classica e moderna che ben si sposa con i toni del giallo-commedia della pellicola.', 'Making-of ufficiale e resoconti della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:34:43.021447+00:00'),
('c1bf3f74-3051-49a8-9a51-e799c9d12ceb', 325, 'Citazioni & Easter Egg', 'Il tributo ai classici della commedia gialla', 'La struttura narrativa di ''Scoop'', incentrata su una giornalista in erba e un investigatore improvvisato che indagano su un presunto serial killer aristocratico, ricalca volutamente le classiche dinamiche dei gialli cinematografici degli anni ''30 e ''40 e richiama fortemente le atmosfere di ''Omicidio a bordo'' (The Last of Sheila) e i toni leggeri dei film di Agatha Christie.', 'Recensioni storiche e analisi critiche del cinema di Woody Allen', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:34:43.021447+00:00'),
('3c274295-5eb4-490c-b69e-781cdc4fd3a4', 8, 'Casting & Scelte', 'Il provino rifiutato da Julia Roberts', 'Julia Roberts fu originariamente scelta per interpretare Mary Corleone, ma l''attrice dovette rinunciare all''ultimo minuto a causa di conflitti di programmazione e di una grave infezione influenzale che la costrinse a rifiutare la parte, aprendo la strada all''ingresso nel cast di Sofia Coppola.', 'Biografie ufficiali e documentari sulla produzione di The Godfather Part III', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:35:53.40309+00:00'),
('19975da9-ccec-441e-aa4b-316404cf2dd7', 297, 'Curiosità & Retroscena', 'La connessione con Sicario e Hell or High Water', 'Wind River rappresenta il capitolo finale della trilogia non ufficiale scritta da Taylor Sheridan incentrata sulla frontiera americana moderna, preceduto da Sicario (2015) e Hell or High Water (2016).', 'Intervista ufficiale a Taylor Sheridan', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:34:16.373884+00:00'),
('f7fba438-34a9-4620-887e-9f1984066385', 297, 'Aneddoti dal set', 'Condizioni meteorologiche estreme', 'Le riprese si sono svolte nello Utah e nel Wyoming a temperature spesso inferiori ai 20 gradi sotto zero, costringendo la troupe a utilizzare riscaldatori portatili speciali per evitare che le telecamere si congelassero.', 'Diario di bordo del direttore della fotografia Ben Richardson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:34:16.373884+00:00'),
('c247c731-780d-4dd6-be89-c1378727c7d4', 297, 'Casting & Scelte', 'Il casting di Gil Birmingham', 'L''attore nativo americano Gil Birmingham è stato fortemente voluto da Taylor Sheridan dopo aver lavorato insieme in Hell or High Water, per dare un volto autentico e di grande spessore emotivo al dolore del padre della vittima.', 'Special TV featurette sul casting', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:34:16.373884+00:00'),
('d1347325-f8ce-4a0f-a236-803a2da9482d', 297, 'Segreti di produzione', 'L''uso limitato della CGI', 'Per mantenere il massimo realismo visivo, la produzione ha evitato l''uso di effetti digitali per la neve e i paesaggi, affidandosi interamente a location reali nello Utah che imitavano perfettamente le lande desolate del Wyoming.', 'Articolo di approfondimento tecnico su American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:34:16.373884+00:00'),
('ecc76c52-abfa-4b98-af72-055d99678f6c', 297, 'Aneddoti dal set', 'La preparazione atletica e di sopravvivenza', 'Jeremy Renner ha trascorso diversi giorni a vivere a stretto contatto con guide alpine ed esperti di tracciamento nella neve per apprendere i movimenti corretti del cacciatore di predatori prima di girare la prima scena.', 'Intervista a Jeremy Renner per Collider', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:34:16.373884+00:00'),
('15492039-e969-4ec8-9431-0bfe63778a34', 136, 'Curiosità & Retroscena', 'La modifica del titolo originale', 'Durante la fase di lavorazione e persino poco prima della distribuzione nelle sale cinematografiche, il film era originariamente intitolato ''They Died with Their Boots On'', ma in seguito la Warner Bros. valutò diverse variazioni per il mercato internazionale prima di confermare il titolo definitivo.', 'Warner Bros. Production Archives', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:05:16.320358+00:00'),
('4894cbfa-d5bf-4393-82df-b1513ac6244e', 309, 'Curiosità & Retroscena', 'L''introduzione del Popolo della Cenere', 'James Cameron ha rivelato che in questo terzo capitolo la rappresentazione dei Na''vi non sarà più divisa rigidamente tra buoni e cattivi, introducendo il ''Popolo della Cenere'' (Ash People) per mostrare un lato più aggressivo, oscuro e manipolatore della specie nativa di Pandora.', 'D23 Expo e interviste ufficiali di James Cameron', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:34:27.645453+00:00'),
('36ca3af0-c3c8-466c-ada4-87d1888fb806', 309, 'Casting & Scelte', 'Il ruolo guida di Oona Chaplin', 'L''attrice Oona Chaplin, celebre per il suo ruolo in ''Game of Thrones'', è stata ingaggiata per interpretare Varang, la spietata leader del Popolo della Cenere, diventando una figura centrale e antagonista chiave nella trama del film.', 'Comunicati stampa ufficiali della 20th Century Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:34:27.645453+00:00'),
('2d51ded5-b48f-434e-a5da-ff6f3ebf727c', 309, 'Effetti speciali & Trucco', 'La continuità delle riprese subacquee e di performance capture', 'Gran parte delle riprese con la tecnica di performance capture si sono svolte simultaneamente a quelle del secondo capitolo ''La via dell''acqua'', per evitare il problema della crescita anagrafica dei giovani attori come Jack Champion sul set.', 'Note di produzione e reportage dal set di Jon Landau', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:34:27.645453+00:00'),
('a6727d2f-4791-4869-ab36-98ea93aec5ff', 309, 'Segreti di produzione', 'La gestione della performance capture in condizioni estreme', 'James Cameron e la troupe della Lightstorm Entertainment hanno dovuto perfezionare ulteriormente i sistemi di marcatura facciale subacquea per consentire agli attori come Sam Worthington e Zoe Saldaña di recitare in vasche da 900.000 litri d''acqua senza perdere la precisione dei dati digitali.', 'Note di produzione ufficiali Lightstorm Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:34:27.645453+00:00'),
('e5e39929-9bec-4e9c-8b60-1eda1ddb8306', 309, 'Casting & Scelte', 'Il ritorno di Sigourney Weaver in un ruolo inedito', 'Dopo aver interpretato la dottoressa Grace Augustine nel primo film, Sigourney Weaver ha affrontato la complessa sfida di impersonare Kiri, un''adolescente Na''vi legata misticamente a Eywa, studiando il comportamento e le voci di veri adolescenti.', 'Intervista ufficiale Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:34:27.645453+00:00'),
('6289bfc9-a2f6-4dcd-afdc-35028dcdb55e', 309, 'Curiosità & Retroscena', 'L''espansione della mitologia di Pandora', 'Il produttore Jon Landau ha confermato che in questo terzo capitolo viene esplorata una porzione geografica completamente inedita di Pandora, distaccandosi dagli ambienti marini di The Way of Water per focalizzarsi su biomi vulcanici e desertici.', 'Conferenza stampa ufficiale CinemaCon', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:34:27.645453+00:00'),
('a0d7a060-dc3e-4650-a2ae-f9d65dc52b90', 309, 'Aneddoti dal set', 'La sfida logistica delle riprese simultanee', 'Gran parte delle sequenze con i giovani attori che interpretano la nuova generazione di Na''vi sono state girate anni prima dell''uscita cinematografica per evitare evidenti cambiamenti fisici dovuti alla crescita naturale del cast giovanile.', 'Making-of ufficiale e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:34:27.645453+00:00'),
('8842849c-af3f-46e3-951e-c56a17789291', 351, 'Curiosità & Retroscena', 'La graphic novel originale di Alan Moore e Eddie Campbell', 'Il film è l''adattamento cinematografico della celebre graphic novel omonima ''From Hell'' creata da Alan Moore e Eddie Campbell, sebbene i registi Albert e Allen Hughes abbiano dichiarato di aver modificato significativamente il finale e il destino di alcuni personaggi rispetto alla controparte cartacea.', 'Note di produzione ufficiali della 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:35:19.527848+00:00'),
('7358183c-8428-4b38-90c9-01aeacf3509d', 351, 'Casting & Scelte', 'Il rifiuto iniziale dei fratelli Hughes', 'I registi Albert e Allen Hughes inizialmente rifiutarono l''offerta di dirigere il film perché ritenevano che la sceneggiatura iniziale non rispettasse lo spirito complesso del fumetto di Alan Moore, accettando l''incarico solo dopo che il copione fu riscritto da Terry Hayes.', 'Intervista retrospettiva ai registi nel making-of del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:35:19.527848+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('a722ede1-3847-4424-b646-0e7291d0defb', 351, 'Segreti di produzione', 'La ricostruzione di Whitechapel a Praga', 'Poiché il vero quartiere di Whitechapel a Londra era ormai troppo modernizzato per rappresentare l''epoca vittoriana, la produzione ha deciso di ricostruire interamente i vicoli londinesi nei Barrandov Studios e nelle strade esterne di Praga, nella Repubblica Ceca.', 'Featurette ''The Making of From Hell'' nel contenuto extra', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:35:19.527848+00:00'),
('119e3501-533f-4e82-85b4-fdf35ffaf8aa', 351, 'Curiosità & Retroscena', 'L''uso dell''assenzio e la dipendenza di Abberline', 'Nel film viene dato grande risalto alla dipendenza dell''ispettore Abberline dall''assenzio e dall''oppio per indurre le sue visioni chiaroveggenti; tali elementi visivi lisergici sono stati realizzati mescolando riprese rallentate e filtri di colore cianotico sul set.', 'Commento audio del regista Albert Hughes', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:35:19.527848+00:00'),
('75089177-0d79-4a7b-9fa2-cef39bb49e63', 298, 'Segreti di produzione', 'La scelta della luce naturale e la regola del crepuscolo', 'Il direttore della fotografia Emmanuel Lubezki e il regista Alejandro G. Iñárritu decisero di girare l''intero film utilizzando esclusivamente luce naturale. Per rispettare questo dogmatico vincolo, la troupe aveva a disposizione solo una finestra temporale di circa novanta minuti al giorno durante il crepuscolo pomeridiano per catturare le scene chiave.', 'Diario di produzione e interviste ufficiali a Emmanuel Lubezki', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:34:20.857671+00:00'),
('2f378abc-5fbd-4553-8ea4-ab64a0eaba3e', 298, 'Aneddoti dal set', 'Il fegato di bisonte crudo mangiato da Leonardo DiCaprio', 'Sebbene Leonardo DiCaprio sia vegetariano nella vita reale, nella drammatica scena in cui Hugh Glass mangia un fegato di bisonte crudo per sopravcipere, l''attore accettò di consumare un organo vero. Lo scenografo e la produzione avevano preparato una finta versione di cioccolato e gelatina per le prove, ma per la ripresa ufficiale fu utilizzato un vero fegato animale.', 'Intervista ufficiale di Variety a Leonardo DiCaprio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:34:20.857671+00:00'),
('c9ac7fc9-2e1e-4c6d-92ba-7f84737c9404', 298, 'Casting & Scelte', 'La preparazione linguistica di Duane Howard', 'L''attore Duane Howard, che interpreta il capo Arikara Elk Dog, ha dovuto lavorare intensamente con un linguista per imparare correttamente la lingua Pawnee (usata nel film per rappresentare quella della tribù Arikara). Nonostante le sue origini indigene (First Nations canadesi), non conosceva quel particolare idioma storico.', 'Note di produzione ufficiali della 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:34:20.857671+00:00'),
('acf1e752-6c1e-4964-9b0b-b7abd5c384f8', 298, 'Effetti speciali & Trucco', 'L''uso pionieristico delle lenti grandangolari digitali', 'Per enfatizzare il senso di isolamento e immersione nei paesaggi incontaminati, la produzione ha utilizzato quasi esclusivamente cineprese digitali ARRI Alexa XT M e le nuovissime lenti grandangolari Prime DNA. Questa combinazione tecnica ha costretto la troupe a lavorare vicinissimi agli attori, catturando anche il respiro e la condensa sulle lenti.', 'American Cinematographer, articolo tecnico di approfondimento', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:34:20.857671+00:00'),
('157ec606-9806-439f-9d06-a6e571bd4194', 298, 'Aneddoti dal set', 'Il congelamento dell''attrezzatura e le cineprese in tilt', 'Le temperature estreme registrate in Canada e in seguito in Argentina, scese spesso ben al di sotto dei -25°C, causarono gravi malfunzionamenti meccanici. Le telecamere digitali si bloccavano regolarmente a causa del freddo intenso, costringendo i tecnici a costruire speciali custodie termiche riscaldate artigianalmente per evitare lo stop delle riprese.', 'Special contenuto nel Blu-ray ufficiale ''A World Unseen: Making The Revenant''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:34:20.857671+00:00'),
('42cefae6-6062-455c-8b12-01010044e017', 298, 'Effetti speciali & Trucco', 'Il trucco prostetico di Leonardo DiCaprio', 'Il celebre trucco delle ferite inflitte dall''orso al corpo di Hugh Glass richiedeva ogni giorno fino a cinque ore di applicazione da parte del reparto guidato da Siân Grigg. Le protesi erano realizzate in silicone avanzato per muoversi in modo estremamente realistico con la pelle dell''attore durante le sequenze di sforzo fisico.', 'Intervista al make-up designer Siân Grigg per Makeup Artist Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:34:20.857671+00:00'),
('f2a92b5b-a1ae-4d8f-9ac8-e16c391554ec', 310, 'Aneddoti dal set', 'L''addestramento subacqueo dei Navy SEAL', 'Per girare le scene sott''acqua in apnea, tutto il cast principale, inclusi Kate Winslet e Sigourney Weaver, è stato seguito da istruttori professionisti di immersione dei Navy SEAL per imparare tecniche di respirazione e controllo del battito cardiaco.', 'Documentario di produzione ufficiale e interviste a Vanity Fair', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:34:31.717283+00:00'),
('bb9318cc-8802-40f2-a28c-dae653fd3fe0', 310, 'Aneddoti dal set', 'Il record di apnea di Kate Winslet', 'L''attrice Kate Winslet ha sorpreso la troupe durante le riprese subacquee trattenendo il fiato per ben 7 minuti e 14 secondi, battendo il precedente record sul set cinematografico che apparteneva a Tom Cruise per Mission: Impossible - Rogue Nation.', 'Dichiarazioni ufficiali di Kate Winslet e note di produzione 20th Century Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:34:31.717283+00:00'),
('b6344f3b-7328-471d-a27f-185780b1bdc8', 310, 'Segreti di produzione', 'Il sistema di performance capture sottomarino', 'Poiché i tradizionali sistemi di motion capture a infrarossi non funzionano sott''acqua a causa della rifrazione della luce, James Cameron ha incaricato la Wētā FX di sviluppare una nuova tecnologia basata su punti di riferimento subacquei e telecamere multiple.', 'Special report tecnico di American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:34:31.717283+00:00'),
('707ea6e6-75f7-4c40-b35a-cf0796a01304', 310, 'Casting & Scelte', 'La scelta di Kate Winslet per il ruolo di Ronal', 'Kate Winslet ha accettato immediatamente il ruolo di Ronal dopo che James Cameron le ha inviato una concept art in cui il suo personaggio veniva raffigurato con un pancione incinto, cavalcando una creatura marina e lottando per la sua tribù.', 'Intervista di Empire Magazine a Kate Winslet', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:34:31.717283+00:00'),
('fe29a26f-ea8e-4988-9d6e-52afa5ce3c43', 310, 'Curiosità & Retroscena', 'L''ispirazione per il clan Metkayina', 'La cultura e lo stile di vita del clan dei Metkayina sono stati ideati da James Cameron unendo elementi di diverse popolazioni indigene della Polinesia, inclusi i Maori della Nuova Zelanda e varie tribù di pescatori oceanici.', 'Note di regia ufficiali e conferenze stampa di presentazione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:34:31.717283+00:00'),
('80d88c80-0c5e-43f9-a2ed-f80df749a12a', 310, 'Segreti di produzione', 'Il ritardo di 13 anni spiegato dalla tecnologia', 'James Cameron ha dovuto aspettare oltre un decennio prima di realizzare il sequel non solo per la complessità della sceneggiatura, ma perché la tecnologia informatica necessaria per catturare i movimenti facciali in combinazione con il fotorealismo subacqueo semplicemente non esisteva all''epoca dell''uscita del primo film.', 'Intervista retrospettiva a Deadline e Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:34:31.717283+00:00'),
('cc64079a-115e-4288-b925-df95c5eb44b0', 310, 'Aneddoti dal set', 'Il monitoraggio medico costante durante le apnee', 'Sul set della gigantesca piscina da 900.000 galloni d''acqua, la produzione ha impiegato personale medico d''emergenza e subacquei di sicurezza pronti ad intervenire in ogni frazione di secondo per prevenire episodi di blackout o ipossia negli attori.', 'Making-of ufficiale ''Behind the Art of Avatar: The Way of Water''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:34:31.717283+00:00'),
('5a566396-b8f6-4f55-952d-364750328cdc', 352, 'Aneddoti dal set', 'La vera allergia al cioccolato di Johnny Depp', 'Nonostante interpretasse un affascinante maestro cioccolatiere, Johnny Depp nella realtà soffriva di una leggera intolleranza al cioccolato e, in molte scene in cui doveva mangiarlo, consumava in realtà versioni finte fatte di sostanze alternative.', 'Commento audio del regista e note di produzione del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:35:22.747351+00:00'),
('010f8239-5dfa-4389-b6aa-a5d392ec6ac2', 352, 'Casting & Scelte', 'Il rifiuto iniziale di Lasse Hallström', 'Il regista Lasse Hallström inizialmente rifiutò di dirigere il film perché temeva che la sceneggiatura fosse troppo simile nello spirito alle sue precedenti opere, ma cambiò idea dopo aver letto attentamente il romanzo di Joanne Harris.', 'Intervista retrospettiva a Lasse Hallström per BBC Films', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:35:22.747351+00:00'),
('92f368be-c635-41e5-af45-b92aa59fb2b4', 315, 'Aneddoti dal set', 'La preparazione fisica estrema di Mickey Rourke', 'Per trasformarsi fisicamente nel lottatore, Mickey Rourke si è sottoposto a sette mesi di allenamento intensivo sotto la guida del leggendario lottatore Afa Anoa''i (della storica dinastia dei Samoans), guadagnando oltre quindici chili di massa muscolare e imparando le tecniche d''impatto sul ring.', 'Note di produzione e interviste al cast nel making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:34:36.320842+00:00'),
('8ba26174-7921-4a67-9a79-918d2bfc9f93', 315, 'Casting & Scelte', 'L''uso di veri wrestler professionisti', 'Per garantire il massimo realismo alle sequenze di lotta, Aronofsky ha ingaggiato veri lottatori del circuito indipendente e leggende della disciplina come Ernest ''The Cat'' Miller e Ron Killings (R-Truth), oltre a numerose comparse prese direttamente dal pubblico degli show locali.', 'Crediti del film e interviste al coordinatore degli stunt', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:34:36.320842+00:00'),
('ef27074e-dd9a-460d-a06a-1a68da11ac79', 136, 'Segreti di produzione', 'Il compenso record per la sceneggiatura', 'Gli sceneggiatori del film, Casey Robinson e Randall Garrett, ricevettero un compenso particolarmente elevato per l''epoca grazie alla complessità di adattare la controversa vita di Custer in un''epopea patriottica adatta agli standard del Codice Hays.', 'The Hollywood Studio Blueprints', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:05:16.320358+00:00'),
('26ad8e3a-1b4d-4fbf-bea9-aced8a9833d2', 315, 'Effetti speciali & Trucco', 'Il trucco delle ferite e delle lame', 'Il reparto trucco, guidato da Judy Chin, ha utilizzato protesi avanzate e sangue fittizio altamente realistico per replicare le cicatrici e la pratica del ''blading'' (il taglio autoinflitto o simulato per sanguinare sul ring), studiando i match reali della Extreme Championship Wrestling (ECW).', 'Articolo tecnico su American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:34:36.320842+00:00'),
('8984c531-94ee-4165-91ba-810fdd7519ed', 315, 'Segreti di produzione', 'La scelta della pellicola Super 16mm', 'La direttrice della fotografia Maryse Alberti ha girato il film in formato Super 16mm per conferire alla pellicola una grana ruvida, intima e documentaristica, ideale per riflettere la decadenza e il realismo sporco della vita del protagonista fuori dai riflettori.', 'Intervista a Maryse Alberti per la rivista American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:34:36.320842+00:00'),
('66af65c8-543c-42bb-8caf-56a135fc957b', 315, 'Aneddoti dal set', 'L''improvvisazione al banco gastronomia', 'La scena in cui Randy lavora al supermercato e serve i clienti al banco deli è stata parzialmente improvvisata: Mickey Rourke ha lavorato per qualche giorno in un vero negozio di alimentari del New Jersey prima delle riprese per entrare nella parte e interagire con clienti ignari.', 'Audio commento del regista Darren Aronofsky', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:34:36.320842+00:00'),
('3c43ee6a-20bd-4d26-b920-c34a52dec940', 326, 'Curiosità & Retroscena', 'L''origine letteraria del racconto', 'Il film è liberamente tratto dal racconto breve ''Eisenheim l''illusionista'' (Eisenheim the Illusionist) scritto da Steven Millhauser e incluso nella sua raccolta del 1990 ''The Barnum Museum''. La sceneggiatura del regista Neil Burger ha ampliato notevolmente la figura dell''ispettore Uhl e la trama politica per adattarla al lungometraggio.', 'Note di produzione ufficiali della Yari Film Group', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:34:47.580862+00:00'),
('9c35af36-0b22-499a-8060-c9269f63aa21', 326, 'Casting & Scelte', 'La preparazione magica di Edward Norton', 'Per prepararsi al ruolo di Eisenheim, Edward Norton ha lavorato a stretto contatto con professionisti della magia di fama internazionale. Tra questi spicca James Freedman, che ha insegnato all''attore non solo la manipolazione dei piccoli oggetti come monete e carte, ma anche la corretta postura scenica e la gestualità tipica dei prestigiatrici di fine Ottocento.', 'Commento audio del regista Neil Burger nel DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:34:47.580862+00:00'),
('f3cc32e6-b7a7-4e2c-98bf-da144dcfbb07', 136, 'Aneddoti dal set', 'L''infortunio sul set di una controfigura', 'Durante le complesse sequenze di carica della cavalleria girate nelle vicinanze di Calabasas in California, uno stuntman professionista riportò la frattura di una clavicola dopo che il suo cavallo inarcò la schiena durante una caduta programmata.', 'The Los Angeles Times, cronache di set del 1941', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:05:16.320358+00:00'),
('00ed2217-a607-49e3-a5e7-6964e298ec31', 326, 'Effetti speciali & Trucco', 'L''uso reale dell''arancione cinese', 'Il celebre trucco dell''arancio che cresce rapidamente da un piccolo seme sotto un telo, mostrato da Eisenheim durante le sue esibizioni, non è un''invenzione cinematografica ma un numero classico della prestigiazione storica noto come ''L''albero dei naranjeros''. Nel film è stato ricreato combinando effetti pratici sul set e interventi digitali per la fase di germogliazione accelerata.', 'Special ''The Making of The Illusionist'' contenuto nell''edizione home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:34:47.580862+00:00'),
('ce341ff8-1b4f-4f0a-8f3f-952df8a1cebd', 326, 'Aneddoti dal set', 'Le riprese nella Repubblica Ceca', 'Sebbene la storia sia ambientata a Vienna, la quasi totalità delle riprese si è svolta nella Repubblica Ceca tra la primavera e l''estate del 2005. Luoghi storici come il Castello di Český Krumlov, la città di Tabor e vari edifici storici di Praga sono stati riconvertiti per simulare la Vienna asburgica del 1900.', 'Press Kit ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:34:47.580862+00:00'),
('e8b79bc0-ff20-440e-be9f-ee92debe5231', 326, 'Segreti di produzione', 'La scelta della palette cromatica', 'Il direttore della fotografia Dick Pope ha utilizzato una speciale color grading e filtri fotografici particolari per dare alla pellicola l''aspetto di un''antica fotografia seppia o di una lastra di vetro d''epoca. L''intento era quello di trasportare visivamente lo spettatore nell''atmosfera nostalgica e misteriosa del primo Novecento.', 'Intervista a Dick Pope su American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:34:47.580862+00:00'),
('40d52084-6626-4ef8-a612-f50d295a385d', 326, 'Casting & Scelte', 'La collaborazione con Ricky Jay', 'Il leggendario prestigiatore e storico della magia Ricky Jay è stato ingaggiato come consulente tecnico principale per la produzione. Oltre a supervisionare i trucchi eseguiti da Edward Norton, Jay ha aiutato a strutturare le sequenze di magia affinché risultassero storicamente plausibili per il periodo in cui è ambientata la vicenda.', 'Note di produzione e crediti del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:34:47.580862+00:00'),
('98f01bbe-2ed3-466f-8b49-8eb48cd19704', 326, 'Effetti speciali & Trucco', 'I fantasmi della lanterna magica', 'Le proiezioni spettrali create da Eisenheim sul palco sfruttano la tecnica storica della ''fantasmagoria'', resa popolare tra la fine del XVIII e il XIX secolo grazie all''uso avanzato di lanterne magiche nascoste e fumo di scena. Per ottenere l''effetto traslucido desiderato sullo schermo, la produzione ha combinato proiezioni dal vivo sul set e leggeri ritocchi in post-produzione.', 'Making-of ufficiale e approfondimenti sugli effetti visivi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:34:47.580862+00:00'),
('8c5b66a8-4f86-47f2-a51b-da171055e760', 10, 'Curiosità & Retroscena', 'La scelta del titolo come prequel', 'George Lucas decise consapevolmente di ambientare il film nel 1935, un anno prima degli eventi de ''I predatori dell''arca perduta'', per evitare di dover riproporre i nazisti come antagonisti principali e mantenere così una maggiore freschezza narrativa.', 'Documentario ufficiale ''The Making of Indiana Jones and the Temple of Doom''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:35:57.707658+00:00'),
('14b74864-873f-4738-9bfa-c901ccfcd453', 333, 'Curiosità & Retroscena', 'La colonna sonora composta dallo stesso Eastwood', 'Come spesso accade nei suoi film, Clint Eastwood ha composto personalmente gran parte della delicata e malinconica colonna sonora del film al pianoforte, riflettendo la solitudine e il dramma interiore dei protagonisti.', 'Note di copertina della colonna sonora ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:35:02.632578+00:00'),
('49e693e3-99c0-4df7-bbaa-9ed1d3e3060a', 333, 'Segreti di produzione', 'L''uso della luce naturale e della fotografia scura', 'Il direttore della fotografia Tom Stern ha utilizzato una palette cromatica fortemente desaturata e forti contrasti di luce e ombra, ispirandosi ai dipinti di Edward Hopper per accentuare il senso di isolamento della palestra di Frankie Dunn.', 'American Cinematographer, intervista a Tom Stern', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:35:02.632578+00:00'),
('0b9350cc-adb5-4b44-abb7-3dbdb489cb97', 333, 'Aneddoti dal set', 'L''addestramento pugilistico di Morgan Freeman', 'Sebbene il suo personaggio di Scrap-Iron Dupris fosse un ex pugile ormai cieco da un occhio e ridotto a fare il guardiano della palestra, Morgan Freeman si allenò comunque per settimane con un vero coach per padroneggiare la postura e i movimenti tipici degli uomini di mondo cresciuti tra le corde del ring.', 'Making-of ufficiale ''Born to Fight''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:35:02.632578+00:00'),
('f3c2fa57-ee16-49ee-85d8-c543e0a1db4c', 333, 'Curiosità & Retroscena', 'Il rifiuto della Warner Bros. di finanziare interamente il film', 'La Warner Bros. era scettica sul potenziale commerciale di un dramma sul pugilato incentrato su una boxeur e si rifiutò di coprire l''intero budget di circa 30 milioni di dollari. La Lakeshore Entertainment intervenne come co-finanziatrice del progetto.', 'Archivio storico Variety e biografie di Clint Eastwood', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T15:35:02.632578+00:00'),
('d21dc20c-ed4d-4180-bba8-aca3ad22947f', 11, 'Effetti speciali & Trucco', 'La polvere di mattone per il tempio finale', 'Per ricreare la spettacolare sequenza in cui il tempio del Graal crolla alla fine del film, la troupe utilizzò una combinazione di set in scala ridotta costruiti agli Elstree Studios e tonnellate di polvere di mattone macinato e sughero per simulare i detriti in sicurezza.', 'Documentario ufficiale ''The Making of Indiana Jones and the Last Crusade''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:36:00.168412+00:00'),
('d0155e7f-d353-4d53-ac9c-ae33f355f309', 11, 'Casting & Scelte', 'Il costume di Alison Doody e i riferimenti storici', 'Il look dell''attrice Alison Doody nel ruolo di Elsa Schneider fu espressamente modellato dai costumisti ispirandosi alle spie e alle donne fatali del cinema noir degli anni ''40 e alle reali collaboratrici del regime nazista fotografate negli archivi storici dell''epoca.', 'Note di produzione e reparti costumi Lucasfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:36:00.168412+00:00'),
('39b6c3bf-5276-448e-b983-455acb3c37fe', 11, 'Aneddoti dal set', 'La scena del salto dal carro armato e le controfigure', 'Durante la sequenza dell''inseguimento del carro armato nel deserto, lo stuntman Vic Armstrong, storico controfigura di Harrison Ford, rischiò un infortunio grave quando dovette saltare dal dorso del veicolo in corsa simulando di essere trascinato via.', 'Autobiografia di Vic Armstrong ''The True Adventures of the World''s Greatest Stuntman''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:36:00.168412+00:00'),
('201a6113-16b2-4a55-8d21-f6f77df894c3', 287, 'Segreti di produzione', 'La gestione degli spazi ristretti sul set', 'Poiché l''appartamento ricostruito in studio aveva pareti parzialmente mobili per facilitare l''ingombrante attrezzatura delle cineprese 3D, operatori e attori dovettero muoversi con estrema precisione millimetrica per evitare di intralciare le inquadrature.', 'Reportage d''epoca dal set di American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:49:14.838086+00:00'),
('fc8ec606-7f12-4e40-9d62-af9712ef244c', 314, 'Segreti di produzione', 'La vera Ford Gran Torino sportiva del 1972', 'Per le riprese del film furono utilizzate ben quattro automobili Ford Gran Torino del 1972 identiche, fornite da collezionisti e modellate per apparire come la vettura impeccabile curata dal protagonista Walt Kowalski nel corso degli anni. Tutte le auto montavano un motore V8 autentico dell''epoca per garantire il tipico rombo originale durante le accelerazioni.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:50:33.216736+00:00'),
('592f8727-690a-46aa-a50d-ce682a5d6e81', 314, 'Casting & Scelte', 'Il debutto attoriale della comunità Hmong', 'La maggior parte degli attori che interpretano i membri della famiglia Lor e i vicini Hmong, inclusi i giovani Bee Vang e Ahney Her, non aveva mai recitato prima in un film professionale. Clint Eastwood decise di effettuare i casting direttamente nei centri comunitari del Minnesota e del Wisconsin per trovare volti totalmente sconosciuti e realistici.', 'Special content ''Manning the Wheel'' - Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:50:33.216736+00:00'),
('24503157-4829-4be7-ad70-a8b178929800', 314, 'Aneddoti dal set', 'La rapidità record delle riprese', 'Fedele al suo celebre stile di regia minimalista ed efficiente, Clint Eastwood diresse ''Gran Torino'' completando l''intera lavorazione sul set in sole trentasette giornate di riprese. Molte sequenze venivano chiuse alla prima o alla seconda ripresa per preservare l''energia e la spontaneità degli attori non professionisti.', 'Intervista al direttore della fotografia Tom Stern', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:50:33.216736+00:00'),
('11faa657-d3f3-4e07-abc2-6873ad352bd1', 314, 'Curiosità & Retroscena', 'L''improvvisazione della canzone dei titoli di coda', 'Il brano principale ''Gran Torino'', che accompagna i titoli di coda ed è cantato dallo stesso Clint Eastwood accompagnato al pianoforte da Jamie Cullum, è stato composto a quattro mani da Eastwood con suo figlio Kyle e Michael Stevens, vincendo anche il premio come miglior canzone originale ai Critics'' Choice Movie Awards.', 'Crediti ufficiali della colonna sonora e commento audio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:50:33.216736+00:00'),
('b36faa58-41ac-4637-8fa8-759b91801a33', 314, 'Aneddoti dal set', 'Il cane di Walt e i suoi addestratori', 'Daisy, la cagnolina di razza Labrador Retriever che interpreta il fedele cane di Walt di nome ''Daisy'', era sul set sotto la costante supervisione di due addestratori professionisti. Nelle scene in cui doveva abbaiare o mostrarsi protettiva verso il padrone, venivano utilizzati particolari segnali visivi fuori campo e croccantini speciali.', 'Reportage dal set di American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:50:33.216736+00:00'),
('d562fcc2-ddd3-4cab-b944-3b9042107817', 331, 'Curiosità & Retroscena', 'Il cambio di ambientazione da New York a Londra', 'Woody Allen aveva originariamente scritto la sceneggiatura ambientandola a New York, ma l''impossibilità di ottenere i finanziamenti necessari negli Stati Uniti lo costrinse a trasferire la produzione a Londra, modificando i dettagli culturali della classe alta britannica.', 'Note di produzione ufficiali e interviste a Woody Allen', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:51:25.793568+00:00'),
('51425598-b655-48dc-9c12-29bd887ffb55', 331, 'Casting & Scelte', 'Il rifiuto iniziale di Kate Winslet', 'Il ruolo di Nola Rice era stato inizialmente offerto a Kate Winslet, la quale accettò ma dovette rinunciare poco prima dell''inizio delle riprese per motivi personali e per trascorrere più tempo con la famiglia, aprendo la strada all''ingaggio di Scarlett Johansson.', 'Archivio storico di Variety e dichiarazioni dell''attrice', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:51:25.793568+00:00'),
('ba8e4c0f-eb1e-4aad-acef-abf46873b39e', 342, 'Curiosità & Retroscena', 'La collaborazione con i sopravvissuti', 'Diversi sopravvissuti reali dell''Olocausto e testimoni oculari della distruzione di Varsavia furono consultati sul set come consulenti storici per garantire che ogni dettaglio comportamentale, dai gesti alle divise, fosse accurato al massimo.', 'Booklet ufficiale di produzione di ''The Pianist''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:35:05.811538+00:00'),
('9cfe5af0-68b8-4e4c-9e14-8448589ddd1b', 350, 'Casting & Scelte', 'Il provino fortuito di Naomi Watts', 'Naomi Watts ottenne la parte di Betty senza dover sostenere un provino tradizionale in presenza di David Lynch; il direttore del casting Johanna Ray le inviò semplicemente le pagine del copione e l''attrice registrò la sua audizione su nastro nella sua cucina, venendo scelta quasi immediatamente dal regista sulla base di quel videotape.', 'Intervista retrospettiva a Naomi Watts nei contenuti speciali del DVD edizione Criterion', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:35:15.189502+00:00'),
('65ded9f0-460f-4e73-a5d9-c00d9127962e', 350, 'Casting & Scelte', 'La scelta iniziale per il ruolo di Rita', 'Prima che Laura Elena Harring sostenesse il provino e conquistasse la parte di Rita, David Lynch aveva preso in forte considerazione l''attrice portoghese Maria de Medeiros, celebre per il suo ruolo in Pulp Fiction, per interpretare la donna smemorata della limousine.', 'Note di produzione e biografia ufficiale di David Lynch', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:35:15.189502+00:00'),
('9bea4420-0f64-4add-9681-8377f9edffc0', 350, 'Aneddoti dal set', 'La telefonata notturna di Dan Hedaya', 'Dan Hedaya, che interpreta il proprietario del locale che riceve la chiamata dal sicario, ha raccontato che per girare quella sequenza telefonica David Lynch gli diede pochissime indicazioni verbali, preferendo fargli ascoltare rumori ambientali distorti direttamente in cuffia per alterare la sua reazione emotiva sul set.', 'Dietro le quinte e documentario di lavorazione dell''edizione home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:35:15.189502+00:00'),
('8fc6d516-bf78-4f3a-8af5-bee157378d9a', 350, 'Aneddoti dal set', 'L''infortunio sfiorato sul set di Justin Theroux', 'Durante la sequenza in cui Justin Theroux fugge in fretta dalla sua villa dopo aver scoperto la relazione della moglie, l''attore rischiò realmente di farsi male guidando l''auto sportiva d''epoca su strade sterrate e ripide delle colline di Los Angeles senza l''ausilio di una controfigura per i campi medi.', 'Audio commento del cast e della troupe sul Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:35:15.189502+00:00'),
('dad0f903-958a-486d-a8b8-6395a1d81bb0', 350, 'Segreti di produzione', 'L''uso della pellicola scaduta e la grana visiva', 'Per alcune delle riprese aggiuntive girate dopo la trasformazione del pilot in lungometraggio cinematografico, il direttore della fotografia Peter Deming e David Lynch utilizzarono parzialmente lotti di pellicola non convenzionali e stock differenti per accentuare volutamente la discontinuità visiva tra la prima parte luminosa e la seconda metà onirica e cupa.', 'Intervista al direttore della fotografia Peter Deming su American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:35:15.189502+00:00'),
('3d71a8af-7edd-4884-8644-912cb4d386dd', 2, 'Effetti speciali & Trucco', 'La CGI per completare le scene di Oliver Reed', 'Dopo la tragica scomparsa di Oliver Reed prima della fine delle riprese, la produzione ha speso circa 3,2 milioni di dollari per ricreare digitalmente il suo volto su una controfigura usando la tecnologia CGI della Mill Film, permettendo al personaggio di Prossimo di completare il suo arco narrativo.', 'Note di produzione ufficiali e documentario sul making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:35:32.722066+00:00'),
('cb4bc133-3459-489a-a766-1ce7269ae75b', 2, 'Segreti di produzione', 'La statua di marmo gonfiabile', 'Nella scena in cui Massimo entra nella stanza dove si trova una gigantesca statua di marmo dell''imperatore, la struttura non era di pietra ma una gigantesca scultura gonfiabile dipinta per sembrare marmo, progettata per facilitare lo spostamento sul set.', 'Commento audio del regista Ridley Scott nel DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:35:32.722066+00:00'),
('1547e3fb-1d24-4098-b9ac-cc46c7e0f7be', 2, 'Aneddoti dal set', 'L''uso di cavalli veri e finti nella battaglia iniziale', 'Durante la sequenza della battaglia in Germania, la produzione ha utilizzato una combinazione di cavalli meccanici controllati da remoto e cavalli veri addestrati per cascatelle controllate, garantendo la sicurezza degli animali pur mantenendo un impatto visivo estremamente realistico.', 'Intervista al coordinatore degli stuntman Phil Neilson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:35:32.722066+00:00'),
('4a867fed-ef8c-4181-a555-3c2e2a7582f4', 2, 'Segreti di produzione', 'Il Colosseo ricostruito a Malta', 'Poiché le riprese nel vero Colosseo di Roma erano impossibili per motivi di tutela storica, la produzione ha fatto costruire a Fort Ricasoli, a Malta, una riproduzione a grandezza naturale alta circa 15 metri della sola sezione inferiore dell''arena, completata poi digitalmente per il resto dell''altezza.', 'Archivio storico della produzione DreamWorks/Universal', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:35:32.722066+00:00'),
('ae014b46-13fc-4989-b1df-6f0eb85b90c0', 2, 'Casting & Scelte', 'Il nome originale del protagonista modificato', 'Nella primissima versione della sceneggiatura scritta da David Franzoni, il protagonista non si chiamava Massimo Decimo Meridio, bensì Narciso, riprendendo il nome del leggendario lottatore storico che realmente strangolò l''imperatore Commodo nel 192 d.C.', 'Dichiarazioni di David Franzoni nel libro ''Gladiator: The Making of the Ridley Scott Film''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:35:32.722066+00:00'),
('739f3459-fbd0-4de2-b5a7-5bb7bd9f212d', 2, 'Citazioni & Easter Egg', 'Il cameo vocale di Hans Zimmer', 'Il celebre compositore della colonna sonora Hans Zimmer, collaborando con Lisa Gerrard, ha inserito registrazioni di veri canti tradizionali berberi e mediterranei mescolati a strumenti elettronici per creare il timbro unico della colonna sonora, inserendo anche brevi vocalizzi eseguiti dallo stesso staff in studio.', 'Note di copertina della colonna sonora ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:35:32.722066+00:00'),
('55fec0cf-d613-41c5-b710-37c1bb380feb', 288, 'Casting & Scelte', 'La scelta iniziale di Grace Kelly', 'Alfred Hitchcock aveva originariamente pensato a Grace Kelly per il ruolo di Melanie Daniels, sperando di convincerla a tornare a recitare dopo il suo matrimonio con il Principe Ranieri di Monaco. Tuttavia, l''opposizione del Principato di Monaco costrinse la Kelly a rinunciare, spingendo il regista a puntare sulla scoperta di Tippi Hedren.', 'Biografie ufficiali e note di produzione di Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:49:19.119042+00:00'),
('008ac30d-10f3-4446-b5d5-f7c09b5310fd', 288, 'Aneddoti dal set', 'Uccelli vivi sul set e tensioni psicologiche', 'Durante la famigerata scena dell''attacco nella soffitta, Tippi Hedren fu sottoposta per una settimana all''uso di veri gabbiani lanciati contro di lei da operatori fuori campo con fili elastici invisibili. L''esaurimento nervoso dell''attrice fu reale e documentato, portando a una pausa forzata di cinque giorni ordinata dal medico di produzione.', 'Documentario ''All About The Birds'' e autobiografia di Tippi Hedren', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:49:19.119042+00:00'),
('28f9b478-2e8a-4956-b5b1-6659e41052ee', 288, 'Segreti di produzione', 'Il doppiaggio meccanico del suono', 'Non essendoci partitura musicale tradizionale, Hitchcock ingaggiò Oskar Sala e Remi Gassmann per creare la colonna sonora utilizzando il trautonium, uno dei primi sintetizzatori elettronici. I suoni stridenti e minacciosi degli uccelli furono ottenuti manipolando elettronicamente le frequenze di strumenti a corda e registrazioni di veri volatili.', 'Note tecniche d''archivio e registrazioni delle sessioni di montaggio audio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:49:19.119042+00:00'),
('586428b1-4173-41e7-b338-db17c3f2031b', 288, 'Citazioni & Easter Egg', 'Il cameo di Alfred Hitchcock', 'Il celebre cameo del regista avviene nei primissimi minuti della pellicola: Alfred Hitchcock appare uscendo dal negozio di animali ''Pet Shop'' a San Francisco mentre porta al guinzaglio due terrieri bianchi, poco prima che Tippi Hedren entri nel locale.', 'Analisi visiva ufficiale dei cameo hitchcockiani', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:49:19.119042+00:00'),
('1d05957d-a041-4f2c-94c1-eb87062963ee', 288, 'Effetti speciali & Trucco', 'Uccelli meccanici di precisione', 'Gli oggetti di scena includevano dozzine di uccelli meccanici e robotici costruiti dal reparto effetti speciali guidato da Ub Iwerks, ex collaboratore di Walt Disney. Questi automi venivano impiegati nelle inquadrature più pericolose in cui i veri animali avrebbero potuto ferire gli attori o rifiutarsi di collaborare.', 'Archivi storici degli studi Disney e Universal', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:49:19.119042+00:00'),
('b4b1b72e-b374-4c50-b550-5d8878211aec', 288, 'Segreti di produzione', 'La sequenza della stazione di servizio', 'Per girare la spettacolare scena dell''esplosione alla stazione di servizio, in cui Melanie osserva la distruzione dall''alto, la produzione combinò riprese dal vero eseguite in studio con la tecnica della sovrapposizione ottica e mascherine di vetro dipinte dal pittore Albert Whitlock.', 'Making-of ufficiale ''The Birds: The Greatest Show on Earth''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:49:19.119042+00:00'),
('831bd31b-153e-419a-9be8-8f7be0fca868', 137, 'Segreti di produzione', 'L''esperienza bellica di J.D. Smith come base per il realismo', 'L''ex agente della CIA e veterano del Vietnam J.D. Smith, assunto come consulente tecnico e militare, ha preteso che gli attori maneggiassero le armi e si muovessero esattamente come veri operatori paramilitari, rifiutando qualsiasi posa cinematografica stereotipata.', 'Documentario ''Ronin: Under the Real'' inserito nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:05:23.602361+00:00'),
('8e87b8b9-b78a-4010-a41e-5ba1f6badc98', 306, 'Casting & Scelte', 'Il rifiuto di James Franco', 'Prima che Tom Hardy ottenesse la parte del falsario Eames, Christopher Nolan aveva offerto il ruolo a James Franco. L''attore dovette tuttavia rifiutare l''offerta a causa di conflitti di programmazione con i suoi impegni universitari e teatrali.', 'Interviste di produzione e report di casting di Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:50:06.35404+00:00'),
('a96082e0-709d-4062-b2de-b2cb405e453c', 351, 'Effetti speciali & Trucco', 'Il trucco prostetico per le vittime dello Squartatore', 'Gli elaborati effetti speciali di trucco e le raccapriccianti ricostrazioni dei corpi mutilati delle vittime sono stati supervisionati dal celebre truccatore e creatore di effetti speciali Matthew Mungle, che ha utilizzato silicone medicale e sangue fucsia-scuro per simulare la decomposizione sotto le luci delle lanterne a gas.', 'Documentario sugli effetti speciali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:35:19.527848+00:00'),
('0dbd4fbf-6252-425d-a9cb-3828eeec4e1b', 3, 'Segreti di produzione', 'La vera natura della videocamera di Hud', 'L''attore T.J. Miller, che interpreta l''operatore video Hud, ha realmente filmato gran parte delle scene con una videocamera in mano per mesi durante le riprese. Questa scelta ha causato in molti membri della troupe e del cast disturbi da movimento simili al mal di mare, costringendo la produzione a tenere a portata di mano rimedi contro la nausea.', 'Commento audio del regista Matt Reeves nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:35:37.419779+00:00'),
('018ee5c8-1457-4704-bc83-6c2097932c93', 3, 'Curiosità & Retroscena', 'Il titolo provvisorio Slusho!', 'Prima dell''annuncio ufficiale del titolo definitivo, il film fu girato sotto il nome in codice di ''Slusho!'', un marchio fittizio di bevande apparso in precedenza nella serie TV ''Alias'' di J.J. Abrams. Tale strategia servì a sviare i fan e la stampa durante le prime fasi della produzione a New York.', 'Note di produzione ufficiali della Bad Robot', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:35:37.419779+00:00'),
('5c77f054-7a90-41ad-975a-b1ca8533d87f', 3, 'Effetti speciali & Trucco', 'Il grido di morte della creatura tratto da Lost', 'Il caratteristico verso emesso dal mostro di Cloverfield alla fine del film include un easter egg sonoro nascosto: il sound designer Douglas Grinton ha inserito una variazione del celebre rumore del ''Monster'' della serie televisiva ''Lost'', anch''essa creata da J.J. Abrams.', 'Intervista al sound designer Douglas Grinton su SoundWorks Collection', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:35:37.419779+00:00'),
('ae6bec5c-2cd3-4ec3-85bb-244d25bac3b1', 3, 'Casting & Scelte', 'Il cameo vocale di Chris Mulkey', 'Nella scena in cui il gruppo attraversa il ponte di Brooklyn per fuggire da Manhattan, la voce dell''ufficiale dell''esercito che ordina ai civili di rientrare e mantenere la calma appartiene all''attore caratterista Chris Mulkey, sebbene non compaia mai direttamente inquadrato.', 'Crediti del film e IMDb', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:35:37.419779+00:00'),
('f66fa41c-a867-4706-8c87-762a5c5cda78', 3, 'Citazioni & Easter Egg', 'L''apparizione nascosta di C-3PO', 'In una delle sequenze iniziali all''interno dell''appartamento durante la festa d''addio, è possibile intravedere brevemente un poster o una sagoma stilizzata che richiama il droide C-3PO della saga di Star Wars, un classico omaggio inserito dai collaboratori di J.J. Abrams.', 'Analisi visiva ufficiale e fan database verificati', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:35:37.419779+00:00'),
('b9e39d30-9270-43c0-94c9-9123ed49af45', 3, 'Segreti di produzione', 'La riproduzione in studio di Coney Island', 'La sequenza finale ambientata a Coney Island non è stata girata realmente nel celebre parco divertimenti di New York, ma è stata interamente ricostruita e riprodotta all''interno dei teatri di posa della Paramount utilizzando schermi verdi e scenografie parziali.', 'Special ''The Making of Cloverfield'' presente nei contenuti extra home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:35:37.419779+00:00'),
('58218bc3-7ec7-4245-847d-823dbc756d45', 3, 'Effetti speciali & Trucco', 'L''ispirazione per i parassiti della creatura', 'I piccoli e feroci parassiti che cadono dal corpo del mostro gigante e infestano le metropolitane di New York sono stati modellati dal character designer Neville Page ispirandosi a una combinazione di pulci di mare, zecche e granchi reali.', 'Intervista di Neville Page al magazine Cinefex', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:35:37.419779+00:00'),
('ef61ddc5-5547-4bee-b756-39c7b85a73e8', 7, 'Casting & Scelte', 'La scelta iniziale di Martin Scorsese come regista', 'Prima di affidare nuovamente la regia a Francis Ford Coppola, la Paramount pensò seriamente a Martin Scorsese per dirigere il sequel, su forte raccomandazione dello stesso Coppola che lo considerava perfetto per un film sulla criminalità italo-americana.', 'Documentario ''The Godfather Family: A Look Inside'' e biografie ufficiali della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:35:48.864825+00:00'),
('3fe277d4-9964-43b2-b054-a8a3bf6b792a', 7, 'Effetti speciali & Trucco', 'Il trucco di Robert De Niro per la voce di Vito Corleone', 'Per interpretare il giovane Vito Corleone replicando la cadenza e il timbro vocale resi celebri da Marlon Brando nel primo film, Robert De Niro visse per mesi in Sicilia e utilizzò piccoli pezzi di cotone in bocca durante le prove per modificare la forma delle guance.', 'Commento audio del regista Francis Ford Coppola all''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:35:48.864825+00:00'),
('1f0a21bc-598c-48f6-9fa0-2ef83a915798', 306, 'Curiosità & Retroscena', 'La genesi decennale della sceneggiatura', 'Christopher Nolan ha impiegato circa dieci anni per completare la stesura della sceneggiatura di Inception. Inizialmente aveva concepito il progetto come un horror sui sogni prima di trasformarlo in un heist movie ad alto budget.', 'Note di produzione ufficiali Warner Bros e press book', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:50:06.35404+00:00'),
('e645c0e8-ad77-4aa3-9cea-c43c95bc7241', 292, 'Citazioni & Easter Egg', 'L''ispirazione visiva da The 400 Blows e la Nouvelle Vague', 'Taika Waititi ha dichiarato di essersi fortemente ispirato a film classici come ''I 400 colpi'' di François Truffaut e ad altre pellicole della Nouvelle Vague per catturare la prospettiva e l''energia visiva infantile, specialmente nella sequenza in cui Jojo corre per le strade della città.', 'Note di produzione ufficiali e interviste al regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:49:25.134846+00:00'),
('8519477c-5bd4-44ef-a9f1-f50a03aa53c6', 292, 'Curiosità & Retroscena', 'La proiezione di prova segreta per valutare il tono', 'Prima di finalizzare il montaggio, la produzione ha organizzato proiezioni di prova blindate per capire se il delicato equilibrio tra satira grottesca e dramma dell''Olocausto potesse funzionare con il grande pubblico, ricevendo riscontri positivi che hanno rassicurato lo studio.', 'Diario di produzione e interviste al montatore Tom Eagles', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:49:25.134846+00:00'),
('5694b2aa-d5b6-41da-a55c-ddfb7bb5d23e', 299, 'Aneddoti dal set', 'La controversia del bambino finto', 'In una delle scene più discusse del film, Bradley Cooper tiene in braccio un neonato che appariva palesemente come una bambola di plastica rigida. La sceneggiatrice e produttrice Jason Hall dovette successivamente spiegare su Twitter che il bambino vero programmato per le riprese si era ammalato improvvisamente all''ultimo minuto.', 'Dichiarazione ufficiale della produzione e tweet di Jason Hall', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:49:42.708221+00:00'),
('f6b2d638-1d0b-409f-a257-393ab8cadca6', 299, 'Casting & Scelte', 'Il passaggio di consegne da Steven Spielberg a Clint Eastwood', 'Inizialmente il progetto doveva essere diretto da Steven Spielberg, con un copione molto incentrato sul duello psicologico tra Kyle e un cecchino nemico in stile ''Il nemico alle porte''. Quando Spielberg lasciò la produzione per divergenze creative sul budget e sulla struttura, Clint Eastwood subentrò rapidamente rielaborando il tono del film.', 'Note di produzione e report di Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:49:42.708221+00:00'),
('5deca9d3-91a5-42bc-9e81-487cbd609d6a', 299, 'Effetti speciali & Trucco', 'L''incredibile trasformazione fisica di Bradley Cooper', 'Per impersonare Chris Kyle, Bradley Cooper si è sottoposto a un rigido regime di allenamento intensivo durato dieci settimane sotto la supervisioni del personal trainer Jason Walsh, arrivando ad ingrassare di circa 18 chili di sola massa muscolare consumando fino a 8000 calorie al giorno.', 'Intervista di Bradley Cooper a Men''s Health', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:49:42.708221+00:00'),
('789ae92d-cfeb-4817-95ce-e99720bc0a36', 299, 'Citazioni & Easter Egg', 'Il tributo finale con il vero filmato del funerale', 'Nei titoli di coda del film non viene utilizzata alcuna colonna sonora drammatica per rispettare la solennità della figura di Chris Kyle. Al loro posto si sentono i veri silenzi e le immagini della processione funebre reale svoltasi in Texas, a cui parteciparono migliaia di cittadini e veterani.', 'Analisi del montaggio finale e commento del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:49:42.708221+00:00'),
('83f12a95-39e6-4abe-bcb4-4038d2feb98e', 352, 'Segreti di produzione', 'L''uso di veri cioccolatini nelle riprese', 'Per mantenere la massima autenticità visiva durante i primi piani ravvicinati, la produzione utilizzò oltre 400 chilogrammi di vero cioccolato artigianale fornito da pasticcerie francesi locali, sebbene gran parte di esso si sciogliesse rapidamente sotto i fari caldi del set.', 'Reportage dal set di American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:35:22.747351+00:00'),
('55632a74-96bf-4798-b43e-256263f6311e', 352, 'Curiosità & Retroscena', 'La scelta della location borgognona', 'Il pittoresco villaggio di Lansquenet è stato ricreato principalmente nel borgo medievale di Flavigny-sur-Ozerain, in Borgogna, famoso anche per la produzione delle celebri caramelle all''anice.', 'Guida turistica ufficiale ai set cinematografici francesi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:35:22.747351+00:00'),
('0c07499c-8d9e-4dac-8f9f-45f21051b249', 299, 'Segreti di produzione', 'L''uso di vere famiglie di rifugiati iracheni come comparse', 'Molte delle comparse impopolari che interpretavano i civili iracheni in fuga tra le zone di guerra erano in realtà veri rifugiati fuggiti dai conflitti in Medio Oriente, scelti dalla produzione per garantire un realismo espressivo ed emotivo autentico durante le sequenze di rastrellamento.', 'Making-of ufficiale nel Blu-ray del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:49:42.708221+00:00'),
('c9d96caa-e3e2-423c-ac79-69505bbbed28', 312, 'Casting & Scelte', 'Il rifiuto di Jodie Foster per il ruolo di Sophie Neveu', 'Prima che Audrey Tautou venisse scelta per interpretare l''agente Sophie Neveu, i produttori avevano pensato a Jodie Foster. L''attrice premio Oscar, grande fan del libro, rifiutò la parte a causa di impegni pregressi con altri progetti cinematografici.', 'Note di produzione ufficiali della Sony Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:50:24.950596+00:00'),
('d213d122-cd9a-4ee4-84a7-46e48c4eaa18', 312, 'Segreti di produzione', 'La ricostruzione millimetrica del Louvre nei Pinewood Studios', 'Poiché il vero museo del Louvre ha negato il permesso di girare all''interno delle sale espositive durante gli orari di apertura e per scene d''azione invasive, la produzione ha ricostruito fedelmente in scala reale la Grande Galerie nei Pinewood Studios in Inghilterra.', 'Special content del DVD e documentario sul making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:50:24.950596+00:00'),
('1e42217b-f0af-4de3-8821-507c4a9ba4cf', 312, 'Aneddoti dal set', 'L''infortunio di Paul Bettany sul set', 'Paul Bettany, che interpreta il monaco Silas dedito all''autoflagellazione con il cilicio, ha accidentalmente colpito se stesso con troppa forza durante una scena drammatica, procurandosi un taglio reale che ha richiesto l''intervento medico immediato della troupe.', 'Intervista rilasciata da Paul Bettany al Graham Norton Show', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:50:24.950596+00:00'),
('15505101-b8d8-4cdd-97ce-5e9f7a16be04', 312, 'Casting & Scelte', 'La scelta di Ian McKellen e il suo scetticismo iniziale', 'Ian McKellen, prima di accettare il ruolo dell''esperto di storia del Graal Sir Leigh Teabing, ha ammesso in varie interviste di aver trovato il romanzo di Dan Brown piuttosto inverosimile, accettando poi la parte grazie al fascino della sceneggiatura di Akiva Goldsman.', 'Intervista promozionale al Festival di Cannes 2006', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:50:24.950596+00:00'),
('55bba970-46fe-42f3-88bc-29c3293d3f92', 312, 'Effetti speciali & Trucco', 'L''uso di telecamere ad altissima definizione per i dettagli dei dipinti', 'Per riprendere i dettagli nascosti dei dipinti di Leonardo da Vinci senza danneggiare le tele originali o le repliche museali, la troupe ha utilizzato speciali lenti macro e sistemi di illuminazione a freddo brevettati per evitare qualsiasi alterazione cromatica.', 'Diario di bordo del direttore della fotografia Salvatore Totino', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:50:24.950596+00:00'),
('a8755ae0-fb28-4615-9cb1-400ec732b313', 329, 'Casting & Scelte', 'La preparazione atletica con Kevin Rooney', 'Russell Crowe si è allenato per mesi sotto la stretta supervisione di Kevin Rooney, lo storico allenatore di Mike Tyson che conosceva personalmente Jim Braddock, per apprendere la corretta postura e lo stile di combattimento degli anni Trenta.', 'Making-of ufficiale nel DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:51:16.48477+00:00'),
('ef17bfd1-e676-42e4-9370-2b153b17746e', 293, 'Citazioni & Easter Egg', 'Il collegamento con Taxi Driver tramite il nome di Sophie', 'Il personaggio di Sophie Dumond, interpretato da Zazie Beetz, prende parzialmente il nome e si ispira alla figura di Betsy del capolavoro di Martin Scorsese ''Taxi Driver'' (1976), condividendo l''essere un interesse amoroso idealizzato dal protagonista alienato in un contesto urbano degradato.', 'Note di produzione e analisi di sceneggiatura ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:49:28.431733+00:00'),
('0599a4b3-e438-4f6b-8edf-c4cec4f065c9', 293, 'Casting & Scelte', 'Il rifiuto del ruolo di Thomas Wayne da parte di Alec Baldwin', 'Inizialmente l''attore Alec Baldwin era stato scelto per interpretare il miliardario Thomas Wayne, ma ha dovuto rinunciare alla parte a causa di conflitti di programmazione con altri impegni cinematografici pochi giorni prima dell''inizio delle riprese, venendo sostituito da Brett Cullen.', 'Dichiarazioni ufficiali di Alec Baldwin e report di casting di Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:49:28.431733+00:00'),
('0e8612eb-b95c-4b5a-bfaf-e82f2631d671', 300, 'Effetti speciali & Trucco', 'Il peso estremo delle esoscheletri mech', 'Le tute meccaniche indossate da Tom Cruise ed Emily Blunt pesavano tra i 27 e i 38 chilogrammi ciascuna, a seconda degli accessori e delle armi montate. Per riuscire a muoversi agilmente durante le riprese delle sequenze d''azione, entrambi gli attori hanno dovuto sottoporsi a mesi di rigoroso allenamento fisico intensivo.', 'Featurette ufficiale ''Creatures and Gear'' del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:49:46.619885+00:00'),
('22c24954-d4b9-4d9b-9eab-a7906e7e8b89', 300, 'Aneddoti dal set', 'Gli infortuni di Emily Blunt sul set', 'Durante una scena di guida spericolata in cui Emily Blunt doveva pilotare una Dodge Charger modificata con Tom Cruise come passeggero, l''attrice ha perso per un attimo il controllo ed è finita contro un albero. Cruise è scoppiato a ridere di gusto, ricordandole l''accaduto in seguito come momento di grande ilarità.', 'Intervista al Tonight Show with Jimmy Fallon', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:49:46.619885+00:00'),
('854faeab-35ba-4fa4-b19c-b7875409612d', 300, 'Curiosità & Retroscena', 'La riscrittura quotidiana della sceneggiatura', 'Il regista Doug Liman e gli sceneggiatori lavoravano quotidianamente sul set modificando costantemente le battute e la struttura delle scene a seconda di ciò che funzionava meglio durante le riprese. Questo metodo caotico ma creativo ha spiazzato inizialmente la produzione ma ha permesso di snellire notevolmente i dialoghi.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:49:46.619885+00:00'),
('b0795ef8-98ca-43f3-9e36-bbc24b39a481', 300, 'Casting & Scelte', 'Brad Pitt come prima opzione per il ruolo principale', 'Prima che Tom Cruise venisse ufficialmente ingaggiato per interpretare il tenente William Cage, la produzione aveva considerato Brad Pitt come la prima scelta assoluta per il ruolo. L''accordo tuttavia non si concretizzò, spingendo la Warner Bros. a puntare su Cruise.', 'Report di Hollywood Reporter sui casting del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:49:46.619885+00:00'),
('4ee3c832-84c1-46b7-8de4-6aa9f214fe59', 354, 'Casting & Scelte', 'Rinunce eccellenti nel cast', 'Prima che Russell Crowe venisse ufficialmente ingaggiato per il ruolo del negoziatore Terry Thorne, la produzione aveva valutato diversi altri attori di primissimo piano di Hollywood, tra cui Harrison Ford, che tuttavia declinò l''offerta.', 'Variety Casting Report', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:35:25.701801+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('8347fed5-7dc1-4dd2-a73b-d3811a2ab906', 354, 'Aneddoti dal set', 'Spostamento delle location di ripresa', 'Sebbene la storia sia ambientata in Colombia, le rigide questioni di sicurezza impedirono di girare interamente nel paese sudamericano; la maggior parte delle sequenze tropicali e della giungla fu quindi spostata e girata tra l''Ecuador e la Polonia.', 'Making-of ufficiale incluso nel DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:35:25.701801+00:00'),
('5b6c60cc-bf88-4d66-a67a-9136e81e5308', 354, 'Aneddoti dal set', 'Preparazione militare e consulenti reali', 'Russell Crowe si sottopose a un rigoroso addestramento e consultò negoziatori di ostaggi professionisti, tra cui esperti realmente operativi in casi di sequestri internazionali, per rendere il più verosimile possibile l''approccio tattico del suo personaggio.', 'Intervista audio al regista Taylor Hackford', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:35:25.701801+00:00'),
('0f8d86d2-2e8f-460f-8345-51929ae80f91', 300, 'Segreti di produzione', 'L''uso pionieristico delle telecamere digitali aeree', 'Per catturare la frenesia dei combattimenti sulla spiaggia senza appesantire la troupe, la produzione ha fatto largo impiego di camere digitali leggere montate su supporti speciali e droni sperimentali. Questo ha garantito una prospettiva immersiva simile a quella di un videogioco sparatutto.', 'Articolo tecnico su American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:49:46.619885+00:00'),
('0d4be411-d78c-4d59-b6e2-8621cd15c6d9', 300, 'Citazioni & Easter Egg', 'Il tributo ai fan del manga originale', 'Il nome della protagonista femminile, Rita Vrataski, è un chiaro omaggio al personaggio di Rita Vrataski (nota come ''Full Metal Bitch'') del romanzo leggero giapponese ''All You Need Is Kill'' di Hiroshi Sakurazaka, da cui il film è liberamente tratto.', 'Note di adattamento della sceneggiatura', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:49:46.619885+00:00'),
('cacc472e-5ca0-4389-b137-7cc9afbfc4c2', 304, 'Casting & Scelte', 'La sostituzione last-minute di Michael Sheen', 'Il ruolo del pedante Paul Bates fu originariamente offerto a David Tennant, ma l''attore dovette rinunciare a causa di conflitti di programmazione teatrale. Woody Allen ripiegò prontamente su Michael Sheen, che accettò la parte volando a Parigi tra un impegno cinematografico e l''altro.', 'Note di produzione ufficiali Sony Pictures Classics', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:49:57.983447+00:00'),
('51c2b8b8-9996-4774-bb4e-7612ee99f8d2', 304, 'Casting & Retroscena', 'Il debutto cinematografico di Carla Bruni', 'L''allora Première dame di Francia Carla Bruni fu scritturata da Woody Allen dopo un incontro fortuito a Parigi, senza bisogno di sostenere alcun provino. Durante le riprese al Musée Rodin, la troupe fu costretta a ripetere la sua scena di dialogo ben trentadue volte a causa del perfezionismo maniacale del regista.', 'Intervista rilasciata da Carla Bruni al settimanale Paris Match', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:49:57.983447+00:00'),
('27d9310b-b5cd-4dcc-bdfc-7ca102964ef1', 304, 'Aneddoti dal set', 'La pioggia parigina come personaggio invisibile', 'Le celebri sequenze sotto la pioggia notturna di Parigi non facevano parte della sceneggiatura originale in modo così esteso, ma Allen decise di sfruttare le pessime condizioni meteorologiche della primavera 2010. La troupe dovette ricorrere continuamente a cannoni sparaneve e tubi di irrigazione per mantenere la stessa bagnatura costante tra i campi e i controcampi girati in giorni differenti.', 'Making-of ufficiale incluso nel Blu-ray Warner Home Video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:49:57.983447+00:00'),
('2481a2c9-4d5c-42d8-b886-fb5f16cc1e84', 304, 'Citazioni & Easter Egg', 'L''omaggio nascosto a Luis Buñuel', 'La sequenza in cui il protagonista Gil Pender racconta al pittore surrealista Luis Buñuel l''idea per un film incentrato su un gruppo di persone bloccate in una stanza che non riescono più ad uscire è un chiaro ed esplicito omaggio al capolavoro di Buñuel ''L''angelo sterminatore'' (1962).', 'Commento audio e analisi critica della sceneggiatura', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:49:57.983447+00:00'),
('880abdff-0d35-4805-94ee-d5846f316bbb', 294, 'Curiosità & Retroscena', 'La collaborazione musicale di fermata in fermata', 'Il regista Bong Joon-ho ha inviato al compositore Jaeil Jung la sceneggiatura completa prima ancora che le riprese iniziassero, permettendo alla colonna sonora di essere sviluppata in tandem con la produzione visiva. Questa sincronia ha consentito al tema musicale centrale di adattarsi millimetricamente ai movimenti di macchina durante la fuga sotto la pioggia.', 'Commento audio ufficiale del regista e note di produzione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:49:31.803864+00:00'),
('922ca3dd-e4c5-424a-841c-66f8b9486a09', 294, 'Aneddoti dal set', 'La precisione millimetrica della sequenza della pesca', 'La scena in cui la governatrice Moon-gwang viene colpita dalle pesche lanciate dai Kim ha richiesto oltre venti ciak di prove a secco per calcolare la traiettoria esatta della frutta senza rischiare di colpire realmente l''attrice Lee Jung-eun con troppa forza durante il lancio coordinato del cast.', 'Featurette ''Behind the Scenes of Parasite'' e diari di troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:49:31.803864+00:00'),
('d934dae9-65e1-42c8-bb16-016c5f183bd4', 294, 'Casting & Scelte', 'La scelta iniziale per il ruolo di Kim Ki-taek', 'Il protagonista Song Kang-ho non ha dovuto sostenere alcun provino per la parte di Ki-taek, poiché il regista Bong Joon-ho aveva scritto il personaggio avendo in mente esclusivamente lui fin dalla primissima stesura del soggetto originale, avvenuta nel 2015.', 'Intervista al regista per Variety e conferenze stampa ufficiali a Cannes', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:49:31.803864+00:00'),
('b83c3ebb-ea08-4aff-877a-daf705ba1457', 294, 'Segreti di produzione', 'Il design geometrico delle scale e degli spazi', 'Lo scenografo Lee Ha-jun ha progettato i vari livelli della villa e le strade circostanti basandosi sui concetti di architettura brutalista e minimalista per riflettere la rigida stratificazione sociale della Corea del Sud contemporanea, lavorando a stretto contatto con il direttore della fotografia Hong Kyung-pyo.', 'Articolo di approfondimento di Architectural Digest sulla produzione del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:49:31.803864+00:00'),
('9b4a6cdb-6578-4b5b-b8ef-623b62717a66', 305, 'Casting & Scelte', 'La lunga preparazione di Natalie Portman', 'Natalie Portman ha accettato il ruolo circa dieci anni prima dell''effettivo inizio delle riprese, quando il regista Darren Aronofsky le parlò per la prima volta del progetto nel 2000. L''attrice si è sottoposta a un anno di nuoto e allenamento cardio prima di iniziare sei mesi di lezioni quotidiane di balletto classico per cinque ore al giorno.', 'Note di produzione ufficiali della Fox Searchlight', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:50:01.964831+00:00'),
('7637ab2b-14fa-4ae8-9c6d-5920632011fb', 305, 'Casting & Scelte', 'Il debutto cinematografico di Benjamin Millepied', 'Il ballerino e coreografo principale del New York City Ballet Benjamin Millepied non solo ha curato tutte le coreografie del film, ma ha anche fatto il suo esordio come attore interpretando il ruolo di David, uno dei colleghi di Nina. Sul set, Millepied ha conosciuto Natalie Portman, con cui si è successivamente sposato.', 'Intervista ufficiale al cast e retroscena di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:50:01.964831+00:00'),
('6fb7791e-4add-4862-b7ee-316071662861', 4, 'Curiosità & Retroscena', 'Il legame con i veri Miami Dolphins', 'La franchigia NFL dei Miami Dolphins collaborò attivamente alla produzione, permettendo alla troupe di girare alcune sequenze cruciali all''interno del Joe Robbie Stadium durante i giorni di pausa della squadra. Molti dei giocatori dell''epoca fecero brevi apparizioni come comparse nelle scene ambientate nello stadio e durante la sequenza finale del Super Bowl.', 'Archivio storico dei Miami Dolphins e interviste promozionali del 1994', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:35:41.328003+00:00'),
('94aba890-a5d3-47f8-a20a-cf0dce4238f9', 4, 'Casting & Scelte', 'La riscrittura del personaggio e il tono iniziale', 'Nelle prime bozze di sceneggiatura scritte da Jack Bernstein, Ace Ventura era concepito come un investigatore meno sopra le righe e più simile ai tradizionali detective dei film noir. Fu l''arrivo di Jim Carrey e l''intervento di riscrittura dello stesso Carrey insieme a Tom Shadyac a spostare radicalmente il tono verso la farsa slapstick e l''iperattività fisica.', 'Intervista agli sceneggiatori in ''Creative Screenwriting Magazine''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:35:41.328003+00:00'),
('a7d5e296-a1f6-4ac8-9036-0570ec5442b2', 305, 'Segreti di produzione', 'La scelta delle doppiatrici per la danza', 'Nonostante l''enorme impegno fisico di Natalie Portman e Mila Kunis, per alcune delle sequenze di danza più complesse e tecniche del Lago dei Cigni è stata utilizzata la ballerina solista dell''American Ballet Theatre Sarah Lane come controfigura per i piedi e le piroette più avanzate, scatenando in seguito un acceso dibattito mediatico sull''effettivo minutaggio di danza della Portman.', 'Dichiarazioni ufficiali di Sarah Lane e comunicati di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:50:01.964831+00:00'),
('b038e6c7-3aca-42b7-be39-52a0bf1f8018', 305, 'Effetti speciali & Trucco', 'L''uso mirato delle lenti a contatto', 'Per enfatizzare la trasformazione psicologica e fisica di Nina nel cigno nero, la produzione ha utilizzato speciali lenti a contatto colorate che modificavano l''aspetto degli occhi di Natalie Portman, facendoli apparire via via più minacciosi e simili a quelli di un rapace durante le allucinazioni.', 'Making-of e approfondimento del reparto trucco', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:50:01.964831+00:00'),
('4c776952-1d31-456e-bef3-38c33fad86b2', 305, 'Citazioni & Easter Egg', 'Il legame tematico con The Wrestler', 'Darren Aronofsky ha più volte ribadito che ''Il cigno nero'' è idealmente il compagno speculare del suo film precedente, ''The Wrestler'' (2008). Entrambe le pellicole esplorano il tema dell''ossessione totalizzante per una forma d''arte o disciplina fisica che consuma e distrugge il corpo del protagonista.', 'Commento audio del regista all''edizione Home Video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:50:01.964831+00:00'),
('ded694cc-1af0-4d3b-9646-c5d80a68db13', 320, 'Aneddoti dal set', 'L''infortunio sul set di Rudy Youngblood', 'Durante le lunghe e faticose riprese nella giungla messicana, il protagonista Rudy Youngblood subì diverse contusioni minori, tra cui un taglio a una mano durante la sequenza in cui il suo personaggio fugge dai predatori. Nonostante il dolore e le condizioni climatiche estreme, l''attore scelse di continuare a girare senza ricorrere a una controfigura.', 'Making-of ufficiale ''The Journey of Apocalypto''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:50:55.755293+00:00'),
('bc77fda6-6d3e-4b72-ad9d-5d86a7eabea0', 320, 'Casting & Scelte', 'La scelta rigorosa di un cast di esordienti', 'Mel Gibson decise deliberatamente di non scritturare attori famosi o volti noti di Hollywood, preferendo attingere a talenti locali, indigeni e in molti casi assolutamente esordienti come Dalia Hernández e Gerardo Taracena, per preservare l''autenticità visiva e culturale dell''opera senza distrazioni per lo spettatore.', 'Note di produzione ufficiali Touchstone Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:50:55.755293+00:00'),
('6dedb419-81c2-48f9-901f-0f3d0f09b4ea', 320, 'Effetti speciali & Trucco', 'Il massiccio lavoro di body painting', 'Il reparto trucco guidato da Aldo Signoretti ha dovuto coordinare ogni giorno decine di artisti per applicare tatuaggi temporanei, scarificazioni finte e complessi disegni corporei basati su reperti storici a centinaia di comparse, impiegando ore prima dell''inizio effettivo delle riprese di ogni singola scena.', 'Intervista al reparto trucco e parrucco nei contenuti speciali del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:50:55.755293+00:00'),
('604f3ee6-513d-4708-9842-6e6b455f6de8', 295, 'Segreti di produzione', 'La consulenza del chitarrista pluri-premiato per le animazioni delle mani', 'Per garantire che i movimenti delle mani di Miguel mentre suonava la chitarra fossero anatomicamente e tecnicamente perfetti, la produzione ha filmato il chitarrista e consulente musicale germano-messicano Jason Vieaux in studio, utilizzando i suoi movimenti come riferimento diretto per l''animazione.', 'Audio commento del regista Lee Unkrich e del co-regista Adrian Molina', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:49:34.720718+00:00'),
('51e900bc-8c67-4336-9e8c-791cc5c44349', 316, 'Casting & Scelte', 'L''ispirazione per il personaggio di Sanborn', 'Il personaggio del sergente J.T. Sanborn, interpretato da Anthony Mackie, è stato modellato da Mark Boal unendo i tratti di diversi veri operatori EOD incontrati durante il suo periodo di reportage in Iraq, focalizzandosi in particolare sulla loro fredda gestione del terrore quotidiano.', 'Note di produzione ufficiali e interviste a Mark Boal', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:50:37.786423+00:00'),
('3d132167-4c3b-4894-838d-5fde0000e3ee', 316, 'Aneddoti dal set', 'Improvvisazione nella scena della lotta', 'La violenta colluttazione nel fango tra Jeremy Renner e Anthony Mackie all''interno della base militare non era rigidamente coreografata; Kathryn Bengelow ha incoraggiato gli attori a lasciarsi andare a una vera lotta fisica per catturare la frustrazione reale dei soldati.', 'Audio commento del Blu-ray con Kathryn Bengelow e Jeremy Renner', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:50:37.786423+00:00'),
('d2210294-f23c-44f5-ba2b-4fd7a8f8cc73', 316, 'Segreti di produzione', 'Uso di vere tute EOD pesanti', 'Gli attori hanno dovuto indossare autentiche tute protettive EOD che pesavano oltre 35 chili durante le scene di disinnesco, aumentando notevolmente il carico fisico e lo stress termico sul set in Giordania.', 'Documentario dietro le quinte ''The Hurt Locker: Behind the Scenes''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:50:37.786423+00:00'),
('cdd44f47-f82a-49dd-8a4c-025f172a9f9b', 316, 'Segreti di produzione', 'La scelta del direttore della fotografia', 'Kathryn Bigelow ha fortemente voluto Barry Ackroyd come direttore della fotografia dopo aver ammirato il suo lavoro in ''United 93'' di Paul Greengrass, apprezzando la sua straordinaria abilità nel gestire cineprese a mano in spazi ristretti.', 'Intervista a Barry Ackroyd per American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:50:37.786423+00:00'),
('652137dc-5317-486b-af48-f9871fa3644a', 316, 'Curiosità & Retroscena', 'Consulenti militari sul set', 'Per garantire la massima autenticità nelle procedure di disinnesco degli ordigni, la produzione ha assunto veterani delle forze armate ed esperti EOD reali come consulenti fissi sul set durante tutte le riprese in Medio Oriente.', 'Making-of ufficiale incluso nell''edizione home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:50:37.786423+00:00'),
('f73b7e11-0e92-4e84-8903-ad044ce48dbe', 7, 'Aneddoti dal set', 'L''improvvisazione di Robert De Niro con la pistola fumante', 'Durante la scena in cui il giovane Vito Corleone uccide Don Fanucci nei vicoli di Little Italy, Robert De Niro improvvisò il gesto di soffiare via il fumo dalla canna della pistola dopo lo sparo, un dettaglio divenuto iconico nella storia del cinema.', 'Note di produzione e retroscena ufficiali della Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:35:48.864825+00:00'),
('4ec455d3-313d-45c4-a353-a9795bcb6ded', 7, 'Casting & Scelte', 'Il rifiuto iniziale di Marlon Brando per il cameo finale', 'Francis Ford Coppola aveva scritto un piccolo cameo per Marlon Brando nella scena del flashback finale a tavola, ma l''attore rifiutò categoricamente di presentarsi sul set a causa di vecchi rancori economici con la produzione risalenti al primo film.', 'Autobiografia di Francis Ford Coppola e archivi di produzione Paramount', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:35:48.864825+00:00'),
('e5986079-138e-4696-adb6-4993a98992a1', 7, 'Aneddoti dal set', 'Le difficoltà linguistiche di Robert De Niro in siciliano', 'Nonostante l''impegno maniacale per imparare il dialetto siciliano, Robert De Niro recitò quasi interamente in siciliano stretto durante le sue scene, ma gran parte delle sue battute dovettero essere sottotitolate perché ritenute poco comprensibili anche per i madrelingua.', 'Making-of ufficiale e interviste d''archivio al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:35:48.864825+00:00'),
('244d7e3e-58c9-41d9-a22d-cb944d09a831', 137, 'Effetti speciali & Trucco', 'La guida ad alta velocità degli stuntman professionisti', 'Per le celebri sequenze di guida contromano nel tunnel e nel traffico parigino, la produzione ha ingaggiato piloti professionisti ed ex piloti di Formula 1, tra cui Jean-Pierre Jabouille, che guidavano le berline tedesche modificate a velocità superiori ai 160 chilometri orari.', 'Note di produzione e Making-of ufficiale MGM', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:05:23.602361+00:00'),
('6699fe0d-dec3-4486-9b26-9d8a7ac891d7', 7, 'Segreti di produzione', 'La ricostruzione di Little Italy nel 1917 a Washington Avenue', 'Poiché New York era troppo modernizzata negli anni ''70, la produzione ricostruì meticolosamente la Little Italy del 1917 su un''intera strada di East 6th Street a Manhattan, spendendo oltre un milione di dollari dell''epoca per trasformare facciate, negozi e pavimentazioni.', 'Archivio storico della produzione Paramount e registri di scenografia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:35:48.864825+00:00'),
('92be99bd-2027-4af4-90d4-5057cc1ccc2e', 316, 'Casting & Scelte', 'L''uso di attori locali iracheni', 'Gran parte delle comparse e dei ruoli secondari nel film sono stati interpretati da veri rifugiati iracheni trasferitisi in Giordania, conferendo alle sequenze di strada una veridicità linguistica e culturale assoluta.', 'Note di produzione e recensioni della stampa specializzata', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:50:37.786423+00:00'),
('bb01de27-b3f3-4e35-b722-7406ba97790b', 323, 'Casting & Scelte', 'Il rifiuto di Brad Pitt e il coinvolgimento iniziale', 'Inizialmente Brad Pitt era stato associato al progetto quando la Plan B Entertainment acquistò i diritti del film originale coreano ''Infernal Affairs''. Pitt avrebbe dovuto interpretare uno dei ruoli principali, ma in seguito decise di rimanere solo come produttore esecutivo, ammettendo di essere ormai troppo vecchio per la parte e spingendo per l''ingresso di Leonardo DiCaprio e Matt Damon.', 'Intervista a Brad Pitt per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:51:09.572055+00:00'),
('698c3131-bc30-4108-8463-8f08a014c63e', 323, 'Curiosità & Retroscena', 'La scelta del titolo originale e il riferimento a James Whitey Bulger', 'Il personaggio di Frank Costello interpretato da Jack Nicholson è liberamente ispirato alla figura del famigerato boss di Boston James ''Whitey'' Bulger, latitante per decenni. Tuttavia, lo sceneggiatore William Monahan ha dichiarato di aver attinto anche alla figura di John Connolly, l''agente dell''FBI corrotto che protetto da Bulger operava nella stessa zona.', 'Note di produzione ufficiali della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:51:09.572055+00:00'),
('003e2557-96f6-4d6b-bb24-26f543a364e7', 323, 'Segreti di produzione', 'Il cambio di ambientazione da Hong Kong a Boston', 'Il produttore Graham King e William Monahan decisero di spostare l''ambientazione da Hong Kong a Boston perché la città offriva un contesto culturale unico, fortemente caratterizzato dalla rivalità tra comunità irlandese-americana e italiana, ideale per dare una nuova identità culturale e geografica al remake rispetto all''originale ''Infernal Affairs''.', 'Audio commento del DVD con Martin Scorsese e William Monahan', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:51:09.572055+00:00'),
('73c8a19a-cb1f-4023-9b82-e6bbac6fea91', 7, 'Aneddoti dal set', 'L''infortunio sul set di John Cazale durante la scena del lago', 'Durante le riprese della drammatica sequenza della pesca sul Lago Tahoe, John Cazale (Fredo) accusò un forte malessere dovuto alle basse temperature dell''acqua e alla stanchezza, costringendo la troupe a ripetuti stop per consentirgli di riscaldarsi.', 'Diari di produzione e retroscena del set di Francis Ford Coppola', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:35:48.864825+00:00'),
('0353a708-b229-4345-8433-86612918c1a4', 7, 'Casting & Scelte', 'Il vero nome del personaggio di Frank Pentangeli', 'Il personaggio di Frankie Pentangeli, interpretato da Michael V. Gazzo, era originariamente stato scritto per includere il ritorno di Peter Clemenza; a seguito del rifiuto di Richard Castellano, il nome del personaggio fu cambiato ma la sceneggiatura mantenne intatte le dinamiche originali.', 'Sceneggiatura originale annotata da Mario Puzo e Francis Ford Coppola', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:35:48.864825+00:00'),
('ffb9c04e-5f27-4dc0-aad1-5cf12250bd24', 296, 'Casting & Scelte', 'La genesi televisiva mai realizzata', 'Prima di diventare un lungometraggio uscito nel 2016, la storia concepita da Shane Black e Anthony Bagarozzi alla fine degli anni ''90 fu originariamente pensata come una serie televisiva. Il progetto rimase fermo per oltre un decennio prima che i creatori decidessero di adattarlo in un film cinematografico R-rated.', 'Intervista ufficiale agli sceneggiatori per Collider', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:49:38.819315+00:00'),
('312de22d-8beb-46ca-87ee-c7ca0ddfdbd2', 296, 'Casting & Scelte', 'Il provino fulmineo di Angourie Rice', 'La giovane attrice australiana Angourie Rice ha ottenuto la parte di Holly March inviando un semplice videotape registrato a Sydney. La sua incredibile chimica con Ryan Gosling e la capacità di reggere il confronto con attori del calibro di Russell Crowe sono state lodate dal regista Shane Black durante le sessioni di lettura del copione.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:49:38.819315+00:00'),
('5b41e001-cbe2-43f7-aa4e-56e60b79f3b7', 296, 'Effetti speciali & Trucco', 'Il look d''ispirazione suburbana per Ryan Gosling', 'Per caratterizzare Holland March come un investigatore privato perennemente al verde e sfortunato nella Los Angeles del 1977, il costumista Karyn Wagner ha attinto a cataloghi di moda vintage e vecchi numeri di Playboy, puntando su abiti dai colori slavati e poliestere economico.', 'Audio commento del regista Shane Black', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:49:38.819315+00:00'),
('787a07ee-5bd3-4ad5-bd21-260a20d962ed', 296, 'Segreti di produzione', 'La ricostruzione digitale della Los Angeles del 1977', 'Molte delle iconiche location di Los Angeles degli anni ''70 non esistono più o sono state radicalmente trasformate. La produzione ha fatto un uso massiccio di effetti visivi digitali supervisionati da Zoic Studios per rimuovere grattacieli moderni e aggiungere insegne d''epoca lungo Hollywood Boulevard.', 'VFX Breakdown ufficiale di Zoic Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:49:38.819315+00:00'),
('b31fa8b1-ac69-4e29-b4e3-1403efff5a5e', 296, 'Citazioni & Easter Egg', 'Il cameo vocale di un celebre attore', 'L''attore Robert Downey Jr., che aveva già lavorato con Shane Black in Iron Man 3, appare brevemente nel film in un ruolo non accreditato: presta infatti la voce fuori campo a un anziano membro della gang dei teppisti nella sequenza della festa in piscina.', 'Crediti finali del film e interviste promozionali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:49:38.819315+00:00'),
('0cdb2882-8e23-4828-8bd9-f9622eb887f2', 296, 'Aneddoti dal set', 'L''improvvisazione con il cane da guardia', 'Durante la sequenza in cui Jackson Healy irrompe nella villa, l''interazione tra Russell Crowe e il grande cane da guardia fu in gran parte improvvisata sul momento poiché l''animale non seguiva rigorosamente i comandi dell''addestratore, costringendo Crowe a improvvisare battute per mantenere la tensione comica.', 'Making-of incluso nell''edizione Home Video Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:49:38.819315+00:00'),
('2d7f7c60-6984-40a6-8276-2736a68fdca3', 317, 'Casting & Scelte', 'La scelta iniziale di Guillermo del Toro alla regia', 'Prima che Francis Lawrence prendesse le redini del progetto, la Warner Bros. aveva offerto la regia a Guillermo del Toro, il quale declinò l''offerta per poter dirigere Hellboy II: The Golden Army.', 'Intervista ufficiale di Guillermo del Toro a Collider', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:50:41.844123+00:00'),
('9d599e79-b25f-4c6a-bb6f-71f043676bb7', 317, 'Aneddoti dal set', 'Il blocco di Times Square e il permesso speciale', 'La produzione ottenne il permesso di bloccare completamente diverse strade di New York, inclusa la zona di Times Square, per sole due settimane consecutive, spendendo circa 5 milioni di dollari solo per gestire la chiusura e la logistica urbana.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:50:41.844123+00:00'),
('714754aa-9daa-4137-ba7f-208db0c08a60', 317, 'Casting & Scelte', 'Il rifiuto di Arnold Schwarzenegger nel 1997', 'Negli anni ''90, quando il progetto era sviluppato con il titolo provvisorio ''A Man Alone'' e Ridley Scott alla regia, il ruolo di Robert Neville fu offerto ad Arnold Schwarzenegger, ma l''accordo saltò a causa dei costi di produzione giudicati troppo alti dallo studio.', 'Archivio storico di Variety e Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:50:41.844123+00:00'),
('257d952f-6729-4b06-8cc0-1a0a78c67761', 317, 'Segreti di produzione', 'L''uso dei manichini a grandezza naturale', 'Per girare le sequenze in cui Robert Neville interagisce con i manichini nel negozio di video, la produzione utilizzò veri manichini personalizzati, dislocati in punti strategici per dare a Will Smith una reale percezione dello spazio e della solitudine sul set.', 'Commento audio del regista Francis Lawrence nel DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:50:41.844123+00:00'),
('f14f9a63-54fe-43c2-8b06-5f6ff845aff1', 317, 'Effetti speciali & Trucco', 'La conversione digitale dei Darkseekers', 'Inizialmente la produzione aveva pianificato di utilizzare attori in carne e ossa con il trucco prostetico per i vampiri mutati, ma il regista decise in seguito di affidarsi quasi interamente alla CGI per accentuare i loro movimenti innaturali e la loro agilità.', 'Making-of ufficiale ''Creating a New York City''s Wasteland''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:50:41.844123+00:00'),
('4206cab2-2c20-4803-ad9d-3aae3f7c7c9e', 317, 'Citazioni & Easter Egg', 'L''Easter egg del manifesto di Batman vs Superman', 'Nella sequenza in cui Robert Neville cammina per le strade di New York, si vede sullo sfondo un cartellone pubblicitario con il logo combinato di Batman e Superman, inserito dal produttore Akiva Goldsman come scherzo autoreferenziale dato che stava scrivendo una sceneggiatura su quei personaggi all''epoca.', 'Dichiarazione ufficiale del produttore Akiva Goldsman', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:50:41.844123+00:00'),
('825fd91c-f161-4481-839f-abb76ef7b3a7', 317, 'Casting & Scelte', 'L''alternativa del finale originale basato sul libro', 'Il film girò originariamente un finale in cui Neville capiva di essere diventato un mostro per i Darkseekers (fedele al romanzo di Richard Matheson), ma fu cambiato all''ultimo minuto dopo che il pubblico dei test screening negative espresse forte disapprovazione.', 'Documentario sui finali alternativi nell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:50:41.844123+00:00'),
('41c5b316-69f0-4cb0-a14d-296017074092', 328, 'Casting & Scelte', 'La scelta lampo di Dakota Fanning', 'Steven Spielberg ha scelto Dakota Fanning per il ruolo di Rachel Ferrier senza farle sostenere alcun provino, avendola già fortemente voluta e ammirata per le sue straordinarie doti attoriali dimostrate in ''Mi chiamo Sam'' e ''Man on Fire''.', 'Audio commento del regista e making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:51:13.293584+00:00'),
('20721eb2-78db-4748-b3c0-fc71ed6950ff', 8, 'Casting & Scelte', 'Il ruolo mancato di Winona Ryder', 'Winona Ryder era stata scritturata ufficialmente per interpretare Mary Corleone e si trovava già a Roma pronta per iniziare le riprese, ma dovette abbandonare il set il primo giorno a causa di un esaurimento nervoso diagnosticatole dai medici.', 'Dichiarazioni di Francis Ford Coppola nelle interviste di approfondimento per l''edizione home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:35:53.40309+00:00'),
('3c365bee-3602-47a0-9b0a-76659b2a3138', 8, 'Casting & Scelte', 'La scelta di Sofia Coppola per disperazione', 'Con l''abbandono improvviso di Winona Ryder e senza il tempo materiale per organizzare nuovi casting internazionali, Francis Ford Coppola decise di affidare il ruolo cruciale di Mary Corleone a sua figlia Sofia, mossa che scatenò feroci polemiche da parte della critica cinematografica.', 'Note di produzione e recensioni d''epoca del Los Angeles Times', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:35:53.40309+00:00'),
('4a34125f-5896-4796-a84f-a4d9247e0b2e', 8, 'Casting & Scelte', 'Il ritorno mancato di Robert Duvall', 'Robert Duvall rifiutò di riprendere il suo iconico ruolo del consigliere Tom Hagen perché la produzione gli offrì un compenso economico nettamente inferiore rispetto a quello percepito da Al Pacino e Diane Keaton, portando alla creazione del personaggio sostitutivo di B.J. Harrison interpretato da George Hamilton.', 'Interviste di Robert Duvall a programmi televisivi e stampa specializzata', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:35:53.40309+00:00'),
('f0f0f755-95b0-4048-bffc-5d4c2431ba5f', 301, 'Curiosità & Retroscena', 'La scelta del titolo nella versione italiana', 'Il titolo originale del film, ''All Is Lost'', deriva dalla primissima riga della sceneggiatura scritta da J.C. Chandor, che constava originariamente di sole 32 pagine. Nella versione italiana è stato aggiunto il sottotitolo ''Tutto è perduto'' per enfatizzare ulteriormente la drammaticità della lotta per la sopravvivenza del protagonista.', 'Note di produzione ufficiali e pressbook del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:49:49.592541+00:00'),
('56fd7476-2986-4e3c-9f2a-970d8122e0b2', 301, 'Casting & Scelte', 'La quasi totale assenza di dialoghi nel copione', 'Robert Redford ha accettato il ruolo senza esitazione nonostante la sceneggiatura fosse estremamente scarna e priva quasi del tutto di dialoghi, ad eccezione di poche imprecazioni e della lettera iniziale. L''attore ha trovato la sfida di recitare quasi esclusivamente con la fisicità e le espressioni facciali estremamente stimolante per la sua carriera.', 'Intervista a Robert Redford al Festival di Cannes 2013', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:49:49.592541+00:00'),
('6c6a8d30-47a4-49e8-93f2-197abe60994e', 301, 'Segreti di produzione', 'Le riprese nei teatri di posa messicani', 'Gran parte delle sequenze acquatiche e delle tempeste non è stata girata in mare aperto, ma all''interno dei celebri Baja Studios in Messico. La produzione ha utilizzato enormi serbatoi d''acqua esterni già resi celebri da kolossal come ''Titanic'' e ''Master and Commander'', permettendo alla troupe di controllare i movimenti delle onde e la sicurezza delle riprese.', 'Making-of ufficiale e documentario sulla produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:49:49.592541+00:00'),
('88c51b1e-4a01-46c8-8ff0-3b64879f5ee0', 307, 'Casting & Scelte', 'Il rifiuto originale di Mark Ruffalo tramite lettera', 'Mark Ruffalo ottenne la parte di Chuck Aule scrivendo direttamente a Martin Scorsese una lettera in cui esprimeva la sua profonda ammirazione e il forte desiderio di lavorare con lui, dopo aver saputo che il regista stava valutando altri interpreti.', 'Intervista ufficiale a Mark Ruffalo nel press kit del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:50:10.120437+00:00'),
('a1acf059-1598-4e24-a622-3d77b856efea', 307, 'Aneddoti dal set', 'La scelta della sigaretta accesa per mantenere la continuità', 'Leonardo DiCaprio ha rivelato che sul set di Shutter Island la gestione della continuità con le sigarette accese era estremamente complessa a causa dei continui cambi d''inquadratura, costringendolo a calcolare con precisione millimetrica la cenere consumata tra un ciak e l''altro.', 'Audio commento e interviste dal backstage del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:50:10.120437+00:00'),
('2c086ea1-3f43-4969-8618-be33a86c5d87', 307, 'Citazioni & Easter Egg', 'L''omaggio visivo ai classici del noir e del thriller psicologico', 'Martin Scorsese ha esplicitamente modellato l''atmosfera e alcune inquadrature di Shutter Island sui classici del cinema noir e thriller degli anni ''40 e ''50, citando pelliche storiche come ''Il bacio della pantera'' (Cat People) di Jacques Tourneur e ''Vertigo'' di Alfred Hitchcock.', 'Note di regia ufficiali e conferenze stampa della Berlinale 2010', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:50:10.120437+00:00'),
('ba2c320f-8ae9-47d6-9432-58d26a890d9e', 307, 'Segreti di produzione', 'L''uso dei colori primari per definire la psiche dei personaggi', 'La costumista Sandy Powell e Martin Scorsese hanno studiato una palette cromatica rigorosa in cui i colori primari, in particolare il rosso acceso dei cappotti delle donne nelle visioni di Teddy, venivano usati deliberatamente per simboleggiare il trauma e il sangue rimosso dal protagonista.', 'Featurette ''Behind the Shutters'' nel materiale extra', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:50:10.120437+00:00'),
('fb21d38a-a915-48c4-85df-3a2dee4b701f', 307, 'Curiosità & Retroscena', 'Il ritardo dell''uscita cinematografica strategica', 'Il film, inizialmente previsto per l''autunno del 2009 per concorrere nella stagione dei premi Oscar, fu posticipato da Paramount Pictures a febbraio 2010 a causa di problemi di bilancio dello studio e per consentire una campagna di marketing più mirata.', 'Comunicato stampa ufficiale Paramount Pictures del 2009', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:50:10.120437+00:00'),
('f617115c-e202-4894-ad10-07a7417eaa23', 322, 'Casting & Scelte', 'La scelta iniziale di David Bowie per Nikola Tesla', 'Christopher Nolan voleva fortemente David Bowie per il ruolo di Nikola Tesla, ma il musicista rifiutò inizialmente l''offerta. Nolan volò personalmente a New York per convincerlo, paragonando l''unicità di Tesla a quella di Bowie stesso.', 'Intervista di Christopher Nolan a Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:51:04.761677+00:00'),
('9db8e826-9414-4a03-a92c-aea4af3b791a', 322, 'Aneddoti dal set', 'L''infortunio sul set di Hugh Jackman', 'Durante una delle sequenze in cui il suo personaggio esprime intensa frustrazione, Hugh Jackman si è ferito accidentalmente al collo con una lama di scena che doveva essere smussata. Per fortuna l''incidente si è risolto con un piccolo taglio senza gravi conseguenze.', 'Commento audio del DVD e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:51:04.761677+00:00'),
('70e6b8a4-1f59-420f-8839-a52744e9fa50', 322, 'Segreti di produzione', 'La riproduzione del laboratorio di Tesla a Colorado Springs', 'Gli scenografi guidati da Nathan Crowley hanno studiato i veri progetti e brevetti di Nikola Tesla per ricostruire fedelmente il laboratorio e la torre di Wardenclyffe nel deserto, integrando macchinari realmente funzionanti per l''epoca.', 'Making-of ufficiale ''The Director''s Notebook''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:51:04.761677+00:00'),
('00363018-88c2-4290-a0c8-7e4cc4883626', 322, 'Aneddoti dal set', 'L''uso di veri piccioni ammaestrati', 'Per le sequenze di magia con i piccioni, Hugh Jackman e Christian Bale hanno dovuto lavorare con veri uccelli da illusionismo sotto la supervisione di addestratori professionisti, imparando le basi dei giochi di prestigio con i volatili.', 'Intervista al cast nel documentario sul making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:51:04.761677+00:00'),
('dc0f5184-f7e8-4c40-9ae4-53ca55f0e142', 302, 'Aneddoti dal set', 'Il taglio di capelli di Jamie Foxx', 'Jamie Foxx ha insistito per montare a cavallo senza sella per gran parte del film, portando a termine l''impresa nonostante le difficoltà fisiche e guadagnandosi il rispetto della troupe. L''attore ha inoltre voluto mantenere una cicatrice autentica sul viso derivante da una vecchia caduta giovanile.', 'Intervista ufficiale nel making-of del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:49:53.748308+00:00'),
('21f92428-8d1d-45c3-a5a2-2f826f22ead4', 302, 'Aneddoti dal set', 'Il vero sangue sulla mano di Leonardo DiCaprio', 'Durante la drammatica scena in cui Calvin Candie colpisce con violenza il tavolo da pranzo, Leonardo DiCaprio si è realmente tagliato una mano con un bicchiere di cristallo rotto. L''attore ha continuato a recitare imperterrito, mantenendo l''immersione nel personaggio e incorporando il sangue reale nella sequenza, lodato da Tarantino che ha tenuto la versione nel montaggio finale.', 'Note di produzione e intervista a Stacey Sher', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:49:53.748308+00:00'),
('039a67c6-72d6-4418-9029-94c90b268400', 302, 'Casting & Scelte', 'Il rifiuto di Will Smith per il ruolo principale', 'Quentin Tarantino aveva scritto originariamente il ruolo di Django pensando a Will Smith. L''attore ha rifiutato la parte perché riteneva che il personaggio principale non fosse abbastanza centrale rispetto al dottor King Schultz di Christoph Waltz, aprendo così la strada all''ingaggio di Jamie Foxx.', 'Dichiarazioni pubbliche di Will Smith e Quentin Tarantino', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:49:53.748308+00:00'),
('cd38f18c-51b9-4309-a4d0-3ee63abb51db', 302, 'Citazioni & Easter Egg', 'L''ispirazione per il personaggio di Leonardo DiCaprio', 'Per costruire la figura spregevole del proprietario terriero Calvin Candie, Leonardo DiCaprio si è ispirato in parte a figure storiche del Sud schiavista e ai magnati descritti nei romanzi di Herman Melville, accentuando la crudeltà silenziosa del personaggio.', 'Commento audio e interviste promozionali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:49:53.748308+00:00'),
('d0dc36d8-8be0-46a1-aefe-ce031aa48f2b', 308, 'Casting & Scelte', 'Il rifiuto di Matt Damon e la clausola sugli utili', 'James Cameron offrì inizialmente il ruolo del protagonista Jake Sully a Matt Damon, promettendogli anche il 10% degli introiti al botteghino del film. L''attore dovette rifiutare a causa dei suoi impegni pregressi con il franchise di The Bourne Identity, perdendo così quella che sarebbe stata una delle percentuali di guadagno più alte della storia del cinema.', 'Dichiarazione ufficiale di Matt Damon al Festival di Cannes 2021', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:50:16.852539+00:00'),
('742c7798-8b9b-45d8-9e41-264ed674b361', 308, 'Aneddoti dal set', 'Il soprannome sul set di Sam Worthington', 'Durante le lunghe e faticose riprese in motion capture, l''attore Sam Worthington viveva in gran parte in un furgone convertito a causa della mancanza di una fissa dimora in quel periodo. Questo stile di vita spartano spinse il regista James Cameron a chiamarlo affettuosamente sul set con il soprannome ironico di ''The Vagabond''.', 'Intervista di James Cameron per GQ Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:50:16.852539+00:00'),
('44018ca6-f210-45b9-9a23-f68d51599316', 308, 'Segreti di produzione', 'L''invenzione della lingua Na''vi da parte di un linguista', 'Per rendere i Na''vi il più realistici possibile, James Cameron assunse il professore di linguistica Paul Frommer della University of Southern California. Frommer lavorò per anni per sviluppare un vocabolario iniziale di circa un millennio di parole, insegnando poi personalmente la grammatica e la pronuncia corretta agli attori del cast durante la preparazione.', 'Note di produzione ufficiali 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:50:16.852539+00:00'),
('82380572-b622-4e81-959c-d6a2f887cc38', 308, 'Effetti speciali & Trucco', 'La creazione fisica dei modelli in scala', 'Nonostante la forte impronta digitale, la Weta Workshop creò anche enormi modelli fisici dettagliati delle navi spaziali e dei veicoli militari della RDA, tra cui il gigantesco Samson e il Dragon Gunship. Questi modelli venivano scansionati in 3D per ottenere una base di riferimento geometrica estremamente dettagliata prima del rendering finale.', 'Art of Avatar: James Cameron''s Art Book', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:50:16.852539+00:00'),
('13436683-b0aa-4cb5-8b5e-11c6314e90bc', 308, 'Curiosità & Retroscena', 'Il vero significato della parola ''Avatar''', 'All''interno del canone narrativo del film, la parola ''avatar'' non è un termine inventato dai terrestri per caso, ma deriva direttamente dalla mitologia indù, dove indica la discesa di una divinità sulla terra in forma corporea. Nella sceneggiatura originale, la dottoressa Augustine spiega esplicitamente ai marines che il termine è stato scelto dai genetisti per sottolineare la natura transitoria e spirituale del trasferimento di coscienza.', 'Sceneggiatura originale di produzione di Avatar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:50:16.852539+00:00'),
('0a933cd1-293f-4992-bcd9-86a208695863', 318, 'Casting & Scelte', 'Il forfait dell''attore originale e l''arrivo di Paul Dano', 'Nel ruolo dei fratelli Sunday (Paul ed Eli) all''inizio delle riprese c''era l''attore Kel O''Neill. Dopo poche settimane sul set, Paul Thomas Anderson decise di sostituirlo con Paul Dano, riprendendo da capo tutte le scene già girate con il nuovo interprete.', 'Note di produzione ufficiali e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:50:47.350887+00:00'),
('b34ff386-7590-4e3d-baaa-2995229dee9f', 318, 'Curiosità & Retroscena', 'La scelta della colonna sonora di Jonny Greenwood', 'La colonna sonora candidata all''Oscar fu composta da Jonny Greenwood dei Radiohead, il quale utilizzò in gran parte brani preesistenti scritti per orchestre sinfoniche, tra cui il suo pezzo ''Popcorn Superhet Receiver'', riadattato per il film.', 'Documentario sul making-of e note di edizione della Nonesuch Records', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:50:47.350887+00:00'),
('45c6b16f-04fa-4044-b9bb-89274f74e8d4', 318, 'Citazioni & Easter Egg', 'Il ranch di Stanley Kubrick come fonte d''ispirazione', 'Paul Thomas Anderson ha scritto gran parte della sceneggiatura alloggiando nel ranch di Stanley Kubrick, un''esperienza che ha influenzato profondamente l''approccio rigoroso e metodico alla messa in scena del film.', 'Intervista di Paul Thomas Anderson a Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:50:47.350887+00:00'),
('c9e6ecbf-c9e1-4121-af9f-327dccef61f3', 318, 'Aneddoti dal set', 'La rottura della caviglia di Daniel Day-Lewis', 'Durante le riprese della celebre sequenza in cui Daniel Plainview insegue Eli Sunday nel fango e lo colpisce con dei birilli, Daniel Day-Lewis si ruppe una costola e si ferì gravemente una caviglia, costringendo la produzione a rallentare temporaneamente i piani di lavorazione.', 'Diario di produzione e interviste concesse da Paul Thomas Anderson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:50:47.350887+00:00'),
('88aa4441-b297-46fb-8a19-9f5e79e95cdf', 318, 'Casting & Scelte', 'Il debutto cinematografico di Dillon Freasier', 'Dillon Freasier, che interpreta il figlio sordo di Daniel Plainview (H.W.), fu scoperto dal direttore del casting in una scuola elementare in Texas. Il bambino non aveva alcuna precedente esperienza di recitazione e fu scelto dopo una ricerca durata mesi.', 'Special features del DVD e conferenze stampa ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:50:47.350887+00:00'),
('d87dcc59-8b5f-4e34-847e-7b595dd8f877', 318, 'Aneddoti dal set', 'L''infortunio sul set di Kevin J. O''Connor', 'L''attore Kevin J. O''Connor, che interpreta il finto fratello Henry Brands, rimase ferito durante la scena in cui Daniel tenta di annegarlo; la colluttazione fu così intensa che l''attore subì contusioni reali che richiesero cure mediche sul set.', 'Commento audio e interviste al cast tecnico', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:50:47.350887+00:00'),
('164be501-326b-423b-bff7-5a8634ac2859', 304, 'Segreti di produzione', 'La scelta musicale d''archivio di Sidney Bechet', 'Woody Allen ha fortemente voluto inserire i brani del sassofonista jazz Sidney Bechet come colonna sonora portante del film, attingendo direttamente alla sua collezione personale di dischi in vinile 78 giri registrati negli anni ''20 e ''30.', 'Note di copertina della colonna sonora ufficiale Sony Masterworks', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:49:57.983447+00:00'),
('605cec78-cfa6-400f-853b-0192d94c93c2', 304, 'Segreti di produzione', 'La finta libreria antiquaria di Shakespeare and Company', 'Sebbene la storica libreria parigina ''Shakespeare and Company'' esista realmente nei pressi della Senna, gli interni e le sequenze con i librai furono interamente ricostcoliti in un teatro di posa per consentire alla macchina da presa di muoversi agilmente nei corridoi stretti senza disturbare i clienti reali.', 'Reportage dal set della rivista American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:49:57.983447+00:00'),
('c9122562-71ae-4539-8e4f-cf1b1701782a', 313, 'Curiosità & Retroscena', 'Il rifiuto del Vaticano', 'Il Vaticano negò categoricamente alla produzione l''autorizzazione a girare all''interno della Città del Vaticano e nelle chiese romane, costringendo la troupe a ricostruire gran parte degli ambienti nei teatri di posa dei Sony Studios di Culver City.', 'Note di produzione ufficiali della Sony Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:50:29.264441+00:00'),
('359efb81-76c8-4089-b104-92b86360588a', 313, 'Casting & Scelte', 'Naomi Watts in lizza per il ruolo di Vittoria Vetra', 'Prima che la parte venisse assegnata all''attrice israeliana Ayelet Zurer, il nome di Naomi Watts fu seriamente preso in considerazione dai produttori per interpretare la scienziata del CERN Vittoria Vetra.', 'Hollywood Reporter Casting News', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:50:29.264441+00:00'),
('22585cd5-f10d-4565-8a92-7de36c22c1d3', 313, 'Segreti di produzione', 'L''uso della CGI per Piazza San Pietro', 'Poiché non fu possibile ottenere i permessi per girare in modo estensivo nella vera Piazza San Pietro, la piazza e l''accesso alla basilica furono quasi interamente ricreati in computer grafica dai tecnici della Industrial Light & Magic.', 'The Making of Angels & Demons - Special Features DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:50:29.264441+00:00'),
('0fb724bf-abfc-4f43-b6ce-c044558d26bf', 313, 'Effetti speciali & Trucco', 'Il trucco delle ustioni per il Cardinale Ebner', 'Per la scena in cui il cardinale Ebner viene trovato morto con i polmoni bruciati dalla terra, i truccatori guidati da Mark Coulier hanno impiegato protesi in silicone avanzate e polveri speciali per simulare l''effetto soffocamento.', 'Intervista al reparto trucco in Cinefex Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:50:29.264441+00:00'),
('7d767e76-88ef-4bd4-942d-3300710efd92', 313, 'Citazioni & Easter Egg', 'Il cameo del regista nei panni di un cardinale', 'Ron Howard ha inserito un piccolo cameo visivo per se stesso: appare brevemente tra la folla di cardinali e fedeli durante le sequenze girate in esterni digitali a Roma.', 'Audio commento del regista nel Blu-ray del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:50:29.264441+00:00'),
('4c1f2aed-e55f-4799-9e80-b81e49e58673', 313, 'Segreti di produzione', 'La polvere da sparo storica utilizzata per l''illuminazione', 'Per la scena della camera di decompressione al CERN e le sequenze con l''antimateria, gli scenografi hanno utilizzato veri strumenti di laboratorio dismessi forniti da università europee per garantire l''autenticità visiva.', 'Documentario ufficiale ''CERN: The Science Behind the Fiction''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:50:29.264441+00:00'),
('d74c1e21-7932-4821-9fbd-0254f1bc1ada', 330, 'Casting & Scelte', 'La sostituzione last-minute di Harrison Ford', 'Nelle primissime fasi di sviluppo, quando il progetto era concepito come un film d''azione più tradizionale per la New Line Cinema, Harrison Ford fu considerato per il ruolo principale di Tom Stall prima che la produzione virasse verso un budget inferiore e un tono autoriale, portando all''ingaggio di Viggo Mortensen.', 'Note di produzione e interviste storiche al sceneggiatore Josh Olson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:51:20.803428+00:00'),
('2daecd0b-b98e-415a-8314-646cdb553a62', 330, 'Casting & Scelte', 'La scelta del look e dei baffi di Viggo Mortensen', 'Per marcare la netta distinzione tra la mitezza della vita di provincia di Tom Stall e il suo passato violento come gangster di Filadelfia (Joey Cusack), fu proprio Viggo Mortensen a suggerire l''uso dei baffi e un taglio di capelli specifico, ispirandosi alle vecchie fotografie di famiglia americane degli anni ''50.', 'Commento audio del regista David Cronenberg nel DVD/Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:51:20.803428+00:00'),
('9efff39f-7902-4410-8bea-4f539008bc2d', 8, 'Aneddoti dal set', 'L''improvvisazione nella scena della confessione', 'Durante la drammatica sequenza in cui Michael Corleone confessa i suoi peccati al futuro Papa Giovanni Paolo I (Cardinale Lamberto), Al Pacino richiese diverse riprese per calarsi emotivamente nel dolore del personaggio, arrivando a inserire pause e sussurri non previsti strettamente nel copione originale di Mario Puzo e Coppola.', 'Commento audio del regista all''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:35:53.40309+00:00'),
('5192b564-2022-4c21-ae17-539cc924e283', 8, 'Segreti di produzione', 'La riproduzione del Teatro Massimo di Palermo', 'Le imponenti sequenze finali ambientate durante la rappresentazione della Cavalleria Rusticana richiesero settimane di pianificazione logistica e permessi speciali per girare all''interno del vero Teatro Massimo di Palermo, coinvolgendone centinaia di comparse locali e maestranze teatrali.', 'Archivi storici della produzione e documentario ''The Godfather Family: A Look Inside''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:35:53.40309+00:00'),
('9741a975-9ad3-4245-85bb-2babefaf5a91', 12, 'Casting & Scelte', 'Il ritorno di Karen Allen e la telefonata di Spielberg', 'Karen Allen ha scoperto che il suo personaggio di Marion Ravenwood sarebbe tornato nel franchise grazie a una telefonata diretta del regista Steven Spielberg, avvenuta nel 2007, nella quale le chiese semplicemente se avesse ancora il vestito bianco del primo film.', 'Intervista ufficiale di Karen Allen per il Press Kit del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:36:04.192837+00:00'),
('240373bf-4bec-4a3b-be93-0938bcfbfd65', 12, 'Casting & Scelte', 'Il rifiuto di Sean Connery e la riscrittura del personaggio', 'Sean Connery fu fortemente corteggiato per riprendere il ruolo del Professor Henry Jones Sr., ma rifiutò categoricamente dichiarando che la pensione era troppo divertente; il suo rifiuto costrinse gli sceneggiatori a inserire la morte del personaggio nel canone della storia.', 'Dichiarazione ufficiale di Sean Connery rilasciata a The Scotsman nel 2007', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:36:04.192837+00:00'),
('31a97ab6-d7b2-48fd-81b6-f3431d415dd4', 12, 'Aneddoti dal set', 'La cicatrice di Harrison Ford e l''autenticità delle acrobazie', 'All''età di 65 anni, Harrison Ford ha eseguito personalmente la stragrande maggioranza delle sue scene d''azione e dei combattimenti, dimostrando di essere ancora in grado di indossare l''iconico costume e di adattare la sua celebre cicatrice al volto invecchiato dell''archeologo.', 'Documentario The Production Diary di Indiana Jones 4', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:36:04.192837+00:00'),
('c85db092-a1e7-4ce1-9777-fc84d4cb24ac', 306, 'Segreti di produzione', 'L''assenza quasi totale di CGI', 'Nonostante la natura surreale della trama, il film contiene meno di 500 inquadrature con effetti digitali (CGI), un numero estremamente basso per un blockbuster contemporaneo del valore di 160 milioni di dollari, privilegiando effetti pratici sul set.', 'Making-of ufficiale e documentario sul backstage', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:50:06.35404+00:00'),
('3158719e-e9bd-477c-a5d3-78fc51836e0a', 306, 'Citazioni & Easter Egg', 'Il brano di Edith Piaf come ancora temporale', 'La celebre canzone ''Non, je ne regrette rien'' di Édith Piaf funge da segnale acustico per il risincronizzatore dei sogni. La durata del brano originale, pari a 2 minuti e 28 secondi, ha ispirato direttamente la durata delle diverse fasi di discesa nei sogni ideate da Hans Zimmer per la colonna sonora.', 'Commento audio del regista nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:50:06.35404+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('c33a31a0-245e-4aa5-87b5-ebf0797e6d2a', 306, 'Aneddoti dal set', 'La neve finta di Calgary e i disordini', 'Durante le riprese della sequenza della fortezza innevata a Calgary, in Canada, la produzione ha utilizzato tonnellate di plastica e cellulosa per simulare la neve, causando curiosità e lievi disagi alla viabilità locale che richiesero comunicati speciali alla cittadinanza.', 'Reportage dal set di Variety e cronache locali canadesi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:50:06.35404+00:00'),
('db045a95-1a09-4a45-85fc-16836c995b3a', 306, 'Citazioni & Easter Egg', 'Il blocco numerico recurrente dell''hotel', 'Il numero della camera d''albergo in cui Cobb e Mal soggiornano spesso all''interno del sogno è il 528. Lo stesso numero torna ciclicamente in altri dettagli visivi della narrazione come omaggio alla struttura tonale della colonna sonora di Hans Zimmer.', 'Analisi visive ufficiali e DVD Easter Eggs', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:50:06.35404+00:00'),
('a6a44034-00cb-4f89-a830-b4b13af5e752', 306, 'Casting & Scelte', 'La scelta iniziale per il ruolo di Mal', 'Prima che Marion Cotillard venisse definitivamente ingaggiata per il ruolo della tormentata moglie Mal, la produzione aveva valutato diverse attrici di primo piano, tra cui Evan Rachel Wood, la quale rifiutò la parte per altri impegni cinematografici.', 'Notizie di casting di Deadline Hollywood', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:50:06.35404+00:00'),
('4939beb4-608a-4725-9a2c-eba8f823cece', 321, 'Casting & Scelte', 'La scelta di Zoë Bell come protagonista', 'Quentin Tarantino decise di scrivere il ruolo principale della seconda metà del film specificamente per Zoë Bell, dopo aver lavorato con lei come sua controfigura in ''Kill Bill''. Il regista rimase così colpito dal suo talento e dalla sua personalità sul set da volerla come vera e propria attrice protagonista.', 'Audio commento del regista e making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:51:00.869784+00:00'),
('901259ab-2a69-44a2-a711-9c1bf71e852f', 321, 'Casting & Scelte', 'Il ruolo originario di Mickey Rourke', 'Prima che la parte dello sceriffo McGraw venisse affidata a Michael Parks, Tarantino aveva offerto il ruolo a Mickey Rourke. L''attore dovette tuttavia rifiutare l''offerta a causa di conflitti di programmazione con le riprese di un altro film.', 'Note di produzione e interviste ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:51:00.869784+00:00'),
('ef36a66b-06eb-4395-8b30-cac1d198989c', 321, 'Segreti di produzione', 'L''uso di una vera auto da stunt', 'La Chevy Nova guidata da Kurt Russell nel film era una vera automobile da stunt modificata con un roll-bar interno saldato alla struttura per proteggere l''attore durante le spericolate sequenze d''azione, sebbene Kurt Russell abbia eseguito personalmente molte delle manovre.', 'Documentario sul dietro le quinte ''The Hot Rod of Death''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:51:00.869784+00:00'),
('d72c1827-6499-4a8e-9c9f-0c898ab6dabe', 321, 'Effetti speciali & Trucco', 'La mancanza di CGI nelle scene d''impatto', 'Coerentemente con l''estetica dei film grindhouse degli anni ''70, Tarantino e il coordinatore degli stunt Jeff Dashnaw scelsero di limitare al minimo l''uso della computer grafica, affidandosi a veri scontri meccanici, cavi e classici effetti fisici dal vivo.', 'Special report sugli stunt di Grindhouse', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:51:00.869784+00:00'),
('b468e6bd-af22-4a7e-8648-618b8b63b930', 321, 'Citazioni & Easter Egg', 'Omaggio a Vanishing Point', 'La Dodge Challenger bianca guidata dalle ragazze nella seconda parte del film è un chiaro omaggio alla celebre vettura protagonista del cult movie action del 1971 ''Punto zero'' (Vanishing Point), di cui riprende modello e spirito ribelle.', 'Analisi visiva e note della troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:51:00.869784+00:00'),
('da4ed265-f08e-40ef-914d-0a66954eb8a4', 321, 'Aneddoti dal set', 'L''infortunio sul cofano', 'Durante la celebre sequenza in cui Zoë Bell si trova legata e aggrappata al cofano della Dodge Challenger in movimento (la manovra nota come ''Ship''s Mast''), la stuntwoman rischiò realmente di cadere sull''asfalto a velocità sostenuta a causa di una brusca frenata non preventivata perfettamente.', 'Intervista retrospettiva a Zoë Bell', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:51:00.869784+00:00'),
('644d2b21-9c77-4a96-be85-002e967f48c7', 321, 'Citazioni & Easter Egg', 'Il cameo di Eli Roth e i registi', 'Nel locale Texas Chili Parlor compaiono in brevi camei non accreditati diversi amici e collaboratori di Tarantino, tra cui il regista Eli Roth, il produttore Bob Weinstein e lo stesso Quentin Tarantino nel ruolo di un avventore barbuto.', 'Crediti del film e trivia ufficiali IMDb', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:51:00.869784+00:00'),
('cbe98226-dd60-436d-b5a7-19e479ce923f', 10, 'Aneddoti dal set', 'L''infortunio alla schiena di Harrison Ford', 'Durante le riprese della celebre lotta nella camera da letto di Pankot contro la guardia thugee, Harrison Ford subì una grave ernia discale. Dovette essere operato d''urgenza a Los Angeles e la produzione proseguì temporaneamente utilizzando la sua controfigura, Vic Armstrong, ripreso di spalle o nell''ombra.', 'Commento audio del regista Steven Spielberg', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:35:57.707658+00:00'),
('d702f5d0-9b58-4784-8547-20b3092374b6', 10, 'Citazioni & Easter Egg', 'La genesi del nome del cane', 'Il nome del piccolo compagno di avventure di Indy, Short Round (interpretato da Ke Huy Quan), deriva direttamente dal nome del cane di George Lucas, un Alaskan Malamute che aveva ispirato anche il personaggio di Chewbecca nella saga di Star Wars.', 'Note di produzione e interviste d''archivio a George Lucas', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:35:57.707658+00:00'),
('1f0a3428-23ca-43f5-8bcf-de246d67b38f', 10, 'Casting & Scelte', 'Sharon Stone considerata per Willie Scott', 'Prima che Kate Capshaw ottenesse la parte della cantante di nightclub Willie Scott, Steven Spielberg prese seriamente in considerazione Sharon Stone per il ruolo, ma alla fine la scelta ricadde sulla Capshaw su insistenza del produttore George Lucas.', 'Archivi di casting della Lucasfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:35:57.707658+00:00'),
('1786b28b-f04f-438e-b5c6-eddfa1229c18', 10, 'Citazioni & Easter Egg', 'Il cameo di George Lucas e Dan Aykroyd', 'Nella sequenza iniziale all''aeroporto di Shanghai, nei panni dei due sfortunati passeggeri che aiutano Indy a salire sull''aereo cargo ci sono in realtà il creatore della saga George Lucas e l''attore Dan Aykroyd, vestiti da turisti britannici.', 'Libro ''The Complete Making of Indiana Jones''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:35:57.707658+00:00'),
('e05d3188-8038-4cce-aacb-65875d88be8f', 321, 'Segreti di produzione', 'Il cambio di pellicola fittizio', 'Per simulare la proiezione di una pellicola rovinata e consunta tipica dei cinema di seconda visione, il montatore Sally Menke inserì transizioni e tagli netti con bruciature di sigaretta e graffi meccanici sulla pellicola, ricreati digitalmente e fisicamente.', 'Note di montaggio ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:51:00.869784+00:00'),
('ae30e88f-8ba1-4d52-a05c-33efebd6bdbb', 311, 'Casting & Scelte', 'La scelta di Jordan Nagai per la voce di Russell', 'Il regista Pete Docter ha visionato oltre 400 bambini prima di scegliere il giovanissimo Jordan Nagai, che all''epoca aveva solo otto anni. Nagai fu scelto non per le sue doti di attore professionista, ma perché durante i provini continuava a correre e a non stare fermo, incarnando perfettamente l''iperattività e la parlantina irrefrenabile di Russell.', 'Commento audio del regista nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:50:20.852288+00:00'),
('4a8e6507-9403-4ebf-8c03-a4ab601986a1', 311, 'Citazioni & Easter Egg', 'Il tributo al Luxo Ball e al Pizza Planet Truck', 'Come da tradizione Pixar, anche in ''Up'' compaiono celebri Easter Egg interni agli studi: il famoso Luxo Ball (la palla gialla con la stella blu) appare nella stanza da letto di una bambina mentre la casa si alza in volo, mentre il furgone di Pizza Planet fa una breve apparizione in una scena cittadina.', 'Documentario ''The Many Endings of Yertle the Turtle & Other Stories'' e guide ufficiali Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:50:20.852288+00:00'),
('3595613e-6938-4c71-acbd-fdc52fbcbc1f', 311, 'Casting & Scelte', 'L''omaggio a John Ratzenberger in ogni film Pixar', 'L''attore John Ratzenberger, considerato un vero e proprio portafortuna per la Pixar, ha doppiato il personaggio minore di Tom il mastino edile. La sua presenza in ''Up'' mantiene intatta la tradizione che lo ha visto recitare in ogni singolo lungometraggio d''animazione dello studio da ''Toy Story'' in poi.', 'Note di produzione ufficiali Pixar Animation Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:50:20.852288+00:00'),
('f3566e70-53b7-4c33-aae9-eae7f35205a6', 311, 'Citazioni & Easter Egg', 'Il codice A113 ricorrente', 'Il misterioso codice alfanumerico A113, che fa riferimento all''aula del California Institute of Arts frequentata da molti animatori storici tra cui John Lasseter e Brad Bird, compare chiaramente sul cartello del tribunale dove Carl viene convocato prima dell''ordine di eviction.', 'Analisi ufficiale dei dettagli nascosti nei film Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:50:20.852288+00:00'),
('49d3208a-3825-41c7-8a20-e7156ddeb9fb', 311, 'Segreti di produzione', 'L''ispirazione per le forme geometriche dei protagonisti', 'I due protagonisti principali, Carl e Russell, sono stati progettati basandosi su forme geometriche opposte e complementari volute dal production designer Ralph Eggleston: Carl è interamente costruito su linee squadrate e rettangolari per simboleggiare la sua rigidità e testardaggine, mentre Russell è composto da forme circolari e morbide che ne riflettono la natura socievole e rotondetta.', 'Libro d''arte ufficiale ''The Art of Up''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:50:20.852288+00:00'),
('60523e95-3acb-49b9-91f3-e6ed10ff9d1e', 319, 'Citazioni & Easter Egg', 'Il cameo di Peter Jackson', 'Il celebre regista neozelandese Peter Jackson fa una breve apparizione non accreditata nei panni di Babbo Natale che accoltella la mano di Nicholas Angel nella sequenza iniziale ambientata a Londra. La partecipazione è nata grazie all''amicizia con Edgar Wright, cementata anche dal successivo coinvolgimento reciproco in altri progetti.', 'Commento audio del DVD / Making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:50:51.415259+00:00'),
('5db4eda7-1f06-4ac1-a390-17a3d0b287f4', 319, 'Casting & Scelte', 'Cate Blanchett nei panni della scienziata della buoncostume', 'L''attrice premio Oscar Cate Blanchett interpreta Janine, la poliziotta della scientifica pesantemente travestita e mascherata che indossa una tuta protettiva all''inizio del film. Il suo volto è quasi interamente coperto e la sua voce è alterata, rendendo la sua presenza un cameo celebre svelato solo nei titoli di coda.', 'Crediti del film e interviste promozionali di Simon Pegg', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:50:51.415259+00:00'),
('af45d2f6-89fd-44df-9380-d5371712f98d', 319, 'Segreti di produzione', 'Le vere riprese nella città natale di Edgar Wright', 'Le riprese esterne del villaggio fittizio di Sandford sono state girate principalmente a Wells, nel Somerset, che è la vera città natale del regista Edgar Wright. La produzione ha scelto questa location proprio per sfruttare la profonda conoscenza dei luoghi e delle caratteristiche architettoniche ed ecclesiastiche da parte del regista.', 'Note di produzione ufficiali Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:50:51.415259+00:00'),
('f51384b6-adf2-4f96-82a7-145690302b3d', 319, 'Curiosità & Retroscena', 'La consulenza di Quentin Tarantino per il montaggio', 'Il regista Quentin Tarantino ha visionato un primo montaggio di Hot Fuzz e ha suggerito a Edgar Wright di accorciare leggermente alcune sequenze per mantenere un ritmo ancora più serrato, paragonando lo stile del film ai grandi classici del poliziottesco anni ''70. Wright ha accolto parte dei consigli per ottimizzare il flusso narrativo.', 'Interviste di Edgar Wright per la promozione home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:50:51.415259+00:00'),
('2e517af8-58da-4030-b02b-89440d9be1fc', 319, 'Citazioni & Easter Egg', 'I camei dei registi all''interno della stazione di polizia', 'I registi Garth Jennings e Joe Cornish appaiono rispettivamente nei panni del sostituto e di altri personaggi minori all''interno delle sequenze corali della stazione di polizia. La loro presenza fa parte di una rete di amicizie e collaborazioni tra cineasti britannici indipendenti dell''epoca.', 'Speciali e contenuti extra del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:50:51.415259+00:00'),
('16750f68-3345-48d8-b5c9-9323190d8ae5', 337, 'Aneddoti dal set', 'La folgorazione di Jim Caviezel sul set', 'Durante le riprese del Discorso della Montagna a Matera, l''attore Jim Caviezel fu accidentalmente colpito da un fulmine, così come l''aiuto regista Jan Michelini. Nonostante l''incidente scioccante, nessuno dei due riportò gravi lesioni, sebbene la notizia fece il giro del mondo alimentando il misticismo attorno alla produzione.', 'Intervista ufficiale di Jim Caviezel a ABC News', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:51:42.433094+00:00'),
('cd18c77d-1640-4ec5-9240-f8b76f5e351f', 10, 'Segreti di produzione', 'Il ponte di corda in miniatura', 'Il drammatico climax sul ponte di corda sospeso sopra il fiume infestato da coccodrilli fu realizzato in gran parte utilizzando modelli in scala ridotta ed effetti ottici di marcatura, poiché costruire un ponte a grandezza naturale in grado di reggere le scene di lotta era logisticamente impossibile.', 'Documentario sugli effetti speciali della Industrial Light & Magic', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:35:57.707658+00:00'),
('46cc7890-b342-4b7d-ba94-bd530c3a4103', 10, 'Curiosità & Retroscena', 'La reazione di Spielberg al tono del film', 'Steven Spielberg ha più volte ammesso pubblicamente di considerare ''Il tempio maledetto'' il capitolo meno riuscito della trilogia originale, definendolo eccessivamente cupo, violento e privo dell''ironia che caratterizzava il primo e il terzo film.', 'Intervista retrospettiva a Steven Spielberg per Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:35:57.707658+00:00'),
('1a190c24-440f-4e97-b773-c3e2871d0057', 137, 'Segreti di produzione', 'La modifica segreta delle automobili', 'Per permettere agli attori di trovarsi nell''abitacolo durante gli inseguimenti senza rischiare la vita, i meccanici del set hanno inserito una seconda postazione di guida nascosta sul tetto di alcune vetture, controllata da stuntman mentre gli attori recitavano all''interno.', 'Intervista al coordinatore degli stunt Simon Crane', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:05:23.602361+00:00'),
('5800681c-be72-40bc-abd5-6bfa2ab9ee33', 320, 'Curiosità & Retroscena', 'La genesi del titolo e il significato filosofico', 'Il titolo ''Apocalypto'' deriva dal verbo greco antico che significa ''rivelare'' o ''scoprire''. Mel Gibson ha spesso spiegato nelle interviste promozionali che il titolo non si riferiva a una fine catastrofica del mondo, ma alla rivelazione di una civiltà che stava già consumando se stessa dall''interno prima dell''arrivo degli spagnoli.', 'Conferenza stampa ufficiale al Festival Internazionale del Cinema di Roma 2006', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:50:55.755293+00:00'),
('8c7e12ca-65aa-45db-a28c-d1c8fbf84c9b', 320, 'Casting & Scelte', 'L''uso della lingua yucateca antica', 'Poiché nessuno dei membri del cast principale parlava fluentemente la variante antica del Maya yucateco parlato nel film, gli attori hanno dovuto memorizzare interamente i loro dialoghi foneticamente, lavorando ogni giorno sul set con coach linguistici dedicati per mantenere la cadenza corretta.', 'Audio commentario del regista Mel Gibson e dello sceneggiatore Farhad Safinia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:50:55.755293+00:00'),
('82ab0458-ae0e-4e4a-baac-311788cd406b', 338, 'Citazioni & Easter Egg', 'Il cameo del vero Frank Abagnale Jr.', 'Il vero Frank Abagnale Jr., la cui vita ha ispirato il libro e il film, fa un cameo nel ruolo di un poliziotto francese che arresta il personaggio di Leonardo DiCaprio verso la fine della pellicola.', 'Contenuti speciali e commento audio del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:51:45.813824+00:00'),
('398582a7-a43f-4967-ae9b-1b590193fbda', 338, 'Casting & Scelte', 'La scelta iniziale di David Fincher e Gore Verbinski', 'Prima che Steven Spielberg decidesse di dirigere personalmente il film (dopo aver inizialmente pensato di farlo solo da produttore), la regia era stata affidata a David Fincher e successivamente a Gore Verbinski.', 'Note di produzione ufficiali DreamWorks', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:51:45.813824+00:00'),
('e05c81a6-ab3c-4b4e-85fe-014a960b93f9', 338, 'Casting & Scelte', 'Tom Hanks e l''ispirazione per Carl Hanratty', 'Per prepararsi al ruolo dell''agente dell''FBI Carl Hanratty, Tom Hanks ha studiato approfonditamente la figura dei veri agenti federali dell''epoca e ha basato alcuni tic del personaggio su un agente incontrato durante le ricerche.', 'Press kit ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:51:45.813824+00:00'),
('df09bf9f-9c69-4576-85ad-127b33e1a4d2', 338, 'Curiosità & Retroscena', 'L''accuratezza dei controlli aeroportuali ricostruiti', 'Molti degli aeroporti presenti nel film non erano veri scali moderni, ma hangar ed edifici storici riconvertiti, poiché i rigidi controlli di sicurezza post-2001 rendevano impossibile girare nei veri aeroporti commerciali con le scenografie d''epoca.', 'Making-of ufficiale ''Catch Me If You Can: Behind the Camera''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:51:45.813824+00:00'),
('70d99619-65f9-498e-a5f6-d4c143f94693', 346, 'Aneddoti dal set', 'L''infortunio reale di Brad Pitt', 'Durante le riprese della sequenza dell''inseguimento sotto la pioggia per il peccato dell''Ira, Brad Pitt scivolò accidentalmente fracassandosi il braccio contro il parabrezza di un''auto di scena. La ferita fu così grave da richiedere un intervento chirurgico e la produzione dovette riorganizzare il piano di lavorazione integrando il gesso dell''attore direttamente nella sceneggiatura.', 'Commento audio del regista David Fincher e making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:52:07.969091+00:00'),
('ed8e98d7-53b8-4e95-8552-98c68e3d5832', 346, 'Casting & Scelte', 'La insistente opposizione allo script originale', 'New Line Cinema cercò ripetutamente di costringere David Fincher e Brad Pitt a modificare il finale con la testa nella scatola, proponendo finali alternativi meno cupi in cui il personaggio di Pitt non uccideva John Doe o in cui a morire fosse Somerset. Pitt accettò di firmare per il film solo a condizione che il finale originale ideato da Andrew Kevin Walker rimanesse assolutamente intatto.', 'Interviste retrospettive a Brad Pitt e David Fincher su Premiere Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:52:07.969091+00:00'),
('9bc06261-7af4-4282-87d5-7763d161eab0', 346, 'Effetti speciali & Trucco', 'Il make-up prostetico estremo per la Gola', 'Per la raccapricciante scena della vittima costretta a mangiare fino a scoppiare per il peccato della Gola, l''attore subì lunghe sessioni di trucco prostetico avanzato realizzate dal team di Rob Bottin. Venne costruito un corpo finto e imbottito collegato a complessi sistemi meccanici per simulare lo stomaco dilaniato e le lesioni interne.', 'Documentario sugli effetti speciali nel cofanetto Blu-ray speciale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:52:07.969091+00:00'),
('1351a2bd-a3e7-496e-8e07-b8a42050b958', 346, 'Casting & Scelte', 'La scelta iniziale di Sylvester Stallone', 'Prima che Brad Pitt fosse scelto per il ruolo del detective David Mills, la sceneggiatura fu proposta a Sylvester Stallone, il quale rifiutò categoricamente la parte perché giudicò la storia troppo cupa, pessimista e violenta per il suo pubblico.', 'Archivi di produzione New Line Cinema e biografie ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:52:07.969091+00:00'),
('a318a690-021a-4fc9-8b22-8a13823e623d', 346, 'Segreti di produzione', 'Il libro di appunti di John Doe', 'I migliaia di pagine di diari scritti a mano e rilegati rinvenuti nell''appartamento di John Doe non erano semplici oggetti di scena stampati, ma furono compilati a mano da un team di grafici e artisti per mesi, riempiendoli di ossessioni religiose, disegni inquietanti e testi filosofici.', 'Note di produzione e art department featurette', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:52:07.969091+00:00'),
('2bd40afc-26d1-419b-9f64-5b2360bc580a', 12, 'Citazioni & Easter Egg', 'Il tributo fotografico a Denholm Elliott', 'Per ricordare il defunto attore Denholm Elliott, che interpretava il collega Marcus Brody nei primi film, la produzione ha inserito nel campus universitario una grande statua in bronzo e una fotografia incorniciata del personaggio all''interno dell''ufficio di Indy.', 'Analisi visiva e note di scenografia del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:36:04.192837+00:00'),
('ebaed5fd-cb0f-423b-abe2-67717c4e5a0d', 12, 'Effetti speciali & Trucco', 'L''assenza deliberata della grafica digitale per i serpenti', 'Fedele alla tradizione della trilogia originale, Steven Spielberg ha preteso l''utilizzo di serpenti veri sul set durante la sequenza delle sabbie mobili in Amazzonia, ricorrendo alla CGI solo per un numero limitato di rettili digitali per motivi di sicurezza.', 'Specialefilm Making of The Kingdom of the Crystal Skull', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:36:04.192837+00:00'),
('8ac56b4e-51fd-48c3-a8cc-dcb4f50f02d7', 12, 'Citazioni & Easter Egg', 'Il cameo della figlia di Steven Spielberg', 'Destry Allyn Spielberg, la figlia del regista, appare brevemente in un cameo non accreditato all''interno della pellicola, interpretando una giovane studentessa nella scena in cui la moto di Mutt attraversa il campus universitario.', 'Credits di produzione e trivia ufficiale di IMDb', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:36:04.192837+00:00'),
('e5cb9a2a-93dd-45a1-a153-118980c0f540', 12, 'Segreti di produzione', 'La scelta rigorosa della pellicola analogica', 'Nonostante l''avvento massiccio del digitale nel 2008, il direttore della fotografia Janusz Kamiński e Steven Spielberg hanno girato l''intero film su pellicola 35mm utilizzando cineprese Panavision, replicando meticolosamente l''illuminazione in stile chiaroscuro dei film degli anni Ottanta.', 'American Cinematographer Magazine, giugno 2008', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:36:04.192837+00:00'),
('4aa94cc4-fa5c-4dd3-8aca-b5cdc1f1eff7', 322, 'Segreti di produzione', 'I costumi d''epoca di Deborah Lynn Scott', 'La costumista premio Oscar Deborah Lynn Scott ha progettato abiti rigorosamente aderenti alla moda londinese della fine del XIX secolo, differenziando nettamente lo stile borghese e raffinato di Angier da quello più bohémien e trasandato di Borden.', 'Note di produzione e press kit ufficiale Warner Bros', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:51:04.761677+00:00'),
('42202aa6-e107-4ead-bf35-c4242e4233a3', 322, 'Curiosità & Retroscena', 'Gli studi sui veri diari segreti nel romanzo', 'La struttura narrativa basata sui diari cifrati che i due protagonisti cercano di rubare e decifrare è un chiaro omaggio alle vere pratiche di spionaggio industriale e ai diari dei maghi del diciannovesimo secolo descritti nel libro di Christopher Priest.', 'Analisi letteraria e interviste allo sceneggiatore Jonathan Nolan', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:51:04.761677+00:00'),
('c3842957-7122-4869-9913-34b841d02803', 335, 'Casting & Scelte', 'La scelta del romanzo breve di Stephen King', 'Il film è tratto dalla novella ''Secret Window, Secret Garden'' pubblicata nella raccolta ''Quattro dopo mezzanotte'' di Stephen King del 1990. David Koepp decise di adattare la storia focalizzandosi sulla discesa nella follia dello scrittore, mantenendo intatta la struttura claustrofobica del testo originale.', 'Note di produzione ufficiali Columbia Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:51:33.726723+00:00'),
('e6745a1b-88cf-49f1-a8a0-6b1215887dbc', 335, 'Aneddoti dal set', 'Il cappello da pescatore di Johnny Depp', 'L''insolito e trasandato cappello da pescatore indossato da Johnny Depp nel film è stato scelto personalmente dall''attore per riflettere lo stato di isolamento e trascuratezza del personaggio di Mort Rainey. Depp volle che il suo look apparisse volutamente dimesso e fuori moda per evidenziare la depressione del protagonista.', 'Commento audio del regista David Koepp nel DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:51:33.726723+00:00'),
('41eb443c-d6b2-4e7b-916d-75c62662674e', 335, 'Casting & Scelte', 'La preferenza di David Koepp per la sceneggiatura', 'Prima di dirigere il film, David Koepp era principalmente noto come sceneggiatore di grande successo di blockbuster come ''Jurassic Park'' e ''Mission: Impossible''. Scelse di dirigere personalmente ''Secret Window'' perché amava profondamente il materiale originale e voleva mantenere il controllo totale sulle atmosfere psicologiche.', 'Intervista a David Koepp per Cinefex', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:51:33.726723+00:00'),
('7ef0c7e4-3e41-480c-89af-d0f04618485e', 335, 'Segreti di produzione', 'La scelta del travestimento di John Turturro', 'John Turturro ha studiato la camminata e la postura del suo personaggio, John Shooter, ispirandosi ai vecchi film noir degli anni ''40 e ai thriller rurali. Il suo look con il cappello a tesa larga e la salopette serve a rimarcare l''aria minacciosa e anacronistica del misterioso scrittore del Mississippi.', 'Making-of ufficiale ''From Book to Screen''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:51:33.726723+00:00'),
('9848d67d-c39a-42c8-b5d1-e749cf6ff259', 335, 'Citazioni & Easter Egg', 'Il nome della marca di mais', 'Nel film, Mort mangia ripetutamente i Doritos e cereali specifici, ma la confezione di mais dolce utilizzata nelle scene della cucina presenta etichette studiate appositamente dalla scenografia per evitare problemi di copyright, pur mantenendo un''estetica rétro anni ''90.', 'Articolo di produzione su American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:51:33.726723+00:00'),
('0213ddb5-f880-46c4-b167-41d1e4e89770', 353, 'Aneddoti dal set', 'La pausa di un anno per la perdita di peso', 'Le riprese del film furono interrotte per circa un anno a metà produzione per permettere a Tom Hanks di perdere 25 chili e farsi crescere capelli e barba lunghi, così da rendere credibile la trasformazione fisica del naufrago. Nello stesso intervallo di tempo, il regista Robert Zemeckis diresse un altro intero lungometraggio, ''Le verità nascoste'' (What Lies Beneath), con Harrison Ford e Michelle Pfeiffer.', 'Commento audio del regista Robert Zemeckis nell''edizione DVD speciale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:52:23.624263+00:00'),
('630705ae-ecd8-466c-9b47-a44ae581f31c', 353, 'Aneddoti dal set', 'L''infortunio sul set e il rischio di setticemia', 'Durante la lavorazione sulle isole Fiji, Tom Hanks si ferì a una gamba provocandosi un taglio che si infettò gravemente dopo pochi giorni. L''infezione costrinse la produzione a sospendere le riprese per tre giorni per consentire il ricovero dell''attore in ospedale e una terapia antibiotica d''urgenza, rischiando persino la setticemia.', 'Interviste promozionali ufficiali di Tom Hanks per l''uscita del film nel 2000', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:52:23.624263+00:00'),
('1f1c4328-5b88-44c7-96d5-c5ca67a9552a', 353, 'Segreti di produzione', 'La nascita del pallone Wilson', 'Il celebre compagno d''avventure di Chuck, il pallone da volley battezzato Wilson, nacque da un''idea dello sceneggiatore William Broyles Jr., il quale decise di isolarsi volontariamente per una settimana su un''isola disabitata per fare esperienza diretta della solitudine e capire come un naufrago avrebbe potuto mantenere la propria sanità mentale.', 'Documentario ''The Making of Cast Away'' presente nei contenuti speciali home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:52:23.624263+00:00'),
('eb4fddb2-0ec2-46eb-aad3-67f1e4e68abc', 13, 'Casting & Scelte', 'L''assenza di Steven Spielberg alla regia', 'Per la prima volta nella storia del franchise, Steven Spielberg ha deciso di non sedersi sulla sedia del regista, rimanendo comunque a bordo come produttore esecutivo. Spielberg ha ceduto volontariamente il timone a James Mangold per offrire una prospettiva registica fresca e un punto di vista generazionale differente sulla figura creata nel 1981.', 'Dichiarazioni ufficiali di Steven Spielberg e James Mangold al CinemaCon', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:36:06.349743+00:00'),
('162d7df3-69cf-4e88-bcce-f80ff0f980c8', 13, 'Segreti di produzione', 'La ricostruzione fisica della Vespa del 1969', 'Durante la sequenza dell''inseguimento a Tangeri, la troupe ha dovuto reperire e restaurare diversi modelli originali di scooter d''epoca per garantire l''autenticità storica del 1969. Alcuni di questi veicoli sono stati pesantemente modificati dai reparti speciali per montare cineprese nascoste e permettere agli stuntman di eseguire le acrobazie in sicurezza tra i vicoli marocchini.', 'Note di produzione e reparto scenografia del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:36:06.349743+00:00'),
('9ec25709-5f85-4a95-a6df-2d8e4e5bcce8', 47, 'Casting & Scelte', 'Il provino di Henry Cavill scartato per l''età', 'Henry Cavill era il principale concorrente di Daniel Craig per il ruolo di James Bond, ma il regista Martin Campbell lo scartò perché all''epoca aveva solo 22 anni e la produzione cercava un attore più maturo e vissuto.', 'Dichiarazioni ufficiali del regista Martin Campbell nei documentari di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:37:18.964131+00:00'),
('87b3f681-d4e2-4f60-9745-a9dea1d1ec05', 137, 'Casting & Scelte', 'Il cameo e l''uso dei veri mercenari', 'John Frankenheimer decise di scritturare alcune comparse con reali trascorsi nei servizi di sicurezza internazionali e nella legione straniera francese per supervisionare la postura e i movimenti della squadra durante le scene di pianificazione tattica nei rifugi.', 'Commento audio del regista John Frankenheimer nell''edizione speciale Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:05:23.602361+00:00'),
('b234523d-e0f2-427e-9fb8-39ad40a1c706', 47, 'Segreti di produzione', 'La Aston Martin DBS modificata con cannone ad aria compressa', 'Per girare la celebre sequenza in cui la Aston Martin DBS si ribalta sette volte stabilendo un record mondiale, la troupe ha dovuto installare un cannone ad aria compressa nascosto sotto il telaio dell''auto.', 'Guinness World Records e featurette tecniche del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:37:18.964131+00:00'),
('e1d885bd-ec4c-4cc3-9b3e-eb401e56f385', 138, 'Casting & Scelte', 'Il nome cambiato alla protagonista rispetto al romanzo', 'Nel romanzo originale ''Rum Punch'' di Elmore Leonard, la protagonista si chiama Jackie Burke ed è una donna bianca. Quentin Tarantino decise di cambiare il cognome in Brown e di adattare il personaggio specificamente per Pam Grier, trasformandola in una donna afroamericana.', 'Note di produzione ufficiali e interviste a Quentin Tarantino', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:06:26.870211+00:00'),
('1bc4b8ee-a74d-4b34-bd37-35e848ae2493', 138, 'Effetti speciali & Trucco', 'L''ispirazione per il look di Melanie Ralston', 'Il look sfoggiato da Bridget Fonda nel ruolo della fricchettona Melanie Ralston, fatto di abiti larghi, scarpe platform e una costante aria annoiata, fu ideato dalla costumista Mary Claire Hannan traendo ispirazione diretta dalle riviste di moda californiane della fine degli anni ''70.', 'Special feature ''The Making of Jackie Brown'' sul DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:06:26.870211+00:00'),
('924deda5-111d-4ea0-a788-cef612a00cca', 138, 'Citazioni & Easter Egg', 'Il cameo vocale di Quentin Tarantino', 'Quentin Tarantino non appare fisicamente in un cameo visivo come in altre sue pellicole, ma presta la sua voce alla segreteria telefonica di Ordell Robbie, ascoltata durante una scena chiave del film.', 'Commento audio del regista e crediti del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:06:26.870211+00:00'),
('f45dc586-3d03-4c2e-9f46-bcddc72a9284', 138, 'Curiosità & Retroscena', 'La scelta del brano d''apertura e l''omaggio a The Graduate', 'La celebre sequenza iniziale in cui Pam Grier cammina sul tapis roulant all''aeroporto di LAX è un omaggio visivo e ritmico all''incipit del film ''Il laureato'' (The Graduate), accompagnata dal brano ''Across 110th Street'' di Bobby Womack.', 'Analisi critiche e interviste di approfondimento con il montatore Sally Menke', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:06:26.870211+00:00'),
('55bb888e-d8cf-47d8-a505-f5b5ed5aac6b', 14, 'Citazioni & Easter Egg', 'Il nome ricorrente di Michele Apicella', 'In ''Bianca'' Nanni Moretti utilizza per la quarta volta consecutiva il nome ''Michele Apicella'' per il suo alter ego protagonista, una consuetudine che proseguirà anche nei suoi film successivi come ''Palombella rossa'' e ''Caro diario''. Il cognome Apicella è un omaggio alla madre del regista, mentre Michele diventerà il nome simbolo di tutta la prima fase della sua filmografia.', 'Note di produzione e monografie sul cinema di Nanni Moretti', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:36:10.479065+00:00'),
('f51d8ea0-0fc2-4338-8a4d-a0a6dd50027f', 14, 'Casting & Scelte', 'La scelta del liceo sperimentale', 'Il liceo ''Marilyn Monroe'' in cui insegna il protagonista non è un''invenzione casuale ma riflette il dibattito culturale dei primi anni ottanta sulla sperimentazione scolastica in Italia. Moretti scelse di ambientare la pellicola in un contesto scolastico atipico per accentuare il senso di isolamento e le manie di controllo del professore di matematica.', 'Intervista d''archivio a Nanni Moretti sui luoghi dei suoi film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:36:10.479065+00:00'),
('83e08236-a053-4dc0-ad92-0f79b2253e6d', 14, 'Segreti di produzione', 'La collaborazione con Franco Piersanti per le musiche', 'La colonna sonora del film è firmata da Franco Piersanti, storico collaboratore di Nanni Moretti. Le musiche giocano un ruolo fondamentale nel sottolineare le nevrosi ossessive del protagonista, alternando toni leggeri a sonorità fortemente stranianti che accompagnano le sequenze notturne e i pedinamenti.', 'Crediti ufficiali e note di edizione della colonna sonora', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:36:10.479065+00:00'),
('8c8b891b-35ed-4d6b-9625-24f99d1e7fac', 14, 'Curiosità & Retroscena', 'Il rifiuto del lieto fine investigativo', 'Moretti decise fin dalla fase di sceneggiatura di strutturare la componente gialla non come un tradizionale whodunit, ma come un pretesto esistenziale. L''identità dell''assassino viene svelata senza il classico colpo di scena da thriller hollywoodiano, focalizzando l''attenzione sul dramma morale e sentimentale di Michele Apicella.', 'Dichiarazioni del regista in conferenza stampa all''uscita del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:36:10.479065+00:00'),
('27b431f1-74ea-4eec-be76-e78d984b4327', 14, 'Segreti di produzione', 'L''uso dei dolci come metafora delle ossessioni', 'Le gigantesche torte preparate da Michele (come quella monumentale realizzata con centinaia di bignè) sono state create appositamente da maestri pasticceri romani per le riprese. La sequenza in cui il protagonista mangia la Nutella direttamente dal barattolo o modella enormi dolci è diventata una delle scene cult più citate del cinema italiano contemporaneo.', 'Aneddoti di troupe dal set di Bianca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:36:10.479065+00:00'),
('d22b2eb4-2257-4ff2-8ead-b634a95846f0', 28, 'Casting & Scelte', 'La transizione di Gordon Scott dal Tarzan americano al peplum italiano', 'Gordon Scott, celebre interprete di Tarzan in cinque pellicole hollywoodiane tra il 1955 e il 1958, fu scelto come protagonista assoluto grazie alla sua imponente mole fisica e alla popolarità internazionale già acquisita, diventando uno dei volti di punta del cinema storico-mitologico italiano dei primi anni sessanta.', 'Dizionario del cinema italiano: I film dal 1960 al 1969', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:36:27.27063+00:00'),
('f87a3f7e-96d5-4836-9ab5-8b0af83c330f', 28, 'Segreti di produzione', 'La valorizzazione della fisicità statuaria di Gordon Scott', 'Il regista Mario Costa e il direttore della fotografia sfruttarono ampiamente l''esperienza circense e ginnica di Gordon Scott, riducendo al minimo le controfigure nelle sequenze di lotta nell''arena e nei combattimenti corpo a corpo per garantire la massima verosimiglianza visiva.', 'Note di produzione d''epoca e biografie degli stuntman del cinema peplum', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:36:27.27063+00:00'),
('580bf8d4-e757-4e63-b77b-fe81374b1f2d', 28, 'Casting & Scelte', 'Il coinvolgimento di Ombretta Colli prima della carriera musicale e politica', 'Nel cast figurava anche Ombretta Colli, accreditata con il suo vero nome e all''inizio della sua carriera artistica, prima di affermarsi come nota cantante, attrice di teatro e successivamente figura politica di rilievo nazionale.', 'Archivio del cinema italiano ANICA', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:36:27.27063+00:00'),
('627f0f73-52fa-4a51-90be-06b4ee0e124a', 28, 'Aneddoti dal set', 'Le location storiche e l''uso degli stabilimenti cinematografici romani', 'Le riprese si sono svolte principalmente all''interno dei teatri di posa romani e nelle aree limitrofe adibite a ricostruzioni scenografiche dell''antica Roma, sfruttando le maestranze artigianali locali specializzate nella costruzione rapida di templi e arene in compensato e gesso.', 'Giornate di lavorazione negli archivi storici Cinecittà', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:36:27.27063+00:00'),
('a65c8bda-146c-4b0f-8c9c-7b16b6031760', 35, 'Casting & Scelte', 'Il rifiuto del ruolo di Denethor da parte di John Noble', 'Prima che John Noble ottenesse la parte del Sovrintendente Denethor, Peter Jackson valutò altri attori di calibro internazionale. Lo stesso Noble ha raccontato nei contenuti speciali del DVD di aver dovuto superare un lungo processo di audizioni prima di convincere la produzione della sua follia regale.', 'Extended Edition Appendices - The Lord of the Rings: The Return of the King', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:36:52.595712+00:00'),
('d9705fd5-3e4c-479a-9d93-abfb52623e0c', 35, 'Aneddoti dal set', 'La ferita reale di Viggo Mortensen durante il set', 'Viggo Mortensen era noto per la sua dedizione fisica estrema sul set, al punto che durante le riprese delle sequenze d''azione si ruppe due dita di un piede calciando un elmetto di ferro uragano, urlo di dolore che fu inserito direttamente nella versione finale del montaggio.', 'Commento audio del regista e del cast - Edizione Estesa', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:36:52.595712+00:00'),
('42a40edd-2627-4a82-93a8-7cb83ee0da3b', 139, 'Aneddoti dal set', 'L''infortunio sul set di Aaron Taylor-Johnson', 'Durante le riprese di una delle intense sequenze di combattimento, Aaron Taylor-Johnson si è ferito gravemente a una mano dopo aver dato un pugno a un vetro, tanto da dover essere portato d''urgenza in ospedale dove gli sono stati applicati dei punti di sutura prima di tornare a lavorare lo stesso giorno.', 'Intervista stampa ufficiale del cast per Bullet Train (2022)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:06:33.522639+00:00'),
('139185ab-3f51-4164-834f-1cd6ced897dd', 139, 'Casting & Scelte', 'Il cameo non accreditato di Ryan Reynolds', 'Nel film compare brevemente in un cameo non accreditato l''attore Ryan Reynolds nei panni dell''assassino Carver. La sua partecipazione è nata come favore personale e reciproco: Brad Pitt aveva infatti precedentemente recitato un piccolo cameo nei panni del furgonista in Deadpool 2, diretto proprio da David Leitch.', 'Note di produzione ufficiali di Bullet Train', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:06:33.522639+00:00'),
('d93527b9-c49e-4fd9-8fd6-2e98093c833a', 139, 'Segreti di produzione', 'La preparazione fisica estrema basata sui film di Jackie Chan', 'Il regista David Leitch e il coordinatore degli stunt Greg Rabley hanno studiato a fondo lo stile di combattimento coreografico e slapstick di Jackie Chan e dei film d''azione di Hong Kong. L''obiettivo era sfruttare lo spazio angusto dei vagoni ferroviari e qualsiasi oggetto di scena disponibile per creare risse dinamiche e ironiche.', 'Special video ''Stunts of Bullet Train'' dal making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:06:33.522639+00:00'),
('957e5f16-3792-41ac-b7fc-a3c15e6e63af', 139, 'Curiosità & Retroscena', 'Il legame tra il romanzo originale e l''adattamento cinematografico', 'L''autore del libro Kotaro Isaka ha dichiarato in diverse interviste di essere rimasto sorpreso dal fatto che i produttori americani abbiano deciso di mantenere quasi inalterata la nazionalità mista e internazionale dei killer, pur modificando alcuni tratti caratteriali dei protagonisti per adattarli al ritmo del cinema hollywoodiano.', 'Intervista a Kotaro Isaka per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:06:33.522639+00:00'),
('4f48583d-432f-4a7a-8e7f-81fb0012f17b', 15, 'Segreti di produzione', 'La controversia del frame nascosto', 'Nel 1999, oltre vent''anni dopo l''uscita nelle sale, la Walt Disney Pictures fu costretta a richiamare e ritirare dal mercato circa 3,4 milioni di copie VHS del film a causa della presenza di un singolo fotogramma inappropriato. Durante la scena in cui la bionda Penny piange nella sua stanza, un fotogramma inserito fraudolentemente in post-produzione mostrava l''immagine a mezzo busto di una donna in topless.', 'Comunicato stampa ufficiale della Walt Disney Company del gennaio 1999 e registri di richiamo home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:36:14.171101+00:00'),
('d2185e50-287e-4d8a-bb56-d7a07ae11fdf', 15, 'Citazioni & Easter Egg', 'Il cameo di Bernard e Bianca nei titoli di coda', 'Sebbene non si tratti di un easter egg inserito da un altro film, l''animatore Ollie Johnston inserì una serie di caricature di animatori reali e dettagli ironici nei titoli di coda e nei bozzetti preparatori, riflettendo lo stile di transizione dell''era post-Nine Old Men della Disney.', 'The Illusion of Life: Disney Animation e archivi del Walt Disney Animation Research Library', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:36:14.171101+00:00'),
('f1ae99d3-f32a-4241-8a08-594718a63545', 15, 'Casting & Scelte', 'Il provino rifiutato per il ruolo di Bernie', 'Prima che Bob Newhart venisse definitivamente scelto per prestare la sua voce inconfondibilmente esitante e balbettante al timido Bernie, i registi valutarono diversi attori comici della televisione statunitense degli anni ''70, tra cui Dick Smothers, per conferire al personaggio un tono di costante insicurezza.', 'Note di produzione d''archivio e biografie ufficiali degli studi Disney', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:36:14.171101+00:00'),
('0245c400-1050-46c7-ba96-defbb0980632', 15, 'Segreti di produzione', 'L''eredità di Don Bluth nel reparto animazione', 'Don Bluth, futuro fondatore dei Don Bluth Studios, lavorò come animatore supervisore su questo film prima del suo celebre e travagliato distacco dalla Disney avvenuto nel 1979. Il suo stile di animazione pulito ed espressivo è particolarmente evidente nelle sequenze incentrate sui movimenti fluidi di Miss Bianca.', 'Crediti ufficiali del film e documentari storici sull''animazione americana degli anni ''70', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:36:14.171101+00:00'),
('bcfe86bd-963e-4cb7-a683-3ec8b57c777d', 31, 'Aneddoti dal set', 'La celebre dissolenteria improvvisata con la pistola', 'Il famoso duello al Cairo in cui Indiana Jones spara semplicemente allo spadaccino vestito di nero non era previsto nel copione originale. Harrison Ford era gravemente debilitato da una forte dissenteria e, incapace di reggere una lunga sequenza di combattimento con la sciabola come previsto, propose a Steven Spielberg di risolverla con un colpo di pistola.', 'Commento audio del regista Steven Spielberg e interviste di making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:36:31.930483+00:00'),
('c7898163-7090-46a2-aa94-72f159cfd0f7', 31, 'Casting & Scelte', 'Il rifiuto di Tom Selleck e l''arrivo last-minute di Harrison Ford', 'Tom Selleck fu la primissima scelta di George Lucas e ottenne ufficialmente la parte di Indiana Jones. Tuttavia, dovette rinunciare all''ultimo momento perché vincolato dal contratto televisivo per la serie Magnum P.I., aprendo la strada a Harrison Ford che fu ingaggiato appena tre settimane prima dell''inizio delle riprese.', 'Documentario ufficiale ''The Making of Raiders of the Lost Ark''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:36:31.930483+00:00'),
('c7d2de46-0eb7-40cc-8de3-655bf939d93a', 31, 'Aneddoti dal set', 'L''infortunio alle costole di Harrison Ford in Tunisia', 'Durante la sequenza in cui il camion tedesco trascina Indiana Jones, le ruote del veicolo passarono realmente molto vicine a Ford. L''attore subì la rottura di alcune costole dopo essere stato calpestato da una ruota, ma rifiutò la sosta medica prolungata facendosi fasciare e continuando a girare con l''ausilio di un cuscino per attutire i dolori.', 'Archivio di produzione Lucasfilm e biografie ufficiali del cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:36:31.930483+00:00'),
('71bebd9a-5cf1-4d0c-8ca8-acaea54b50b7', 31, 'Segreti di produzione', 'La scimmietta spia collaborazionista con i nazisti', 'La piccola scimmia incappucciata al servizio dei nazisti al Cairo creò enormi grattacapi alla troupe sul set. L''animale era solito salutare con il braccio teso imitando il saluto nazista spontaneamente, un gesto che divertiva la troupe ma che costrinse gli addestratori a ripetere decine di ciak per evitare che lo facesse nei momenti inappropriati.', 'Note di produzione e diari di bordo della troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:36:31.930483+00:00'),
('36859ce6-c8c0-4354-b73c-ed333ac7d9a1', 31, 'Citazioni & Easter Egg', 'La targa della vettura e il tributo a Star Wars', 'Nella sequenza iniziale del film in cui i cattivi fuggono a bordo di un''automobile, la targa del veicolo riporta la sigla ''OB 31''. Si tratta di un chiaro omaggio e riferimento diretto al personaggio di Obi-Wan Kenobi della saga di Star Wars, sempre ideata da George Lucas.', 'Analisi visive ufficiali e registri degli oggetti di scena', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:36:31.930483+00:00'),
('acacc8dc-0c60-4913-9471-2a2c64e997d2', 31, 'Citazioni & Easteregg', 'I geroglifici nascosti con R2-D2 e C-3PO', 'All''interno del Pozzo delle Anime, nella scena in cui Indiana Jones e Sallah rimuovono la grande lastra tombale per rivelare l''Arca, sui muri circostanti sono scolpiti dei geroglifici egizi che ritraggono chiaramente i droidi R2-D2 e C-3PO di Star Wars.', 'Libri fotografici ufficiali e guide alle curiosità del set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:36:31.930483+00:00'),
('13d414d7-8412-4b62-b12f-3e3960baf380', 140, 'Curiosità & Retroscena', 'L''ispirazione autobiografica familiare', 'James Gray ha basato gran parte delle dinamiche emotive del film sui racconti dei suoi nonni paterni, immigrati ebrei russi arrivati negli Stati Uniti attraverso Ellis Island all''inizio del Novecento. Il regista ha dichiarato in varie interviste che le difficoltà di adattamento e il senso di sradicamento vissuti da Ewa riflettono fedelmente le memorie familiari tramandate nella sua infanzia.', 'Note di produzione ufficiali e conferenza stampa al Festival di Cannes 2013', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:06:40.601104+00:00'),
('4277f864-ec3f-4e99-95a1-6e96f414748a', 140, 'Segreti di produzione', 'La ricostruzione filologica del teatro di posa', 'Poiché molte zone storiche di New York sono profondamente mutate nel XXI secolo, lo scenografo Happy Mascolo ha dovuto ricostruire gran parte degli interni di Ellis Island e dei tenement di Manhattan nei Kaufman Astoria Studios nel Queens, consultando i piani architettonici originali del 1921 conservati negli archivi municipali.', 'Production notes e intervista allo scenografo Happy Mascolo', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:06:40.601104+00:00'),
('d4100be1-6713-4e87-a745-52c0909210d1', 140, 'Aneddoti dal set', 'Il lavoro linguistico sul dialetto polacco d''epoca', 'Marion Cotillard e Angela Sarafyan (che interpreta la sorella Magda) hanno lavorato a stretto contatto con un linguista specializzato per padroneggiare non solo il polacco moderno, ma le inflessioni e i vocaboli specifici parlati dagli immigrati della regione della Galizia all''inizio degli anni ''20.', 'Pressbook ufficiale del film e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:06:40.601104+00:00'),
('af220cac-5196-4a02-9b3a-5420051ace26', 140, 'Segreti di produzione', 'I costumi d''epoca originali e le tinture naturali', 'La costumista Patricia Norris ha evitato i tessuti sintetici o troppo uniformi, reperendo in Europa tessuti d''epoca autentici e applicando tinture a base vegetale per conferire ai vestiti logori degli immigrati la giusta consistenza polverosa e vissuta visibile sullo schermo.', 'Featurette ''The Look of the Film'' nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:06:40.601104+00:00'),
('4eefb4fe-5fa0-4753-9f44-a0ca45549128', 16, 'Segreti di produzione', 'La prima pietra miliare del CAPS', 'Bianca e Bernie nella terra dei canguri detiene il primato storico di essere il primo lungometraggio d''animazione Disney realizzato interamente senza l''uso della tradizionale carta e della camera da mela, sfruttando invece il sistema digitale CAPS (Computer Animation Production System), sviluppato in collaborazione con la Pixar.', 'Documentario di produzione e note ufficiali Disney Animation', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:36:18.176313+00:00'),
('801eb071-c78c-44ec-ac0f-6f6934b81807', 16, 'Casting & Scelte', 'La scelta iniziale di Jean Stapleton', 'Attrice nota per ''Arcibaldo'', Jean Stapleton fu originariamente contattata per doppiare il personaggio di Bianca prima che Eva Gabor riprendesse il ruolo. La produzione optò poi per mantenere la Gabor per continuità con il film originale del 1977.', 'Archivi storici di casting Disney e registri di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:36:18.176313+00:00'),
('7e6acf24-873b-472a-a32b-cac8f7abe191', 16, 'Casting & Scelte', 'Il tributo vocale a John Candy', 'L''albatros Wilbur fu scritto appositamente pensando alla corporatura e alla verve comica di John Candy, dopo la morte di Jim Backus (che aveva doppiato Orville nel primo film). Molte delle battute di Candy furono registrate tramite sessioni di improvvisazione vocale in studio.', 'Note di regia nel commento audio del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:36:18.176313+00:00'),
('1ddf7066-ea01-4f4c-a4b8-49dd78885a81', 16, 'Casting & Scelte', 'I movimenti ispirati a Crocodile Dundee', 'Il personaggio di Jake, il topo saltatore interpretato da Tristan Rogers, è stato modellato graficamente e caratterialmente attingendo all''archetipo dell''eroe australiano reso celebre da Paul Hogan in ''Crocodile Dundee'', unendo spavalderia e profonda conoscenza del territorio.', 'Libro ''The Disney Films'' di Leonard Maltin e interviste agli animatori', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:36:18.176313+00:00'),
('7b9187a1-7623-4cef-9742-193c61691174', 16, 'Segreti di produzione', 'La riutilizzazione e il riciclo di sequenze', 'A causa di stringenti vincoli di budget e scadenze di calendario, gli animatori riutilizzarono alcuni movimenti di volo di Bianca e Bernie dal primo film, adattandoli digitalmente nei nuovi sfondi in 3D generati dal sistema CAPS.', 'Analisi tecniche e confronti fotogramma per fotogramma su MovieMistakes', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:36:18.176313+00:00'),
('014395dc-a53b-4c4f-8d1f-6dba54718116', 16, 'Citazioni & Easter Egg', 'L''omaggio a Topolino nei titoli di coda', 'Durante la sequenza iniziale del volo sul dorso di Wilbur, tra le nuvole e i riflessi digitali generati dal sistema CAPS, gli artisti inserirono abilmente una nuvola che richiama la silhouette della testa di Topolino.', 'Rilevamenti ufficiali di Easter Egg nelle edizioni Home Video speciali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:36:18.176313+00:00'),
('f6fe17ed-666d-4a4d-a9fd-014380a0a453', 37, 'Aneddoti dal set', 'Il rischio di cecità per Malcolm McDowell', 'Durante la famigerata scena della Cura Ludovico in cui Alex viene costretto a tenere gli occhi spalancati con dei divaricatori metallici, l''attore Malcolm McDowell subì gravi danni alla cornea a causa dell''asciugatura dei bulbi oculari. Un medico fu costretto a intervenire regolarmente sul set per applicargli colliri anestetici, e in un''occasione l''attore perse temporaneamente la vista.', 'Documentario O Lucky Malcolm! e interviste retrospettive di Malcolm McDowell', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:37:01.932618+00:00'),
('013c9b1a-12b4-4195-9c72-784a0e384412', 37, 'Aneddoti dal set', 'La frattura alle costole di Patrick Magee', 'Nella celebre sequenza in cui Alex calpesta e prende a calci lo scrittore Frank Alexander immobilizzato a terra, Malcolm McDowell calpestò accidentalmente con troppa foga l''attore Patrick Magee, fratturandogli realmente una costola. Magee continuò la ripresa nonostante il forte dolore, guadagnandosi il rispetto della troupe.', 'Audio commento del DVD di Malcolm McDowell e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:37:01.932618+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('6ab6db0f-b296-469f-acc0-e19179dc315c', 37, 'Aneddoti dal set', 'L''improvvisazione di Cantin'' in the Rain', 'La celebre sequenza in cui Alex irrompe nella casa dello scrittore cantando e ballando ''Singin'' in the Rain'' mentre devasta l''abitazione fu quasi interamente improvvisata da Malcolm McDowell. Stanley Kubrick, insoddisfatto delle prime riprese, chiese all''attore di fare qualcosa di spensierato e riconoscibile, e McDowell si ricordò di quell''unica canzone che sapeva ballare.', 'Intervista a Stanley Kubrick per la Directors Guild of America', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:37:01.932618+00:00'),
('5cceca9f-5e29-4c64-b51a-ea7677e2ac5a', 37, 'Aneddoti dal set', 'La ripresa rischiosa dal tetto', 'Per girare la scena in cui il giovane Alex viene aggredito dai suoi stessi compagni traditori (i Drughi) vicino a un lago artificiale, Kubrick utilizzò una cinepresa montata su una gru. Durante le riprese, la troupe rischiò di far cadere accidentalmente l''attore Malcolm McDowell in acqua gelida da un''altezza considerevole.', 'Making-of ufficiale e diari di produzione della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:37:01.932618+00:00'),
('43f2891c-2484-42c6-a223-62069ce518a4', 37, 'Segreti di produzione', 'L''uso di una cinepresa a mano per la rissa iniziale', 'Per dare un senso di caos visivo e dinamismo estremo durante la rissa tra la banda di Alex e la banda rivale nei bagni abbandonati, Stanley Kubrick decise di utilizzare personalmente la cinepresa a mano. Questa fu una delle rare occasioni in cui il meticoloso regista operò direttamente la macchina da presa.', 'Note tecniche e cinematografiche della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:37:01.932618+00:00'),
('4040f512-77c4-4d79-a846-cff76fe516fc', 141, 'Segreti di produzione', 'L''invenzione della colonna sonora d''emergenza', 'Visto che i malfunzionamenti continui dello squalo meccanico impedivano a Spielberg di mostrare chiaramente la creatura, il regista commissionò a John Williams un tema musicale ossessivo basato su sole due note per suggerire la presenza del predatore attraverso la suspense.', 'Documentario ''The Making of Jaws'' e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:06:48.221741+00:00'),
('4144b49a-7d00-4bfb-b54f-9a79947b5abf', 141, 'Casting & Scelte', 'Il rifiuto iniziale di Roy Scheider', 'Roy Scheider accettò il ruolo del capo della polizia Martin Brody quasi per caso, dopo aver sentito casualmente Steven Spielberg a una festa parlare di uno squalo che avrebbe divorato un cittadino intero, rimanendo affascinato dall''idea.', 'Biografie ufficiali e interviste retrospettive a Roy Scheider', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:06:48.221741+00:00'),
('65b9fae6-ea00-4d0f-bb8b-aac6a5488c8e', 141, 'Casting & Scelte', 'La modifica del finale nel libro', 'Nel romanzo originale di Peter Benchley, lo squalo muore dissanguato dopo aver subito numerosi attacchi, mentre Steven Spielberg pretese di cambiare il finale facendo esplodere il predatore con una bombola d''ossigeno per garantire un epilogo cinematografico più spettacolare.', 'Confronto tra sceneggiatura e romanzo originale di Peter Benchley', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:06:48.221741+00:00'),
('ef5bb23f-03c2-4676-9a4c-29a916498c9f', 18, 'Casting & Scelte', 'L''uso di veri marinai e personale militare', 'Per mantenere il massimo realismo propagandistico e documentaristico richiesto dal regime, Rossellini decise di non impiegare attori professionisti per i ruoli dei marinai, ma scelse di utilizzare il vero equipaggio della Regia Marina e soldati realmente feriti o convalescenti.', 'Note di produzione e archivi storici della Regia Marina', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:36:21.640731+00:00'),
('46520d9e-0562-4a1c-b5a7-707c9642f9d4', 18, 'Casting & Scelte', 'La scelta delle crocerossine volontarie', 'Anche per il ruolo delle infermiere a bordo della nave ospedale ''Arno'', la produzione evitò attrici di professione, scritturando autentiche crocerossine volontarie della Croce Rossa Italiana per garantire una naturalezza assoluta nei gesti clinici.', 'Monografie storiche sul cinema del periodo bellico', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:36:21.640731+00:00'),
('e08531f4-5d04-40dd-85eb-1ee73aa93dd2', 18, 'Segreti di produzione', 'Il ruolo della nave ospedale Arno', 'La nave ospedale ''Arno'' protagonista del film non era un set ricostruito in studio, ma una vera unità navale della Regia Marina realmente adibita al soccorso e al recupero dei feriti nel Mediterraneo durante il conflitto.', 'Documentazione ufficiale della Marina Militare italiana', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:36:21.640731+00:00'),
('baf0d273-fbdf-4131-a3d4-af09c21af580', 18, 'Aneddoti dal set', 'L''autenticità delle procedure mediche', 'Le scene di chirurgia e primo soccorso girate all''interno della nave non prevedevano l''uso di consulenti o attori formati per finta: i medici e i paramedici inquadrati erano ufficiali medici reali della Marina in servizio effettivo.', 'Archivi storici di Cinecittà e testimonianze della troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:36:21.640731+00:00'),
('521bab87-a988-4e9e-9170-9a113bc310d7', 18, 'Segreti di produzione', 'La genesi del montaggio di Mario Serandrei', 'Il montaggio del film fu curato da Mario Serandrei, figura chiave del proto-neorealismo, il quale lavorò intensamente per raccordare il materiale documentario girato in mare aperto con le sequenze narrative girate da Rossellini.', 'Saggi critici sul montaggio cinematografico italiano', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:36:21.640731+00:00'),
('8f34abd6-00a5-448b-a132-01fa8161d88d', 18, 'Aneddoti dal set', 'Le riprese in condizioni di navigazione reale', 'Molte sequenze furono effettuate mentre la nave era in movimento durante normali operazioni di trasferimento, costringendo troupe, operatori e macchinari a fare i conti con il beccheggio e il rollio reale del mare aperto.', 'Memorie di lavorazione della troupe di Rossellini', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:36:21.640731+00:00'),
('e516b996-9ba5-4824-bf43-06276f074422', 33, 'Casting & Scelte', 'La scelta iniziale di Stuart Townsend per Aragorn', 'Stuart Townsend fu originariamente scelto per interpretare Aragorn e si allenò per due mesi prima che Peter Jackson e i produttori si rendessero conto, pochi giorni prima dell''inizio delle riprese, che l''attore era troppo giovane per il ruolo. Fu sostituito d''urgenza da Viggo Mortensen, che accettò la parte anche grazie all''insistenza di suo figlio Henry.', 'Documentario ''The Making of The Fellowship of the Ring'' e commento audio del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:36:42.471542+00:00'),
('e7248fae-7d88-4908-ae02-d9ede3036744', 33, 'Aneddoti dal set', 'La frattura alle costole di Viggo Mortensen', 'Durante le riprese della sequenza in cui Aragorn combatte contro gli Uruk-hai ad Amon Hen, Viggo Mortensen si ruppe accidentalmente due costole dopo aver parato con la spada un pugnale di metallo scagliato contro di lui da una controfigura che non vedeva nulla attraverso l''elmo.', 'Extra del DVD edizione estesa e interviste ufficiali al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:36:42.471542+00:00'),
('abcfec23-912c-4b4f-bdc1-618c2017d0d4', 33, 'Aneddoti dal set', 'Il dente rotto e la colla di Sean Astin', 'Mentre girava la scena in cui Sam corre nell''acqua per inseguire la barca di Frodo alla fine del film, Sean Astin calpestò un grosso pezzo di vetro nascosto sul fondo del fiume, che gli trafisse il piede ferendolo gravemente. Fu trasportato d''urgenza in ospedale in elicottero per essere operato.', 'Diario di produzione e documentario del making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:36:42.471542+00:00'),
('09d99fe4-40bc-47f7-bc18-f114cb384ab0', 33, 'Segreti di produzione', 'La tecnica di prospettiva forzata per le scale di Moria', 'Per simulare la vertiginosa vastità delle miniere di Moria, la produzione costruì un set enorme con veri ponti sospesi, ma per la celebre fuga sulle scale a chioccia venne impiegata una complessa combinazione di miniature in scala e il sistema della prospettiva forzata, in cui alcuni attori recitavano su piattaforme distanti per apparire più piccoli.', 'The Lord of the Rings: Appendices - Design and Production', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:36:42.471542+00:00'),
('e52b59c4-a1b6-4203-9e8f-924403dfb631', 33, 'Effetti speciali & Trucco', 'La cicatrice e il dente finto di Viggo Mortensen', 'Durante una pausa dalle riprese, Viggo Mortensen si scheggiò un dente in uno scontro simulato; invece di correre dal dentista, chiese al reparto trucco di incollarlo temporaneamente con del comune super Attak per poter finire la giornata di lavoro sul set.', 'Intervista a Viggo Mortensen nel documentario ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:36:42.471542+00:00'),
('af704a70-9913-4d23-8d25-9fc23d105be2', 33, 'Citazioni & Easter Egg', 'Il cameo dei figli di Peter Jackson', 'I figli del regista Peter Jackson, Katie e Billy, fanno una rapida apparizione nel film durante la scena in cui Bilbo racconta la storia dei Troll ai giovani Hobbit nella festa di compleanno, interpretando due piccoli Hobbit in ascolto.', 'Credits del film e commento audio del cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:36:42.471542+00:00'),
('cf2e9691-c928-47a9-9867-b279f54ea6e1', 46, 'Aneddoti dal set', 'L''improvvisazione nella lite tra De Niro e la Stone', 'Durante la drammatica scena in cui Sam scopre Ginger in auto a contare i soldi e scoppia una violenta lite verbale, Sharon Stone e Robert De Niro decisero di improvvisare gran parte dei loro battibecchi, cogliendo di sorpresa la troupe e persino Martin Scorsese, che decise di mantenere buona la ripresa per la sua estrema autenticità.', 'Commento audio del regista nel DVD ufficiale di Casino', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:37:15.781084+00:00'),
('520ab7b5-8e93-4181-bd90-4fef66554617', 141, 'Casting & Scelte', 'Il vero pescatore locale nel cast', 'Per interpretare il pescatore Ben Gardner fu scelto Craig Kingsbury, un vero pescatore e abitante eccentrico di Martha''s Vineyard, che non aveva alcuna esperienza di recitazione e le cui battute dovettero essere corrette da Spielberg perché spesso incomprensibili.', 'Note di casting del film e documentari d''archivio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:06:48.221741+00:00'),
('645459b3-196b-4449-b6db-491bbdaec16d', 141, 'Casting & Scelte', 'Il rifiuto del ruolo di Quint da parte di Lee Marvin', 'Prima che la parte del cacciatore di squali Quint venisse affidata a Robert Shaw, il ruolo fu offerto a Lee Marvin, il quale rifiutò l''offerta affermando preferibilmente di dedicarsi alla pesca in alto mare anziché recitarci.', 'Archivi di produzione Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:06:48.221741+00:00'),
('77904c93-6af6-4f1b-9b9c-6b317e94793e', 31, 'Effetti speciali & Trucco', 'Il vero veleno del serpente sputatore nascosto nel vetro', 'Nella scena in cui il cobra reale si alza di fronte a Indiana Jones nel tempio, l''animale sputava realmente veleno verso la telecamera. Per proteggere l''attore e la troupe senza alterare le riprese, fu posizionato un pannello di vetro trasparente invisibile tra Harrison Ford e il serpente.', 'Documentario ''The Great Movie Stunts: Raiders of the Lost Ark''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:36:31.930483+00:00'),
('600d8edf-a164-4ff6-bdcb-09ded813d2f5', 36, 'Effetti speciali & Trucco', 'L''uso massiccio del rotoscopio con comparse in costume', 'Per realizzare le scene di battaglia e i movimenti realistici dei personaggi, Ralph Bakshi filmò attori in carne ed ossa vestiti con costumi medievali e armature nel parcheggio degli studi. Queste riprese dal vero furono poi ricalcate fotogramma per fotogramma attraverso la tecnica del rotoscopio.', 'Documentario ''The Making of Ralph Bakshi''s The Lord of the Rings''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:36:56.436784+00:00'),
('44794a7a-b9fc-4c11-b4f9-82a795ad0fd7', 36, 'Casting & Scelte', 'Il provino rifiutato di Ian McKellen', 'Anni prima di interpretare Gandalf nella trilogia live-action di Peter Jackson, a Ian McKellen fu offerta l''opportunità di partecipare al film d''animazione del 1978 come doppiatore, ma declinò l''offerta a causa di impegni teatrali.', 'Archivio storico delle interviste di Ian McKellen', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:36:56.436784+00:00'),
('3133bb74-0dd0-41e0-be77-576153ec135e', 36, 'Aneddoti dal set', 'L''impiego di veri soldati spagnoli come comparse', 'Per le sequenze di massa dell''esercito di Orcie e dei cavalieri di Rohan, la produzione assunse reparti dell''esercito spagnolo stazionati vicino agli studi di Madrid dove venivano eseguite parte delle lavorazioni, sfruttandone la disciplina militare per le scene corali.', 'Note di produzione e memo di Ralph Bakshi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:36:56.436784+00:00'),
('37085445-08a5-453f-83d6-66a230cb7b7c', 36, 'Curiosità & Retroscena', 'Il taglio netto del secondo libro', 'Il film avrebbe dovuto originariamente coprire anche gli eventi de ''Le Due Torri'' in un secondo lungometraggio, ma a causa del fallimento finanziario della distribuzione iniziale, il progetto del sequel fu cancellato, lasciando la storia bruscamente interrotta alla Battaglia del Fosso di Helm.', 'Cinefantastique Magazine, Vol. 8, No. 4', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:36:56.436784+00:00'),
('1eec707e-90d1-4862-8127-0b8f6391adea', 36, 'Segreti di produzione', 'La riutilizzazione di sequenze live-action nelle scene dei Nazgûl', 'Per accentuare il senso di terrore e la natura spettrale dei Cavalieri Neri, Bakshi applicò effetti ottici e filtri solarizzati direttamente sulle pellicole in live-action prima di completare il processo di stampa e animazione.', 'Commento audio del regista all''edizione DVD Warner Home Video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:36:56.436784+00:00'),
('eb9ced1a-4553-4533-a7e0-9a19c5eeda1e', 71, 'Aneddoti dal set', 'L''origine della frase d''amore improvvisata', 'Nella celebre scena in cui Leila dice ''Ti amo'' a Ian Solo prima dell''ibernazione, la sceneggiatura originale prevedeva che Harrison Ford rispondesse ''Anch''io ti amo''. Su suggerimento del regista Irvin Kershner, Ford improvvisò la battuta ''Lo so'', diventata una delle citazioni più iconiche della storia del cinema.', 'Commento audio e documentari ufficiali sul making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:38:59.54142+00:00'),
('c0febbd2-b9ce-4a16-948f-d7579aca367f', 71, 'Casting & Scelte', 'La vera identità di Yoda nel design iniziale', 'Prima che Stuart Freeborn definisse il look definitivo di Yoda ispirandosi al proprio volto e a quello di Albert Einstein, la produzione prese seriamente in considerazione l''idea di addestrare una scimmietta vera affinché indossasse una maschera e un mantello per interpretare il maestro Jedi.', 'Archivi di produzione Lucasfilm e libri retrospettivi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:38:59.54142+00:00'),
('04988736-84a3-4783-bb04-5130be4f109f', 71, 'Effetti speciali & Trucco', 'Il peso nascosto di Yoda e la fatica di Frank Oz', 'Il burattinaio Frank Oz doveva manovrare Yoda da una trincea profonda scavata nel set di Dagobah, lavorando in condizioni di forte stress fisico con le braccia sollevate per ore. La voce e la personalità iconica del personaggio furono interamente modellate e improvvisate dallo stesso Oz sul set.', 'Speciali di approfondimento sulla realizzazione degli effetti visivi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:38:59.54142+00:00'),
('8b23ee2e-aab9-4488-8a8c-e35184e2cd15', 71, 'Citazioni & Easter Egg', 'Il cameo nascosto di Joe Johnston come pilota di AT-AT', 'Joe Johnston, celebre artista concettuale e storyboarder della trilogia originale, appare brevemente in un cameo non accreditato come pilota imperiale all''interno di un AT-AT durante la celebre Battaglia di Hoth.', 'Registri di produzione e note ufficiali della troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:38:59.54142+00:00'),
('95d29191-e64e-4b4a-bff0-417b2d0195a0', 71, 'Casting & Scelte', 'L''assenza di David Prowse durante i duelli con la spada laser', 'Sebbene David Prowse abbia indossato l''armatura di Darth Vader per l''intero film, le sequenze di combattimento più agili furono interamente girate dallo schermidore professionista e coordinatore degli stunt Bob Anderson, accreditato solo successivamente.', 'Interviste ufficiali al cast e troupe della trilogia classica', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:38:59.54142+00:00'),
('0e80e793-7d79-4bcb-bcd1-f22a59563cec', 71, 'Citazioni & Easter Egg', 'Il casco di Ian Solo nascosto tra i detriti di Bespin', 'Nel corso della sequenza in cui Ian Solo viene estratto dalla cella di tortura a Cloud City, tra gli oggetti di scarto sul set si intravede un casco che riprende chiaramente il design dei piloti dei caccia ribelli, inserito come piccolo Easter Egg dai tecnici degli oggetti di scena.', 'Analisi dei dettagli di scena e guide ai contenuti nascosti del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:38:59.54142+00:00'),
('77611e8a-68bc-4c53-95d1-cde58f560e8a', 71, 'Aneddoti dal set', 'La neve sintetica tossica di Hoth', 'Per simulare la neve e le tempeste ghiacciate del pianeta Hoth, la produzione utilizzò grandi quantità di plastica sminuzzata e persino fibra di vetro soffiata negli studi di Finse, in Norvegia, causando non pochi problemi respiratori e irritazioni agli attori e alle comparse.', 'Documentari storici e diari di troupe delle riprese in Norvegia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:38:59.54142+00:00'),
('8cfaf84a-95b3-4c0b-8a07-84c375c971fa', 142, 'Segreti di produzione', 'Il taglio della scena del killer whale', 'Nel copione originale era prevista una scena iniziale in cui lo squalo attaccava e uccideva un''orca assassina (killer whale), arenando poi la carcassa mutilata sulla spiaggia di Amity. La sequenza fu girata ma poi tagliata nel montaggio finale perché l''orca meccanica non funzionava correttamente e appariva del tutto finta sullo schermo.', 'Documentario ''The Making of Jaws 2'' / Note di produzione Universal', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:06:56.485909+00:00'),
('95740a8b-8fe5-49bf-b02e-b89b8dd57878', 142, 'Curiosità & Retroscena', 'La censura della MPAA per la violenza sui giovani', 'Il film rischiò seriamente di ottenere un visto di censura ''R'' (vietato ai minori non accompagnati) a causa della ferocia con cui lo squalo attaccava il gruppo di adolescenti sulle barche. Il regista Jeannot Szwarc fu costretto a tagliare diversi fotogrammi cruenti e a stemperare la violenza visiva per ottenere il più commerciale visto ''PG''.', 'Archivi storici MPAA / Interviste retrospettive al montatore Arthur Schmidt', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:06:56.485909+00:00'),
('48bb1e8a-4da0-4616-84d0-2623ead2b3f5', 142, 'Aneddoti dal set', 'L''infortunio sul set di Lorraine Gary', 'Durante le estenuanti riprese in mare aperto a Navarre, in Florida, l''attrice Lorraine Gary (Ellen Brody) rischiò la vita quando una delle barche di supporto perse il controllo durante una burrasca improvvisa. L''attrice riportò contusioni multiple e la produzione dovette interrompere le lavorazioni per quarantotto ore.', 'Reportage d''epoca della rivista American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:06:56.485909+00:00'),
('0dfd7de8-6da9-4f8b-b858-c18ec92b54c8', 32, 'Casting & Scelte', 'La preparazione fisica estrema di Paul Mescal', 'Per trasformarsi nel guerriero Lucio, Paul Mescal ha seguito un rigido programma di allenamento e dieta durato mesi sotto la supervisione di trainer professionisti. L''attore ha dichiarato di aver dovuto consumare enormi quantità di cibo e di aver evitato i social media per mantenere la concentrazione sul personaggio.', 'Interviste promozionali ufficiali del cast (2024)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:36:38.323707+00:00'),
('947907fc-887f-49f8-8292-e9e097fcfb24', 32, 'Segreti di produzione', 'La ricostruzione digitale e fisica del Colosseo', 'La produzione ha combinato imponenti set fisici costruiti a Malta e in Marocco con avanzate tecniche di CGI per ricreare la Roma antica e l''interno del Colosseo. Gli scenografi hanno studiato i documenti storici per garantire la massima accuratezza architettonica possibile, pur adattandola alle esigenze narrative di Ridley Scott.', 'Note di produzione ufficiali Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:36:38.323707+00:00'),
('a1a02620-b04e-4cdb-9443-4177e4e7cdc0', 32, 'Effetti speciali & Trucco', 'I costumi epici di Janty Yates', 'La celebre costumista premio Oscar Janty Yates è tornata a collaborare con Ridley Scott realizzando oltre diecimila costumi per il film tra gladiatori, senatori e soldati romani. Ogni armatura è stata lavorata artigianalmente per conferirgli un aspetto vissuto e realistico nelle sequenze di combattimento.', 'Backstage e interviste alla costumista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:36:38.323707+00:00'),
('c3511a96-5eb4-48a7-8247-028e040210f7', 32, 'Casting & Scelte', 'La scelta di Barry Keoghan e l''ingresso di Fred Hechinger', 'Inizialmente l''attore irlandese Barry Keoghan era stato fortemente voluto per il ruolo dell''imperatore Caracalla, ma ha dovuto rinunciare alla parte a causa di conflitti di programmazione con le riprese del film ''Bird'' di Andrea Arnold. La produzione ha così rapidamente ripiegato su Fred Hechinger, che ha ereditato il ruolo del sovrintendente folle e tirannico.', 'Deadline / Note di casting ufficiali di Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:36:38.323707+00:00'),
('104d8990-3b9e-4279-a8ba-f7a73532fe3b', 32, 'Effetti speciali & Trucco', 'L''ispirazione per i babbuini digitali', 'La feroce sequenza in cui Lucio affronta dei babbuini nel Colosseo è stata realizzata combinando stuntmen in tuta di cattura del movimento e primati interamente generati in CGI. Ridley Scott ha dichiarato di aver voluto inserire questi animali dopo aver visto video documentari reali sulla spaventosa forza e aggressività dei babbuini in natura.', 'Intervista a Ridley Scott per Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:36:38.323707+00:00'),
('774ee383-8026-4552-b473-cd5da1ec457a', 32, 'Segreti di produzione', 'Il ritorno della costumista Janty Yates e di Arthur Max', 'Per mantenere intatta la continuità visiva e lo stile epico del primo capitolo del 2000, Ridley Scott ha richiamato i suoi collaboratori storici: la costumista premio Oscar Janty Yates e lo scenografo Arthur Max. Entrambi hanno condotto mesi di ricerche storiche approfondite per ricreare l''architettura e la moda della Roma imperiale del II secolo d.C.', 'Production Notes ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:36:38.323707+00:00'),
('1f2514f4-0b03-4829-b1b6-43323916d16b', 32, 'Effetti speciali & Trucco', 'La cicatrice di Pedro Pascal come omaggio a Marco Acacio', 'Il generale Marco Acacio, interpretato da Pedro Pascal, sfoggia sul volto una cicatrice dettagliata che racconta visivamente il suo passato di veterano delle campagne militari in Numidia. Il reparto trucco ha impiegato protesi in silicone avanzate applicate quotidianamente prima di ogni sessione di ripresa per garantire la massima verosimiglianza in alta definizione.', 'Making-of ufficiale e dietro le quinte Paramount', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:36:38.323707+00:00'),
('ba76b698-c705-47a9-bcf7-df3d460ddf2f', 32, 'Aneddoti dal set', 'L''uso delle trivelle d''acqua nel set marocchino', 'Durante le riprese nel deserto vicino a Ouarzazate, la troupe ha dovuto affrontare temperature torride che superavano regolarmente i 45 gradi Celsius. La produzione ha dovuto installare speciali trivelle e sistemi di climatizzazione portatili per evitare colpi di calore tra le comparse e proteggere le delicate attrezzature da presa dalla polvere desertica.', 'Reportage dal set di The Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:36:38.323707+00:00'),
('687b9234-34e9-4000-aba0-20625be2e055', 32, 'Citazioni & Easter Egg', 'Il cameo vocale e visivo degli archivi del primo film', 'All''inizio del film, per riassumere il legame tra Lucio e Massimo, la produzione ha ottenuto i diritti per riutilizzare brevi fotogrammi e la voce originale di Richard Harris nel ruolo dell''imperatore Marco Aurelio, integrandoli nei ricordi d''infanzia del protagonista.', 'Analisi visiva e credits di fine pellicola', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T15:36:38.323707+00:00'),
('bdff3514-40cd-4e62-93b5-eaa50bb180aa', 45, 'Casting & Scelte', 'La voce doppiata di Auric Goldfinger', 'L''attore tedesco Gert Fröbe, scelto per interpretare il magnate Auric Goldfinger, parlava un inglese fortemente accentato e con un timbro considerato poco minaccioso dai produttori. Per questo motivo, l''intero suo ruolo fu doppiato in post-produzione dall''attore britannico Michael Collins, sebbene in Germania Fröbe potè mantenere la sua voce originale.', 'Documentario ufficiale ''The Making of Goldfinger''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:37:11.590881+00:00'),
('52bb41bc-a632-465d-894a-ab99fbd73d1c', 45, 'Aneddoti dal set', 'Il malore sul set per la vernice dorata', 'Durante le riprese della celebre sequenza della morte di Jill Masterson, l''attrice Shirley Eaton fu interamente dipinta con una vernice dorata a base di lacca. Si diffuse rapidamente la leggenda metropolitana che l''attrice stesse rischiando l''asfissia cutanea e la morte; in realtà, la produzione lasciò una piccola porzione di pelle non dipinta sullo stomaco proprio per consentire al corpo di respirare in sicurezza.', 'Intervista d''archivio a Shirley Eaton', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:37:11.590881+00:00'),
('1f499734-b003-445f-bdb9-d1daca079b9c', 142, 'Casting & Scelte', 'Il rifiuto di Steven Spielberg di dirigere il sequel', 'La Universal Pictures offrì inizialmente a Steven Spielberg una cifra faraonica e la totale libertà creativa per dirigere il seguito del suo celebre capolavoro. Il regista rifiutò categoricamente, definendo l''esperienza del primo film estenuante e dichiarando che fare un sequel di ''Lo squalo'' sarebbe stato come ''inseguire un''aspirazione impossibile''.', 'Biografia ufficiale ''Steven Spielberg: A Biography'' di Joseph McBride', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:06:56.485909+00:00'),
('3bbf253a-372c-4641-94e5-93224a865d5d', 34, 'Aneddoti dal set', 'La ferita al piede di Sean Astin', 'Durante le riprese della scena in cui Sam corre verso la barca di Frodo sul fiume Anduin, l''attore Sean Astin calpestò un pezzo di vetro nascosto nell''acqua torbida che gli trapassò la protesi del piede da parte a parte, richiedendo un immediato trasporto in ospedale in elicottero.', 'Commento audio del cast nel DVD esteso', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:36:47.884141+00:00'),
('02aa28d4-33c0-4f6f-9539-572bf635370b', 34, 'Aneddoti dal set', 'Il grave infortunio alla spalla di Viggo Mortensen', 'Mentre girava la sequenza in cui Aragorn cerca i corpi degli Hobbit bruciati dagli Uruk-hai, Viggo Mortensen si ruppe due dita del piede calciando un elmetto di ferro; lo sforzo fu così intenso che l''urlo di dolore inserito nel montaggio finale è autentico.', 'Documentario ''The Appendices'' - Edizione Estesa Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:36:47.884141+00:00'),
('02b023b4-2eb2-4b42-a9ad-9a1d6326f1e3', 34, 'Casting & Scelte', 'La scelta iniziale di Stuart Townsend come Aragorn', 'Prima che Viggo Mortensen ottenesse la parte, il ruolo di Aragorn fu originariamente assegnato al giovane attore irlandese Stuart Townsend, che si allenò per due mesi prima di essere licenziato da Peter Jackson appena quattro giorni prima dell''inizio delle riprese perché ritenuto troppo giovane per il personaggio.', 'Intervista ufficiale a Peter Jackson su Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:36:47.884141+00:00'),
('4fcf5b80-4813-4abc-a4c2-843120894f0e', 34, 'Casting & Scelte', 'La voce abrasiva di Bernard Hill', 'Per ottenere la tonalità roca e autorevole di Re Théoden, l''attore Bernard Hill dovette sottoporsi a sessioni di riscaldamento vocale estreme e a volte inalare fumo di scena per irritare deliberatamente le corde vocali prima di pronunciare i discorsi più intensi.', 'Diario di produzione ufficiale della Weta Workshop', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:36:47.884141+00:00'),
('ca9bbc59-2cb6-4040-a088-3a2457d9b6f0', 34, 'Aneddoti dal set', 'Le lacrime reali di Miranda Otto', 'Durante la preparazione per la carica dei cavalieri di Rohan, l''attrice Miranda Otto (Éowyn) dovette superare una forte fobia dei cavalli, imparando a cavalcare da zero e arrivando a piangere di frustrazione durante le sessioni di addestramento equestre intensivo in Nuova Zelanda.', 'Making-of ''I guerrieri di Rohan'' - Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:36:47.884141+00:00'),
('26746db1-2c20-45e0-99f7-6c530c9e6582', 34, 'Effetti speciali & Trucco', 'L''invenzione tecnica del sistema di motion capture per Gollum', 'Per dare vita a Gollum, la Weta Digital sviluppò un rivoluzionario software di tracciamento facciale chiamato ''Massive'' e in seguito ''Tissue'', che permetteva di trasferire le micro-espressioni dell''attore Andy Serkis direttamente sul modello digitale in CGI.', 'Documentario sui VFX - Weta Digital Production Notes', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:36:47.884141+00:00'),
('8f61308a-9323-47d6-94b6-0705deb2d5d9', 34, 'Citazioni & Easter Egg', 'Il cameo dei registi Peter Jackson e dei suoi figli', 'Il regista Peter Jackson fa una breve apparizione nei panni di un difensore del Fosso di Helm che scaglia una lancia contro gli Uruk-hai durante l''assalto alle scale della fortezza; anche i suoi figli compaiono brevemente come rifugiati nelle caverne di Aglarond.', 'Easter Egg e tracce di commento del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:36:47.884141+00:00'),
('c802fbb4-9b05-4d03-a651-495003b8f970', 34, 'Effetti speciali & Trucco', 'I problemi di salute di John Rhys-Davies con il trucco di Gimli', 'John Rhys-Davies ha dovuto affrontare una grave reazione allergica quotidiana alle protesi di lattice applicate sul viso per interpretare Gimli, che gli causavano la corrosione della pelle e lo costringevano a saltare un giorno di riprese ogni tre.', 'Intervista a John Rhys-Davies nel documentario ''Behind the Make-up''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:36:47.884141+00:00'),
('55871556-253b-43de-a33f-3b28d9682c61', 53, 'Curiosità & Retroscena', 'Il taglio radicale della versione cinematografica', 'La versione cinematografica di ''Highlander: Endgame'' subì pesanti tagli di montaggio da parte della Dimension Films, che ridusse drasticamente la durata e rimosse intere sottotrame per accelerare il ritmo. Questa versione fu ampiamente criticata dai fan, portando alla successiva pubblicazione di una Director''s Cut in home video che ripristinava circa venti minuti di materiale inedito e modificava la struttura narrativa.', 'Commento audio del regista e sceneggiatore nel DVD dell''edizione Director''s Cut', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:37:41.621922+00:00'),
('c66fa946-6904-420b-9edb-abad47292114', 53, 'Casting & Scelte', 'Il ritorno mancato di Elizabeth Russell', 'Nelle prime fasi di sviluppo della sceneggiatura, si valutò il ritorno di Sheilaish Lambert o di altri personaggi storici dei precedenti film, ma gli sceneggiatori optarono per introdurre nuovi volti legati al passato di Connor e Duncan, come Kate/Faith, interpretata da Lisa Barbuscia.', 'Note di produzione e bozze preliminari della sceneggiatura', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:37:41.621922+00:00'),
('9602e804-cc67-4748-8516-685526de2a8f', 53, 'Aneddoti dal set', 'La cicatrice di Donnie Yen e le coreografie marziali', 'Donnie Yen, che interpreta l''immortale Jin Virk, non fu solo attore ma contribuì attivamente alla stilizzazione dei combattimenti corpo a corpo e con la spada, fondendo lo stile tradizionale di Highlander con le arti marziali asiatiche. Durante le prove, si verificarono piccoli incidenti a causa della velocità dei fendenti eseguiti da Yen e Adrian Paul.', 'Intervista al making-of inclusa nell''edizione speciale home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:37:41.621922+00:00'),
('72a4ae04-35e7-4e29-bbc9-c15fe250d471', 53, 'Segreti di produzione', 'La ricostruzione di New York nei teatri di posa rumeni', 'Gran parte delle sequenze ambientate nella New York contemporanea non furono girate nella metropoli americana, ma ricostruite nei famosi studi MediaPro a Bucarest, in Romania. Gli scenografi dovettero ricreare strade, vicoli e dettagli urbani americani utilizzando set in scala e facciate mobili.', 'Reportage dal set e documentario sulla produzione rumena', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:37:41.621922+00:00'),
('d0fbe25f-7dbb-4d5a-912a-c1da50d337e8', 53, 'Effetti speciali & Trucco', 'L''uso esteso di stunt double per le scene d''azione', 'A causa della complessità delle sequenze di lotta e dei salti mortali eseguiti dai vari Immortali, la troupe degli stunt coordinata da Doug Aarniokoski fece un uso massiccio di cavi e tappeti di protezione digitalmente rimossi in post-produzione. Christopher Lambert, per le riprese ravvicinate, utilizzò spade alleggerite in alluminio e fibra di vetro per evitare infortuni.', 'Featurette sugli effetti visivi e stunt work del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:37:41.621922+00:00'),
('d3efaf85-a31a-408f-a6ea-76076c887b89', 58, 'Aneddoti dal set', 'La temporanea chiusura delle riprese per uragani', 'Durante la lavorazione alle isole Bahamas e Dominica, la produzione fu costretta a interrompere temporaneamente le riprese e a evacuare parte della troupe a causa del passaggio devastante di uragani tropicali, che danneggiarono alcune delle scenografie costiere costruite appositamente.', 'Documentario ufficiale ''Making of Dead Man''s Chest'' e note di produzione Disney', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:38:05.186276+00:00'),
('ac333a7b-2ef8-464e-ab76-e8a149315528', 35, 'Curiosità & Retroscena', 'La delusione di Christopher Lee per il taglio di Saruman', 'Christopher Lee rimase profondamente amareggiato quando la sequenza della morte di Saruman alla Torre di Orthanc fu completamente tagliata dalla versione cinematografica distribuita nelle sale nel 2003, spingendolo persino a disertare la prima mondiale del film a Londra.', 'Intervista ufficiale a Christopher Lee per Daily Telegraph', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:36:52.595712+00:00'),
('5b2d39f6-8064-4986-bd91-4bf38c6bd263', 35, 'Segreti di produzione', 'I costumi extra large per la scala di Minas Morgul', 'Per enfatizzare la fragilità e la piccolezza di Frodo e Sam mentre affrontano la spaventosa scala che conduce a Minas Morgul, il reparto costumi creò versioni ingigantite delle armature e degli abiti dei due hobbit da far indossare alle controfigure e ai pupazzi.', 'Weta Workshop: Design and Making of The Lord of the Rings', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:36:52.595712+00:00'),
('65246cfc-ac0a-45a8-8cad-c723daae6a49', 35, 'Effetti speciali & Trucco', 'L''uso massiccio di comparse digitali nel ''Massive''', 'Per la grandiosa battaglia finale ai Cancelli Neri, la Weta Digital impiegò in modo massiccio il software proprietario ''MASSIVE'', in grado di generare migliaia di guerrieri digitali dotati di intelligenza artificiale autonoma per combattere individualmente sullo schermo.', 'Documentario sui VFX di The Return of the King', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:36:52.595712+00:00'),
('5db250f3-d505-45a7-82ee-31741715cdf3', 35, 'Citazioni & Easter Egg', 'Il cameo dei figli di Peter Jackson come rifugiati', 'I figli del regista Peter Jackson, Katie e Billy Jackson, compiono una breve apparizione nel film interpretando due giovani rifugiati di Rohan che cercano riparo all''interno delle caverne di Helm''s Deep / Minas Tirith nelle scene corali.', 'Credits ufficiali del film e Appendici DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:36:52.595712+00:00'),
('30389f17-7649-40cf-a7be-e9fcc9a3e5f8', 35, 'Aneddoti dal set', 'Sean Astin e la reale ferita da vetro sulla spiaggia', 'Durante la drammatica scena in cui Samwise Gamgee viene allontanato da Frodo e cammina da solo sulla spiaggia, Sean Astin calpestò un pezzo di vetro nascosto nella sabbia che gli trapassò il piede da parte a parte, richiedendo un intervento medico urgente sul set.', 'Making-of ufficiale della produzione - National Geographic Special', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:36:52.595712+00:00'),
('e21ae854-8714-4d84-8fc4-201c441f3491', 51, 'Casting & Scelte', 'L''ispirazione per il look nomade di Captain America', 'Per il look di Steve Rogers, i fratelli Russo e i reparti artistici si sono ispirati direttamente alla versione ''Nomad'' dei fumetti, eliminando la stella dal petto e sporcando l''uniforme per riflettere lo status di fuorilegge del personaggio dopo gli eventi di ''Captain America: Civil War''.', 'Visual Dictionary ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:37:35.314163+00:00'),
('47882434-3914-44b6-86cb-22cb3b3d547a', 51, 'Aneddoti dal set', 'La sequenza di Edinburgh girata parzialmente dal vivo', 'L''attacco a Visione e Wanda a Edimburgo è stato girato in gran parte on location nella storica Royal Mile, costringendo la produzione a coordinare complesse acrobazie con cavi nel mezzo di una delle zone più trafficate della città scozzese.', 'Note di produzione Marvel Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:37:35.314163+00:00'),
('fb23627a-5e2f-4072-9763-608f0f9069a2', 51, 'Curiosità & Retroscena', 'Il destino improvvisato del Collezionista', 'La scena in cui Thanos interroga Il Collezionista (Benicio Del Toro) a Knowhere è stata girata sfruttando una complessa proiezione olografica in CGI per simulare la realtà alterata creata dalla Pietra della Realtà, con Del Toro che ha dovuto recitare in un set quasi completamente vuoto.', 'Commento audio del Blu-ray dei fratelli Russo', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:37:35.314163+00:00'),
('5cf05cdc-7316-4b90-83e4-fa61ada711bd', 51, 'Segreti di produzione', 'La creazione dei suoni dell''ascia Stormbreaker', 'Per creare il suono unico dell''impatto e del lancio di Stormbreaker, il supervisore del montaggio sonoro Shannon Mills ha combinato registrazioni di urla di animali, lamiere metalliche contorte e persino il rumore di alberi che si spezzano durante una tempesta.', 'Intervista a SoundWorks Collection', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:37:35.314163+00:00'),
('4c02f6a8-52d1-4a02-b4fc-4443c5d9be55', 51, 'Casting & Scelte', 'Il cameo nascosto di Sylvester Stallone mancato', 'Sebbene Sylvester Stallone fosse apparso in ''Guardiani della Galassia Vol. 2'' nei panni di Stakar Ogord, i registi valutarono inizialmente di inserire il suo personaggio nel gruppo di supporto cosmico, idea poi scartata per mantenere il focus narrativo sui personaggi principali.', 'Intervista agli sceneggiatori Christopher Markus e Stephen McFeely', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:37:35.314163+00:00'),
('3cea23df-1af7-4e70-9b6a-fa07f81afa57', 54, 'Segreti di produzione', 'La statua di Rocky e la sua permanenza a Filadelfia', 'La celebre statua in bronzo di Rocky Balboa fu commissionata da Sylvester Stallone alla fine delle riprese di Rocky III, ma dopo la conclusione della saga fu donata alla città di Filadelfia. A causa di accese discussioni sul fatto che fosse un''opera d''arte o un semplice oggetto di scena cinematografico, fu inizialmente spostata davanti al Wachovia Spectrum prima di trovare la sua collocazione definitiva in cima alla scalinata del Philadelphia Museum of Art.', 'Archivio storico della città di Filadelfia e note di produzione United Artists', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:37:47.810383+00:00'),
('1aa38317-56c9-477d-846f-7dcb5973587d', 54, 'Aneddoti dal set', 'Il giubbotto di pelle e la tartaruga di Adriana', 'Il celebre giubbotto di pelle nera che Rocky indossa per gran parte del film e le due tartarughe domestiche di Adriana, di nome Cuff e Link, appartenevano realmente a Sylvester Stallone nella vita di tutti i giorni prima dell''inizio delle riprese. A causa del budget estremamente ridotto della produzione (circa 1 milione di dollari), Stallone decise di utilizzare i propri oggetti personali per risparmiare sui costi di reparto.', 'Commento audio ufficiale del regista e del cast nell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:37:47.810383+00:00'),
('32a07656-55ef-46fb-8bd2-8d32e02dd169', 54, 'Curiosità & Retroscena', 'L''improvvisazione della battuta sulla carne nel mattatoio', 'La celebre scena in cui Rocky colpisce i quarti di bue nel mattatoio di Paulie non era stata originariamente provata con quella specifica intensità. Durante le riprese, lo stunt coordinator e i tecnici dovettero aggiungere imbottiture speciali ai ganci di carne per evitare che Stallone si ferisse gravemente le mani a causa dei pugni sferrati senza protezione adeguata.', 'Documentario ''The Making of Rocky: In the Ring'' del 2000', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:37:47.810383+00:00'),
('3eda49ff-1fe5-4cbd-9310-61f257ed9ba6', 54, 'Casting & Scelte', 'La comparsa di Lloyd Kaufman nei panni di un ubriaco', 'Lloyd Kaufman, co-fondatore della celebre casa di produzione indipendente Troma e amico di lunga data di Sylvester Stallone, appare brevemente nel film in un piccolo cammeo non accreditato nei panni di un ubriaco che barcolla per strada durante le sequenze notturne a Filadelfia.', 'Autobiografia di Lloyd Kaufman e crediti di produzione indipendenti', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:37:47.810383+00:00'),
('cd851306-6422-48b0-970e-0a2c19b566d0', 54, 'Segreti di produzione', 'L''uso innovativo della Steadicam con Garrett Brown', 'Rocky è stato uno dei primi film nella storia del cinema a sfruttare l''invenzione della Steadicam, creata da Garrett Brown. Grazie a questo dispositivo stabilizzato, la troupe ha potuto seguire Stallone in corsa lungo le strade di Filadelfia e su per la scalinata del museo senza i sussulti tipici delle cineprese a spalla tradizionali.', 'Documentario tecnico sulla storia della Steadicam e interviste a Garrett Brown', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:37:47.810383+00:00'),
('4eac159c-f40b-41dd-bc5d-73e3fa26fce8', 37, 'Casting & Scelte', 'Il rifiuto iniziale di Mick Jagger', 'Prima che Malcolm McDowell venisse scelto definitivamente per il ruolo di Alex, i Rolling Stones (con Mick Jagger in testa) tentarono di acquisire i diritti del romanzo di Anthony Burgess per farne un film psichedelico interpretato dalla celebre band rock britannica. Il progetto fu rapidamente accantonato quando Kubrick subentrò nella produzione.', 'Archivi storici di Anthony Burgess e biografie di Stanley Kubrick', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:37:01.932618+00:00'),
('105a58b0-ec56-4745-9f96-ed763336522b', 37, 'Effetti speciali & Trucco', 'Il falso serpente e la vera paura', 'Il serpente domestico di Alex, chiamato ''Basil'', era un vero boa constrictor utilizzato sul set. Durante le riprese delle scene in cui l''animale si avvolgeva attorno al collo di Malcolm McDowell, l''attore, pur non amando i rettili, dovette mantenere la calma mentre il serpente stringeva la presa inaspettatamente.', 'Interviste sul set e retroscena d''archivio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:37:01.932618+00:00'),
('e688ed35-d545-4be8-a3ec-9c724fd0b55e', 48, 'Curiosità & Retroscena', 'La gestazione ultradecennale del progetto', 'Béla Tarr cercò di portare sul grande schermo il romanzo omonimo di László Krasznahorkai sin dalla pubblicazione del libro nel 1985, ma le autorità comuniste ungheresi e la cronica mancanza di finanziamenti bloccarono la produzione per quasi dieci anni.', 'Note di produzione ufficiali e retrospettive cinematografiche', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:37:22.442619+00:00'),
('0f1b3f76-93a5-4e95-8cb3-befaf8baf70f', 48, 'Segreti di produzione', 'La troupe ridotta all''osso', 'Durante le riprese, protrattesi per oltre un anno e mezzo a causa della necessità di attendere le condizioni meteorologiche adatte (soprattutto fango e pioggia persistente), Béla Tarr lavorò con una troupe microscopica, composta quasi esclusivamente da amici e collaboratori di strettissima fiducia.', 'Interviste d''archivio al regista e al direttore della fotografia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:37:22.442619+00:00'),
('30fa3d7c-e679-446a-9409-1318a61b4f16', 48, 'Casting & Scelte', 'L''utilizzo quasi esclusivo di attori non professionisti', 'Gran parte degli abitanti del villaggio e dei compari che seguono Irimiás non furono scelti tra gli attori professionisti del teatro ungherese, bensì reclutati direttamente da Tarr in contesti rurali e marginali per donare al film un realismo crudo e tangibile.', 'Documentario sul making-of e recensioni critiche storiche', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:37:22.442619+00:00'),
('56b8c72e-a4d5-45bd-a1bb-3232843e39ea', 48, 'Aneddoti dal set', 'La famosa sequenza della campana e la gestione del tempo reale', 'La celebre e ipnotica sequenza in cui i personaggi camminano interminabilmente nella nebbia e nel fango fu girata con lunghissimi piani sequenza senza tagli, costringendo gli attori a mantenere la massima concentrazione fisica in condizioni climatiche estenuanti.', 'Commento audio del regista e analisi tecniche di pellicola', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:37:22.442619+00:00'),
('52850612-9532-462d-8013-ce356d7546c4', 48, 'Segreti di produzione', 'Il montaggio fiume durato anni', 'Il meticoloso processo di montaggio, curato personalmente da Béla Tarr insieme alla moglie e collaboratrice Ágnes Hranitzky, richiese tantissimo tempo proprio a causa della durata complessiva di oltre sette ore e della scelta di preservare ogni minimo respiro dei lunghi piani sequenza.', 'Archivio storico della Biennale di Berlino e note di edizione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:37:22.442619+00:00'),
('de577cda-4273-402a-b1e0-1fd1d58a1a84', 61, 'Aneddoti dal set', 'L''infortunio di Johnny Depp e lo stop alle riprese in Australia', 'Nel marzo del 2015, durante le riprese nel Queensland, Johnny Depp subì un infortunio alla mano che richiese il suo ritorno temporaneo negli Stati Uniti per un intervento chirurgico. Questo incidente costrinse la produzione a fermare il lavoro sul set per circa un mese, coinvolgendo quasi duecento membri della troupe che rimasero inattivi in attesa del ritorno del protagonista.', 'Comunicati stampa di produzione e report di Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:38:18.939186+00:00'),
('1c5b677f-6231-4e6a-946c-1079b3ff3368', 61, 'Casting & Scelte', 'La rielaborazione del personaggio di Carina Smyth', 'Prima che Kaya Scodelario ottenesse ufficialmente la parte di Carina Smyth, la produzione valutò diverse giovani attrici di calibro internazionale, tra cui Gabriella Wilde, Gemma Arterton, Keira Knightley (per un possibile cameo poi non concretizzato in quel modo) e Lucy Boynton. Il ruolo fu modificato in fase di pre-produzione per accentuare le competenze scientifiche e l''indipendenza del personaggio rispetto ai canoni dei capitoli precedenti.', 'Note di produzione ufficiali della Disney', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:38:18.939186+00:00'),
('cda57921-6693-49cb-a06c-c39875490fc9', 61, 'Effetti speciali & Trucco', 'Il trucco prostetico avanzato per Javier Bardem', 'Per trasformare Javier Bardem nel capitano non-morto Armando Salazar, il team di truccatori guidato da Peter Swords King ha impiegato fino a tre ore di applicazione quotidiana per le protesi facciali in silicone e le cicatrici necrotiche. Le ferite aperte e i dettagli di putrefazione sul volto dell''attore sono stati combinati con interventi di pulizia digitale in post-produzione per accentuare l''aspetto spettrale.', 'Making-of ufficiale e interviste al reparto trucco', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:38:18.939186+00:00'),
('a0cfa609-08f2-4eb5-8fb5-83f1a41e5b10', 72, 'Segreti di produzione', 'La finta locandina di Blue Harvest', 'Per evitare speculazioni e l''assalto dei fan o dei media durante le riprese iniziali nel deserto dello Utah, la produzione si finse una troupe indipendente impegnata in un film horror a basso budget intitolato ''Blue Harvest: Horror Beyond Imagination''. Tale titolo fittizio fu stampato perfino sulle felpe e sulle t-shirt della troupe.', 'Documentario ''Classic Creatures: Return of the Jedi''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:39:05.374409+00:00'),
('c8051d82-e46f-46bf-8571-1c9d9dffb3f5', 72, 'Casting & Scelte', 'Il rifiuto di Steven Spielberg alla regia', 'George Lucas avrebbe voluto originariamente che Steven Spielberg dirigesse il film. Tuttavia, a causa dei dissidi passati di Lucas con la Directors Guild of America legati alla gestione dei crediti d''apertura de ''L''Impero colpisce ancora'', Spielberg non poté accettare l''incarico per via delle regole sindacali.', 'Archivi storici di Lucasfilm e interviste retrospettive', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:39:05.374409+00:00'),
('e7162921-8986-44f3-898a-a784c0fd44cd', 72, 'Casting & Scelte', 'La morte riscritta di Han Solo', 'Nelle prime fasi di stesura della sceneggiatura, Harrison Ford era favorevole alla morte di Han Solo alla fine del film per dare maggiore drammaticità alla trilogia. George Lucas e gli sceneggiatori si opposero fermamente, ritenendo che avrebbe danneggiato la vendita del merchandising e la chiusura della favola.', 'Intervista a Harrison Ford per i commenti audio e late-night show', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:39:05.374409+00:00'),
('f288a486-7a1f-418e-bd30-4fd5527afd4b', 44, 'Casting & Scelte', 'La pistola di Bond e il cambio drastico', 'Nel romanzo di Ian Fleming, James Bond usa una pistola Beretta calibro .25. Sul set, l''esperto di armi Geoffrey Boothroyd scrisse a Fleming criticando aspramente la scelta, definendola un''arma adatta a una signora, e suggerì invece la Walther PPK, che divenne poi il leggendario marchio di fabbrica cinematografico di 007.', 'Libro di Ian Fleming e note di produzione ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:37:07.006731+00:00'),
('d8465c08-7972-444d-96c1-7b58b723974c', 44, 'Aneddoti dal set', 'La ragnatela e la tarantola vera', 'Durante la famosa scena in cui una tarantola cammina sul petto di Sean Connery, l''attore aveva preteso un pannello di plexiglas di protezione tra la sua pelle e il ragno. Il regista Terence Young girò i primi piani rimuovendo il vetro per aumentare il realismo, costringendo Connery a recitare terrorizzato.', 'Documentario ufficiale ''Inside Dr. No''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:37:07.006731+00:00'),
('1019b8ec-623b-45ad-bcbd-ad6fb5865843', 44, 'Segreti di produzione', 'L''improvvisazione della voce di Ursula Andress', 'L''attrice svizzera Ursula Andress aveva un forte accento tedesco e una padronanza limitata dell''inglese all''epoca delle riprese. Per il suo ruolo di Honey Ryder, la sua voce fu interamente doppiata in post-produzione dall''attrice Nikki van der Zyl, mentre le sue canzoni furono cantate da Diana Coupland.', 'Archivi di post-produzione Eon Productions', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:37:07.006731+00:00'),
('ad6bd197-c5ef-4e88-94a3-47ac5843b617', 44, 'Segreti di produzione', 'Il budget ridotto e la scenografia economica', 'Il film fu realizzato con un budget estremamente limitato di circa un milione di dollari. Lo scenografo Ken Adam, alla sua prima grande produzione, dovette inventarsi soluzioni ingegnose e minimaliste, come la stanza del Dr. No con il finto acquario protetto da vetro antiproiettile che in realtà conteneva semplici pesci rossi ingranditi da lenti.', 'Commento audio del regista Terence Young e Ken Adam', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:37:07.006731+00:00'),
('40d14985-11da-45e2-872c-571822fbf0c5', 44, 'Casting & Scelte', 'Il rifiuto di Patrick McGoohan', 'Prima che la scelta ricadessi definitivamente su Sean Connery, i produttori Albert R. Broccoli e Harry Saltzman offrirono il ruolo di James Bond all''attore britannico Patrick McGoohan, celebre per le serie TV ''Il pericolo esce di scena'' e ''Il prigioniero'', ma egli rifiutò l''offerta.', 'Biografie ufficiali e interviste a Albert R. Broccoli', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:37:07.006731+00:00'),
('08cb0597-c8ea-4763-bf1d-eed00e74705e', 44, 'Effetti speciali & Trucco', 'La finta esplosione nucleare finale', 'Per la sequenza finale in cui la base segreta di Crab Key salta in aria, la troupe non aveva a disposizione un budget per grandi effetti visivi digitali o esplosioni su scala reale. Vennero utilizzate riprese in miniatura realizzate negli studi Pinewood e filmati di repertorio di veri test nucleari montati abilmente nel climax.', 'Making-of storico e archivi degli studi Pinewood', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:37:07.006731+00:00'),
('2c4ca3a6-fc90-40bc-b0c2-13977c62547d', 44, 'Costumi & Oggetti di scena', 'Il costume storico di Ursula Andress', 'Il celebre bikini bianco indossato da Ursula Andress mentre emerge dalle acque della Giamaica fu disegnato dall''attrice stessa in collaborazione con il regista Terence Young. L''indumento divenne un''icona pop mondiale e, all''asta da Christie''s nel 2001, fu venduto per oltre 60.000 dollari.', 'Cataloghi d''asta Christie''s e archivi di moda cinematografica', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:37:07.006731+00:00'),
('d9db74b9-25ce-48c5-b360-6d15cd784a60', 49, 'Casting & Scelte', 'La riscrittura notturna di Joss Whedon', 'La notte prima dell''inizio delle riprese, il regista Joss Whedon si rese conto che la sceneggiatura non offriva abbastanza spazio emotivo per legare tutti gli eroi. Lavorò tutta la notte con lo sceneggiatore Zak Penn e i produttori per riscrivere gran parte dei dialoghi e delle dinamiche di gruppo.', 'Commento audio del regista nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:37:26.970284+00:00'),
('1d50558e-9875-422d-90c2-528a9813cd40', 49, 'Casting & Scelte', 'Edward Norton e il cambio di ruolo', 'Edward Norton avrebbe dovuto riprendere il ruolo di Bruce Banner/Hulk dopo il film del 2008, ma iMarvel Studios decisero di sostituirlo con Mark Ruffalo a causa di divergenze creative sul controllo del personaggio e sulla direzione della sceneggiatura.', 'Comunicato ufficiale dei Marvel Studios e interviste a Kevin Feige', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:37:26.970284+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('b8e937b4-a78b-418d-8547-17b706344733', 49, 'Aneddoti dal set', 'Tom Hiddleston e le percosse reali di Chris Hemsworth', 'Durante la sequenza in cui Thor affronta Loki, Tom Hiddleston chiese a Chris Hemsworth di colpirlo davvero con il martello per rendere la scena più realistica. Hemsworth rifiutò inizialmente, ma Hiddleston insistette, finendo per subire un colpo doloroso che richiese una pausa sul set.', 'Intervista a Tom Hiddleston al The Graham Norton Show', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:37:26.970284+00:00'),
('c013a281-7f89-4ca1-8e1b-6cfe76eb7cf1', 49, 'Segreti di produzione', 'Il costume scomodo di Captain America', 'Chris Evans ha più volte dichiarato che il costume di Captain America in questo film era estremamente rigido e caldo, dotato di un sistema di aerazione così inefficace che l''attore rischiava spesso il colpo di calore durante le scene d''azione più concitate a New York.', 'Intervista a Chris Evans per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:37:26.970284+00:00'),
('f1b23a89-9b06-4087-8639-57a0bbaec831', 49, 'Effetti speciali & Trucco', 'La tuta per la motion capture di Mark Ruffalo', 'A differenza dei precedenti interpreti di Hulk, Mark Ruffalo ha recitato direttamente sul set indossando una tuta grigia per il motion capture dotata di telecamere facciali dedicate, permettendo così di catturare le sue reali micro-espressioni e tradurle sul volto del Golia Verde.', 'Documentario sul making-of presente nell''edizione home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:37:26.970284+00:00'),
('5a94fa22-2322-43e5-9155-406c62787181', 49, 'Citazioni & Easter Egg', 'Omaggio a Black Sabbath in cucina', 'Nella scena in cui Bruce Banner indossa una giacca scura con il colletto alzato mentre parla con Tony Stark, la maglietta che si intravede sotto riporta il logo della celebre band Black Sabbath, un chiaro omaggio alla loro storica canzone ''Iron Man''.', 'Analisi ufficiale degli Easter Egg del film su Marvel.com', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:37:26.970284+00:00'),
('0f6d8b73-0b3e-4f4a-bcee-a9fcae0b39ec', 49, 'Aneddoti dal set', 'L''improvvisazione del braccio bionico', 'La famosa battuta in cui Tony Stark definisce Loki ''un re dei formiche'' e discute con gli altri eroi fu in gran parte arricchita da battute estemporanee di Robert Downey Jr., il quale portava regolarmente foglietti con battute scritte dai suoi autori personali nascosti sul set.', 'Note di produzione e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:37:26.970284+00:00'),
('ee802deb-244f-4207-abac-7e6554b72d7f', 62, 'Aneddoti dal set', 'La polvere di cocaina finta', 'Le scene in cui i personaggi inalano cocaina sono state girate utilizzando Vitamina B in polvere e zucchero a velo. Jonah Hill ha rivelato che l''inalazione continua di questa sostanza durante le riprese gli ha causato una bronchite che lo ha costretto a tre settimane di ricovero ospedaliero.', 'Intervista a Jonah Hill su The Daily Show', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:38:24.431243+00:00'),
('9eabda09-6e01-4a9e-bd88-e31ed85c4473', 45, 'Segreti di produzione', 'L''automobile truccata di James Bond', 'La celebre Aston Martin DB5 utilizzata nel film era equipaggiata con gadget reali progettati dal premio Oscar John Stears, tra cui targhe girevoli, sedili eiettabili e cortine fumogene. Per sostenere il peso extra delle modifiche meccaniche e delle corazze d''acciaio, la casa automobilistica dovette fornire vetture prototipo rinforzate con sospensioni speciali.', 'Note di produzione e archivi tecnici EON Productions', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:37:11.590881+00:00'),
('8b8ccf52-9948-48fc-94b5-c1230d110fbc', 45, 'Casting & Scelte', 'Il rifiuto del regista Orson Welles', 'Prima di ingaggiare Gert Fröbe, i produttori Albert Broccoli e Harry Saltzman tentarono a lungo di scritturare Orson Welles per il ruolo del cattivo principale Auric Goldfinger. La trattativa fallì miseramente a causa delle richieste economiche esorbitanti avanzate dall''autore di ''Quarto potere''.', 'Biografia ufficiale di Albert R. Broccoli ''When the Snow Melts''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:37:11.590881+00:00'),
('108b0715-b497-44c2-be90-64d4d3ef7a21', 45, 'Effetti speciali & Trucco', 'La finta distruzione di Fort Knox', 'Poiché il governo degli Stati Uniti negò categoricamente l''autorizzazione a effettuare riprese cinematografiche all''interno o nei pressi della vera riserva aurea di Fort Knox, lo scenografo Ken Adam fu costretto a ricostruire l''intero complesso e il deposito interno interamente in studio su scala ridotta.', 'Commento audio del regista Guy Hamilton nel DVD speciale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:37:11.590881+00:00'),
('d4e8afd6-e667-44bd-81b5-ca552d447e67', 45, 'Curiosità & Retroscena', 'Il nome scandaloso di Pussy Galore', 'I dirigenti della censura americana della MPAA tentarono in tutti i modi di imporre il cambio del nome del personaggio di Pussy Galore, ritenuto eccessivamente volgare e osceno per il pubblico del 1964. I produttori resistettero fermamente alle pressioni e il nome rimase inalterato, diventando uno dei marchi di fabbrica del film.', 'Archivi storici di censura cinematografica e carteggi di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:37:11.590881+00:00'),
('52d04cb2-547a-435f-9de5-9ca0bde78066', 50, 'Casting & Scelte', 'La gravidanza nascosta di Scarlett Johansson', 'Durante la produzione del film, Scarlett Johansson era incinta. Per permetterle di completare le riprese senza che la gravidanza risultasse evidente nei panni della Vedova Nera, la produzione ha impiegato tre stunt-woman identiche e utilizzato complesse tecniche di CGI per rimuovere il pancione in post-produzione.', 'Entertainment Weekly / Note di produzione ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:37:31.812285+00:00'),
('a782dd3a-8b72-4ffe-bb98-2ec90a9ba9ee', 50, 'Casting & Scelte', 'Il cameo mancato di Tom Hiddleston come Loki', 'Tom Hiddleston aveva originariamente girato un cameo nei panni di Loki per la sequenza della visione di Thor guidata da Heimdall. Tuttavia, la scena fu tagliata dal montaggio finale perché i test screening indicarono che il pubblico si confondeva, pensando che Loki fosse il vero burattinaio dietro le azioni di Ultron.', 'Commento audio del regista Joss Whedon', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:37:31.812285+00:00'),
('8d61b3bf-2025-418b-8edd-b5ddff59bf3c', 50, 'Aneddoti dal set', 'La scena della festa e il martello di Thor', 'Durante la scena in cui gli Avengers cercano a turno di sollevare il Mjolnir nel soggiorno di Tony Stark, Chris Hemsworth ha improvvisato la sua reazione di genuino shock quando capisce che Steve Rogers sta effettivamente riuscendo a muovere il martello.', 'Featurette ''Assembling the Universe'' nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:37:31.812285+00:00'),
('f863382d-bab2-4c67-b200-79c0217e2a79', 50, 'Effetti speciali & Trucco', 'L''uso estensivo delle tute per il motion capture di Ultron', 'James Spader, interprete di Ultron, indossava una tuta per il motion capture dotata di due grandi antenne luminose sulla testa. Queste servivano agli altri attori per mantenere la corretta linea di sguardo, dato che Ultron nel film è molto più alto rispetto all''attore.', 'Making-of ufficiale ''From the Ashes''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:37:31.812285+00:00'),
('1bebeec1-4860-4691-b1fd-42a2467908af', 50, 'Citazioni & Easter Egg', 'Il riferimento a Stan Lee nel caos cittadino', 'Durante la sequenza in cui gli Avengers evacuano i civili a Sokovia, Stan Lee appare nei panni di un veterano della Seconda Guerra Mondiale che beve un liquore troppo forte offerto da Thor, pronunciando la sua celebre battuta ''Excelsior!'' prima di essere portato via barcollando.', 'Analisi ufficiale Easter Egg Marvel Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:37:31.812285+00:00'),
('c3e45be1-6ac7-4a0a-aa9d-5a4dbe5b06bd', 50, 'Segreti di produzione', 'La creazione fisica della culla di rigenerazione di Visione', 'La ''culla'' in cui viene creato Visione utilizzando il vibranio non era interamente generata al computer: la scenografia ha realizzato un imponente oggetto di scena meccanico con veri circuiti interni ed elementi illuminati a LED per permettere agli attori di interagire fisicamente sul set.', 'Art of the Movie Book - Marvel''s Avengers: Age of Ultron', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:37:31.812285+00:00'),
('ede04b18-c2f2-4131-b738-3e1efcce54ef', 50, 'Effetti speciali & Trucco', 'La cicatrice e il trucco di Aaron Taylor-Johnson', 'Per interpretare Quicksilver (Pietro Maximoff), Aaron Taylor-Johnson ha dovuto sottoporsi a lunghe sedute giornaliere di trucco per applicare cicatrici temporanee e polvere da sparo finta sul viso, riflettendo lo stile di vita ribelle e da guerriglieri condotto dai gemelli in Europa dell''Est.', 'Intervista al reparto trucco e parrucco', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:37:31.812285+00:00'),
('23dddbdd-1fdb-4fc4-9f89-95f21ac47896', 323, 'Aneddoti dal set', 'La pistola in faccia a Leonardo DiCaprio', 'Durante la celebre scena in cui Jack Nicholson punta una pistola contro Leonardo DiCaprio nell''ufficio abbandonato, Nicholson improvvisò gran parte dei gesti minacciosi e della tensione fisica senza avvisare il collega. Lo spavento e la reazione di DiCaprio furono autentici, poiché Scorsese voleva catturare una sorpresa genuina sul volto dell''attore.', 'Special ''The Making of The Departed'' nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:51:09.572055+00:00'),
('28ff1636-3565-4db1-9787-9ebd0d865824', 323, 'Citazioni & Easter Egg', 'Il riferimento alla ''X'' nei film di gangster', 'Martin Scorsese ha inserito un esplicito omaggio al classico ''Scarface'' del 1932 diretto da Howard Hawks: in molte scene chiave del film, in particolare quelle che anticipano la morte dei personaggi o tradimenti imminenti, compaiono delle ''X'' nascoste nell''inquadratura, impiegate come firma visiva premonitrice.', 'Analisi visiva e intervista al montatore Thelma Schoonmaker', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:51:09.572055+00:00'),
('3ba9feea-5760-4ec1-86ac-58a324a401cb', 323, 'Casting & Scelte', 'Il ruolo di Mark Wahlberg basato su poliziotti reali', 'Mark Wahlberg ha ottenuto una candidatura all''Oscar per il ruolo del sergente Dignam attingendo direttamente alle esperienze e al linguaggio scurrile dei veri agenti di polizia di Boston da lui conosciuti durante la giovinezza trascorsa nei quartieri difficili della città.', 'Intervista promozionale a Mark Wahlberg per Rolling Stone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:51:09.572055+00:00'),
('36ecaa28-e381-48d5-a578-0ead181226f6', 341, 'Curiosità & Retroscena', 'Il think tank futuristico', 'Nel 1999, prima di iniziare la pre-produzione, Steven Spielberg organizzò un vertice di tre giorni a Santa Monica riunendo quindici esperti tra futurologi, urbanisti, ingegneri e scrittori di fantascienza, tra cui Peter Schwartz e Jaron Lanier, per delineare il mondo credibile del 2054 mostrato nel film.', 'Documentario ''The Making of Minority Report'' / Note di produzione ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:51:59.858683+00:00'),
('699d9679-d891-4d2f-8411-2e22d31f1c22', 46, 'Curiosità & Retroscena', 'Il record di parolacce nella sceneggiatura', 'Il film stabilì un record non ufficiale per l''uso della parola ''fuck'' (e derivati), pronunciata ben 422 volte nel corso della pellicola, superando ampiamente i precedenti film di gangster di Scorsese come ''Quei bravi ragazzi'' e piazzandosi tra i lungometraggi mainstream più scurrile della storia del cinema all''epoca.', 'Note di produzione e analisi lessicale cinematografica', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:37:15.781084+00:00'),
('f6093d5d-d694-44bf-ab7f-eaeaa424cf98', 46, 'Casting & Scelte', 'Il rifiuto iniziale di Madonna per il ruolo di Ginger', 'Prima che Sharon Stone ottenesse la parte e la sua celebre candidatura all''Oscar, la produzione prese in seria considerazione popstar e attrici di altissimo profilo, tra cui Madonna, che fu scartata o rinunciò a causa di conflitti di programmazione, aprendo la strada alla trionfale performance della Stone.', 'Archivi di casting di Hollywood e biografie di Martin Scorsese', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:37:15.781084+00:00'),
('9818105c-a2de-4c52-9b6e-f4c6f46e6e06', 46, 'Curiosità & Retroscena', 'Il vero nome dei personaggi modificato per motivi legali', 'Nonostante il film sia tratto dal libro-inchiesta di Nicholas Pileggi e basato su fatti reali, i nomi dei protagonisti furono cambiati (Frank ''Lefty'' Rosenthal divenne Sam Rothstein, Anthony Spilotro divenne Nicky Santoro) per evitare possibili azioni legali da parte dei reali soggetti coinvolti o delle famiglie legate alla mafia di Chicago.', 'Intervista a Nicholas Pileggi per il making-of ''The Making of Casino''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:37:15.781084+00:00'),
('8b547ff6-d248-41d3-b165-96032c702b5e', 46, 'Effetti speciali & Trucco', 'La parrucca da 10.000 dollari di Sharon Stone', 'Per rispecchiare i continui e sfarzosi cambi di look di Ginger nel corso degli anni ''70 e ''80, la reparto costumi e trucco utilizzò decine di parrucche personalizzate dal costo complessivo di migliaia di dollari, permettendo all''attrice di trasformarsi visivamente in modo drastico senza dover danneggiare i propri capelli con tinte quotidiane.', 'Documentario sui costumi nel Blu-ray di Casino', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:37:15.781084+00:00'),
('63590075-bce5-4ccb-9011-1618cba290f4', 46, 'Citazioni & Easter Egg', 'Il cameo dei veri mafiosi sul set', 'Alcune comparse ed ex criminali realmente legati alla malavita di Las Vegas e Chicago negli anni d''oro furono assunti come consulenti sul set e apparvero persino in piccoli ruoli di sfondo, aggiungendo un livello di inquietante realismo alle scene nei retrobottega dei casinò.', 'Aneddoti di produzione e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:37:15.781084+00:00'),
('18786725-140e-4c84-b645-b0210b1493bd', 78, 'Effetti speciali & Trucco', 'La voce di Darth Vader assemblata digitalmente', 'Per ricreare la voce di Darth Vader in una scena chiave in cui Kylo Ren parla con l''ologramma dell''Imperatore, il sound designer Matthew Wood ha utilizzato una combinazione di registrazioni d''archivio di James Earl Jones e algoritmi vocali avanzati per adattarla all''età dell''attore.', 'Documentario ''The Skywalker Legacy'' allegato all''edizione home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:39:29.099948+00:00'),
('c4bcb447-450d-4eec-ac4d-ae143a2d0c9f', 78, 'Casting & Scelte', 'Lin-Manuel Miranda e il caminetto della Resistenza', 'Il celebre compositore e autore di ''Hamilton'' Lin-Manuel Miranda ha scritto insieme a J.J. Abrams un brano musicale originale per il film ed è apparso personalmente in un cameo nei panni di un membro della Resistenza che festeggia la vittoria finale.', 'Note di produzione ufficiali Lucasfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:39:29.099948+00:00'),
('740b57d6-0273-4900-a4ad-e965df87d7f3', 78, 'Segreti di produzione', 'La polvere di deserto riutilizzata da Una Nuova Speranza', 'Per le scene ambientate sul pianeta Pasaana, la produzione ha girato nel deserto dello Wadi Rum in Giordania, lo stesso paese in cui furono girate le sequenze di Tatooine nel film originale del 1977, creando una continuità geografica voluta da J.J. Abrams.', 'Diario di produzione e interviste alla troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:39:29.099948+00:00'),
('6a13c28f-1cfb-4c22-800e-4616ad76abb8', 78, 'Casting & Scelte', 'Il tributo a Carrie Fisher attraverso la figlia Billie Lourd', 'L''attrice Billie Lourd, figlia della defunta Carrie Fisher, ha indossato fisicamente il costume della Generale Leia Organa in diverse sequenze in cui l''inquadratura non mostrava il volto, fungendo da controfigura per onorare la madre scomparsa.', 'Dichiarazioni ufficiali di J.J. Abrams e Billie Lourd', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:39:29.099948+00:00'),
('4e1e027b-737a-4c1e-9b80-7724c49562e1', 328, 'Citazioni & Easter Egg', 'Il cameo vocale di Ann Robinson e Gene Barry', 'Gli attori protagonisti della celebre versione cinematografica de ''La guerra dei mondi'' del 1953, Gene Barry e Ann Robinson, compaiono in un cameo speciale alla fine del film, interpretando i nonni di Rachel e Robbie.', 'Note di produzione e crediti del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:51:13.293584+00:00'),
('4fca9d3e-e1db-4dd5-8f0a-dedd605b154a', 328, 'Segreti di produzione', 'Il vero aereo fatto a pezzi sul set', 'Per la drammatica scena in cui un Boeing 747 si schianta contro una casa, la produzione ha acquistato un vero aereo commerciale fuori servizio, l''ha smontato in sezioni e l''ha ricostruito nel backlot degli Universal Studios.', 'Documentario ''Designing the Fall'' nel Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:51:13.293584+00:00'),
('d5f2cc25-f8b8-4674-b673-451dabdad795', 328, 'Aneddoti dal set', 'L''improvvisazione sulle urla di Dakota Fanning', 'Per mantenere le reazioni di terrore della giovane Dakota Fanning il più naturali possibili, Spielberg le proibì di vedere preventivamente i concept art completi dei Tripodi e le permetteva di urlare seguendo le indicazioni del regista sul momento.', 'Intervista promozionale a Dakota Fanning e Spielberg', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:51:13.293584+00:00'),
('39cf1c7d-e335-4705-b55b-e3537c3d7206', 328, 'Citazioni & Easter Egg', 'Il tributo a 1941 - Allarme a Hollywood', 'In una sequenza del film, tra le macerie e i detriti della strada si intravede chiaramente la targa di un''automobile con un riferimento numerico nascosto che omaggia la precedente commedia catastrofica diretta da Spielberg nel 1979.', 'Analisi visive dei fan e registri di produzione Universal', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:51:13.293584+00:00'),
('85669e7f-de30-4c7f-8281-b4c1e0100b64', 359, 'Casting & Scelte', 'Il cameo di Martin Landau', 'Il celebre attore Martin Landau appare in un breve ma significativo cameo iniziale nei panni del giudice che invia Ichabod Crane a Sleepy Hollow. Landau accettò il ruolo per amicizia e profonda stima nei confronti del regista Tim Burton, dopo aver lavorato con lui in Ed Wood.', 'Commento audio del regista e note di produzione del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:52:42.709549+00:00'),
('8a008bfd-f344-4620-b833-23788e9c19d8', 359, 'Aneddoti dal set', 'La voce originale di Christopher Walken', 'Per la sua interpretazione del feroce Cavaliere Senza Testa quando è in vita, Christopher Walken ha pochissime battute e, non parlando fluentemente il tedesco, dovette memorizzare la sua breve battuta foneticamente con l''aiuto di un coach linguistico. Per i ruggiti e i versi ferini del cavaliere spettrale, la produzione utilizzò invece vocalizzi registrati appositamente dal cantante e musicista Frank Zappa.', 'Documentario ''The Making of Sleepy Hollow'' e interviste alla troupe del suono', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:52:42.709549+00:00'),
('9d19904a-fb97-454c-a06f-8535f812eac2', 47, 'Citazioni & Easter Egg', 'Il cameo di Richard Branson all''aeroporto di Miami', 'Il miliardario Richard Branson, fondatore della Virgin Atlantic, appare brevemente in un cameo nei panni di un passeggero sottoposto ai controlli di sicurezza all''aeroporto internazionale di Miami.', 'Crediti del film e interviste promozionali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:37:18.964131+00:00'),
('2d57f285-49e7-43df-8380-a078441adae4', 47, 'Aneddoti dal set', 'L''infortunio alle ginocchia di Daniel Craig durante le riprese a Venezia', 'Durante la sequenza d''azione finale all''interno del palazzo di Venezia che sta sprofondando, Daniel Craig ha riportato un infortunio ai legamenti delle ginocchia, costringendo temporaneamente a riorganizzare il piano di lavorazione.', 'Reportage dal set di EON Productions', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:37:18.964131+00:00'),
('e5b48321-3211-4049-8210-7b7f98a5db88', 47, 'Curiosità & Retroscena', 'La vera partita di poker supervisionata da professionisti', 'Le mani di poker giocate nel film sono state supervisionate da giocatori professionisti, tra cui il noto esperto di poker Tomer Benvenisti, per garantire la massima autenticità delle giocate e dei bluff sullo schermo.', 'Note di produzione e interviste ai consulenti di gioco', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:37:18.964131+00:00'),
('40ae9764-6998-4014-9636-13b2cfabc9c2', 55, 'Casting & Scelte', 'Il provino di Brigitte Nielsen tramite polaroid', 'Brigitte Nielsen ottenne la parte di Ludmilla Drago dopo aver spedito di sua spontanea volontà alcune fotografie polaroid dallo Studio 54 di New York direttamente a Sylvester Stallone, il quale rimase folgorato dal suo aspetto algido e imponente.', 'Documentario di produzione e interviste d''archivio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:37:52.999387+00:00'),
('34829414-f17a-4f59-8d6f-5faa37f9fbe4', 55, 'Casting & Scelte', 'La vera nazionalità di Dolph Lundgren nascosta', 'Dolph Lundgren, svedese di nascita, si presentò ai provini come lottatore di arti marziali e ingegnere chimico. Per accentuare la sua aura sovietica e imponente, la produzione decise di farlo parlare il meno possibile, riducendo le sue battute a circa cinquantasei parole in tutto il film.', 'Note di produzione ufficiali e commento audio del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:37:52.999387+00:00'),
('5f898092-435c-41f3-a1f7-87b14fc8a241', 55, 'Casting & Scelte', 'Il rifiuto del vero pugile per il ruolo di Drago', 'Prima di scegliere Dolph Lundgren, Sylvester Stallone aveva valutato migliaia di candidati e cercato persino pugili professionisti reali, ma nessuno sembrava possedere la combinazione perfetta di altezza, corporatura statuaria e distacco gelido richiesta per il villain sovietico.', 'Intervista retrospettiva a Sylvester Stallone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:37:52.999387+00:00'),
('44ab6719-4c2d-4415-af1c-e45ff4f7a983', 55, 'Aneddoti dal set', 'I colpi reali di Dolph Lundgren sul set', 'Dolph Lundgren, grazie al suo passato agonistico nel full-contact karate, colpì così duramente Sylvester Stallone durante i ciak dell''incontro che l''attore e regista dovette essere ricoverato d''urgenza in terapia intensiva a causa di una pressione sanguigna salita a oltre 200.', 'Autobiografia di Sylvester Stallone e making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:37:52.999387+00:00'),
('ea9b6f03-3a8a-4449-a3ec-48b0bb3ca384', 55, 'Segreti di produzione', 'La finta neve in Canada', 'Durante le riprese delle sequenze ambientate nella steppa siberiana, girate in realtà nel Wyoming e in Canada, la produzione dovette fare i conti con una insolita assenza di neve naturale, costringendo gli addetti agli effetti a utilizzare ingenti quantità di scaglie di plastica bianca e sapone.', 'Diario di bordo della troupe e documentario sul set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:37:52.999387+00:00'),
('93f9c1b4-0ec3-4c96-8c81-a06e509ae157', 55, 'Segreti di produzione', 'Il robot domestico giocattolo donato a Paulie', 'Il robot umanoide Sico, che nel film regala a Paulie una bizzarra storia d''amore meccanica, era in realtà un''invenzione creata dall''inventore Robert Doornick per assistere i bambini autistici. Stallone lo vide in televisione e decise di acquistarlo e inserirlo nella sceneggiatura.', 'Note di produzione e archivi della International Robotics', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:37:52.999387+00:00'),
('cb5abc15-1e8c-4551-88b8-6199c8696fa4', 55, 'Curiosità & Retroscena', 'La durata record dei montaggi musicali', 'Circa un terzo dell''intera durata del film è composto da sequenze di montaggio musicale, inclusi i celebri allenamenti incrociati e i flashback nostalgici, una scelta criticata all''epoca dai recensori ma divenuta iconica per la cultura pop degli anni ottanta.', 'Analisi critica e dati di montaggio ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:37:52.999387+00:00'),
('b80613b6-ddd9-47e6-83ac-aea00a7ca7fd', 55, 'Citazioni & Easter Egg', 'L''assenza di James Gandolfini come comparsa', 'Nonostante persistenti leggende metropolitane sul web, le voci secondo cui un giovane James Gandolfini sarebbe apparso come comparsa tra la folla dell''arena sovietica smentite categoricamente dai registi del casting e dai registri ufficiali delle comparse di Vancouver.', 'Verifiche di produzione e registri del casting di Vancouver', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:37:52.999387+00:00'),
('76b8d9cd-38d3-4fee-a282-e47a02f79d46', 60, 'Casting & Scelte', 'La gravidanza di Penélope Cruz nascosta dalla sorella', 'Durante le riprese del film, l''attrice Penélope Cruz era incinta. Per girare le scene più dinamiche e i campi larghi senza rischi, la produzione ha utilizzato sua sorella Monica Cruz come controfigura per i piani sequenza e le azioni fisiche.', 'Note di produzione ufficiali e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:38:15.523936+00:00'),
('0e34b217-8f96-4740-8c36-ece9c9d39fab', 60, 'Aneddoti dal set', 'La generosità di Johnny Depp per la troupe', 'A causa del freddo intenso durante le riprese a Londra nei Pinewood Studios, Johnny Depp ha personalmente acquistato di tasca sua cinquemila cappotti impermeabili per tutti i membri della troupe cinematografica.', 'Tabloid britannici e resoconti dal set della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:38:15.523936+00:00'),
('200139c7-db04-4f22-8ce5-521f0f8d4fcd', 60, 'Curiosità & Retroscena', 'L''ispirazione letteraria da Tim Powers', 'Il soggetto del film è tratto direttamente dall''omonimo romanzo di Tim Powers del 1987, intitolato in italiano ''Forze oscure''. Il produttore Jerry Bruckheimer acquistò i diritti del libro anni prima di adattarlo ufficialmente per integrarlo nella saga di Jack Sparrow.', 'Crediti del film e interviste a Jerry Bruckheimer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:38:15.523936+00:00'),
('2fd46276-9aa0-40d6-807c-1563fd10d9de', 60, 'Citazioni & Easter Egg', 'Il cameo non accreditato di Keith Richards', 'Keith Richards, chitarrista dei Rolling Stones e principale fonte di ispirazione per la gestualità e l''andatura di Jack Sparrow, torna a interpretare il ruolo del Capitano Teague, padre di Jack, in un breve ma celebre cameo.', 'Accrediti ufficiali e making-of del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:38:15.523936+00:00'),
('e66af081-5a6e-4706-9a74-5148ab01b2b4', 60, 'Effetti speciali & Trucco', 'I costumi delle sirene e la post-produzione', 'Le attrici che interpretavano le sirene indossavano costumi speciali in silicone ma anche abiti dotati di marcatori digitali. Molti dei movimenti e la coda da sirena sono stati interamente ricreati in CGI dalla Industrial Light & Magic.', 'Speciali sugli effetti visivi della ILM', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:38:15.523936+00:00'),
('b5477a1d-222f-4d7d-aa9f-b55cb8f6d5ab', 60, 'Casting & Scelte', 'L''addio di Gore Verbinski e l''arrivo di Rob Marshall', 'Dopo aver diretto la prima trilogia, Gore Verbinski decise di lasciare il timone della regia per dedicarsi al film d''animazione ''Rango''. La produzione scelse allora Rob Marshall, noto per i musical come ''Chicago'', per dare una nuova impronta visiva e ritmica alla saga.', 'Comunicati stampa ufficiali Disney', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:38:15.523936+00:00'),
('414692f9-d36b-4d23-afab-6fb9b37ae724', 52, 'Effetti speciali & Trucco', 'Il braccio bionico di Bucky e i guanti di gomma', 'Sebastian Stan ha dovuto indossare uno speciale manicotto di compressione verde sul braccio sinistro durante tutte le riprese per consentire ai tecnici della VFX di applicare in post-produzione il celebre braccio metallico del Soldato d''Inverno. L''attore ha spesso ironizzato sulle difficoltà di indossare costumi così aderenti durante le lunghe e calde giornate sul set di Atlanta.', 'Commento audio del Blu-ray dei fratelli Russo', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:37:37.432422+00:00'),
('4068e3be-8319-4051-9c48-970412fab1bb', 52, 'Citazioni & Easter Egg', 'Il cameo di Jim Starlin nel gruppo di supporto', 'Jim Starlin, il leggendario fumettista della Marvel Comics che ha creato il personaggio di Thanos nel 1973, appare in un cameo nei primi minuti del film. È uno dei membri del gruppo di supporto guidato da Steve Rogers a cui partecipa anche Joe Russo, il co-regista della pellicola.', 'Insider Marvel e crediti del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:37:37.432422+00:00'),
('22aa54cd-511e-4cfc-b024-a0fd2ea0d081', 57, 'Casting & Scelte', 'Il rifiuto di Robert De Niro', 'Inizialmente i produttori avevano offerto il ruolo di Capitan Jack Sparrow a Robert De Niro. L''attore rifiutò la parte perché convinto che il film sarebbe stato un flop al botteghino, esattamente come era accaduto al suo precedente film sui pirati, ''Corsari'' del 1995.', 'Note di produzione ufficiali e interviste ai produttori', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:38:03.022973+00:00'),
('76ec3477-ecdf-4ad2-874a-99304c6c2551', 57, 'Casting & Scelte', 'La scelta iniziale per Will Turner', 'Prima che Orlando Bloom ottenessi la parte di Will Turner, la produzione prese in seria considerazione attori come Heath Ledger, Ewan McGregor, Christian Bale, Tobey Maguire e Ashton Kutcher per il ruolo.', 'Audizioni e provini d''archivio della Walt Disney Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:38:03.022973+00:00'),
('e0f64816-6d09-42fb-835f-7d5826e17dfa', 57, 'Segreti di produzione', 'La dentatura d''oro di Johnny Depp', 'Johnny Depp fece applicare diversi denti d''oro permanenti inseriti dai dentisti durante la preparazione del personaggio. I dirigenti della Disney rimasero scioccati e gli chiesero di ridurne il numero, ma Depp negoziò per mantenerne quanti più possibile.', 'Commento audio del regista Gore Verbinski nel DVD del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:38:03.022973+00:00'),
('91188e29-3a6d-449c-805b-d7f04dd89866', 57, 'Segreti di produzione', 'La costruzione delle navi in scala reale', 'La nave Interceptor era in realtà una chiatta d''acciaio camuffata con una struttura in legno e compensato, mossa da un proprio motore, mentre la Perla Nera fu costruita sopra una chiatta galleggiante nei cantieri navali di Bayou La Batre, in Alabama.', 'Documentario sul making-of presente nell''edizione speciale Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:38:03.022973+00:00'),
('3d4a5a82-319c-4ac0-bab2-82416e3789a7', 57, 'Effetti speciali & Trucco', 'L''invenzione dei costumi degli scheletri', 'Per girare le scene in cui i pirati rivelano le loro sembianze scheletriche al chiaro di luna, gli attori indossavano tute per il motion capture in neoprene grigio chiaro, recitando la scena due volte: una volta normalmente e una volta senza gli attori per riprendere solo lo sfondo.', 'Articolo tecnico della rivista American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:38:03.022973+00:00'),
('43b250b6-a173-4baf-aa6f-ed55da6b9331', 57, 'Aneddoti dal set', 'Il cane con le chiavi di Tortuga', 'Il celebre cane che tiene in bocca le chiavi della cella dei pirati era un cane di razza briard di nome Scupper. Durante le riprese sul set, l''animale aveva la tendenza a scappare attratto dai gabbiani, costringendo la troupe a continui stop.', 'Diario di bordo e interviste agli addestratori del set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:38:03.022973+00:00'),
('b8e1aaf2-6ea0-431b-9ae7-61aff37f49ad', 57, 'Aneddoti dal set', 'Il vero autore della cicatrice di Norrington', 'L''attore Jack Davenport, che interpreta il Commodoro Norrington, si procurò una vera cicatrice sul mento durante le prove di combattimento con la spada, un piccolo infortunio che il regista decise di sfruttare visivamente per il personaggio.', 'Intervista promozionale a Jack Davenport per il lancio del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:38:03.022973+00:00'),
('9a118d8c-f40d-4efb-8d77-4fd86352e40b', 57, 'Citazioni & Easter Egg', 'L''omaggio a Disneyland', 'Il film è direttamente basato sull''omonima attrazione dei parchi a tema Disney aperta nel 1967. All''interno della pellicola ci sono numerosi omaggi, come la scena in cui i pirati inseguono i cani o il cannoneggiamento della fortezza che ricorda fedelmente le gag degli animatronic.', 'Archivio storico dei parchi Disney e note di sceneggiatura', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:38:03.022973+00:00'),
('f45b8eb5-87e2-4422-9c01-a1d7e03f222e', 67, 'Casting & Scelte', 'Il debutto cinematografico di Dave Chappelle', 'Il celebre comico Dave Chappelle ha fatto il suo esordio sul grande schermo proprio in questo film interpretando Ahchoo, all''età di diciannovesimi anni. Mel Brooks lo notò durante i suoi spettacoli di stand-up comedy e decise di affidargli il ruolo, lanciando ufficialmente la sua carriera cinematografica.', 'Commento audio del regista nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:38:46.818769+00:00'),
('e66e39c5-c9ea-4cbf-8f40-1f5edeebc2fb', 67, 'Curiosità & Retroscena', 'La parodia preventiva di Kevin Costner', 'Mel Brooks decise di realizzare il film dopo il successo planetario di ''Robin Hood - Principe dei ladri'' (1991) con Kevin Costner. Brooks acquistò i diritti per fare la parodia ancora prima che uscisse la versione drammatica, notando nel film di Costner numerosi elementi involontariamente comici pronti per essere satirizzati.', 'Intervista d''archivio a Mel Brooks per Entertainment Tonight (1993)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:38:46.818769+00:00'),
('2bfd09af-f626-4c0c-a6c5-d93ce81a9eb0', 67, 'Curiosità & Retroscena', 'Il rifiuto del titolo originale in favore del tormentone', 'Il film era originariamente intitolato semplicemente ''Robin Hood: Men in Tights''. Durante la post-produzione, Mel Brooks spinse per aggiungere la frase descrittiva in italiano e inglese per marcare fortemente il tono demenziale della pellicola e distanziarla dai kolossal drammatici precedenti.', 'Note di produzione della 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:38:46.818769+00:00'),
('1e8eedee-e7f6-49bc-94e7-d2b7fa20ca99', 67, 'Aneddoti dal set', 'L''infortunio sul set di Cary Elwes', 'Cary Elwes, che interpretava Robin Hood, si ferì accidentalmente a una mano durante le riprese della sequenza del duello con la spada contro lo Sceriffo di Ruttingham. Nonostante la ferita sanguinante, l''attore continuò a girare la scena sfruttando l''adrenalina del momento.', 'Intervista retrospettiva a Cary Elwes per il ventennale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:38:46.818769+00:00'),
('18d48ad7-517c-4d41-a8e9-0b15e6337af9', 67, 'Citazioni & Easter Egg', 'Il cameo autocitofonico di Mel Brooks', 'Oltre a interpretare Rabbi Tuckman, Mel Brooks inserisce una chiara autocitazione quando il suo personaggio distribuisce il vino ''Blinkin'' (un chiaro riferimento al suo precedente film ''Frankenstein Junior'' e al personaggio di Blücher). Inoltre, il rabbino esclama battute che richiamano direttamente la storica comicità ebraica dei suoi vecchi sketch.', 'Analisi visiva e DVD Trivia Track', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:38:46.818769+00:00'),
('51280636-8130-4904-aa47-da29c5d48372', 67, 'Segreti di produzione', 'La cintura di castità e i riferimenti storici', 'La celebre e indistruttibile cintura di castità indossata da Lady Marian è una gag ricorrente scritta da Mel Brooks e J.D. Shapiro. Storicamente le cinture di castità medievali sono considerate dalla storiografia moderna per lo più un mito o un''invenzione di epoche successive, ma nel film diventano un elaborato dispositivo di sicurezza con tanto di chiave smarrita.', 'Making-of ufficiale ''Anatomy of a Parody''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:38:46.818769+00:00'),
('6345ba24-3d7c-4dfd-9e44-63ae62be8e3e', 54, 'Casting & Scelte', 'Il rifiuto iniziale di James Caan e Ryan O''Neal', 'Prima che la produzione puntasse su Sylvester Stallone come protagonista assoluto, i produttori Irwin Winkler e Robert Chartoff avevano valutato attori di grande nome già affermati a Hollywood, tra cui James Caan, Ryan O''Neal, Burt Reynolds e Robert Redford, ma nessuno di essi accettò di rischiare con un copione scritto da un esordiente sconosciuto.', 'Intervista retrospettiva a Irwin Winkler e Robert Chartoff per Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:37:47.810383+00:00'),
('6d3499fe-afd5-456f-8d77-c546e694bba1', 54, 'Aneddoti dal set', 'Le riprese rubate all''ingresso del Philadelphia Museum of Art', 'La celebre sequenza in cui Rocky raggiunge la cima della scalinata del museo ed esulta fu girata all''alba con una troupe ridotta all''osso e senza permessi ufficiali completi per bloccare il traffico. La troupe arrivò sul posto con un furgone non contrassegnato e registrò il tutto in pochissimi minuti prima che arrivassero le forze dell''ordine locali.', 'Diario di produzione e intervista al regista John G. Avildsen', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:37:47.810383+00:00'),
('99b3cdfa-b85f-4341-8c6b-2b3d721f7415', 54, 'Casting & Scelte', 'La scelta di Talia Shire e il provino con Stallone', 'Talia Shire, sorella del celebre regista Francis Ford Coppola, ottenne la parte di Adriana dopo che Carrie Snodgress rifiutò l''offerta. Durante il provino congiunto con Stallone, la Shire si presentò con un paio di occhiali spessi e un atteggiamento estremamente timido, improvvisando gran parte della sua insicurezza vocale che convinse immediatamente il regista.', 'Making-of ufficiale ''The Making of Rocky'' incluso nell''edizione speciale DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:37:47.810383+00:00'),
('b2517928-314d-4566-9789-5d8de3ba9b5a', 59, 'Casting & Scelte', 'La genesi del padre di Jack Sparrow', 'Johnny Depp basò la sua celebre interpretazione del Capitano Jack Sparrow non solo su Keith Richards dei Rolling Stones, ma anche su Pepé Le Pew dei cartoni animati Warner Bros. Quando si trattò di scegliere l''attore ideale per interpretare il padre di Jack, Teague Sparrow, la scelta cadde naturalmente proprio su Keith Richards, che accettò il ruolo creando una storica dinamica padre-figlio sul set.', 'Audio commento del regista Gore Verbinski e documentari del backstage', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:38:11.187912+00:00'),
('c4d04b42-29c6-422b-8394-c8cff2b160ac', 59, 'Effetti speciali & Trucco', 'Il trucco estremo di Bill Nighy', 'L''attore Bill Nighy non ha indossato una vera tuta per il motion capture con i tipici marker fisici per interpretare Davy Jones, ma ha recitato sul set indossando un pigiama speciale ricoperto di punti di riferimento digitali. Grazie a questa tecnologia avanzata della Industrial Light & Magic, ogni minima espressione facciale di Nighy è stata catturata e traslata direttamente sui tentacoli digitali del villain.', 'Making-of ufficiale e note di produzione ILM', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:38:11.187912+00:00'),
('d3bf2167-a6d0-4314-8ae6-585fc18938b9', 59, 'Aneddoti dal set', 'Il blocco della produzione per il clima', 'Le riprese delle sequenze ambientate nel deserto dello Scrigno di Davy Jones (rappresentato dalle saline di Bonneville nello Utah) subirono forti rallentamenti a causa delle inaspettate e violente tempeste di sale e pioggia. La troupe dovette fermarsi ripetutamente per proteggere le costose attrezzature cineprese e riorganizzare il piano di lavorazione in tempi record.', 'Diario di produzione e interviste alla troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:38:11.187912+00:00'),
('e1f1f94f-3540-4c48-b119-d092747e09fe', 59, 'Curiosità & Retroscena', 'La stesura in corsa della sceneggiatura', 'Gli sceneggiatori Ted Elliott e Terry Rossio scrissero gran parte della sceneggiatura di questo terzo capitolo in contemporanea con le riprese del secondo film, arrivando sul set in Malaysia e ai Caraibi spesso senza avere il finale della storia completato. Questo costrinse attori e registi a improvvisare o ad adattare i dialoghi giorno per giorno in base alla disponibilità delle location.', 'Intervista agli sceneggiatori pubblicata su Creative Screenwriting', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:38:11.187912+00:00'),
('5dc47d03-4a64-45aa-8867-f78c53a9b8ff', 59, 'Segreti di produzione', 'La costruzione fisica della Singapore di Beckett', 'La spettacolare sequenza iniziale ambientata a Singapore non fu girata in CGI né in Asia, ma fu interamente ricostruita all''interno di un enorme palcoscenico sonoro e in un bacino di carenaggio esterno ai Universal Studios di Los Angeles. Vennero edificate oltre quaranta strutture in legno in stile cinese e scavati canali artificiali per consentire il movimento delle navi in scala reale.', 'Featurette ''The World of Chow Yun-fat'' nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:38:11.187912+00:00'),
('eaa8bb91-4f97-46b9-8a40-f9f3715ae469', 59, 'Casting & Scelte', 'L''ispirazione per Sao Feng', 'Il personaggio del pirata Sao Feng, interpretato dalla leggenda del cinema di Hong Kong Chow Yun-fat, subì diverse modifiche in fase di sceneggiatura per adattarsi alla presenza scenica dell''attore. Il regista Gore Verbinski e gli autori vollero omaggiare i classici film di cappa e spada orientali, cucendo il ruolo su misura per Yun-fat che eseguì personalmente gran parte dei movimenti d''azione.', 'Note di produzione ufficiali della Walt Disney Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:38:11.187912+00:00'),
('c726c095-6b41-4f09-868d-d2815c359572', 59, 'Effetti speciali & Trucco', 'Il modello in scala del Maelstrom', 'Per girare la titanica battaglia finale all''interno del Maelstrom, la produzione combinò effetti digitali all''avanguardia con enormi elementi meccanici pratici. Venne costruito un gigantesco set con piattaforme cardaniche idrauliche in grado di inclinare i ponti delle navi a 45 gradi, circondati da schermi blu alti decine di metri e vasche d''acqua controllate da pompe idrauliche industriali.', 'Documentario sugli effetti visivi di ILM', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:38:11.187912+00:00'),
('f2992b78-b535-4ff0-91cd-3f4201f77c35', 59, 'Aneddoti dal set', 'L''addio temporaneo di Keira Knightley', 'Durante le lunghe sessioni di ripresa in esterni marittimi, Keira Knightley contrasse una forte infezione agli occhi che costrinse la produzione a sospendere temporaneamente le sue scene in primo piano per evitare rischi per la salute dell''attrice, riorganizzando il calendario per girare prima i campi lunghi con le controfigure.', 'Reportage dal set di Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:38:11.187912+00:00'),
('e431b44a-18dd-4283-af06-051582baea45', 64, 'Casting & Scelte', 'Il cambio alla regia tra William Keighley e Michael Curtiz', 'Il produttore Hal B. Wallis e il capo della Warner Bros. Jack L. Warner decisero di licenziare il regista originale William Keighley dopo che le prime settimane di riprese in esterni a Chico, in California, furono giudicate troppo lente e prive di energia dinamica. Al suo posto fu chiamato Michael Curtiz, che impresse un ritmo più serrato e diresse tutte le sequenze d''azione più memorabili.', 'Note di produzione della Warner Bros. e biografie ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:38:32.53792+00:00'),
('4300d20e-1f48-4424-9765-c4a80775e192', 64, 'Segreti di produzione', 'La scelta obbligata del Technicolor a tre strisce', 'Il film fu uno dei primi in assoluto a sfruttare il complesso sistema Technicolor a tre strisce. Le pesanti e calde telecamere e la necessità di luci accecanti costrinsero la troupe a lavorare a temperature elevatissime sul set, causando non pochi disagi fisici al cast in costume medievale.', 'Documentario storico sul Technicolor e making-of inclusi nell''edizione home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:38:32.53792+00:00'),
('1219b35e-4183-4c21-af89-3d6083fc70c2', 56, 'Aneddoti dal set', 'La frattura del tendine di Stallone', 'Durante le riprese della celebre sequenza dell''allenamento con la corsa per le strade di Filadelfia, Sylvester Stallone subì un grave infortunio strappandosi un tendine del braccio sinistro. Questo incidente costrinse la produzione a modificare temporaneamente il programma delle riprese, privilegiando le inquadrature in cui il braccio infortunato non era visibile.', 'Commento audio del regista nel Blu-ray celebrativo di Rocky II', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:37:57.798975+00:00'),
('a7b66d6e-b8eb-4763-bf72-22c7f505d21e', 56, 'Casting & Scelte', 'Il ritorno sul ring di Carl Weathers', 'Carl Weathers si sottopose a mesi di preparazione atletica intensiva con campioni reali di pugilato per mantenere la stessa incredibile forma fisica del primo film. L''attore insistette affinché gli incontri coreografati mantenessero un livello di realismo estremo, portando a contatti fisici reali durante i ciak più concitati.', 'Documentario ''The Making of Rocky II'' presente nell''edizione speciale home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:37:57.798975+00:00'),
('7abb136e-bf8c-4e38-afc7-3d4255db0be5', 56, 'Segreti di produzione', 'L''uso della cinepresa Panavision', 'Per il secondo capitolo, Sylvester Stallone, qui al suo esordio alla regia, volle ampliare il respiro visivo del film utilizzando lenti anamorfiche Panavision. Questa scelta tecnica permise di dare maggiore enfasi ai combattimenti e alle panoramiche urbane rispetto al primo film girato con budget ridotto.', 'Note di produzione e archivi tecnici della Panavision', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:37:57.798975+00:00'),
('4f6b024d-df80-40e2-9d9f-044cee2c1ffe', 56, 'Effetti speciali & Trucco', 'La cicatrice di Apollo Creed', 'Il reparto trucco guidato da Michael Westmore dovette ricreare con estrema precisione le cicatrici e i segni dei colpi subiti da Apollo Creed nel primo match. Durante il climax di Rocky II, il trucco prostetico fu studiato per deteriorarsi realisticamente sotto i colpi progressivi ricevuti sul ring.', 'Archivio storico del sindacato truccatori cinematografici', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:37:57.798975+00:00'),
('4d61b2b6-05a7-4b28-91ce-38efaa6116af', 56, 'Citazioni & Easter Egg', 'Il cameo dei veri familiari', 'All''interno delle sequenze che ritraggono la folla in delirio prima e dopo il match finale, compaiono diversi membri della famiglia di Sylvester Stallone, incluso suo padre Frank Stallone Sr. e suo fratello Frank Stallone Jr., che contribuì anche alla colonna sonora con brani interpretati dal suo gruppo.', 'Crediti di produzione e note di edizione della soundtrack', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:37:57.798975+00:00'),
('6b5bcbac-e5d4-47ab-86a3-9902ca6ef0e4', 56, 'Curiosità & Retroscena', 'Le vere comparse della scorta poliziotta', 'La scorta della polizia che accompagna Rocky durante la sua corsa trionfale per le scale del Philadelphia Museum of Art era composta in parte da veri agenti del dipartimento di polizia di Filadelfia fuori servizio, impiegati per gestire la folla oceanica di oltre tremila comparse spontanee.', 'Cronache locali del Philadelphia Inquirer durante le riprese del 1978', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:37:57.798975+00:00'),
('3d9aed42-d2cd-4fd2-b9a6-d006cd2016aa', 66, 'Casting & Scelte', 'Il rifiuto di Mel Gibson per il ruolo di Robin Hood', 'Prima che la parte principale venisse affidata a Kevin Costner, i produttori avevano offerto il ruolo di Robin Hood a Mel Gibson. L''attore rifiutò categoricamente l''offerta, preferendo concentrarsi su altri progetti cinematografici in quel periodo.', 'Note di produzione ufficiali e archivi di casting di Hollywood', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:38:42.255584+00:00'),
('d83ffb13-8baa-44c5-a20a-a174f3c30db9', 66, 'Casting & Scelte', 'La voce e le battute tagliate di Christian Slater', 'Christian Slater fu scelto per interpretare Will Scarlett, ma durante la post-produzione il regista Kevin Reynolds decise di ridurre drasticamente le sue battute e di doppiare alcune sue parti per correggere l''incoerenza dell''accento britannico adottato dall''attore americano.', 'Commento audio del regista e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:38:42.255584+00:00'),
('d49ef5d9-2288-43d4-8f0b-402ec55f0b50', 66, 'Aneddoti dal set', 'L''improvvisazione di Alan Rickman sulla decapitazione', 'Alan Rickman, acclamato nel ruolo dello Sceriffo di Nottingham, improvvisò la celebre battuta in cui ordina di ''annullare il Natale'' e quella in cui minaccia di tagliare il cuore di qualcuno con un cucchiaio smussato perché ''fa più male''. Molte delle sue battute più taglienti furono aggiunte da lui stesso sul set.', 'Documentario sul making-of del film e biografia di Alan Rickman', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:38:42.255584+00:00'),
('07ff3703-afb9-444b-82fb-3ed0ec4d1578', 66, 'Aneddoti dal set', 'L''infortunio alla caviglia di Kevin Costner durante le riprese', 'Durante le riprese nel bosco, Kevin Costner si procurò una distorsione alla caviglia saltando da un cavallo. Per permettere alla produzione di continuare senza ritardi eccessivi, la troupe dovette modificare temporaneamente le inquadrature e utilizzare controfigure per le scene di movimento.', 'Diario di produzione e riviste cinematografiche dell''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:38:42.255584+00:00'),
('5255a35e-b09d-4c11-929a-50ef467157d1', 66, 'Casting & Scelte', 'La scelta del castino per il ruolo di Maid Marian', 'Robin Wright fu inizialmente scelta per interpretare Maid Marian, ma dovette rinunciare al ruolo a causa della sua gravidanza. La produzione contattò rapidamente Mary Elizabeth Mastrantonio, che accettò la parte appena poche settimane prima dell''inizio delle riprese principali.', 'Archivi di casting e rivista Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:38:42.255584+00:00'),
('d91076dd-72b6-488c-ae17-54e34954b47d', 66, 'Citazioni & Easter Egg', 'Il cameo di Brian Blessed come Lord Locksley', 'Il celebre attore britannico Brian Blessed appare nei panni di Lord Locksley, il padre di Robin, in un ruolo breve ma cruciale all''inizio del film. La sua presenza scenica imponente e la voce baritonale furono fortemente volute per dare solennità tragica all''incipit della storia.', 'Crediti del film e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:38:42.255584+00:00'),
('3287dcd3-6331-4641-ad6a-2b0cdd276020', 66, 'Segreti di produzione', 'Modelli in scala per il Castello di Nottingham', 'Poiché l''accesso alle vere strutture storiche era limitato e i costi di costruzione di un set a grandezza naturale per l''intero castello erano proibitivi, la produzione realizzò elaborati modelli in scala combinati con tecniche di pittura su vetro per simulare le imponenti mura e torri della fortezza.', 'Report tecnico degli effetti visivi e scenografia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:38:42.255584+00:00'),
('7f61ce64-daa8-4f89-bd01-7d5f69639733', 66, 'Segreti di produzione', 'L''uso di veri falchi addestrati per le scene d''apertura', 'Nelle sequenze iniziali in cui compaiono uccelli rapaci, la produzione non fece ricorso ad animali generati al computer (inesistenti all''epoca per questo livello di dettaglio), ma si affidò a falconieri professionisti che fornirono falchi addestrati per volare in sicurezza sopra le teste degli attori sul set.', 'Note della troupe e reparto animali sul set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:38:42.255584+00:00'),
('e3370b55-3d35-4674-a790-0420851854a3', 69, 'Casting & Scelte', 'Il progetto iniziale intitolato Nottingham', 'Prima di diventare il kolossal incentrato sulle origini dell''eroe, la sceneggiatura scritta da Brian Helgeland s''intitolava originariamente ''Nottingham'' e dipingeva lo Sceriffo come un detective e Robin Hood come un anti-eroe oscuro. La Universal richiese una riscrittura per ribaltare i ruoli e concentrarsi maggiormente sulla figura classica di Robin Longstride.', 'Note di produzione ufficiali Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:38:53.990536+00:00'),
('95a68719-2aaa-4c69-9ac0-71fb2568349e', 60, 'Segreti di produzione', 'Le vere Hawaii come set principale', 'Gran parte delle riprese in esterna si sono svolte sulle isole hawaiiane di Kauai e Oahu, sugli stessi set naturali precedentemente utilizzati per la produzione di ''Jurassic Park'' e della serie televisiva ''Lost''.', 'Diario di bordo e documentario sul set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:38:15.523936+00:00'),
('b17c8dd4-5a8c-4232-87f8-eef05a2941d6', 60, 'Effetti speciali & Trucco', 'La trasformazione di Ian McShane in Barbanera', 'Per rendere il personaggio di Barbanera più minaccioso, l''attore Ian McShane indossava ogni giorno protesi facciali e una complessa barba intrecciata con piccoli oggetti e micce accese simulate per enfatizzare il suo aspetto sulfureo.', 'Reparto trucco e acconciature del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:38:15.523936+00:00'),
('1eae1ce6-ae96-435b-8808-65f263e0f1fe', 65, 'Casting & Scelte', 'La rivalità di vecchia data tra Sean Connery e Robert Shaw', 'Sean Connery e Robert Shaw avevano già condiviso il set di A 007, dalla Russia con amore (1963), dove interpretavano nemici mortali. Richard Lester sfruttò questa loro chimica pregressa e la naturale competizione per dare estremo realismo al loro ultimo e drammatico duello cinematografico.', 'Note di produzione e biografie ufficiali del cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:38:36.983924+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('5934ab69-d22a-4774-ae14-93ce7ce5e58b', 65, 'Casting & Scelte', 'Il rifiuto originale di Richard Harris per il ruolo di Re Riccardo', 'Richard Harris inizialmente declinò l''offerta di interpretare Re Riccardo Cuor di Leone a causa di impegni teatrali concomitanti. Fu solo grazie a una rinegoziazione dei tempi di lavorazione da parte della produzione che l''attore irlandese poté accettare la parte.', 'Archivi storici della produzione cinematografica', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:38:36.983924+00:00'),
('2230aa16-cbbe-4335-90c4-827ba3e719bc', 65, 'Curiosità & Retroscena', 'La direzione antieroica di Richard Lester', 'Il regista Richard Lester decise deliberatamente di smontare il mito cavalleresco di Robin Hood, mostrando un eroe stanco, dolorante e disilluso. Questa visione creò inizialmente attriti con i produttori che si aspettavano un''avventura più tradizionale in stile cappa e spada.', 'Intervista retrospettiva a Richard Lester nel documentario sul film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:38:36.983924+00:00'),
('fc288634-f91e-4e03-ae60-a360f3a20b88', 65, 'Casting & Scelte', 'Il ritiro temporaneo di Audrey Hepburn interrotto dalla sceneggiatura', 'Audrey Hepburn lesse la sceneggiatura scritta da James Goldman mentre si trovava in Svizzera e ne rimase così profondamente colpita da considerare il personaggio di Marian l''unico ritorno plausibile sul set dopo il suo allontanamento dalle scene iniziato nel 1967.', 'Biografie autorizzate di Audrey Hepburn', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:38:36.983924+00:00'),
('aa5fbdb8-72a7-4822-9f23-566c29ed0c0d', 65, 'Curiosità & Retroscena', 'L''accuratezza storica voluta dal sceneggiatore James Goldman', 'James Goldman, celebre per aver scritto Il leone d''inverno, condusse ricerche approfondite sulle vere crociate e sulla vecchiaia nel XII secolo. Scelse di ritrarre un''Inghilterra feudale cupa e fangosa, lontana dalle rappresentazioni idealizzate dei film degli anni trenta con Errol Flynn.', 'Note di sceneggiatura e commento audio del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:38:36.983924+00:00'),
('79e2051b-348f-4fe5-9026-a08026f44e21', 65, 'Aneddoti dal set', 'Le condizioni meteorologiche estreme durante le riprese spagnole', 'Durante la lavorazione in alcune zone montuose della Spagna, la troupe dovette affrontare sbalzi termici drastici, passando da gelate mattutine a ondate di calore inattese che misero a dura prova i costumi pesanti di lana e cuoio indossati da Sean Connery e Robert Shaw.', 'Diario di lavorazione della troupe di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:38:36.983924+00:00'),
('789196df-85a3-4930-9de5-efaa7f01d7de', 79, 'Aneddoti dal set', 'Il mal di schiena di Harrison Ford sul set', 'Durante la famigerata scena del blocco della prigione della Morte Nera, Harrison Ford soffriva di un forte mal di schiena a causa di un vecchio infortunio. Per alleviare il dolore tra un ciak e l''altro, l''attore fu costretto a sdraiarsi ripetutamente sui pavimenti metallici della scenografia.', 'Commento audio del Blu-ray ufficiale e documentari di making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:39:34.55627+00:00'),
('b41e9a9a-5a4b-4da3-8f17-0f869dca639e', 79, 'Aneddoti dal set', 'La polmonite di Kenny Baker nel robot R2-D2', 'L''attore Kenny Baker, che interpretava il droide R2-D2, ha trascorso mesi difficili all''interno del pesante cilindro di metallo e fibra di vetro durante le riprese nel caldo deserto della Tunisia. A causa delle escursioni termiche e della polvere, Baker contrasse una brutta forma di bronchite che sfiorò la polmonite.', 'Interviste d''archivio a Kenny Baker e note di produzione Lucasfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:39:34.55627+00:00'),
('070c0f4e-ed54-497b-b8f5-2c3f0c472101', 79, 'Casting & Scelte', 'La perdita del volo e il provino fortuito di Harrison Ford', 'Harrison Ford non era la prima scelta per il ruolo di Han Solo e George Lucas aveva inizialmente deciso di non richiamare attori già usati in American Graffiti. Ford si trovava casualmente nei corridoi degli studi a costruire una porta per Francis Ford Coppola quando fu notato dal casting director Fred Roos, che lo convinse a leggere le battute con gli attori dei provini.', 'Documentario ''Empire of Dreams: The Making of the Star Wars Trilogy''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:39:34.55627+00:00'),
('1bac393d-af7c-4454-8739-1d19762b20b2', 79, 'Casting & Scelte', 'Kurt Russell e Sylvester Stallone tra i candidati per Han Solo', 'Prima che la parte di Han Solo fosse assegnata a Harrison Ford, George Lucas testò decine di giovani attori di Hollywood. Tra i provinati ufficiali figuravano Kurt Russell, Sylvester Stallone, Christopher Walken, Nick Nolte e Bill Murray.', 'Archivi di casting ufficiali di Lucasfilm e registri dei provini del 1976', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:39:34.55627+00:00'),
('d3be736a-86ce-4602-a4c2-be8ac303fcb6', 79, 'Aneddoti dal set', 'La febbre sul set tunisino di Carrie Fisher', 'Nei primi giorni di riprese nel deserto tunisino, l''attrice diciannovenne Carrie Fisher fu colpita da una grave intossicazione alimentare accompagnata da febbre alta. George Lucas fu costretto a girare le prime sequenze con la principessa Leila utilizzando controfigure e angoli di ripresa strategici.', 'Autobiografia di Carrie Fisher ''Wishful Drinking'' e diari di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:39:34.55627+00:00'),
('3883abe9-e26b-4407-9461-7806546e8730', 79, 'Segreti di produzione', 'L''uso di telecamere naziste per le battaglie spaziali', 'Il supervisore degli effetti speciali John Dykstra e il suo team dovettero modificare vecchie cineprese ad alta velocità risalenti alla Seconda Guerra Mondiale per riprendere i modelli in miniatura delle astronavi. Queste telecamere, montate su enormi binari di movimento controllati da computer (Dykstraflex), permettevano di ottenere la profondità di campo necessaria per simulare il movimento dinamico nello spazio.', 'American Cinematographer Magazine, articolo tecnico del 1977', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:39:34.55627+00:00'),
('153ef730-3527-442d-9afe-0029d552b6ef', 79, 'Citazioni & Easter Egg', 'Il riferimento cinematografico nascosto alla Fortezza Apache', 'L''iconico numero di cella in cui è imprigionata la Principessa Leila nella Morte Nera è il blocco di detenzione AA-23. Questo è un omaggio deliberato e documentato al film western classico ''Fort Apache'' di John Ford, molto amato da George Lucas.', 'Note storiche e trivia ufficiali dal database Star Wars Databank', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:39:34.55627+00:00'),
('ada77699-7218-409f-9f87-304c23af3499', 62, 'Casting & Scelte', 'L''improvvisazione dello sputo di Matthew McConaughey', 'Durante la celebre sequenza del pranzo al ristorante, il gesto di Matthew McConaughey che sputa sul tavolo non era previsto dal copione. Si è trattato di un''iniziativa estemporanea dell''attore per rimanere nel personaggio, che ha colto di sorpresa Leonardo DiCaprio la cui reazione di sconcerto è del tutto autentica.', 'Audio commento del Blu-Ray e interviste promozionali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:38:24.431243+00:00'),
('a727bdff-0736-4b8e-baad-d9515187ad5f', 62, 'Casting & Scelte', 'Margot Robbie e lo schiaffo a Leonardo DiCaprio', 'Durante il provino per la parte di Naomi Lapaglia, Margot Robbie decise di uscire dal copione per stupire i produttori. Al culmine di una lite verbale con Leonardo DiCaprio, invece di pronunciare la sua battuta finale, gli tirò uno schiaffo inaspettato in faccia urlando un insulto, conquistando immediatamente il ruolo.', 'Intervista di Margot Robbie a Harper''s Bazaar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:38:24.431243+00:00'),
('de251238-ab28-4a93-bee7-6c33713af108', 62, 'Segreti di produzione', 'Il lancio reale del nano', 'La controversa scena del lancio del nano è stata realizzata con un mix di effetti visivi e sicurezza sul set. L''attore affetto da nanismo Martin Klebba è stato lanciato realmente ma su un apposito materasso di sicurezza protetto da crash pad digitalmente rimossi in post-produzione.', 'Note di produzione e making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:38:24.431243+00:00'),
('952c04e6-ab51-431a-bd57-28e0da92f60d', 62, 'Aneddoti dal set', 'L''improvvisazione di Jonah Hill con il pesce rosso', 'Nella scena in cui Donnie Azoff si infuria mangiandosi un pesce rosso vivo nell''ufficio, l''attore Jonah Hill ha improvvisato la masticazione simulata con un pesce finto di gomma, mentre in un''altra inquadratura è stato usato un animale vero ma subito salvato e restituito al proprietario dopo pochi secondi.', 'Dietro le quinte ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:38:24.431243+00:00'),
('57dbd386-3a3d-43a2-826d-24a850c0789a', 62, 'Effetti speciali & Trucco', 'L''uso estensivo della CGI per gli sfondi di New York', 'Nonostante sia ambientato principalmente a New York e nei sobborghi di Long Island, gran parte del film è stato girato nello stato di New York con l''ausilio massiccio della CGI. La VFX supervisor Liza McIntosh e la Brainstorm Digital hanno ricreato digitalmente orizzonti urbani, yacht di lusso, moli e folle oceaniche per mantenere il controllo totale sulla palette cromatica satura voluta da Scorsese.', 'Report tecnico di Brainstorm Digital sui VFX del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:38:24.431243+00:00'),
('95e9d2a0-f664-4c64-8ac6-ba85c9f878a8', 62, 'Aneddoti dal set', 'L''infortunio di Jon Bernthal', 'Jon Bernthal, che interpreta il trafficante Brad Bodnar, ha rischiato di compromettere le riprese durante la zuffa con Leonardo DiCaprio nella villa. A causa della foga e della totale assenza di controfigure, Bernthal ruppe accidentalmente una costola a DiCaprio durante una presa particolarmente violenta.', 'Intervista retrospettiva a Jon Bernthal', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:38:24.431243+00:00'),
('0dfb763d-c1eb-413b-9671-8e4040e4c3eb', 62, 'Effetti speciali & Trucco', 'La protesi dentaria di Jonah Hill', 'Per conferire al suo personaggio un aspetto grottesco e distintivo ispirato ai broker arricchiti senza scrupoli, Jonah Hill ha indossato per quasi tutte le riprese delle protesi dentarie in finto allineamento ortodontico e ceramica ingiallita, che ostacolavano volutamente la sua dizione.', 'Note del reparto trucco e protesi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:38:24.431243+00:00'),
('19b9f897-7adf-4ab4-94d5-fa662c56ae68', 73, 'Casting & Scelte', 'Il provino di Leonardo DiCaprio per Anakin Skywalker', 'Prima che Jake Lloyd venisse scelto per il ruolo di Anakin Skywalker, George Lucas prese in considerazione Leonardo DiCaprio. L''attore incontrò il regista, ma declinò l''offerta poiché sentiva di non essere pronto in quel momento a impegnarsi in un blockbuster di tale portata.', 'Intervista a Leonardo DiCaprio per rivista specializzata', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:39:10.378493+00:00'),
('09bd2c98-cd3b-4038-a974-0e196644edf7', 73, 'Effetti speciali & Trucco', 'La voce robotica di Watto creata con lo scotch', 'Per ottenere il caratteristico suono della voce del mercante Watto, il progettista del suono Ben Burtt manipolò la voce dell''attore Andrew Secombe facendola passare attraverso un tubo di plastica coperto di nastro adesivo per simulare le vibrazioni nasali.', 'Documentario The Beginning: Making Star Wars: Episode I', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:39:10.378493+00:00'),
('30dca7c4-faa0-4029-8ece-62d9ea078416', 73, 'Aneddoti dal set', 'La spada laser giocattolo di Ewan McGregor', 'Durante le riprese delle scene di combattimento con la spada laser, Ewan McGregor tendeva a imitare rumorosamente il ronzio dell''arma con la bocca. George Lucas dovette fermare più volte le riprese per ricordargli che il suono sarebbe stato aggiunto in post-produzione.', 'Commento audio del Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:39:10.378493+00:00'),
('73419b43-aafb-494f-96c0-1691631dd5ed', 73, 'Citazioni & Easter Egg', 'I giocattoli di E.T. nel Senato Galattico', 'Durante la sequenza in cui la Regina Amidala richiede un voto di sfiducia contro il Cancelliere Valorum nel Senato Galattico, tra i delegati alieni sullo sfondo compaiono tre membri della stessa specie di E.T. l''extra-terrestre di Steven Spielberg.', 'Libro ufficiale Star Wars: Episode I - The Visual Dictionary', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:39:10.378493+00:00'),
('0fb9c139-0315-49ec-8212-54881613ec70', 73, 'Curiosità & Retroscena', 'L''ispirazione per la pettinatura della Regina Amidala', 'Il complesso design del costume e la famosa pettinatura della Regina Amidala nel suo abito da cerimonia furono ispirati direttamente dalle fotografie delle donne della tribù Hopi dei Native Americans nei primi del Novecento.', 'Articoli di approfondimento sui costumi di Trisha Biggar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:39:10.378493+00:00'),
('5f0542a5-5cf7-474d-b648-17955765d0f0', 73, 'Aneddoti dal set', 'La distruzione accidentale del set di Anakin', 'Durante le riprese della sequenza della corsa degli sgusci (Podrace) negli studi di Leavesden, un malfunzionamento di una macchina del vento di grande potenza spazzò via parte delle scenografie desertiche in miniatura allestite nel backlot.', 'Note di produzione della Lucasfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:39:10.378493+00:00'),
('ba369b8a-2c4a-45a3-ae41-ca3705e83c2e', 83, 'Segreti di produzione', 'La coltivazione di mais reale per il set', 'Invece di affidarsi interamente alla CGI o a campi preesistenti, Christopher Nolan fece piantare e coltivare cinquecento acri di vero mais in Canada, ispirandosi ai metodi visti in ''L''uomo dei sogni''. Alla fine delle riprese, il raccolto fu venduto con un discreto profitto.', 'Note di produzione ufficiali della Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:39:55.487863+00:00'),
('0bdf7daf-aca0-4660-a301-ea56bdb45281', 83, 'Aneddoti dal set', 'Il rifiuto di Anne Hathaway e il rischio ipotermia', 'Durante le riprese sul pianeta ghiacciato in Islanda, Anne Hathaway dimenticò di chiudere la zip della sua muta stagna, riempiendola d''acqua gelida e rischiando l''ipotermia prima che la troupe se ne accorgesse.', 'Intervista di Anne Hathaway al Graham Norton Show', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:39:55.487863+00:00'),
('6acbf87c-3fb5-401c-8df4-779bfb1b4b64', 83, 'Effetti speciali & Trucco', 'L''ispirazione per il design dell''astronave Endurance', 'L''aspetto circolare dell''astronave Endurance fu modellato sulla struttura della Stazione Spaziale Internazionale e sui sottomarini russi, per garantire una verosimiglianza scientifica basata sulla fisica della forza centrifuga.', 'Articolo di approfondimento tecnico su American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:39:55.487863+00:00'),
('739f71f2-33df-4a99-b59e-d7e49ba52cf0', 63, 'Segreti di produzione', 'Il budget faraonico per l''epoca', 'Con un costo di produzione stimato intorno a quasi un milione di dollari, ''Robin Hood'' (1922) fu uno dei film più costosi e ambiziosi del cinema muto, superando persino i budget standard delle produzioni dell''epoca per garantire la massima accuratezza visiva e grandiosità scenica.', 'Archivi storici della United Artists e biografie di Douglas Fairbanks', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:38:27.953771+00:00'),
('191fbfa4-6819-47d1-8796-ae1abfc6e98f', 63, 'Aneddoti dal set', 'La preparazione atletica di Douglas Fairbanks', 'Prima dell''inizio delle riprese, Douglas Fairbanks si sottopose a mesi di rigoroso allenamento fisico quotidiano, inclusi esercizi di scherma e ginnastica acrobatica, per poter eseguire personalmente tutte le complesse evoluzioni e i salti senza ricorrere a stuntmen.', 'Note di produzione e diari personali di Douglas Fairbanks', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:38:27.953771+00:00'),
('84a06090-ae7e-4685-8444-33cf8f9ac186', 63, 'Casting & Scelte', 'Il contributo di Enid Bennett come Lady Marian', 'Enid Bennett, moglie del regista Fred Niblo ma scelta personalmente da Fairbanks per il ruolo di Lady Marian, dovette bilanciare la sua innata eleganza con le esigenze fisiche di un film d''azione pionieristico, diventando una delle prime eroine dinamiche del cinema d''avventura.', 'The Moving Picture World e retroscena di casting d''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:38:27.953771+00:00'),
('45abf193-2b0a-4665-90e8-5cbf6683891d', 63, 'Segreti di produzione', 'L''uso pionieristico delle cineprese multiple', 'Il direttore della fotografia Arthur Edeson impiegò configurazioni avanzate per l''epoca, utilizzando più macchine da presa contemporaneamente per catturare sia i campi lunghi dei grandiosi assedi al castello che i dettagli ravvicinati dei duelli di spada.', 'American Cinematographer e manuali di tecnica cinematografica muta', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:38:27.953771+00:00'),
('7c7e667c-72b0-428f-86f2-be8ee48bcc84', 63, 'Effetti speciali & Trucco', 'La cura filologica dei costumi', 'I costumi di scena furono realizzati ispirandosi direttamente alle illustrazioni medievali di Howard Pyle e ai manoscritti del XIV secolo, imponendo agli attori mesi di prove in abiti pesanti di lana e cotta di maglia metallica.', 'Photoplay Magazine e archivi dei costumi della United Artists', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:38:27.953771+00:00'),
('c3dbceba-0f0b-4fad-b0cb-9b1842662b94', 68, 'Aneddoti dal set', 'L''addestramento intensivo con il tiro con l''arco', 'Per girare le frenetiche scene d''azione, Taron Egerton ha dovuto sottoporsi a settimane di addestramento intensivo con l''arco sotto la supervisione di arcieri professionisti, imparando a scoccare frecce a un ritmo accelerato e moderno simile a una mitragliatrice.', 'Featurette ufficiale del making-of di Lionsgate', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:38:49.986831+00:00'),
('17b1a5f9-7187-4db8-a8a0-19b97a983a13', 68, 'Casting & Scelte', 'La scelta iniziale di Leonardo DiCaprio come produttore', 'Il progetto è nato inizialmente negli uffici della Appian Way Productions di Leonardo DiCaprio, il quale ha contribuito a sviluppare l''idea di una versione di Robin Hood fortemente revisionista, grintosa e stilizzata.', 'Note di produzione ufficiali e report di Deadline', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:38:49.986831+00:00'),
('a61d7dd1-b83a-4b7e-ad42-27fbb3fb0ad2', 68, 'Curiosità & Retroscena', 'Il rifiuto del tono storico tradizionale', 'Il regista Otto Bathurst ha dichiarato apertamente di essersi ispirato a film come ''Il cavaliere oscuro'' e ''Fight Club'' piuttosto che ai classici film in costume su Robin Hood, puntando a un pubblico giovane e a un''estetica contemporanea.', 'Intervista stampa internazionale a Otto Bathurst', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:38:49.986831+00:00'),
('efdec540-9d08-467d-b2f0-4be5dd37abad', 68, 'Segreti di produzione', 'La costruzione delle scenografie a Dubrovnik', 'Alcune sequenze chiave del film e scorci della città sono stati girati a Dubrovnik, in Croazia, sfruttando le imponenti mura medievali che in precedenza avevano ospitato la produzione di ''Game of Thrones''.', 'Diario di produzione e location scout report', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:38:49.986831+00:00'),
('6f7e2b23-e84a-49ab-9649-3fad463e34b6', 68, 'Citazioni & Easter Egg', 'L''ispirazione visiva dai disordini urbani moderni', 'Le scene delle rivolte popolari e degli scontri tra i minatori di Nottingham e le forze dello Sceriffo sono state modellate dai realizzatori studiando i filmati dei moderni disordini urbani e delle proteste di piazza globali.', 'Commento audio del regista e del produttore', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:38:49.986831+00:00'),
('b9fa9f33-ce7e-4a02-8fc8-85b61c9a6b26', 74, 'Effetti speciali & Trucco', 'La ripresa del volto di Ian McDiarmid nel finale', 'Nelle scene finali in cui Palpatine osserva l''esercito di cloni sfilare su Coruscant, l''attore Ian McDiarmid non era disponibile sul set a Londra perché impegnato a teatro a New York. La produzione ha dovuto realizzare una scansione digitale del suo volto e applicarla tramite computer grafica su una controfigura.', 'Documentario ''From Puppets to Pixels''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:39:14.835605+00:00'),
('9b0b39de-15da-4876-8566-04ffdda89df1', 74, 'Citazioni & Easter Egg', 'Il cameo dei figli di George Lucas', 'I tre figli di George Lucas – Amanda, Katie e Jett – fanno brevi camei nel film all''interno della sequenza ambientata negli archivi Jedi. Jett interpreta un giovane Padawan di nome Zett Jukassa, che comparirà anche nel capitolo successivo.', 'The Star Wars Archives / Commento audio del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:39:14.835605+00:00'),
('6a022afd-f9a6-45aa-b6be-b60986c61a81', 74, 'Casting & Scelte', 'La scelta del nome di Jango Fett e l''omaggio a Sergio Leone', 'Il personaggio di Jango Fett fu battezzato così da George Lucas come chiaro omaggio al film western ''Django'' (1966) di Sergio Leone e al personaggio interpretato da Franco Nero. La struttura narrativa del cacciatore di taglie sul pianeta Kamino riprende fortemente le dinamiche dei duelli all''italiana.', 'Star Wars Insider e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:39:14.835605+00:00'),
('0eb49278-805d-4530-bbc6-bd5424c3b9bb', 74, 'Segreti di produzione', 'Le riprese interamente in digitale e la telecamera HD', 'L''attacco dei cloni è stato uno dei primi lungometraggi della storia del cinema ad essere girato interamente in alta definizione digitale utilizzando il sistema di telecamere Sony CineAlta HDW-F900. George Lucas impose questa svolta tecnologica per spingere l''intera industria cinematografica verso la proiezione digitale.', 'Making-of ufficiale ''State of the Art''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:39:14.835605+00:00'),
('28b2db02-fcb7-45ba-a83b-e3998426c856', 74, 'Citazioni & Easter Egg', 'L''apparizione di Ahmed Best nei panni di un cliente del locale', 'Ahmed Best, l''attore che ha interpretato Jar Jar Binks tramite motion capture, fa un cameo in carne e ossa durante la sequenza dell''inseguimento nei bassifondi di Coruscant. Appare brevemente sullo sfondo come un cliente vestito con abiti civili all''interno del locale notturno.', 'IMDb Trivia e DVD Easter Eggs', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:39:14.835605+00:00'),
('a2be74fd-498a-4986-a828-1b4dbe7d4dd9', 74, 'Casting & Scelte', 'Il rifiuto del ruolo di Anakin da parte di Leonardo DiCaprio', 'Prima che Hayden Christensen venisse scelto per il ruolo di Anakin Skywalker, George Lucas incontrò Leonardo DiCaprio per valutare la sua partecipazione. L''attore declinò l''offerta affermando di non sentirsi pronto in quel momento a sostenere l''enorme pressione mediatica legata al franchise.', 'Intervista a Leonardo DiCaprio per ShortList', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:39:14.835605+00:00'),
('2c90121e-bf25-4b32-b0be-c7a962337802', 64, 'Aneddoti dal set', 'Il record dei duelli di scherma coreografati', 'Il leggendario duello finale tra Errol Flynn e Basil Rathbone fu coreografato dal maestro d''armi Fred Cavens. Rathbone, che nella vita reale era un schermidore formidabile, ammise che Flynn era estremamente veloce e abile, pur preferendo la spettacolarità alla pura tecnica agonistica.', 'Interviste d''archivio a Basil Rathbone e biografia di Errol Flynn', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:38:32.53792+00:00'),
('89014deb-c7e9-4f40-b849-b7107febcdf2', 64, 'Effetti speciali & Trucco', 'Le frecce truccate per colpire gli attori', 'Per simulare i colpi di freccia che trafiggevano i costumi dei nemici senza ferire gli attori, venivano usati fili di acciaio invisibili collegati a meccanismi a molla nascosti dietro i corpi delle comparse, mentre alcune frecce erano dotate di punte cave riempite di sangue finto.', 'Archivio tecnico degli effetti speciali della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:38:32.53792+00:00'),
('ccd6def0-76a7-4797-a3d3-f4ab5d867d22', 64, 'Casting & Scelte', 'La scelta iniziale di James Cagney per Robin Hood', 'Prima che il ruolo di Robin Hood venisse assegnato a Errol Flynn, la Warner Bros. aveva pensato di affidare la parte alla star dei gangster James Cagney. Tuttavia, la rottura temporanea del contratto di Cagney con lo studio aprì la strada a Flynn, consacrandolo definitivamente come stella dei film d''avventura.', 'Archivio storico dei contratti di casting della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:38:32.53792+00:00'),
('e19c1b40-daee-4830-bc63-5b8914b41030', 64, 'Segreti di produzione', 'Le calzamaglie tinte per evitare trasparenze', 'A causa della forte luce richiesta dalle riprese in Technicolor, le prime calzamaglie indossate da Errol Flynn risultavano pericolosamente trasparenti alla cinepresa. I costumisti dovettero correre ai ripari aggiungendo una fodera interna e tingendo i tessuti con tonalità più pesanti.', 'Memorie del reparto costumi della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:38:32.53792+00:00'),
('8e12b89e-5435-41e5-b13d-4b746bdd0133', 75, 'Citazioni & Easter Egg', 'La cicatrice di Anakin e il legame con la serie 2D', 'La cicatrice verticale sull''occhio destro di Anakin Skywalker non appare in L''attacco dei cloni ma è presente all''inizio di La vendetta dei Sith; questo dettaglio visivo collega direttamente il film agli eventi della serie animata ''Star Wars: Clone Wars'' prodotta da Gen Tartakovsky, dove Anakin se la procurava nello scontro con Asajj Ventress.', 'Commento audio del DVD e note di produzione Lucasfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:39:19.633814+00:00'),
('66748444-dc28-437b-b1cf-59ef89fdda5b', 75, 'Citazioni & Easter Egg', 'Il cameo dei figli di George Lucas', 'I tre figli di George Lucas – Katie, Amanda e Jett – fanno tutti brevi camei nel film: Jett interpreta un giovane padawan di nome Zett Jukassa che viene ucciso dai cloni durante l''Ordine 66 nel Tempio dei Jedi, mentre Katie e Amanda compaiono rispettivamente come una ragazza nel foyer del teatro dell''opera e come una senatrice.', 'Documentario ''Within a Minute: The Making of Episode III''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:39:19.633814+00:00'),
('26750fd6-3fc3-4ce5-98a0-c3834852d8b8', 75, 'Segreti di produzione', 'Le spade laser a LED e la fine delle lame in legno', 'Per la prima volta nella trilogia prequel, gli attori hanno potuto utilizzare nuove spade laser con lame a LED integrate e rinforzate in policarbonato, che emettevano luce reale sui loro volti, riducendo drasticamente il lavoro di rotoscopio in post-produzione rispetto ai precedenti film in cui venivano usati bastoni di legno rivestiti di materiale riflettente.', 'Special Feature ''The Story of the Dueling Sabers''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:39:19.633814+00:00'),
('bd953193-7694-4174-b4c2-9993d6efb93d', 75, 'Casting & Scelte', 'Il rifiuto di Gary Oldman per il Generale Grievous', 'Gary Oldman era stato originariamente scelto per doppiare il Generale Grievous e aveva anche registrato alcune tracce audio di prova; tuttavia, l''attore dovette rinunciare al ruolo a causa di complicazioni sindacali legate alla Screen Actors Guild (SAG) riguardanti i film indipendenti e le produzioni non union.', 'Intervista ufficiale a Gary Oldman e produzioni Lucasfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:39:19.633814+00:00'),
('89222366-ef08-4975-a768-923d26a32f61', 75, 'Effetti speciali & Trucco', 'La maschera di Darth Vader e l''argilla sul set', 'La sequenza finale in cui Hayden Christensen indossa per la prima volta l''iconica maschera nera di Darth Vader richiese un''attenzione maniacale: il casco venne calzato sul viso dell''attore utilizzando calchi in plastilina e resina meticolosamente adattati alla conformazione cranica di Christensen per replicare fedelmente le proporzioni della trilogia originale.', 'Making-of ufficiale ''It''s All for Real''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:39:19.633814+00:00'),
('fe0a830d-ebb0-4278-b87c-6706be728f00', 75, 'Citazioni & Easter Egg', 'Il cameo di Spielberg sul set di Mustafar', 'Il celebre regista Steven Spielberg ha fatto una visita sul set durante le riprese delle sequenze finali su Mustafar e ha persino diretto alcune inquadrature minori del duello tra Anakin e Obi-Wan, ricambiando un favore cinematografico dopo che George Lucas aveva fatto lo stesso per alcune scene di action in film della Lucasfilm.', 'Diario di produzione ufficiale e documentari sul set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:39:19.633814+00:00'),
('2e3cabee-e391-4d9c-9d6a-323cb92320a0', 75, 'Aneddoti dal set', 'Il costume di Chewbacca e l''età dell''attore Peter Mayhew', 'Peter Mayhew tornò a indossare il costume peloso di Chewbacca a sessant''anni suonati; la produzione dovette assumere un terapista della riabilitazione fisica sul set per assisterlo costantemente durante le impegnative sequenze d''azione girate sul pianeta Kashyyyk.', 'Note di produzione e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:39:19.633814+00:00'),
('3cf267c5-ea55-4640-98ea-d76d63c2d5f2', 329, 'Casting & Scelte', 'Il rifiuto iniziale di Renée Zellweger', 'Renée Zellweger ha inizialmente esitato ad accettare il ruolo di Mae Braddock, temendo di non riuscire a catturare appieno la forza e la dignità delle donne americane durante la Grande Depressione.', 'Note di produzione della Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:51:16.48477+00:00'),
('4c36dae3-482e-4a20-a257-f6a8da2ffa9c', 329, 'Aneddoti dal set', 'L''infortunio ai denti di Craig Bierko', 'Durante le riprese del durissimo match finale, Craig Bierko (interprete di Max Baer) ha subito la frattura accidentale di un dente a causa di un gancio sinistro leggermente fuori misura sferrato da Russell Crowe.', 'Intervista a Craig Bierko per Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:51:16.48477+00:00'),
('0093c190-3583-4cfa-83a0-ecb9de1169bc', 329, 'Segreti di produzione', 'La ricostruzione digitale del Madison Square Garden', 'Gran parte degli spalti e delle folle oceaniche durante gli incontri di boxe non erano comparse in carne ed ossa, ma sono state ricreate digitalmente dalla Digital Domain per replicare l''atmosfera opprimente delle arene anni Trenta.', 'Cinefex Technical Report', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:51:16.48477+00:00'),
('d36bcacc-031e-4b62-83ad-b97f9617d79f', 329, 'Citazioni & Easter Egg', 'Il coinvolgimento dei veri discendenti', 'Rosemarie Braddock DeWaal, la vera figlia sopravvissuta di Jim Braddock, ha visitato più volte il set cinematografico e ha lodato pubblicamente l''accuratezza con cui Ron Howard ha ritratto la vita e la personalità dei suoi genitori.', 'Press junket ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:51:16.48477+00:00'),
('158f9053-f2ad-4b19-b146-1f4b298f220c', 67, 'Effetti speciali & Trucco', 'Il look di Richard Lewis ispirato a Errol Flynn', 'Per il personaggio del Principe Giovanni, interpretato da Richard Lewis, i reparti di trucco e costumi si sono volutamente ispirati ai classici film di cappa e spada degli anni ''30, esagerando i nei finti e le espressioni nevrotiche per accentuare il contrasto comico con la seriosità dei vecchi blockbuster.', 'Documentario sui costumi di Hollywood del 1994', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:38:46.818769+00:00'),
('6c003445-cbd8-44b9-8b9f-3acd230abfba', 330, 'Effetti speciali & Trucco', 'La cicatrice facciale di Ed Harris', 'Il personaggio di Carl Fogarty, interpretato da Ed Harris, sfoggia una vistosa e sfigurante cicatrice sull''occhio destro, frutto di un vecchio scontro con il protagonista. Il truccatore Stephan Dupuis ha impiegato protesi in silicone avanzate applicate quotidianamente per dare un aspetto realistico e sgradevole alla ferita.', 'Documentario sul backstage e making-of ''The Making of A History of Violence''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:51:20.803428+00:00'),
('f290034b-6567-4e42-b9d3-795cf8f82fd4', 330, 'Aneddoti dal set', 'Il metodo di lavoro silenzioso di David Cronenberg', 'Famoso per la sua estrema calma e organizzazione sul set, David Cronenberg non usa mai il megafono e raramente alza la voce. Viggo Mortensen ha raccontato che questa atmosfera rilassata permetteva agli attori di esplorare la tensione psicologica estrema delle scene più violente senza la pressione di un clima caotico.', 'Intervista a Viggo Mortensen per il press junket del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:51:20.803428+00:00'),
('a33f50de-c986-4061-b532-f3151e80b1cf', 330, 'Aneddoti dal set', 'La brutalità coreografata della scena delle scale', 'La celebre e violenta colluttazione tra Viggo Mortensen e Maria Bello sulle scale di casa richiese diversi giorni di prove con il coordinatore degli stunt, per evitare reali infortuni pur mantenendo una violenza domestica cruda, goffa e disperata, lontana dai canoni patinati di Hollywood.', 'Featurette ''The Stunts of A History of Violence''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:51:20.803428+00:00'),
('acf00561-b32a-4e42-9c49-f2245eb69fd2', 330, 'Segreti di produzione', 'La genesi del cane nella sequenza iniziale', 'All''inizio del film, l''omicidio a sangue freddo della bambina e del cane nella tavola calda da parte dei due psicopatici fu girato con estrema cautela: per la scena con l''animale ferito sono stati impiegati rigorosamente effetti animatronici e trucchi di montaggio per evitare qualsiasi rischio per il cane impiegato sul set.', 'Report della American Humane Association sul set del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:51:20.803428+00:00'),
('f17f448c-9162-4ddd-af18-23efea507d4d', 339, 'Aneddoti dal set', 'La polmonite contratta da Daniel Day-Lewis sul set', 'Durante le riprese a Cinecittà, Daniel Day-Lewis rifiutò di indossare cappotti caldi o abiti termici moderni sotto i costumi dell''epoca perché ''non storicamente accurati''. Questa scelta intransigente lo portò a contrarre una grave polmonite, dalla quale accettò di farsi curare con medicinali moderni solo dopo forti pressioni da parte della troupe e dei medici.', 'Intervista ufficiale di produzione e Making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:51:50.711119+00:00'),
('1951acb1-0b89-49db-95f5-aa67bcaf304c', 339, 'Casting & Scelte', 'Il metodo estremo di isolamento di Daniel Day-Lewis', 'Per restare calato nella parte del feroce macellaio anche fuori dal set, Day-Lewis manteneva l''accento di New York del XIX secolo per mesi e ascoltava costantemente musica del gruppo rap Eminem per entrare nello stato d''animo aggressivo del personaggio, rifiutando di parlare con Leonardo DiCaprio tra una ripresa e l''altra.', 'Dichiarazioni del cast e note di regia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:51:50.711119+00:00'),
('ce9d72ac-5de4-4ab3-8a16-94fc2d9b20b4', 339, 'Segreti di produzione', 'La ricostruzione kolossal di Cinecittà', 'La produzione ha ricostruito meticolosamente un intero miglio quadrato di Lower Manhattan del 1863 all''interno degli studios di Cinecittà a Roma. Il set comprendeva sezioni navigabili del porto di New York, interi isolati di edifici in legno, moli e una nave a grandezza naturale immersa in una vasca d''acqua.', 'Documentario sui reparti scenografici e scenografia di Dante Ferretti', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:51:50.711119+00:00'),
('36c4b542-d512-4a0a-af4c-338d1149a9f1', 339, 'Aneddoti dal set', 'L''infortunio alla mano di Leonardo DiCaprio', 'Durante una brutale scena di lotta corpo a corpo, Leonardo DiCaprio si ruppe accidentalmente il naso dopo aver incassato un colpo reale. In un''altra occasione, durante i combattimenti con la carne e le mezzene, si ferì ripetutamente alle mani, ma continuò a girare senza fermare la produzione.', 'Backstage ufficiale e interviste agli stunt coordinator', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:51:50.711119+00:00'),
('1b6bddd6-5dc4-4683-a580-bfae299cdd25', 339, 'Casting & Scelte', 'L''uso di veri macellai per insegnare la tecnica', 'Prima dell''inizio delle riprese, Daniel Day-Lewis ha trascorso settimane a lavorare in incognito in una macelleria tradizionale per imparare l''arte del taglio della carne, la manipolazione delle mezzene e l''uso professionale dei coltelli da macellaio utilizzati poi nel film.', 'Note di produzione e interviste al reparto trucco e costumi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:51:50.711119+00:00'),
('4a5065fb-6041-463b-aba9-aa962bad4bf2', 339, 'Citazioni & Easter Egg', 'La statua della Libertà e gli anacronismi storici voluti', 'Nel film compaiono transatlantici e dettagli architettonici leggermente anticipati rispetto alla cronologia reale del 1863, una scelta stilistica voluta da Scorsese per enfatizzare visivamente l''industrializzazione caotica e travolgente della metropoli in rapida espansione.', 'Commento audio del regista al DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:51:50.711119+00:00'),
('6fcec3c9-d848-40cb-991a-0c0e84222221', 339, 'Effetti speciali & Trucco', 'Le protesi dentarie personalizzate di Bill the Butcher', 'Il reparto trucco guidato da Manlio Rocchetti ha creato speciali protesi dentarie storte e macchiate per Daniel Day-Lewis, progettate per conferire a Billy the Butcher un ghigno sgradevole e minaccioso che accentuasse la sua natura bestiale e spietata.', 'Special report sugli effetti di trucco e make-up', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:51:50.711119+00:00'),
('4e221d55-25bb-4f37-aa11-2bca1e4fdb23', 347, 'Casting & Scelte', 'Il rifiuto iniziale di Jake Gyllenhaal', 'Prima che Russell Crowe venisse definitivamente scelto per il ruolo di John Nash, il giovane Jake Gyllenhaal fu seriamente preso in considerazione dalla produzione ed effettuò diversi provini, ma fu ritenuto troppo giovane per interpretare l''intero arco temporale del personaggio.', 'Report di casting e interviste retrospettive di Ron Howard', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:52:11.921586+00:00'),
('3a6f9a6c-3fd5-478e-980a-dd9c5af3797f', 347, 'Aneddoti dal set', 'La preparazione fisica di Russell Crowe', 'Per calarsi nella parte di John Nash durante gli anni del declino psicologico, Russell Crowe studiò a fondo i movimenti corporei dei pazienti affetti da schizofrenia paranoide, lavorando a stretto contatto con consulenti psichiatrici per simulare la postura rigida e lo sguardo sfuggente del matematico.', 'Commento audio del regista nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:52:11.921586+00:00'),
('c2f25633-39dc-4361-abbf-e39ca41f29c7', 347, 'Casting & Scelte', 'La scelta di Jennifer Connelly senza provino', 'Ron Howard rimase così colpito dalle interpretazioni precedenti di Jennifer Connelly che decise di assegnarle il ruolo di Alicia Nash senza sottoporla a un tradizionale provino, organizzando solo un incontro preliminare per testare la chimica con Russell Crowe.', 'Note di produzione e press kit ufficiale Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:52:11.921586+00:00'),
('5949855d-149b-4dd5-9782-8d0050a03845', 69, 'Casting & Scelte', 'Il rifiuto del ruolo di Marion da parte di Sienna Miller', 'Sienna Miller era stata originariamente scelta per interpretare Lady Marion accanto a Russell Crowe, ma fu costretta a lasciare il progetto prima dell''inizio delle riprese. Secondo i report di casting, la produzione ritenne che l''attrice fosse troppo giovane rispetto a Crowe, portando all''ingaggio di Cate Blanchett.', 'Report di Hollywood Reporter e note di casting', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:38:53.990536+00:00'),
('1822980a-ff95-4444-8ef4-c170a4b531cd', 69, 'Curiosità & Retroscena', 'La trasformazione fisica di Russell Crowe', 'Per prepararsi al ruolo di un arciere veterano dell''esercito di Riccardo Cuor di Leone, Russell Crowe ha seguito un rigoroso allenamento fisico incentrato sul tiro con l''arco tradizionale inglese, imparando a scoccare le frecce con grande rapidità e fluidità direttamente sul set.', 'Intervista al cast nel making-of ufficiale del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:38:53.990536+00:00'),
('83c1fef3-4010-43d7-9111-aefe4e086766', 69, 'Segreti di produzione', 'La ricostruzione del villaggio di Nottingham a Bourne Wood', 'La produzione ha costruito un intero villaggio medievale e una massiccia porta cittadina nella celebre foresta di Bourne Wood, nel Surrey, impiegando mesi di lavoro e centinaia di artigiani per creare un set pratico ed esteso anziché fare affidamento totale sulla computer grafica.', 'Diario di produzione e documentario sul set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:38:53.990536+00:00'),
('af43a509-820b-4382-8178-f6129bd055b0', 69, 'Aneddoti dal set', 'L''uso di cavalli addestrati per la carica sulla spiaggia', 'Durante la complessa sequenza della battaglia anfibia sulla spiaggia di Pembrokeshire, la produzione ha impiegato oltre un centinaio di cavalli appositamente addestrati per mantenere la calma tra esplosioni controllate, sabbia smossa e figuranti in armatura.', 'Special TV sul dietro le quinte delle riprese', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:38:53.990536+00:00'),
('fdef2297-375d-451c-8a32-4b1cefdd9e57', 69, 'Segreti di produzione', 'I costumi di Janty Yates e l''assenza di cliché hollywoodiani', 'La costumista premio Oscar Janty Yates ha evitato l''uso di pelli lisce e pulite tipiche dei film d''avventura tradizionali, preferendo tessuti ruvidi, lana pesante e cuoio vissuto per riflettere le condizioni climatiche e lavorative dell''Inghilterra rurale del XIII secolo.', 'Intervista alla costumista nelle note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:38:53.990536+00:00'),
('e6f92243-af00-4351-87a7-98eeae568a30', 80, 'Aneddoti dal set', 'La battuta improvvisata di Harrison Ford', 'Durante la scena dell''addio in cui Leila dice ''Ti amo'' a Han Solo prima che venga congelato nella carbonite, la sceneggiatura originale prevedeva che Han rispondesse ''Ti amo anch''io''. Sul set, il regista Irvin Kershner concesse a Harrison Ford di improvvisare, portando alla celebre e iconica replica: ''Lo so''.', 'Commento audio ufficiale del regista Irvin Kershner e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:39:40.584971+00:00'),
('fbfd09fb-e25e-4bc6-91bf-d45c50e5690e', 80, 'Casting & Scelte', 'La creazione della voce di Yoda da parte di Frank Oz', 'Il leggendario burattinaio Jim Henson raccomandò il suo collaboratore Frank Oz per dare vita e voce al maestro Yoda. Oz non solo manovrò il pupazzo sul set di Dagobah, ma creò la peculiare e invertita struttura sintattica dei dialoghi del personaggio, ispirandosi in parte ai modi di dire del proprio padre.', 'Documentario ''Empire of Dreams: The Making of the Star Wars Trilogy''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:39:40.584971+00:00'),
('34eee268-db0b-4a7a-963b-94be8f8f3286', 80, 'Effetti speciali & Trucco', 'Il trucco della scarpa da tennis per il burattinaio di Yoda', 'Per muovere Yoda all''interno della palude di Dagobah, Frank Oz operava il burattinaio da una fossa scavata sotto il set mentre teneva le braccia sollevate per ore in posizioni scomode. Per alleviare la tensione alle gambe e muoversi agevolmente sul terreno fangoso finto, Oz indossava spesso una scarpa da tennis logora anche se il resto del costume era mimetizzato.', 'Making-of d''archivio e interviste alla troupe tecnica della Industrial Light & Magic', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:39:40.584971+00:00'),
('bd756389-b77c-4e18-a6e2-de30a1d14147', 80, 'Aneddoti dal set', 'L''improvvisazione di Carrie Fisher con lo strumento medico', 'Nella scena in cui Leila si prende cura delle ferite di Luke dopo la battaglia su Hoth, Carrie Fisher colpì accidentalmente Mark Hamill sul petto con uno strumento medico di plastica. Irvin Kershner decise di tenere la ripresa buona perché rifletteva perfettamente la naturale goffaggine e la stanchezza dei personaggi in quel momento.', 'Archivio ufficiale del Fan Club Lucasfilm e note di montaggio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:39:40.584971+00:00'),
('d9f15582-7500-412e-ac47-d0c24cea6234', 80, 'Segreti di produzione', 'Il costume di Bossk riciclato da una serie TV della BBC', 'Il cacciatore di taglie trandoshano Bossk, visto brevemente sulla plancia della Executor, indossa una tuta spaziale gialla che in realtà è un costume riciclato da una serie fantascientifica della BBC intitolata ''Doctor Who'' (del 1974, episodio ''The Ark in Space''), a cui vennero aggiunte le maschere e le mani rettiliane.', 'Archivio di costumistica Lucasfilm e documentario sui cacciatori di taglie', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:39:40.584971+00:00'),
('134659c7-6cbd-46a2-bc53-fd838c33bd5e', 331, 'Casting & Scelte', 'La sostituzione last-minute di James Hewitt con Jonathan Rhys Meyers', 'Prima che Jonathan Rhys Meyers venisse ufficialmente scritturato, la produzione aveva valutato diversi giovani attori britannici emergenti, tra cui Aaron Eckhart per brevi considerazioni iniziali, prima che Allen optasse per l''irlandese Rhys Meyers per il suo magnetismo ambiguo.', 'Rivista cinematografica Empire e biografie del cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:51:25.793568+00:00'),
('d488ac46-f0cf-45ba-99c0-f4cc22dd60b1', 331, 'Aneddoti dal set', 'Le riprese nei reali club di tennis londinesi', 'Le sequenze in cui Chris lavora come istruttore sono state girate nel prestigioso e storico Queen''s Club di Londra, costringendo la troupe a rispettare i rigidi orari dei soci e a interrompere le riprese durante i tornei ufficiali.', 'Making-of incluso nel DVD edizione speciale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:51:25.793568+00:00'),
('c169036b-a119-41ea-9ff3-e9221f2d46dc', 331, 'Segreti di produzione', 'L''assenza della colonna sonora originale', 'Fedele alla sua abitudine di non utilizzare brani composti appositamente per i suoi film, Woody Allen ha interamente sonorizzato la pellicola attingendo a celebri registrazioni di arie d''opera interpretate da Enrico Caruso, inserite direttamente come diegetiche ed extradiegetiche.', 'Note di montaggio e colonna sonora ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:51:25.793568+00:00'),
('12857d9e-3c3c-4a4a-a38d-60f05d1a46cd', 331, 'Citazioni & Easter Egg', 'Il tributo operistico a Otello', 'L''uso ricorrente delle registrazioni di Enrico Caruso che cantano il ''Otello'' di Giuseppe Verdi non è casuale: riflette esplicitamente la gelosia distruttiva e la paranoia che consumano lentamente il protagonista Chris Wilton, anticipandone la tragedia.', 'Analisi cinematografica e critiche ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:51:25.793568+00:00'),
('16693d60-6174-470a-aaea-5a9be5ff9a4f', 331, 'Aneddoti dal set', 'Le lezioni di tennis intensive per Jonathan Rhys Meyers', 'Pur avendo un passato sportivo scolastico, Jonathan Rhys Meyers ha dovuto seguire settimane di allenamento intensivo con maestri professionisti di tennis prima del ciak iniziale per apparire perfettamente credibile nei panni di un istruttore d''élite.', 'Interviste promozionali di Jonathan Rhys Meyers', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:51:25.793568+00:00'),
('02047ac0-3e1e-4fbc-b609-e3a09048c9bc', 331, 'Aneddoti dal set', 'L''improvvisazione linguistica sul set', 'Nonostante la proverbiale rigidità di Woody Allen nel pretendere che gli attori seguano fedelmente il copione, l''attore Matthew Goode ha ottenuto il permesso di modificare alcune battute minori per rendere più naturale l''eloquio dell''aristocratico britannico che interpreta.', 'Dietro le quinte e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:51:25.793568+00:00'),
('5089e703-0f64-41c0-8a56-d224118961b4', 72, 'Casting & Scelte', 'Il destino alternativo di Luke Skywalker', 'Lo sceneggiatore Lawrence Kasdan propose a metà lavorazione che Luke Skywalker, dopo aver indossato il casco di Vader o dopo la presunta morte, si mettesse la maschera del padre, si voltasse verso il Lato Oscuro e dichiarasse di essere il nuovo imperatore. Lucas respinse l''idea perché si trattava di una fiaba per bambini.', 'Making-of ufficiale e note di sceneggiatura della trilogia classica', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:39:05.374409+00:00'),
('d0f1b206-bc59-4c47-9737-546992d8061e', 72, 'Citazioni & Easter Egg', 'I veri figli di Richard Marquand nel film', 'I due figli del regista Richard Marquand, James e Gareth, fecero una breve apparizione non accreditata come comparse all''interno del villaggio degli Ewok sulla luna boscosa di Endor.', 'Crediti di produzione e note ufficiali del cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:39:05.374409+00:00'),
('6f24beed-b463-4918-8c7f-38117aab18e4', 72, 'Aneddoti dal set', 'Carrie Fisher e il bikini di metallo', 'L''iconico bikini dorato indossato da Carrie Fisher come schiava di Jabba the Hutt causò numerosi problemi tecnici e di vestibilità, tanto che l''attrice rivelò ironicamente in seguito che la parte superiore era tenuta insieme dal nastro adesivo per evitare incidenti sul set.', 'Interviste d''archivio a Carrie Fisher', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:39:05.374409+00:00'),
('9293e3d7-ee13-464b-abb8-d9b8768173ad', 72, 'Effetti speciali & Trucco', 'La spada laser verde e i problemi di contrasto', 'La lama della spada laser di Luke fu cambiata da blu a verde nel secondo atto del film. La decisione fu presa dalla troupe degli effetti visivi della Industrial Light & Magic perché la precedente lama blu si confondeva troppo facilmente con i cieli azzurri durante le scene girate all''aperto nel deserto.', 'Documentario ''Empire of Dreams: The Story of the Star Wars Trilogy''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:39:05.374409+00:00'),
('f1ecd0b5-ed13-4af7-b60e-9c89d8bd8dd9', 72, 'Effetti speciali & Trucco', 'Il braccio bionico e la mano di Luke', 'Durante la sequenza sulla chiatta di Jabba, la mano bionica di Luke colpita da un raggio blaster mostra l''esoscheletro meccanico interno. Gli artisti degli effetti speciali dovettero costruire un guanto speciale in lattice e metallo per simulare i cavi elettrici tranciati.', 'Note di produzione e libro d''arte di ILM', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:39:05.374409+00:00'),
('0f7ae3fc-98eb-42d2-9741-3efa564dff66', 72, 'Curiosità & Retroscena', 'La vera natura della tuta di Boushh', 'Il costume del cacciatore di taglie Boushh, utilizzato da Leia per infiltrarsi nel palazzo di Jabba, fu originariamente ideato dal costumista Nilo Rodis-Jamero riutilizzando parzialmente bozzetti e concept art scartati per i cacciatori di taglie apparsi in ''L''Impero colpisce ancora''.', 'The Making of Return of the Jedi di J.W. Rinzler', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T15:39:05.374409+00:00'),
('59a2ee2c-8c6c-4ffb-afe9-0a9d1012c6ab', 82, 'Aneddoti dal set', 'Il polso rotto di Sean Connery sul set', 'Durante le riprese delle scene d''azione, Sean Connery si fratturò un polso a causa di un eccesso di zelo da parte del coreografo delle arti marziali Steven Seagal, che all''epoca faceva da consulente per i combattimenti. Connery scoprì solo anni dopo, a seguito di un controllo medico, che il polso era stato effettivamente rotto durante quegli allenamenti.', 'Intervista ufficiale di Sean Connery a Entertainment Tonight', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:39:50.763883+00:00'),
('219b4abc-e37a-4c18-bc7e-fa33b8d31efb', 82, 'Curiosità & Retroscena', 'Il titolo dato da Micheline Roquebrune', 'Il titolo definitivo del film, ''Mai dire mai'' (Never Say Never Again), fu suggerito a Sean Connery da sua moglie Micheline Roquebrune. L''attore aveva ripetutamente giurato in passato che non avrebbe mai più interpretato l''agente 007, spingendo la moglie a coniare quel titolo ironico per il suo ritorno nei panni di James Bond.', 'Note di produzione ufficiali e biografia dell''attore', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:39:50.763883+00:00'),
('addd280c-bdf2-406a-bd36-2011e778a4a9', 82, 'Curiosità & Retroscena', 'Il contenzioso legale con i Broccoli', 'Il film fu il risultato di una lunga battaglia legale durata anni tra il produttore Kevin McClory e la Danjaq di Albert R. Broccoli riguardo ai diritti del romanzo ''Thunderball''. Essendo basato sulla stessa storia del film del 1965, la produzione di EON Productions cercò in tutti i modi di bloccare il progetto, etichettandolo come un Bond ''non ufficiale''.', 'Documentazione legale e libri storici sulla saga di 007', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:39:50.763883+00:00'),
('c1062b65-74a5-45a2-8b72-365d4c3a5fb5', 82, 'Casting & Scelte', 'Il rifiuto del ritorno di Ernst Stavro Blofeld', 'Per il ruolo del villain principale Ernst Stavro Blofeld, inizialmente i realizzatori avevano pensato a Donald Pleasence, che aveva già interpretato memorabilmente il personaggio in ''Si vive solo due volte''. Tuttavia, la produzione optò infine per l''attore Max von Sydow a causa dei diritti contesi legati alla sceneggiatura di Kevin McClory.', 'Making-of e retroscena di casting del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:39:50.763883+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('fb04c745-1d1b-4715-9b5f-7b135a38d73a', 82, 'Segreti di produzione', 'L''uso pionieristico dei computer nella sequenza del gioco', 'La sequenza in cui James Bond sfida il cattivo Maximilian Largo al videogioco tridimensionale ''Domination'' richiese l''utilizzo di grafiche computerizzate all''avanguardia per l''epoca. Sebbene la tecnologia del gioco fosse inventata per il film, anticipò l''ascesa dei videogiochi strategici e interattivi negli anni successivi.', 'Archivio tecnico e commento audio del blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:39:50.763883+00:00'),
('82c8b929-4f94-4f49-bfe5-edc834d386fa', 82, 'Casting & Scelte', 'Rowan Atkinson prima del successo planetario', 'Il celebre comico britannico Rowan Atkinson ottenne una parte di supporto nel film nei panni dello sfortunato agente dell''MI6 Nigel Small-Fawcett. Questa apparizione cinematografica avvenne poco prima del suo definitivo successo internazionale con la serie televisiva ''Blackadder'' e successivamente con ''Mr. Bean''.', 'Crediti ufficiali del film e biografia dell''attore', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:39:50.763883+00:00'),
('cabba8c6-2364-4023-8820-532c2b312cdf', 85, 'Casting & Scelte', 'La scelta iniziale di Martin Balsam', 'Prima che Douglas Rain venisse ingaggiato per doppiare HAL 9000 e prima ancora dell''esperimento con Nigel Davenport, l''attore Martin Balsam aveva registrato tutte le battute del computer sul set. Kubrick decise però che la sua voce suonava troppo americana e colloquiale, optando per un tono più neutro e algido.', 'Archivi di produzione e biografie ufficiali di Stanley Kubrick', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:40:03.786084+00:00'),
('1ef0f443-aefa-470f-8061-4f644e05a17e', 85, 'Segreti di produzione', 'La rotazione della centrifuga da 750.000 dollari', 'Per simulare la gravità artificiale nella sezione centrale della Discovery One, la Vickers-Armstrong costruì un enorme set cilindrico rotante dal costo di 750.000 dollari dell''epoca. Il set pesava circa 27 tonnellate e poteva ruotare a una velocità massima di circa 4,8 chilometri orari.', 'Documentario ''2001: The Making of a Myth''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:40:03.786084+00:00'),
('faff9df6-a2b4-44f7-b2b1-948742320e57', 76, 'Effetti speciali & Trucco', 'La spada laser in legno per Adam Driver', 'Durante le prove preliminari delle scene di combattimento, Adam Driver e gli stuntman hanno utilizzato spade con elsa e lama in legno massiccio per abituarsi al peso realistico e alla struttura instabile della particolare arma a guardia incrociata di Kylo Ren.', 'The Force Awakens: The Visual Dictionary', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:39:23.598255+00:00'),
('b12fee69-8a3f-4661-abde-979e2e495277', 76, 'Citazioni & Easter Egg', 'L''omaggio a George Lucas nei codici di sblocco', 'Quando Finn, Han Solo e Chewbacca si infiltrano nella Base Starkiller, la console utilizzata per abbassare gli scudi planetari richiede l''inserimento di un codice numerico che corrisponde esattamente alla data di nascita di George Lucas, ovvero il 14 maggio 1944 (1138 fa invece riferimento al primo film THX 1138).', 'Commento audio del regista J.J. Abrams', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:39:23.598255+00:00'),
('59a86649-c239-4bad-9dfe-8aabde0cc526', 76, 'Segreti di produzione', 'Il cameo vocale di Bill Hader come consulente di BB-8', 'Il comico Bill Hader è stato accreditato come ''vocal consultant'' per il droide BB-8. Hader ha creato la voce unica del droide facendo passare i suoi vocalizzi attraverso un sintetizzatore musicale controllato dal compositore Ben Burtt.', 'Special features del Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:39:23.598255+00:00'),
('276bf5c5-74ad-4f9f-96a0-1b42158116db', 331, 'Segreti di produzione', 'La scelta della pistola d''epoca trafugata', 'L''arma utilizzata da Chris nella drammatica sequenza degli omicidi è una vecchia pistola d''ordinanza della prima guerra mondiale, scelta dal reparto scenografia per risultare anacronistica e giustificare il furto in una casa di periferia.', 'Reparto di scenografia e oggetti di scena di Match Point', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T15:51:25.793568+00:00'),
('c829334a-37d4-4792-b0bf-892b7483c232', 340, 'Casting & Scelte', 'Il rifiuto iniziale di Mark Ruffalo', 'Prima che Joaquin Phoenix venisse scelto per il ruolo di Merrill Hess, la parte era stata offerta a Mark Ruffalo. L''attore dovette però rifiutare l''offerta a causa di gravi problemi di salute, essendo stato operato proprio in quel periodo per un tumore al cervello benigno.', 'Interviste retrospettive di Mark Ruffalo e note di casting della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:51:55.268288+00:00'),
('da7272f1-1061-460e-b445-72a8e7881418', 340, 'Casting & Scelte', 'Il provino e la scrittura per Abigail Breslin', 'M. Night Shyamalan scrisse il personaggio di Bo pensando a un''età leggermente diversa, ma rimase folgorato dal provino della giovanissima Abigail Breslin. Durante le audizioni, la bambina dimostrò una naturalezza tale da spingere il regista a riscrivere alcune sfumature caratteriali del personaggio per adattarle alla sua età.', 'Special contenuto nel DVD ufficiale ''Making of Signs''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:51:55.268288+00:00'),
('9056fef5-6e96-44c3-8ba2-42f1e3f2b6de', 340, 'Casting & Scelte', 'La sostituzione last-minute di Mel Gibson', 'Inizialmente il ruolo del Reverendo Graham Hess fu assegnato a Guy Pearce. Poco prima dell''inizio delle riprese, tuttavia, Pearce dovette abbandonare il progetto per motivi personali e M. Night Shyamalan riuscì a ingaggiare tempestivamente Mel Gibson per salvare la produzione.', 'Archivi di produzione Touchstone Pictures e resoconti di stampa cinematografica del 2001', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:51:55.268288+00:00'),
('8969096b-088a-4afb-bb63-32eedf5f4759', 340, 'Aneddoti dal set', 'L''improvvisazione dei dialoghi tra i fratelli', 'Molti dei momenti di tensione e complicità domestica tra Mel Gibson e Joaquin Phoenix (nei panni dei fratelli Graham e Merrill) nacquero da brevi sessioni di improvvisazione sul set. Shyamalan incoraggiava i due attori a testare battute fuori copione per rendere il legame familiare più autentico e spontaneo.', 'Commento audio del regista nel Blu-ray di ''Signs''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:51:55.268288+00:00'),
('352ff7c4-fe9d-4515-804f-5bf5ddee43e2', 340, 'Segreti di produzione', 'La gestione degli alieni sul set', 'Per mantenere alta la tensione e ottenere reazioni di paura genuine da parte dei giovani attori Rory Culkin e Abigail Breslin, M. Night Shyamalan decise di non mostrare loro l''aspetto completo dell''alieno fino alle riprese delle scene clou, tenendo i costumi e i pupazzi nascosti.', 'Featurette ''The Making of Signs'' e interviste al cast giovanile', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:51:55.268288+00:00'),
('285cd977-5ac3-4b42-8ed3-ee79d450f975', 340, 'Effetti speciali & Trucco', 'I movimenti coreografici della creatura', 'L''aspetto fisico e i movimenti scattanti dell''alieno furono parzialmente studiati attraverso una combinazione di stuntman professionisti in costume e interventi digitali della Industrial Light & Magic (ILM). Per la scena in cui la creatura attraversa il vicolo cieco in televisione, fu ingaggiato un contorsionista per dare un senso di movimento non umano.', 'Documentario sugli effetti visivi di ILM per ''Signs''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:51:55.268288+00:00'),
('c541c3aa-2c04-4ee2-8c42-504b22d61c79', 340, 'Citazioni & Easter Egg', 'Il cameo di M. Night Shyamalan', 'Come in quasi tutti i suoi film, il regista M. Night Shyamalan interpreta un piccolo ruolo all''interno della pellicola. In ''Signs'' veste i panni di Ray Reddy, l''uomo responsabile dell''incidente d''auto in cui perse la vita la moglie del protagonista Graham Hess.', 'Crediti del film e analisi dei camei del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:51:55.268288+00:00'),
('a2c28f2f-d970-4cea-a5f3-fe461d77c504', 348, 'Segreti di produzione', 'La sequenza di Times Square deserta', 'Per girare la celebre scena in cui David cammina da solo in una Times Square completamente vuota, la produzione ottenne un permesso speciale dalla polizia di New York per chiudere l''area per poche ore all''alba di una domenica mattina di novembre del 2000.', 'Commento audio del regista Cameron Crowe nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:52:15.136143+00:00'),
('46e87eef-079f-4123-9958-4b151feeedfd', 76, 'Curiosità & Retroscena', 'La voce di Yoda nel frammento di visione di Rey', 'Nella sequenza della visione di Rey, oltre alle voci di Ewan McGregor e Alec Guinness, è stato inserito un breve frammento audio inedito registrato da Frank Oz che pronuncia la parola ''It''s energy'', utilizzando campioni scartati delle registrazioni storiche della trilogia originale.', 'Intervista ufficiale al sound designer Matthew Wood', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:39:23.598255+00:00'),
('6a6ddf36-eca5-4249-aa51-75d6430b1b04', 76, 'Casting & Scelte', 'Il rifiuto del ruolo di Poe Dameron da parte di un altro attore', 'Prima che Oscar Isaac venisse definitivamente scritturato per il ruolo del pilota della Resistenza Poe Dameron, la produzione aveva valutato diversi altri attori, tra cui l''attore britannico Dominic Monaghan, il quale fu scartato ma ottenne poi un piccolo ruolo nel capitolo successivo della trilogia.', 'Report di casting della Lucasfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:39:23.598255+00:00'),
('e81b3572-aafb-452b-a7cb-4fb10843a822', 81, 'Segreti di produzione', 'Il titolo di lavorazione segreto ''Blue Harvest''', 'Per evitare speculazioni e l''assalto dei fan o dei media durante le riprese esterne a Buttermilk Ranch in California, la produzione utilizzò il finto titolo ''Blue Harvest - Horror Horror'', fingendo si trattasse di un film horror a basso costo.', 'Documentario ''Classic Creatures: Return of the Jedi''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:39:46.356885+00:00'),
('69ec1789-0155-4665-a5bd-0798b996f7ac', 81, 'Casting & Scelte', 'La scelta iniziale di David Lynch', 'Prima che Richard Marquand venisse ingaggiato, George Lucas offrì la regia del film a David Lynch, il quale declinò l''offerta perché preferì dedicarsi alla regia di ''Dune'' (1984).', 'Interviste storiche a David Lynch e George Lucas', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:39:46.356885+00:00'),
('dd5c538f-6312-4f10-b1fd-f1222a5f59e9', 334, 'Aneddoti dal set', 'La coincidenza mitologica di Brad Pitt', 'Durante le riprese in Messico, Brad Pitt si è realmente infortunato al tendine d''achille mentre girava una sequenza di combattimento, un ironico incidente che rispecchiava la vulnerabilità del personaggio mitologico da lui interpretato.', 'Reportage di produzione e note stampa Warner Bros', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:51:29.899335+00:00'),
('2978f5ff-68fc-432d-bbf5-bf64f3a9236c', 334, 'Casting & Scelte', 'L''addio iniziale di Brad Pitt', 'Brad Pitt aveva inizialmente rifiutato il ruolo di Achille quando gli fu offerto per la prima volta nel 2001, ma cambiò idea dopo che il progetto subì una fase di sviluppo più approfondita con l''arrivo del regista Wolfgang Petersen.', 'Intervista ufficiale a Wolfgang Petersen nel commento audio del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:51:29.899335+00:00'),
('bb4b9f61-a715-4fc2-89e7-8438ba4d3353', 334, 'Casting & Scelte', 'Il rifiuto di Julia Ormond', 'L''attrice Julia Ormond fu originariamente considerata e contattata per interpretare la regina Ecuba, ma dovette rinunciare al progetto a causa di conflitti di programmazione con altri impegni cinematografici.', 'Database di casting e report di pre-produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:51:29.899335+00:00'),
('2b1d30ee-71d0-45ed-86d6-3ce80a566ec9', 79, 'Citazioni & Easter Egg', 'Le urla di Wilhelm nascoste nel film', 'Durante la sequenza in cui Luke Skywalker e Ian Solo cercano di fuggire sparando ai soldati imperiali sulla passerella della Morte Nera, uno Stormtrooper colpito da Luke cade nel vuoto emettendo il celebre ''Wilhelm Scream'', un effetto sonoro d''archivio utilizzato fin dal 1951 in decine di pellicole di Hollywood.', 'Analisi audio ufficiale Skywalker Sound e database di sound design cinematografico', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:39:34.55627+00:00'),
('e8a25d53-3116-494a-88ea-f2c775b8db80', 84, 'Aneddoti dal set', 'L''uso di munizioni e proiettili reali', 'Durante le riprese, Elem Klimov decise di non usare proiettili a salve per molte scene d''azione, facendo sparare munizioni vere a pochi centimetri dalla testa del giovane attore Aleksej Kravčenko, come documentato nei diari di produzione sovietici.', 'Intervista al direttore della fotografia Aleksei Rodionov e documentari di making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:39:59.824607+00:00'),
('fe94aeb8-7acf-4205-a6e2-0e5c6f441c1f', 84, 'Segreti di produzione', 'La morte reale della mucca sul set', 'Nella drammatica scena in cui Florya e la ragazza Glasha attraversano un campo aperto sotto il fuoco nemico, una mucca che fungeva da comparsa animale fu colpita e uccisa da un proiettile vagante sparato durante le riprese.', 'Archivi di produzione Mosfilm e memorie del cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:39:59.824607+00:00'),
('f3127fe6-1926-4291-b0e6-4e76775ca25a', 84, 'Curiosità & Retroscena', 'Il blocco della censura sovietica', 'Il progetto rimase bloccato dalla censura di Stato sovietica per ben otto anni perché considerato ''troppo naturalista'', ''disfattista'' e portatore di un''eccessiva crudezza visiva, prima di ricevere il via libera definitivo nel 1985 per il quarantennale della vittoria.', 'Note storiche sui censori del Goskino sovietico', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:39:59.824607+00:00'),
('70894e17-b75e-4912-abba-dceff8b7c2d8', 84, 'Casting & Scelte', 'La scelta dell''esordiente Aleksej Kravčenko', 'Il regista Elem Klimov scelse Aleksej Kravčenko, all''epoca quindicenne e senza alcuna precedente esperienza di recitazione, dopo averlo sottoposto a provini durissimi mirati a testare la sua resistenza emotiva e la sua fotogenia di fronte alla macchina da presa.', 'Intervista retrospettiva ad Aleksej Kravčenko', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:39:59.824607+00:00'),
('155920af-a86c-47a7-9e01-40d3a9f4c103', 84, 'Segreti di produzione', 'L''autenticità dei costumi e degli oggetti di scena', 'Molti dei costumi militari tedeschi e sovietici utilizzati nel film non erano repliche cinematografiche, ma veri uniformi recuperate nei depositi militari dell''epoca o trovate nei luoghi reali dei combattimenti in Bielorussia.', 'Note dei reparti costumi e scenografia della Mosfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:39:59.824607+00:00'),
('912bda54-373f-477a-9f0c-e2be2a3e427f', 84, 'Segreti di produzione', 'Il vero fucile d''assalto sottratto ai partigiani', 'Il vecchio fucile che il giovane protagonista Florya recupera per unirsi ai partigiani era un''arma d''epoca originale disattivata ma perfettamente conservata, proveniente direttamente dai musei storici locali della resistenza bielorussa.', 'Dichiarazioni del reparto armeria della troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:39:59.824607+00:00'),
('499c4941-333c-4072-96d6-8b7b29d4237f', 84, 'Effetti speciali & Trucco', 'La trasformazione fisica estrema del protagonista', 'Per simulare l''invecchiamento precoce e il trauma estremo del volto di Florya nel corso della narrazione, il truccatore e il regista non si affidarono solo al trucco prostetico ma sfruttarono i mesi reali di lavorazione e il drastico dimagrimento forzato dell''attore sul set.', 'Making-of ufficiale e note di regia di Elem Klimov', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:39:59.824607+00:00'),
('a90d6e4a-6940-4f06-9728-e0bd50794100', 334, 'Casting & Scelte', 'Le reali origini di Diane Kruger', 'Per il ruolo di Elena di Troia, Wolfgang Petersen visionò oltre 200 attrici in tutto il mondo prima di scegliere la tedesca Diane Kruger, la quale dovette ingrassare di circa sei chili per acquisire una corporatura più vicina ai canoni estetici dell''epoca.', 'Note di produzione ufficiali e intervista a Diane Kruger', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:51:29.899335+00:00'),
('48539d4f-2967-4334-8a33-125c3b264180', 334, 'Segreti di produzione', 'La ricostruzione digitale delle navi greche', 'La celebre flotta greca composta da ''mille navi'' non fu realizzata costruendo un migliaio di imbarcazioni reali: la produzione ne realizzò solo un numero limitato a grandezza naturale, mentre il resto fu moltiplicato digitalmente attraverso avanzati software di CGI.', 'Documentario sul making-of nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:51:29.899335+00:00'),
('407208de-9083-44ad-8b39-e0ef2334eae7', 334, 'Curiosità & Retroscena', 'Il cambio location dell''ultimo minuto', 'Le riprese principali dovevano originariamente svolgersi in gran parte a Malta, ma il governo maltese e la produzione non trovarono un accordo definitivo, costringendo la troupe a spostare il set in Marocco e a Cabo San Lucas in Messico.', 'Archivio storico di Variety e comunicati stampa della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:51:29.899335+00:00'),
('f9a0bbfb-e8d9-46fa-9026-46d20c089b17', 358, 'Casting & Scelte', 'La trasformazione fisica di Matt Damon', 'Per interpretare Tom Ripley, Matt Damon dovette perdere quasi tredici chili e imparare a remare, sciare e suonare il sassofono oltre al pianoforte, per incarnare la differenza di classe sociale e corporatura rispetto al muscoloso Dickie Greenleaf interpretato da Jude Law.', 'Note di produzione e intervista a Matt Damon nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:52:39.042173+00:00'),
('288cb0c6-9663-4091-8218-21b191fa776b', 358, 'Casting & Scelte', 'Il rifiuto iniziale di Tom Cruise', 'Prima che la parte di Tom Ripley fosse affidata a Matt Damon, il regista Anthony Minghella prese in considerazione diversi giovani attori di Hollywood, tra cui Tom Cruise, che era stato valutato per il ruolo principale nei primi stadi di sviluppo del progetto negli anni ''90.', 'Archivi di pre-produzione della Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:52:39.042173+00:00'),
('99403c87-9b87-4058-99c6-b8dbef9a4d14', 358, 'Segreti di produzione', 'L''ispirazione per i costumi di Gwyneth Paltrow', 'La costumista Ann Roth creò il guardaroba di Marge Sherwood (Gwyneth Paltrow) ispirandosi direttamente alle fotografie d''epoca di Gloria Vanderbilt e alle icone dell''alta società americana in vacanza in Italia alla fine degli anni ''50.', 'Documentario sui costumi nel dietro le quinte del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:52:39.042173+00:00'),
('a5ac68d0-5625-461f-a032-d6752f7f8003', 80, 'Aneddoti dal set', 'Le scarpe da ginnastica di Luke Skywalker congelate', 'Durante le riprese degli esterni sulla neve a Finse, in Norvegia, le temperature scesero drasticamente fino a -28°C. Mark Hamill ha più volte raccontato che in alcune inquadrature ravvicinate in cui camminava nella neve profonda, gli stivali di scena si rivelarono inadatti e dovette indossare provvisoriamente delle normali scarpe da ginnastica nascoste sotto i pantaloni imbottiti.', 'Intervista retrospettiva a Mark Hamill per il ventennale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:39:40.584971+00:00'),
('402f3121-e575-448a-a2e3-dd719050ab96', 80, 'Citazioni & Easter Egg', 'Il cameo dei produttori nel centro di comando della Ribellione', 'Nelle sequenze ambientate all''interno della base della Alleanza Ribelle sul pianeta ghiacciato di Hoth, compaiono nei panni di ufficiali ribelli secondari il produttore Howard Kazanjian e il production designer Norman Reynolds, inseriti come comparse per riempire i quadri scenici in economia di personale.', 'Guida ufficiale agli Easter Egg di Star Wars e crediti di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:39:40.584971+00:00'),
('606735a0-70c9-4c11-ad09-cc468741eb8b', 80, 'Segreti di produzione', 'Il segreto di produzione del droide medico EV-9D9', 'Il droide sadico EV-9D9, che supervisiona la conversione dei droidi nel palazzo di Jabba (scena poi approfondita ma le cui basi furono gettate durante le riprese dell''Impero), fu realizzato combinando parti meccaniche di scarto e animato tramite controllo radio combinato a fili nascosti fuori campo dalla troupe degli effetti speciali di Stuart Freeborn.', 'Making-of e manuale ufficiale degli effetti speciali della Industrial Light & Magic', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:39:40.584971+00:00'),
('b1f86bb4-e6aa-4fe6-8e85-075df479e25b', 336, 'Segreti di produzione', 'La rapidità record delle riprese di Clint Eastwood', 'Come da sua consuetudine, Clint Eastwood ha completato le riprese principali di Mystic River in soli 39 giorni, terminando spesso le giornate lavorative in anticipo rispetto alla tabella di marcia e senza quasi mai ricorrere a riprese aggiuntive.', 'Note di produzione ufficiali della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:51:37.575872+00:00'),
('a0b1d044-acaa-4356-8785-889b3f47ff58', 336, 'Aneddoti dal set', 'Il metodo di recitazione di Sean Penn e Tim Robbins', 'Durante la lavorazione, Sean Penn e Tim Robbins mantenevano una concentrazione feroce ed evitavano di socializzare eccessivamente sul set per preservare la tensione emotiva e il senso di alienazione richiesti dai loro complessi personaggi.', 'Intervista al cast nel documentario ''The Making of Mystic River''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:51:37.575872+00:00'),
('45547cc2-0a87-4dd0-a95e-b1a6da1c373e', 336, 'Curiosità & Retroscena', 'L''ispirazione per la colonna sonora minimalista', 'Clint Eastwood ha composto personalmente il tema musicale principale del film, affidando poi lo sviluppo orchestrale alla Boston Symphony Orchestra, mantenendo una partitura sobria e malinconica per non sovraccaricare il dramma.', 'Note di copertina della colonna sonora ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:51:37.575872+00:00'),
('e8b5e1d5-7351-4a37-ba47-16c246fd0dff', 336, 'Casting & Scelte', 'Il rifiuto del ruolo di Jimmy Marcus da parte di Michael Keaton', 'Prima che Sean Penn ottenesse l''acclamato ruolo di Jimmy Marcus (poi premiato con l''Oscar), l''attore Michael Keaton era stato originariamente preso in considerazione per la parte nelle prime fasi di sviluppo del progetto.', 'Archivio storico di casting di Hollywood (Variety)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:51:37.575872+00:00'),
('8ea040a9-e847-42a9-9fb5-439a4e496666', 336, 'Aneddoti dal set', 'Il doppiaggio originale e le indicazioni verbali del regista', 'Clint Eastwood è noto per non urlare mai ''azione'' o ''taglia'' sul set, preferendo sussurrare le indicazioni agli attori e mantenere un clima di estrema tranquillità che favorisce la spontaneità delle interpretazioni drammatiche.', 'Intervista a Kevin Bacon nel talk show di Charlie Rose', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:51:37.575872+00:00'),
('fe53c04a-4e1e-4abd-9e5b-5ca17b7fea8c', 336, 'Effetti speciali & Trucco', 'La trasformazione fisica di Marcia Gay Harden', 'Per interpretare Celeste Boyle, l''attrice Marcia Gay Harden ha lavorato a stretto contatto con i reparti di trucco e parrucco per adottare un aspetto dimesso e logorato dal dolore, privo di qualsiasi artificio estetico hollywoodiano.', 'Commento audio del DVD con il cast e la troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:51:37.575872+00:00'),
('824cdf0d-e187-4203-b939-c91200a83291', 360, 'Casting & Scelte', 'La preparazione di Haley Joel Osment per il provino', 'Haley Joel Osment ottenne la parte di Cole Sear dopo un''audizione folgorante in cui lesse l''intero copione la notte prima del provino, senza averlo mai visto prima. M. Night Shyamalan rimase talmente sbalordito dalla sua intensità emotiva da offrirgli immediatamente la parte, superando la concorrenza di centinaia di altri giovani attori.', 'Commento audio del regista nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:52:47.310727+00:00'),
('88d27041-3d4b-4ee6-baaf-9451d9f50b44', 360, 'Segreti di produzione', 'La scelta del colore rosso come marcatore spettrale', 'Il regista M. Night Shyamalan e il direttore della fotografia Tak Fujimoto decisero di utilizzare il colore rosso in modo strategico per segnalare ogni volta la presenza del mondo dei morti o eventi legati al soprannaturale. Ogni volta che il colore rosso appare sullo schermo (dai vestiti ai palloncini), indica un punto di contatto tra il mondo reale e quello spettrale.', 'Documentario ''The Making of The Sixth Sense'' (Blu-ray bonus features)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:52:47.310727+00:00'),
('0022ceb1-d43b-469e-b7e2-36c92087fd34', 360, 'Aneddoti dal set', 'L''improvvisazione della balbuzie di Donnie Wahlberg', 'Per interpretare l''ex paziente mentalmente instabile Vincent Gray, l''attore Donnie Wahlberg perse circa venti chili in poche settimane e mantenne una rigorosa tabella di isolamento sul set. Molte delle sue esitazioni vocali e della sua disperazione nella scena iniziale del bagno furono perfezionate attraverso intense prove fisiche che lasciarono impressionata la troupe.', 'Note di produzione e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:52:47.310727+00:00'),
('fde8dbc0-9a99-4bae-8af8-faba38d2a659', 360, 'Effetti speciali & Trucco', 'Il trucco per simulare il respiro freddo', 'Poiché le scene in cui i fantasmi si manifestano richiedevano il tipico effetto del vapore acqueo dovuto al freddo, la produzione non poté utilizzare veri ambienti refrigerati per non danneggiare la strumentazione e la recitazione dei bambini. Gran parte dell''effetto del respiro congelato fu aggiunto in post-produzione tramite CGI, mentre in alcune inquadrature dal vivo venivano utilizzate piccole cannule d''aria fredda nascoste.', 'Rivista ''American Cinematographer'', articolo tecnico sul film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:52:47.310727+00:00'),
('a6100593-884c-421c-b4a5-056c604e7714', 360, 'Curiosità & Retroscena', 'L''ispirazione per la struttura narrativa da ''Ai confini della realtà''', 'M. Night Shyamalan ha più volte ammesso in varie interviste che l''impostazione generale del colpo di scena e il tono malinconico del film traggono ispirazione diretta dai classici episodi a twist narrativo della celebre serie televisiva antologica ''The Twilight Zone'' (Ai confini della realtà).', 'Intervista retrospettiva a M. Night Shyamalan per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:52:47.310727+00:00'),
('51bddd62-4165-480d-9538-bbb26b60296c', 360, 'Citazioni & Easter Egg', 'Il cameo del regista nei panni del medico', 'Il regista M. Night Shyamalan appare nel film in un cameo nei panni del dottor Hill, il medico che visita il personaggio di Toni Collette dopo che quest''ultima scopre la stanza di Cole in disordine, interrogandola sui presunti abusi subiti dal bambino.', 'IMDb Trivia e crediti ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:52:47.310727+00:00'),
('6d704d80-55a2-4004-87d4-8b98f9f49af9', 81, 'Curiosità & Retroscena', 'Il cambio di titolo da ''Revenge'' a ''Return''', 'Il film fu originariamente intitolato ''Revenge of the Jedi'' (La vendetta dello Jedi), ma George Lucas cambiò il titolo pochi mesi prima dell''uscita cinematografica perché riteneva che uno Jedi non dovesse mai cercare vendetta.', 'Note di produzione e materiali promozionali originali del 1982', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:39:46.356885+00:00'),
('8a6990ea-a441-4c81-8098-c275d9815c2a', 81, 'Citazioni & Easter Egg', 'La mano cibernetica di Luke e l''omaggio a Anakin', 'Quando la mano di Luke viene colpita da un raggio blaster durante la battaglia sull''imbarcazione di Jabba, la pelle sintetica salta via rivelando una struttura meccanica che richiama fortemente il design interno delle braccia robotiche di Dart Fener.', 'Analisi visiva e commento audio del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:39:46.356885+00:00'),
('5278d6f4-d1be-4293-a1c4-948ed64836db', 81, 'Effetti speciali & Trucco', 'La voce di Salacious Crumb creata da un doppiatore Disney', 'Il famigerato animaletto di Jabba the Hutt, Salacious Crumb, fu doppiato da Mark Dodson, il quale utilizzò registrazioni accelerate e manipolate della voce di un attore che imitava una risata acuta e stridula.', 'Archivi della Industrial Light & Magic', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:39:46.356885+00:00'),
('5d6608f8-bcd4-4641-8bcf-c62e46cdf2c8', 81, 'Aneddoti dal set', 'Il costume di Ewok e il caldo soffocante', 'Gli attori e i ballerini che indossavano i costumi degli Ewok nelle sequenze girate nei boschi di Crescent City soffrirono terribilmente il caldo all''interno delle pesanti pellicce sintetiche, tanto che sul set dovettero essere allestite tende con aria condizionata e paramedici dedicati.', 'Special TV ''The Making of Star Wars: Return of the Jedi''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:39:46.356885+00:00'),
('0710095a-dd48-40de-bdee-0af35e691d8f', 81, 'Aneddoti dal set', 'La morte improvvisa di un operatore di ripresa', 'Durante la produzione iniziale nei deserti di Yuma (Arizona), la troupe affrontò temperature proibitive e una tempesta di sabbia danneggiò numerose attrezzature, mentre un membro della troupe locale colse un malore fatale legato al caldo estremo.', 'Diari di produzione della Lucasfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:39:46.356885+00:00'),
('064a84a6-c028-4d00-97b9-19bcc45fb386', 81, 'Effetti speciali & Trucco', 'Stuart Freeborn e i pupazzi dei惻 Ewok', 'Il leggendario truccatore Stuart Freeborn progettò i volti degli Ewok dotandoli di meccanismi di cavi nascosti per permettere ai burattinai di muovere occhi e bocca, ispirandosi in parte al volto del suo stesso cane e a un piccolo scimpanzé.', 'Documentario sui trucchi di scena di Stuart Freeborn', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:39:46.356885+00:00'),
('f55e49b5-8c87-454c-be8b-fda08718418e', 81, 'Citazioni & Easter Egg', 'Il cameo di John Williams accreditato come musicista', 'Sebbene non compaia visivamente come attore, il celebre compositore John Williams diresse interamente la London Symphony Orchestra per la colonna sonora, vincendo numerosi riconoscimenti per i nuovi temi musicali introdotti, inclusi quelli dell''Imperatore.', 'Note di copertina dell''album originale della colonna sonora', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T15:39:46.356885+00:00'),
('cd652c4d-6895-4eee-91bd-6edf6d9fe494', 81, 'Segreti di produzione', 'La scena tagliata della tempesta di sabbia', 'Inizialmente fu girata una lunga sequenza in cui i protagonisti lasciavano il palazzo di Jabba affrontando una violenta tempesta di sabbia nel deserto di Tatooine prima di salire a bordo delle loro navette, ma fu tagliata nel montaggio finale per migliorare il ritmo dell''inizio.', 'Materiali d''archivio e scene tagliate inserite nelle edizioni speciali in Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T15:39:46.356885+00:00'),
('9a400dc2-ae86-4fdb-985a-9dd9a76137b0', 337, 'Aneddoti dal set', 'La spalla lussata sotto il peso della croce', 'Nel girare la sequenza in cui Gesù cade rovinosamente sotto il peso della pesante croce di legno, Jim Caviezel si lussò accidentalmente la spalla. Il peso reale della croce, unito alle protesi di trucco e alla stanchezza fisica, rese l''incidente particolarmente doloroso ma la scena rimase nel montaggio finale.', 'Documentario ''The Making of The Passion of the Christ''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:51:42.433094+00:00'),
('25a296d2-fb68-43eb-a34a-764aabd51bd3', 337, 'Effetti speciali & Trucco', 'Le cicatrici permanenti del trucco di flagellazione', 'Il capo del reparto trucco Keith VanderLaan e la sua squadra impiegavano fino a otto ore al giorno per applicare le protesi e i segni delle percosse su Jim Caviezel. Il trucco era così complesso e aderente alla pelle che l''attore sviluppò vere e proprie irritazioni e piccoli tagli che richiesero settimane per guarire dopo la fine delle riprese.', 'Note di produzione e intervista a Keith VanderLaan', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:51:42.433094+00:00'),
('5b3655c7-3bfb-4475-986d-3a64ca4f1efc', 337, 'Segreti di produzione', 'Il doppiaggio segreto delle lingue morte', 'Poiché il film fu girato interamente in aramaico antico e latino, gran parte del cast internazionale dovette imparare le battute foneticamente. In fase di post-produzione, Mel Gibson fece doppiare alcuni attori da madrelingua o esperti di filologia classica per perfezionare la dizione e la corretta cadenza storica delle lingue antiche.', 'Commento audio del regista Mel Gibson nell''edizione DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:51:42.433094+00:00'),
('0b675ce7-8938-4301-bdfc-2994d8847e2f', 337, 'Effetti speciali & Trucco', 'L''uso dei corvi ammaestrati nella scena finale', 'Nella drammatica scena in cui uno dei ladri crocifissi subisce la mutilazione da parte di un uccello, la troupe si affidò a corvi ammaestrati sul set. Tuttavia, per evitare qualsiasi rischio o sofferenza all''animale durante i dettagli ravvicinati, vennero impiegati ingegnosi elementi animatronici controllati via cavo dalla squadra di effetti speciali.', 'Making-of ufficiale e speciali sugli effetti visivi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:51:42.433094+00:00'),
('01e5c602-bef9-4af9-9938-8ba3aed7796a', 337, 'Casting & Scelte', 'La scelta del look senza sopracciglia per i demoni', 'Per rendere l''aspetto dei demoni e delle figure diaboliche inquietante e fuori dal comune, Mel Gibson e i truccatori decisero di far radere completamente le sopracciglia a diversi attori e comparse. Questo dettaglio sottile alterava la simmetria del volto umano, generando nello spettatore un senso inconscio di profondo disagio.', 'Intervista al reparto trucco e parrucco', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:51:42.433094+00:00'),
('345fa151-6d84-4197-b8c2-45ad561212b6', 337, 'Curiosità & Retroscena', 'La proiezione privata per Papa Giovanni Paolo II', 'Prima dell''uscita cinematografica ufficiale, il film fu proiettato in Vaticano per Papa Giovanni Paolo II. Secondo quanto riferito dal segretario personale del pontefice, Stanisław Dziwisz, il Papa dopo la visione pronunciò la celebre frase: ''È stato così come è stato'', confermando indirettamente l''impatto emotivo della pellicola.', 'Dichiarazioni ufficiali della Santa Sede e stampa internazionale dell''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:51:42.433094+00:00'),
('70aa205c-1c20-4dbc-b5f3-94e9a37f8bd0', 343, 'Curiosità & Retroscena', 'La lettura del romanzo prima dei fratelli Weitz', 'I registi Chris e Paul Weitz scoprirono il bestseller di Nick Hornby quasi per caso durante un volo aereo, rimanendo così folgorati dalla storia da decidere immediatamente di opzionarne i diritti cinematografici prima ancora di terminare la lavorazione di American Pie.', 'Commento audio del DVD e note di produzione Working Title', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:52:03.349504+00:00'),
('2b1d6002-c9e0-47d3-a895-8c5dec6dd4c9', 83, 'Curiosità & Retroscena', 'Le proiezioni delle equazioni di Kip Thorne', 'Il fisico teorico premio Nobel Kip Thorne ha partecipato attivamente alla sceneggiatura, pretendendo che le equazioni scritte sulla lavagna nel film fossero reali calcoli matematici complessi relativi alla gravità quantistica.', 'Libro ''The Science of Interstellar'' di Kip Thorne', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:39:55.487863+00:00'),
('906c4e48-d7f1-4862-94d2-9ab5a415e7a7', 83, 'Casting & Scelte', 'Il provino di Matthew McConaughey basato su ''Mud''', 'Christopher Nolan decise di assumere Matthew McConaughey dopo averlo visto nel film indipendente ''Mud'' (2012), notando in lui la combinazione perfetta di pragmatismo rurale e profondità emotiva adatta a interpretare Cooper.', 'Intervista a Christopher Nolan per The Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:39:55.487863+00:00'),
('00bff19c-8b69-4e7f-858e-0904098d7b55', 83, 'Effetti speciali & Trucco', 'L''uso dei proiettori IMAX al posto del green screen', 'Invece di usare il green screen, Nolan fece proiettare enormi animazioni delle galassie e dello spazio direttamente sui pannelli LED fuori dalle finestre della navicella, permettendo agli attori di recitare con riflessi di luce reali sui loro volti.', 'Making-of ufficiale nel Blu-ray Disc', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:39:55.487863+00:00'),
('d85a536d-6a07-458a-8307-974ce599087b', 83, 'Segreti di produzione', 'Il modello in scala gigante dell''Endurance', 'Per molte sequenze di volo, la troupe non ha usato la CGI ma ha filmato un modello in scala dettagliato lungo oltre 15 metri, muovendolo con bracci meccanici di precisione per catturare la luce naturale.', 'Documentario ''Building a Interstellar'' nel materiale extra', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:39:55.487863+00:00'),
('608c1bce-5c2f-4b11-8a87-b9feed4777c2', 83, 'Curiosità & Retroscena', 'L''organo della chiesa come ispirazione per la colonna sonora', 'Hans Zimmer compose la colonna sonora usando principalmente un organo a canne del XX secolo situato nella Temple Church di Londra, desiderando conferire al film un tono spirituale e trascendentale.', 'Intervista a Hans Zimmer per NPR Music', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:39:55.487863+00:00'),
('f924e63e-da4e-4427-a9ff-aa20c15bea32', 341, 'Curiosità & Retroscena', 'L''origine letteraria e il legame con Total Recall', 'Il film è basato sul racconto breve omonimo di Philip K. Dick del 1956. Inizialmente, la sceneggiatura scritta da Jon Cohen fu concepita nei primi anni ''90 come un sequel diretto di ''Atto di forza'' (Total Recall, 1990) con Arnold Schwarzenegger, prima che il progetto venisse radicalmente riscritto e affidato a Spielberg.', 'Archivi della sceneggiatura e interviste agli sceneggiatori', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:51:59.858683+00:00'),
('c9a5ca60-11a7-4eff-a942-0b7057e0317d', 341, 'Citazioni & Easter Egg', 'Cameron Diaz non accreditata', 'Cameron Diaz appare in un rapidissimo cameo non accreditato nei panni di una passeggera della metropolitana che legge un giornale, accanto al regista di seconda unità e produttore esecutivo Gary Scott Thompson. La sua presenza fu il risultato di una visita sul set in amicizia con Tom Cruise.', 'Commento audio del regista Steven Spielberg / IMDb Trivia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:51:59.858683+00:00'),
('47648540-668f-4057-94e4-05c189ec293e', 341, 'Effetti speciali & Trucco', 'Il cambio di tonalità cromatica in post-produzione', 'Per conferire l''aspetto freddo, desaturato e metallico tipico del genere noir, il direttore della fotografia Janusz Kamiński e Spielberg utilizzarono una tecnica di elaborazione della pellicola chiamata ''bleach bypass'' (trattamento di ritenzione dell''argento), che riduce drasticamente la saturazione dei colori aumentando il contrasto.', 'Interviste tecniche a Janusz Kamiński su American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:51:59.858683+00:00'),
('d1cfd4ea-630a-4137-abd1-2de52f7fbc9c', 341, 'Segreti di produzione', 'La Lexus futuristica su misura', 'La casa automobilistica Lexus commissionò appositamente un concept car futuristico guidato da celle a combustibile per il film, spendendo milioni di dollari. Il veicolo, guidato da Tom Cruise nella fuga, fu progettato per riflettere le tendenze del design automobilistico ipotizzate per la metà del XXI secolo.', 'Comunicati stampa ufficiali Lexus e documentario sul design del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:51:59.858683+00:00'),
('784ea384-ccad-4ba5-980d-8c4cc3506732', 349, 'Casting & Scelte', 'Il rifiuto di Charlize Theron', 'Prima che Kate Beckinsale ottenesse la parte dell''infermiera Evelyn Johnson, il regista Michael Bay aveva offerto il ruolo principale femminile a Charlize Theron. L''attrice decise tuttavia di rifiutare l''offerta per poter recitare nel film ''Sweet November - Dolce novembre'' accanto a Keanu Reeves.', 'Reportage di casting di Variety e Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:52:19.169387+00:00'),
('a5784b3a-2412-4c34-aec5-0e96167976b2', 349, 'Casting & Scelte', 'La scelta iniziale per Rafe McCawley', 'Nelle prime fasi di sviluppo della sceneggiatura, la produzione aveva valutato attori come Matt Damon e Mark Wahlberg per interpretare il pilota protagonista Rafe McCawley, prima di affidare definitivamente la parte a Ben Affleck.', 'Note di produzione ufficiali della Touchstone Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:52:19.169387+00:00'),
('4ffd740a-63f3-4b5b-929e-3df7bdce3fdc', 349, 'Segreti di produzione', 'I veri aerei storici impiegati', 'Per garantire il massimo realismo nelle sequenze di volo, la produzione ha recuperato e restaurato alcuni velivoli d''epoca autentici, tra cui veri caccia Curtiss P-40 Warhawk, affiancati da riproduzioni in scala e aerei acrobatici modificati per le riprese più pericolose.', 'Documentario ''The Making of Pearl Harbor'' sul DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:52:19.169387+00:00'),
('e5cb2456-0fff-44df-9c87-e311ed783e05', 349, 'Aneddoti dal set', 'La portaerei USS Lexington come set', 'Molte delle sequenze ambientate sulle navi da guerra americane non sono state ricostruite in CGI o in studio, ma sono state girate a bordo della vera portaerei museo USS Lexington (CV-16), ormeggiata a Corpus Christi in Texas.', 'Commento audio del regista Michael Bay e del produttore Jerry Bruckheimer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:52:19.169387+00:00'),
('ddae2a7b-e914-43ed-9a77-ee98f4513819', 349, 'Effetti speciali & Trucco', 'Il record di esplosioni controllate', 'La celebre sequenza dell''attacco aereo giapponese ha stabilito un record cinematografico per il numero di esplosioni controllate eseguite simultaneamente dal vivo, impiegando oltre 700 stecche di dinamite, 2.000 litri di benzina e centinaia di metri di corda detonante sotto la supervisione del pirotecnico John Frazier.', 'Guinness World Records e documentario sugli effetti speciali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:52:19.169387+00:00'),
('f588c08e-d57b-4b63-9f3d-18d17293280f', 349, 'Citazioni & Easter Egg', 'Il cameo di Ben Affleck Senior', 'Timothy Affleck, il padre di Ben Affleck, fa una breve apparizione non accreditata nel film nei panni di un ufficiale in una delle scene ambientate durante i preparativi militari prima dell''attacco.', 'Trivia ufficiale di IMDb e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:52:19.169387+00:00'),
('f8979ea6-ba79-4aff-ab80-8dfb80660c6b', 349, 'Curiosità & Retroscena', 'La collaborazione con il Pentagono', 'Il Dipartimento della Difesa degli Stati Uniti ha fornito un ampio supporto logistico alla produzione, consentendo l''accesso a basi militari attive, navi e personale in cambio della supervisione sulla sceneggiatura per assicurarsi che i militari fossero ritratti con il dovuto rispetto storico.', 'Archivi ufficiali del Dipartimento della Difesa USA e comunicati stampa della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:52:19.169387+00:00'),
('f98acc91-7af2-4f3b-81a5-e89a13d0d761', 85, 'Aneddoti dal set', 'L''infortunio di Dan Richter sul set', 'Dan Richter, il mimo che interpretava il capo dei primati ''Guida-la-Luna'' nella sequenza iniziale ''L''alba dell''uomo'', si ruppe un costato durante le riprese a causa del pesante costume di pelo e delle sollecitazioni fisiche richieste per la scena dell''osso usato come arma.', 'Memorie di Dan Richter nel libro ''The Making of Kubrick''s 2001''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:40:03.786084+00:00'),
('6fc7f8d4-eb41-44cc-b357-402b54d52de3', 85, 'Effetti speciali & Trucco', 'Il trucco dei front-projection per le scimmie', 'Stanley Kubrick evitò di girare in esterni con attori vestiti da scimmie ricorrendo alla tecnica del front-projection perfezionata da retroscena fotografici scattati in Africa. Questo permise di integrare perfettamente i primati in studio con sfondi reali senza ricorrere al blu screen, all''epoca imperfetto.', 'American Cinematographer, giugno 1968', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:40:03.786084+00:00'),
('c75b2b23-e8b5-4ff6-bb78-ffcb9fe54543', 85, 'Citazioni & Easter Egg', 'Il cameo vocale di Vivian Kubrick', 'La bambina che parla al padre alla stazione spaziale tramite una videochiamata (la videotelefonia futuristica) è interpretata da Vivian Kubrick, figlia del regista, all''epoca di soli tre anni. Il padre la diresse personalmente per farle pronunciare la battuta sul regalo di compleanno.', 'Note audio del commento al film e biografia di Stanley Kubrick', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:40:03.786084+00:00'),
('9919cdee-1d9e-460e-868c-f8ca7d8ad65f', 85, 'Curiosità & Retroscena', 'Il mistero delle voci doppiate in post-produzione', 'Molti degli attori secondari e delle comparse che interpretavano gli scienziati e i tecnici nel film parlavano lingue diverse o recitavano battute casuali sul set (il cosiddetto ''mumble''), poiché Kubrick sapeva che avrebbe doppiato quasi l''intero cast in fase di post-produzione per avere il controllo totale sulla dizione.', 'Making-of ufficiale e diari di produzione di Arthur C. Clarke', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:40:03.786084+00:00'),
('d0f49b84-0336-48f8-a067-48d584c5397a', 343, 'Citazioni & Easter Egg', 'Il cameo mancato di Nick Hornby', 'L''autore del romanzo originale, Nick Hornby, avrebbe dovuto fare un breve cameo nel film nei panni di uno dei genitori presenti al gruppo di supporto per padri single, ma rifiutò all''ultimo momento per timore di risultare troppo imbarazzato davanti alla cinepresa.', 'Intervista retrospettiva a Nick Hornby per The Guardian', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:52:03.349504+00:00'),
('63718e18-1d22-4149-9ec9-0050f855ab4a', 343, 'Aneddoti dal set', 'L''improvvisazione sulle scarpe di marca', 'La celebre sequenza in cui il giovane Nicholas Hoult viene deriso a scuola per via delle sue scarpe da ginnastica non di marca fu arricchita da diversi dettagli improvvisati sul set per ricreare accuratamente le reali pressioni sociali subite dai ragazzi nella Gran Bretagna di quegli anni.', 'Making-of ufficiale incluso nell''edizione home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:52:03.349504+00:00'),
('6145f81f-6989-4847-99bb-fc8fefb12cb0', 343, 'Curiosità & Retroscena', 'Il coinvolgimento musicale di Badly Drawn Boy', 'Damon Gough, noto come Badly Drawn Boy, compose l''intera colonna sonora indossando costantemente il suo iconico cappello di lana anche durante le sessioni di registrazione in studio, diventando un vero e proprio alter ego musicale del protagonista Will Freeman.', 'Note di copertina dell''album della colonna sonora e interviste promozionali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:52:03.349504+00:00'),
('f96bd888-f3cb-4d58-b2e7-2d7f46ce7cf9', 343, 'Segreti di produzione', 'La scelta della location per il parco', 'Molte delle scene all''aperto ambientate nei parchi londinesi furono girate in realtà a Regent''s Park e nei dintorni di Clerkenwell, richiedendo complesse autorizzazioni per gestire il traffico cittadino e la folla di curiosi attratta dalla presenza di Hugh Grant.', 'Production notes e reportage dal set di Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:52:03.349504+00:00'),
('ee647134-ad48-4052-9f6b-328ae7a4dc28', 356, 'Segreti di produzione', 'Il budget ridotto e le riprese in 25 giorni', 'Il film fu realizzato con un budget estremamente limitato stimato intorno ai 4,5 milioni di dollari. La troupe completò l''intero piano di lavorazione in soli 25 giorni di riprese effettive, imponendo ritmi serrati e una pianificazione meticolosa da parte di Christopher Nolan.', 'Audio commento del regista nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:52:31.992971+00:00'),
('b4b8d499-6c9b-44d2-aa3e-b5a29345f560', 356, 'Casting & Scelte', 'Brad Pitt quasi nel cast principale', 'Prima che la produzione ingaggiasse Guy Pearce, l''agente di Brad Pitt mostrò grande interesse per la sceneggiatura dopo che l''attore l''aveva letta. Pitt espresse il desiderio di interpretare Leonard Shelby, ma il progetto sfumò a causa di conflitti di programmazione con le riprese di ''Spy Game''.', 'Dichiarazioni del produttore Aaron Ryder e interviste di casting', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:52:31.992971+00:00'),
('16dff4a3-ad81-4655-872d-f88d574b3450', 356, 'Aneddoti dal set', 'L''auto di Leonard e i problemi di continuità', 'La vettura guidata da Leonard nel film è una Jaguar XJ del 1986. Poiché la produzione possedeva un budget ridotto, furono acquistate due berline identiche da utilizzare come auto di scorta per le scene di guida e per eventuali pezzi di ricambio durante le riprese in esterni a Los Angeles.', 'Note di produzione e reparti veicoli di scena', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:52:31.992971+00:00'),
('5be44582-966b-4c21-9df6-e0d67e11581f', 356, 'Effetti speciali & Trucco', 'Il tatuaggio sul petto con un errore di ortografia', 'Sul petto del personaggio di Leonard compare il celebre comando tatuato ''FIND JOHN G. RAPEOUT''. Durante le prime fasi di progettazione del trucco prostetico, il dipartimento artistico rischiò di includere un errore di battitura nella dicitura provvisoria, corretta appena in tempo prima di applicare il calco definitivo su Guy Pearce.', 'Making-of incluso nell''edizione speciale Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:52:31.992971+00:00'),
('b174df08-d65b-4db6-bb7d-10e3fc315bb8', 356, 'Curiosità & Retroscena', 'L''ispirazione visiva da Nicolas Roeg', 'Christopher Nolan ha più volte dichiarato di aver tratto ispirazione dalla struttura narrativa non lineare del film ''A Venezia... un dicembre rosso shocking'' (''Don''t Look Now'') diretto da Nicolas Roeg nel 1973. Tale influenza si riflette soprattutto nella gestione psicologica dei frammenti di memoria e del lutto.', 'Intervista retrospettiva a Christopher Nolan per Filmmaker Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:52:31.992971+00:00'),
('a4564344-0f3a-4051-bdc8-50a3d766f9c6', 356, 'Casting & Scelte', 'Thomas Lennon e il cameo medico', 'L''attore Thomas Lennon, noto soprattutto per la serie ''Reno 911!'', interpreta un breve ma fondamentale ruolo nei panni del medico che esamina Leonard nella sequenza dell''ospedale. Lennon accettò la parte in extremis e girò le sue sequenze in una sola giornata sul set.', 'Crediti ufficiali del film e archivi di casting', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:52:31.992971+00:00'),
('d294528a-0eb8-48b7-9f05-355c91b0ab01', 367, 'Casting & Scelte', 'Il provino di Tom Felton per il ruolo di Arthur', 'Tom Felton ha ottenuto la parte di Arthur dopo che il regista Kirill Sokolov ha visionato un suo provino autogestito in cui l''attore recitava una scena di dialogo in russo maccheronico, impressionando la produzione per la sua capacità di adattarsi allo stile grottesco richiesto.', 'Intervista ufficiale di Kirill Sokolov per Variety, novembre 2026', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 4, '2026-11-03T16:14:40.167506+00:00'),
('2d953f33-18e4-48d2-b7b6-8c9eddaac3c3', 86, 'Casting & Scelte', 'Il rifiuto di Dustin Hoffman e Al Pacino', 'Prima che Sylvester Stallone ottenesse la parte, il ruolo di John Rambo fu offerto a numerose star di Hollywood, tra cui Dustin Hoffman, Al Pacino, Robert De Niro, Paul Newman e Clint Eastwood. Molti di essi rifiutarono perché ritenevano il personaggio del veterano troppo violento e privo di speranza.', 'Documentario Behind the Scenes e note di pre-produzione della Carolco/Orion', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:40:08.789648+00:00'),
('e8bfa8c3-097f-44bb-ba5f-9772ee27c6b9', 86, 'Aneddoti dal set', 'Il salto reale senza controfigure', 'Durante la sequenza in cui Rambo fugge braccato dalla polizia saltando da una parete rocciosa e finendo appeso a un ramo d''albero, Sylvester Stallone insistette per girare la scena personalmente. Nell''impatto con il ramo si fratturò accidentalmente una costola, un infortunio reale che rese autentiche le sue smorfie di dolore nelle riprese successive.', 'Commento audio del regista Ted Kotcheff nel Blu-ray celebrativo', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:40:08.789648+00:00');
